-- =====================================================================
-- PARTE 2: funcao global de diagnostico (cole antes da funcao de display
-- da bracket; global por causa do limite de 200 locals do chunk)
-- =====================================================================
function f_dumpStageSpriteDiagnostic(stageRef, stageAnim, stageEntry, boxX, boxY)
 tournamentStageDiagDone = tournamentStageDiagDone or {}
    if tournamentStageDiagDone[stageRef] then return end
    tournamentStageDiagDone[stageRef] = true

    local diagFile = io.open("tournament_stage_diag.txt", "a")
    if not diagFile then return end

    local function writePair(label, firstValue, secondValue)
        diagFile:write(label .. " = " .. tostring(firstValue) .. ", " .. tostring(secondValue) .. "\n")
    end

    diagFile:write("=== stage ref " .. tostring(stageRef) .. " | name = "
        .. tostring(stageEntry and stageEntry.name) .. " ===\n")
    writePair("box pos (px,py)", boxX, boxY)

    local motifLocalcoord = motif.info and motif.info.localcoord
    writePair("motif.info.localcoord", motifLocalcoord and motifLocalcoord[1], motifLocalcoord and motifLocalcoord[2])

    local stageConfig = motif.select_info and motif.select_info.stage
    local portraitConfig = stageConfig and stageConfig.portrait
    if portraitConfig then
        writePair("motif portrait.offset", portraitConfig.offset and portraitConfig.offset[1], portraitConfig.offset and portraitConfig.offset[2])
        writePair("motif portrait.scale", portraitConfig.scale and portraitConfig.scale[1], portraitConfig.scale and portraitConfig.scale[2])
    end

    if type(animGetSpriteInfo) == "function" then
        local callOk, spriteInfo = pcall(animGetSpriteInfo, stageAnim)
        diagFile:write("animGetSpriteInfo ok=" .. tostring(callOk) .. " type=" .. type(spriteInfo) .. "\n")
        if callOk and type(spriteInfo) == "table" then
            for infoKey, infoValue in pairs(spriteInfo) do
                diagFile:write("  " .. tostring(infoKey) .. " = " .. tostring(infoValue) .. "\n")
                if type(infoValue) == "table" then
                    for nestedKey, nestedValue in pairs(infoValue) do
                        diagFile:write("    " .. tostring(nestedKey) .. " = " .. tostring(nestedValue) .. "\n")
                    end
                end
            end
        end
    else
        diagFile:write("animGetSpriteInfo MISSING\n")
    end

    diagFile:write("\n")
    diagFile:close()
end


-- Expands any char reference form to .def candidate paths: full .def paths
-- pass through, while bare select.def names / dirs ("kfm720",
-- "chars/kfm720") also gain a "<dir>/<base>.def" guess, since the engine
-- resolves those to chars/<dir>/<base>.def internally.
-- (Global: the main chunk operates near the 200 locals limit.)
-- Canonical char key: lowercase, slashes, full .def guess
-- ("nests-kyo" and "chars/Nests-Kyo/Nests-Kyo.def" -> same key).
-- Pool/select store bare names, fights store full paths: without this the
-- same char misses its scale entry and splits the localcoord cache.
-- Absolute paths are only lowercased (never prefixed).
-- (Global: scale store/lookup + localcoord funnel.)
-- Pure function of its input, and it is called per portrait per frame by the
-- pool / bracket / scale editor draws (~8 string allocations per call), so
-- results are memoized (false = invalid path). Bounded by the number of
-- distinct stored path strings.
tournamentCanonPathCache = {}
function f_canonCharPath(path)
    if type(path) ~= "string" then return nil end
    local memoizedPath = tournamentCanonPathCache[path]
    if memoizedPath ~= nil then return memoizedPath or nil end
    local canonicalPath = nil
    local p = path:gsub("\\", "/")
    p = p:gsub("^%s+", ""):gsub("%s+$", ""):gsub("/+$", "")
    if p ~= "" then
        if p:match("^%a:") or p:match("^/") then
            canonicalPath = p:lower()
        else
            if not p:lower():match("%.def$") then
                local base = p:match("([^/]+)$") or p
                if base ~= "" then p = p .. "/" .. base .. ".def" end
            end
            if not p:lower():match("^chars/") then p = "chars/" .. p end
            canonicalPath = p:lower()
        end
    end
    tournamentCanonPathCache[path] = canonicalPath or false
    return canonicalPath
end

function f_expandCharDefCandidates(path)
    local out = {}
    if type(path) ~= "string" then return out end
    local p = path:gsub("\\", "/")
    p = p:gsub("^%s+", ""):gsub("%s+$", ""):gsub("/+$", "")
    if p == "" then return out end
    local function add(c)
        if c and c ~= "" then out[#out + 1] = c end
    end
    add(p)
    if not p:lower():match("^chars/") then add("chars/" .. p) end
    if not p:lower():match("%.def$") then
        local base = p:match("([^/]+)$") or p
        if base ~= "" then
            add(p .. "/" .. base .. ".def")
            if not p:lower():match("^chars/") then add("chars/" .. p .. "/" .. base .. ".def") end
        end
    end
    return out
end

-- Diagnostic counters of COLD localcoord reads (shown in the [ENTRY] lines).
tournamentLocalcoordParseCount = 0
tournamentLocalcoordParseSeconds = 0
-- LCDbg / LCmiss console traces (one print per char on a cold cache is slow).
TOURNAMENT_DEBUG_LOCALCOORD = TOURNAMENT_DEBUG_LOCALCOORD or false

-- basename (lowercase, no .def) -> first roster .def path. Built ONCE (the old
-- code walked the whole roster, with 4 string ops per entry, for every char).
tournamentRosterBaseIndex = nil
tournamentRosterBaseIndexSize = -1
function f_getRosterDefByBasename(rawBase)
    if type(main) ~= "table" or type(main.t_selChars) ~= "table" then return nil end
    local rosterSize = #main.t_selChars
    if tournamentRosterBaseIndex == nil or tournamentRosterBaseIndexSize ~= rosterSize then
        tournamentRosterBaseIndex = {}
        tournamentRosterBaseIndexSize = rosterSize
        for _, ch in pairs(main.t_selChars) do
            if type(ch) == "table" and type(ch.char) == "string" then
                local rosterBase = ch.char:gsub("\\", "/"):match("([^/]+)$") or ""
                rosterBase = rosterBase:lower():gsub("%.def$", "")
                if rosterBase ~= "" and tournamentRosterBaseIndex[rosterBase] == nil then
                    tournamentRosterBaseIndex[rosterBase] = ch.char
                end
            end
        end
    end
    return tournamentRosterBaseIndex[rawBase]
end

-- Reads [Info] localcoord from a char .def. Returns x, y or nil.
-- Pair ("1280,720") -> x and y. Single value ("425") -> BOTH axes
-- (the Marvel defs use bare "425"; width factor needs an X).
-- Scans [Info] first, then the whole file.
-- nil = absent/unreadable/ZSS (no .def) -> scale factor 1 (no change).
-- Cache key = CANONICAL path: the pool/bracket pass canonical paths while the
-- scale editor passed raw ones, so each char was read twice. The cache lives
-- in memory only (per boot): editing a .def takes effect on the next boot.
function f_getCharLocalcoord(path)
    if type(path) ~= "string" or path == "" then return nil end
    local cacheKey = path
    if type(f_canonCharPath) == "function" then
        cacheKey = f_canonCharPath(path) or path
    end
    local cachedEntry = tournamentCharLocalcoordCache[cacheKey]
    if cachedEntry ~= nil then
        if cachedEntry then return cachedEntry.x, cachedEntry.y end
        return nil
    end

    local parseStartSeconds = (os and os.clock and os.clock()) or 0
    local function finishParse(resultEntry)
        tournamentCharLocalcoordCache[cacheKey] = resultEntry
        tournamentLocalcoordParseCount = tournamentLocalcoordParseCount + 1
        local nowSeconds = (os and os.clock and os.clock()) or 0
        tournamentLocalcoordParseSeconds = tournamentLocalcoordParseSeconds + (nowSeconds - parseStartSeconds)
    end

    -- Bare names ("kfm720") expand to .def guesses; pure ZSS dirs yield none.
    local candidates = {}
    do
        local all = f_expandCharDefCandidates(path)
        for _, cand in ipairs(all) do
            if cand:lower():match("%.def$") then candidates[#candidates + 1] = cand end
        end
    end
    -- Engine roster fallback: match by file basename so ANY stored form
    -- ("CapAmerica", "05 - Marvel/CapAmerica/CapAmerica.def", bare folder)
    -- resolves to the loadable path the game itself uses. Tried first.
    do
        local rawBase = path:gsub("\\", "/"):match("([^/]+)$") or ""
        rawBase = rawBase:lower():gsub("%.def$", "")
        if rawBase ~= "" then
            local rosterDefPath = f_getRosterDefByBasename(rawBase)
            if rosterDefPath ~= nil then
                table.insert(candidates, 1, rosterDefPath)
            end
        end
    end
    local debugTrace = TOURNAMENT_DEBUG_LOCALCOORD == true
    if debugTrace then
        print("[Tournament][LCDbg] in=" .. tostring(path) .. " candidates=" .. table.concat(candidates, " | "))
    end
    if #candidates == 0 then
        finishParse(false)
        return nil
    end
    local foundX, foundY = nil, nil
    pcall(function()
        for _, cand in ipairs(candidates) do
            local f = io.open(cand, "r")
            if debugTrace then print("[Tournament][LCDbg] open " .. tostring(cand) .. " -> " .. tostring(f ~= nil)) end
            if f then
                -- One read; most defs have no localcoord at all, so a plain
                -- find rejects them without any line scanning.
                local fileContent = f:read("*a")
                pcall(function() f:close() end)
                if type(fileContent) == "string" and fileContent:lower():find("localcoord", 1, true) then
                    local lines = {}
                    for line in fileContent:gmatch("[^\n]+") do lines[#lines + 1] = line end
                    -- Pass 1: [Info] only. Pass 2: anywhere (some defs state
                    -- localcoord outside [Info]).
                    for pass = 1, 2 do
                        local inInfo = (pass == 2)
                        for _, line in ipairs(lines) do
                            local t = line:match("^%s*(.-)%s*$") or ""
                            t = (t:match("^(.-);") or t):match("^%s*(.-)%s*$") or ""
                            local low = t:lower()
                            if low:match("^%[.+%]$") then
                                if pass == 1 then
                                    local wasInInfo = inInfo
                                    inInfo = (low:gsub("%s+", "") == "[info]")
                                    -- [Info] is over: nothing left for pass 1.
                                    if wasInInfo and not inInfo then break end
                                end
                            elseif inInfo then
                                local key, value = t:match("^([%w_]+)%s*=%s*(.-)$")
                                if key and key:lower() == "localcoord" and value and value ~= "" then
                                    local nums = {}
                                    for n in value:gmatch("(%d+%.?%d*)") do
                                        nums[#nums + 1] = tonumber(n)
                                    end
                                    if nums[1] and nums[1] > 0 then
                                        -- Pair: X and Y. Single value: both axes
                                        -- (bare "425" means 425-space art).
                                        if nums[2] and nums[2] > 0 then
                                            foundX = nums[1]
                                            foundY = nums[2]
                                        else
                                            foundX = nums[1]
                                            foundY = nums[1]
                                        end
                                        break
                                    end
                                end
                            end
                        end
                        if foundY then break end
                    end
                end
                if foundY then break end
            end
        end
    end)
    if foundY then
        finishParse({ x = foundX, y = foundY })
        if debugTrace then print("[Tournament][LCDbg] FOUND x=" .. tostring(foundX) .. " y=" .. tostring(foundY)) end
        return foundX, foundY
    end
    finishParse(false)
    if debugTrace then
        print("[Tournament][LCmiss] no localcoord for '" .. tostring(path)
            .. "' (" .. tostring(#candidates) .. " candidates tried)")
    end
    return nil
end

-- Parses [Size] xscale/yscale from the char's CNS files. First number only
-- ("xscale=.5;.6" -> 0.5; ";.6" is an author comment). Returns x, y
-- (number|nil each). The CNS filenames always come from the char .def
-- [Files] cns=/st= (resolved against the def dir), never guessed.
function f_parseCharCnsScales(path)
    local candidates = {}
    if type(f_expandCharDefCandidates) == "function" then
        for _, cand in ipairs(f_expandCharDefCandidates(path)) do
            if cand:lower():match("%.def$") then candidates[#candidates + 1] = cand end
        end
    else
        candidates = { path }
    end
    if type(f_getRosterDefByBasename) == "function" then
        local rawBase = path:gsub("\\", "/"):match("([^/]+)$") or ""
        rawBase = rawBase:lower():gsub("%.def$", "")
        if rawBase ~= "" then
            local rd = f_getRosterDefByBasename(rawBase)
            if rd ~= nil then table.insert(candidates, 1, rd) end
        end
    end
    local foundX, foundY = nil, nil
    for _, cand in ipairs(candidates) do
        local f = io.open(cand, "r")
        if f then
            local defDir = cand:match("^(.*/)[^/]*$") or ""
            local cnsRel, stRel = nil, nil
            local inFiles = false
            for line in f:lines() do
                local t = line:match("^%s*(.-)%s*$") or ""
                t = (t:match("^(.-);") or t):match("^%s*(.-)%s*$") or ""
                local low = t:lower()
                if low:match("^%[.+%]$") then
                    inFiles = (low:gsub("%s+", "") == "[files]")
                elseif inFiles then
                    local k, v = t:match("^([%w_]+)%s*=%s*(.-)%s*$")
                    if k and v and v ~= "" then
                        local key = k:lower()
                        v = v:gsub('^["\']', ""):gsub('["\']$', "")
                        v = v:gsub("^%s+", ""):gsub("%s+$", ""):gsub("\\", "/")
                        if key == "cns" then cnsRel = v
                        elseif key == "st" then stRel = v end
                    end
                end
            end
            pcall(function() f:close() end)
            local function absP(rel)
                if not rel or rel == "" then return nil end
                if rel:match("^[A-Za-z]:") or rel:match("^/") then return rel end
                return defDir .. rel
            end
            local cnsFiles = { absP(cnsRel), absP(stRel) }
            for _, cf in ipairs(cnsFiles) do
                if type(cf) == "string" and cf ~= "" and not (foundX and foundY) then
                    local cf2 = io.open(cf, "r")
                    if cf2 then
                        local content = cf2:read("*a")
                        pcall(function() cf2:close() end)
                        if type(content) == "string" then
                            local inSize = false
                            for line in content:gmatch("[^\n]+") do
                                local t = line:match("^%s*(.-)%s*$") or ""
                                t = (t:match("^(.-);") or t):match("^%s*(.-)%s*$") or ""
                                local low = t:lower()
                                if low:match("^%[.+%]$") then
                                    inSize = (low:gsub("%s+", "") == "[size]")
                                elseif inSize then
                                    local k, v = t:match("^([%w_%.]+)%s*=%s*(.-)%s*$")
                                    if k and v then
                                        local kl = k:lower()
                                        if kl == "xscale" or kl == "yscale" then
                                            local n = tonumber(v:match("([%+%-]?%d*%.?%d+)"))
                                            if n and n > 0 then
                                                if kl == "xscale" then foundX = n else foundY = n end
                                                if foundX and foundY then break end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if foundX and foundY then break end
        end
    end
    return foundX, foundY
end

-- X-only wrapper (kept for existing callers).
function f_parseCharCnsXScale(path)
    return f_parseCharCnsScales(path)
end

-- Y-only wrapper.
function f_parseCharCnsYScale(path)
    local _, y = f_parseCharCnsScales(path)
    return y
end

tournamentCharCnsScaleCache = {}  -- canonpath -> {x=, y=} (per boot)

-- Reads [Size] xscale/yscale for a char: engine cns_scale first (no IO),
-- then the .def [Files] parse. Returns x, y (neutral 1 when unreadable).
-- Mr.Saikyo Constants.cns: xscale=.5, yscale=.5. Native select (f_animGet,
-- v[2]==-1) and the fight multiply char ANIMS by these; 9000,0 skips them.
function f_charCnsScales(path)
    if type(path) ~= "string" or path == "" then return 1, 1 end
    local cacheKey = path
    if type(f_canonCharPath) == "function" then
        cacheKey = f_canonCharPath(path) or path
    end
    local hit = tournamentCharCnsScaleCache[cacheKey]
    if type(hit) == "table" then
        return tonumber(hit.x) or 1, tonumber(hit.y) or 1
    end
    local foundX, foundY = nil, nil
    -- 1) Engine first: main.t_selChars[].cns_scale via getCharInfo(). No IO.
    if type(main) == "table" and type(main.t_selChars) == "table" then
        local rawBase = path:gsub("\\", "/"):match("([^/]+)$") or ""
        rawBase = rawBase:lower():gsub("%.def$", "")
        for _, ch in pairs(main.t_selChars) do
            if type(ch) == "table" and type(ch.cns_scale) == "table" then
                local match = false
                if type(ch.char) == "string" then
                    local cb = ch.char:gsub("\\", "/"):match("([^/]+)$") or ""
                    cb = cb:lower():gsub("%.def$", "")
                    if cb ~= "" and cb == rawBase then match = true end
                end
                if match then
                    local cx = tonumber(ch.cns_scale[1])
                    if cx and cx > 0 then foundX = cx end
                    local cy = tonumber(ch.cns_scale[2])
                    if cy and cy > 0 then foundY = cy end
                    break
                end
            end
        end
    end
    -- 2) Fallback: parse CNS directly (.def [Files] cns/st -> [Size]).
    if not (foundX and foundY) then
        pcall(function()
            local px, py = f_parseCharCnsScales(path)
            if not foundX then foundX = px end
            if not foundY then foundY = py end
        end)
    end
    local function clampCns(v)
        v = tonumber(v)
        if not (v and v > 0) then return 1 end
        if v < 0.05 then v = 0.05 end
        if v > 4 then v = 4 end
        return v
    end
    foundX, foundY = clampCns(foundX), clampCns(foundY)
    tournamentCharCnsScaleCache[cacheKey] = { x = foundX, y = foundY }
    return foundX, foundY
end

-- X-only wrapper (kept: existing anim draws call it).
function f_charCnsScaleX(path)
    local x = f_charCnsScales(path)
    return tonumber(x) or 1
end

-- Y-only wrapper (chars with xscale ~= yscale need per-axis anim scale).
function f_charCnsScaleY(path)
    local _, y = f_charCnsScales(path)
    return tonumber(y) or 1
end

-- Applies the char's OWN [Info] localcoord (e.g. KFM720's "1280,720") to an
-- anim's rendering space at draw time, when TOURNAMENT_APPLY_CHAR_LOCALCOORD
-- is on and the numbers are readable. EXPERIMENT: size comes from the swap
-- alone, scale stays 1 (tier table dormant while testing this).
-- Falls back to fixed-reference-space otherwise.
-- path: char .def path as stored by the char pool / t_selGrid (e.g.
--   "kfm720/kfm720.def"), same string f_getCharLocalcoord expects.
function f_applyCharLocalcoord(anim, path)
    -- Space is ALWAYS the fixed reference: swapping char space in would
    -- multiply art by screen/char ratio (proven: pair form broke SD chars,
    -- single form fell back here and looked right).
    -- Scale with APPLY on: REFERENCE_X / localcoordX (1280 matches the
    -- native formula portrait.scale x portraitscale x (motifX/charX)).
    local ws = 1
    if type(animSetLocalcoord) == "function" then
        animSetLocalcoord(anim, TOURNAMENT_REFERENCE_WIDTH, TOURNAMENT_REFERENCE_HEIGHT)
    end
    if TOURNAMENT_APPLY_CHAR_LOCALCOORD and type(path) == "string" and path ~= "" then
        -- Canon key: bare ("nests-kyo") and full paths share one cache entry.
        if type(f_canonCharPath) == "function" then
            path = f_canonCharPath(path) or path
        end
        local x = nil
        if type(f_getCharLocalcoord) == "function" then
            x = f_getCharLocalcoord(path)
        end
        x = tonumber(x)
        if x and x > 0 then
            local base = tonumber(TOURNAMENT_PORTRAIT_REF_W)
                or tonumber(TOURNAMENT_REFERENCE_WIDTH) or 1280
            ws = base / x
            if ws < 0.4 then ws = 0.4 end
            if ws > 16 then ws = 16 end
        end
    end
    return ws
end

-- Preview key edge (press-and-release, no held repeat).
-- Exact paths only: 'd' collides with DOWN in engine commands and with
-- physical-d (C button) in getKey, so the fuzzy checks are skipped here.
function f_checkPreviewKeyEdge()
    local b = string.lower(tostring(TOURNAMENT_PREVIEW_BUTTON or "d"))
    local cur = false
    if f_menuKeyDown and f_menuKeyDown(b) then cur = true end
    if not cur and type(f_joystickCmdDown) == "function" and f_joystickCmdDown(b) then cur = true end
    local trig = cur and not TOURNAMENT_PREVIEW_PREV
    TOURNAMENT_PREVIEW_PREV = cur
    return trig
end

-- Forward of the config table (declared further below); lets
-- f_playTournamentMusic() see the local `tournament`.
local tournament
-- Forward of the displayname reader (defined further below); lets
-- f_buildTournamentSummary()/f_deriveSummaryFromState() see it.
local f_getDisplayNameFromDef
-- Forward of the setup menu (defined further below); lets
-- f_showBracketOrExit() re-open it on bracket ESC.
local f_tournamentOptionsMenu

-- Resets menu items (matched by label) to the defaults from
-- TOURNAMENT_DEFAULTS_SD / TOURNAMENT_DEFAULTS_HD (by CURRENT height:
-- 480 = SD, anything else = HD). Never from JSON saves. Keeps idx/apply
-- in sync (apply() replays each item's side effects: music, bg, anims).
-- Accepts setup page entries ({item=...}) or plain item lists (overlays).
-- SD-locked animated items stay OFF in SD. isInfo/isAction rows are skipped.
-- (Global: the main chunk operates near the 200 locals limit.)
function f_resetMenuItemsToDefaults(list)
    print("[Tournament] RESTORE DEFAULTS key fired")
    local tables = TOURNAMENT_DEFAULTS_TABLES
    local defs = nil
    if type(tables) == "table" then
        -- SD/HD is defined by VIDEO height (f_getScreenHeight): 480 = SD,
        -- anything else = HD. Never localcoord, never JSON saves.
        local h = 480
        if type(f_getScreenHeight) == "function" then
            local ok, v = pcall(f_getScreenHeight)
            if ok and tonumber(v) then h = tonumber(v) end
        end
        -- Diagnostic: show every candidate so a wrong SD pick is easy to spot
        local dbgGH, dbgVO, dbgLC = "?", "?", "?"
        if type(gameHeight) == "function" then
            local ok, v = pcall(gameHeight); if ok then dbgGH = tostring(v) end
        end
        if type(gameOption) == "function" then
            local ok, v = pcall(gameOption, "Video.GameHeight"); if ok then dbgVO = tostring(v) end
        end
        if motif then
            local ly = (motif.info and motif.info.localcoord and motif.info.localcoord[2])
                or (motif.localcoord and motif.localcoord[2])
            dbgLC = tostring(ly)
        end
        -- SD only when runtime height is 480 AND localcoord is not HD-sized.
        -- (Video.GameHeight can be 480 while the screenpack is 1280x720.)
        local lcY = tonumber(dbgLC)
        local isSD = (h == 480) and not (lcY and lcY >= 720)
        if isSD then defs = tables.SD else defs = tables.HD end
        print("[Tournament] RESTORE DEFAULTS source: " .. (isSD and "SD" or "HD")
            .. " (height=" .. tostring(h)
            .. " | gameHeight=" .. dbgGH
            .. " | Video.GameHeight=" .. dbgVO
            .. " | localcoordY=" .. dbgLC .. ")")
    end
    if type(defs) ~= "table" then return end
    local isSD = ((tournament.screenMode or "HD") == "SD")
    local fieldByLabel = {
        ["LANGUAGE:"] = "language",
        ["START MODE:"] = "startMode",
        ["SLOT:"] = "saveSlot",
        ["TOURNAMENT FORMAT:"] = "format",
        ["TOURNAMENT SUBTITLE:"] = "subtitle",
        ["HUMAN PLAYERS:"] = "humanPlayers",
        ["USE ID FOR HUMAN PLAYERS:"] = "useHumanIds",
        ["RANDOM STAGE:"] = "randomStage",
        ["ALLOW RANDOM ID FOR CPU PLAYERS:"] = "allowRandomCpuIds",
        --["RANDOM IDS FOR HUMANS:"] = "randomHumanIds",
        ["RANDOM CHARS FOR ALL PLAYERS:"] = "randomCharsForHumans",
        ["SHOW PLAYER CURSORS:"] = "showPlayerCursors",
        ["SHOW CPU CURSORS:"] = "showCpuCursors",
        ["TEAM MODE:"] = "__team",
        ["TOURNAMENT SIZE:"] = "size",
        ["THIRD-PLACE PLAYOFF:"] = "thirdPlacePlayoff",
        ["ALLOW DUPLICATE CHARACTERS:"] = "allowDuplicateChars",
        ["ALLOW RANDOM CPU PALETTE:"] = "allowRandomCpuPalette",
        ["ROUNDS TO WIN:"] = "rounds",
        ["DIFFICULTY LEVEL:"] = "difficulty",
        ["TIME LIMIT:"] = "timeLimit",
        ["LIFE:"] = "life",
        ["WATCH CPU FIGHTS:"] = "watchCpuFights",
        ["CPU FIGHT SPEED:"] = "cpuSpeedMultiplier",
        ["SHOW VS SCREEN:"] = "showVsScreen",
        ["SHOW BRACKET BETWEEN MATCHES:"] = "showBracketBetweenMatches",
        ["AUTO-SAVE ON BRACKET SCREEN:"] = "autoSave",
        ["JOYSTICK BUTTON ICONS:"] = "padIcons",
        ["NEXT FIGHT ARROWS:"] = "nextFightArrows",
        ["MENU SCREEN MUSIC:"] = "menuMusicTrack",
        ["BRACKET EDIT SCREEN MUSIC:"] = "bracketEditMusicTrack",
        ["BRACKET SCREEN MUSIC:"] = "bracketMusicTrack",
        ["RESULTS SCREEN MUSIC:"] = "resultsMusicTrack",
        ["MENU SCREEN MUSIC VOLUME:"] = "menuMusicVolume",
        ["BRACKET EDIT SCREEN MUSIC VOLUME:"] = "bracketEditMusicVolume",
        ["BRACKET SCREEN MUSIC VOLUME:"] = "bracketMusicVolume",
        ["RESULTS SCREEN MUSIC VOLUME:"] = "resultsMusicVolume",
        ["BACKGROUND SOURCE:"] = "bgChoice",
        ["BACKGROUND OVERLAY OPACITY:"] = "bgOpacity",
        ["PORTRAIT BACKGROUND SPRITE:"] = "portraitBgSprite",
        ["SCREENPACK BG SPRITE SCALE:"] = "screenpackBgScale",
        ["STAGE PORTRAIT SCALE:"] = "stagePortraitScale",
        ["TROPHY SPRITE:"] = "trophySprite",
        ["SHOW ANIMATED PORTRAITS:"] = "showAnimatedPortraits",
        ["SHOW ANIMATED PORTRAIT BGS:"] = "showAnimatedPortraitsBg",
        ["SHOW BIG PORTRAITS:"] = "showBigPortraits",
    }
    if type(list) ~= "table" then return end
    for _, entry in ipairs(list) do
        local it = nil
        if type(entry) == "table" then it = entry.item or entry end
        if type(it) == "table" and not it.isInfo and not it.isAction
           and type(it.label) == "string" and type(it.options) == "table" then
            local field = (type(it.id) == "string" and it.id) or fieldByLabel[it._en or it.label]
            if field ~= nil then
                local found = nil
                if field == "language" then
                    local want = defs.language or "en"
                    if want ~= "ptBR" then want = "en" end
                    local wantLabel = (want == "ptBR") and "Portuguese-BR" or "English"
                    for i, opt in ipairs(it.options) do
                        if opt == wantLabel then found = i; break end
                    end
                elseif field == "__team" then
                    local wantMode = defs.teamMode or "single"
                    local wantChars = defs.teamSize or 1
                    for i, opt in ipairs(it.options) do
                        if type(opt) == "table" and opt.mode == wantMode and opt.chars == wantChars then
                            found = i; break
                        end
                    end
                elseif field == "format" then
                    local want = defs.format or "KNOCKOUT"
                    for i, opt in ipairs(it.options) do
                        if type(opt) == "table" and opt.id == want then
                            found = i; break
                        end
                    end
                elseif field == "bgChoice" then
                    -- Menu options hold display labels, defaults carry the
                    -- canonical key: match either form (legacy "Module2" too).
                    local want = tostring(defs.bgChoice or "original"):lower()
                    local keyOf = {
                        ["module"] = "original", ["module2"] = "original2",
                        ["module 2"] = "original2", ["screenpack select"] = "select",
                        ["screenpack versus"] = "versus", ["screenpack title"] = "title",
                        ["screenpack options"] = "options",
                    }
                    for i, opt in ipairs(it.options) do
                        if type(opt) == "string" then
                            local low = opt:lower()
                            if low == want or keyOf[low] == want then
                                found = i; break
                            end
                        end
                    end
                else
                    local want = defs[field]
                    if want ~= nil then
                        if it.isSDLocked and isSD and want == true then want = false end
                        for i, opt in ipairs(it.options) do
                            if type(opt) ~= "table" and opt == want then
                                found = i; break
                            end
                        end
                    end
                end
                if found ~= nil then
                    it.idx = found
                    if it.apply then it.apply(it.options[it.idx]) end
                    if type(f_markTournamentConfigDirty) == "function" then f_markTournamentConfigDirty() end
                    if (it._en or it.label) == "TOURNAMENT SIZE:" then
                        print("[Tournament] RESTORE size: want=" .. tostring(defs.size) .. " applied=" .. tostring(tournament and tournament.size))
                    end
                end
            end
        end
    end
end

-- Resolves track N to an existing file (mod folder, then mods root,
-- then the game sound folder).
-- Returns path, n. Missing everywhere => primary path (callers silence).
-- (Global: the main chunk has a 200 locals limit.)
function f_getTournamentMusicFile(n)
    n = math.floor(tonumber(n) or 1)
    if n < 1 then n = 1 end
    if n > (TOURNAMENT_MUSIC_COUNT or 5) then n = (TOURNAMENT_MUSIC_COUNT or 5) end
    local primary = string.format(TOURNAMENT_MUSIC_FMT, n)
    do
        local f = io.open(primary, "r")
        if f then f:close(); return primary, n end
    end
    if type(TOURNAMENT_MUSIC_ROOT_FMT) == "string" and TOURNAMENT_MUSIC_ROOT_FMT ~= "" then
        local rootPath = string.format(TOURNAMENT_MUSIC_ROOT_FMT, n)
        local f = io.open(rootPath, "r")
        if f then f:close(); return rootPath, n end
    end
    if type(TOURNAMENT_MUSIC_SOUND_FMT) == "string" and TOURNAMENT_MUSIC_SOUND_FMT ~= "" then
        local soundPath = string.format(TOURNAMENT_MUSIC_SOUND_FMT, n)
        local f = io.open(soundPath, "r")
        if f then f:close(); return soundPath, n end
    end
    return primary, n
end

-- Music path: "menu" => menuMusicTrack | "bracketEdit" => bracketEditMusicTrack
-- | "results" => resultsMusicTrack | "bracket" (default) => bracketMusicTrack.
-- (Global: the main chunk has a 200 locals limit.)
function f_getTournamentMusicPath(which)
    local n = nil
    if which == "menu" then
        n = tournament and tonumber(tournament.menuMusicTrack)
    elseif which == "bracketEdit" then
        n = tournament and tonumber(tournament.bracketEditMusicTrack)
    elseif which == "results" then
        n = tournament and tonumber(tournament.resultsMusicTrack)
    else
        n = tournament and tonumber(tournament.bracketMusicTrack)
    end
    -- Migration: old save with single track
    if n == nil and tournament then n = tonumber(tournament.musicTrack) end
    local defTrack = 3
    if which == "menu" then defTrack = 1
    elseif which == "bracketEdit" then defTrack = 2
    elseif which == "results" then defTrack = 4
    end
    n = math.floor(n or defTrack)
    if n < 1 then n = 1 end
    if n > (TOURNAMENT_MUSIC_COUNT or 5) then n = (TOURNAMENT_MUSIC_COUNT or 5) end
    return f_getTournamentMusicFile(n)
end

function f_updateTournamentMusicPath(which)
    if which == "menu" then
        TournamentSetMusic = f_getTournamentMusicPath("menu")
    elseif which == "bracketEdit" then
        TournamentSetMusic = f_getTournamentMusicPath("bracketEdit")
    elseif which == "results" then
        TournamentSetMusic = f_getTournamentMusicPath("results")
    else
        TournamentSetMusic = f_getTournamentMusicPath("bracket")
    end
    return TournamentSetMusic
end

-- Applies the track with the SAME behavior on all paths
-- (setup page 4, bracket overlay). which "menu" / "bracketEdit" / "results" /
-- "bracket". Preview plays instantly.
-- (Global: the main chunk has a 200 locals limit.)
function f_applyTournamentMusicTrack(v, which)
    if which ~= "menu" and which ~= "results" and which ~= "bracketEdit" then
        which = "bracket"
    end
    local defTrack = 3
    if which == "menu" then defTrack = 1
    elseif which == "bracketEdit" then defTrack = 2
    elseif which == "results" then defTrack = 4
    end
    local n = math.floor(tonumber(v) or defTrack)
    if n < 1 then n = 1 end
    if n > (TOURNAMENT_MUSIC_COUNT or 5) then n = (TOURNAMENT_MUSIC_COUNT or 5) end
    -- No-op when unchanged (menu-exit apply loops re-apply everything:
    -- replaying here made setup confirm play 1,2,3,4 in sequence).
    -- A drifted live file (preview) still resyncs via the plays below.
    local cur = nil
    if which == "menu" then cur = tournament.menuMusicTrack
    elseif which == "bracketEdit" then cur = tournament.bracketEditMusicTrack
    elseif which == "results" then cur = tournament.resultsMusicTrack
    else cur = tournament.bracketMusicTrack end
    if cur == n then
        local okP, wantP = pcall(f_getTournamentMusicPath, which)
        if okP and tostring(TournamentSetMusic) == tostring(wantP) then return n end
    end
    if which == "menu" then tournament.menuMusicTrack = n
    elseif which == "bracketEdit" then tournament.bracketEditMusicTrack = n
    elseif which == "results" then tournament.resultsMusicTrack = n
    else tournament.bracketMusicTrack = n end
    if type(f_updateTournamentMusicPath) == "function" then
        f_updateTournamentMusicPath(which)
    end
    if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
        motif.Music.select[1].bgm = TournamentSetMusic
    end
    if motif and motif.select_info then
        motif.select_info.bgm = TournamentSetMusic
    end
    if type(f_playTournamentMusic) == "function" then
        f_playTournamentMusic(which)
    end
    local who = "Bracket"
    if which == "menu" then who = "Menu"
    elseif which == "bracketEdit" then who = "BracketEdit"
    elseif which == "results" then who = "Results"
    end
    print("[Tournament] " .. who .. " music -> " .. tostring(n) .. " (" .. tostring(TournamentSetMusic) .. ")")
    return n
end

-- Standalone preview (C key on MENU/BRACKET EDIT/BRACKET/RESULTS SCREEN MUSIC):
-- plays track N without changing any of the saved tracks. On menu exit,
-- the context music comes back on its own (setup => run/title; overlay => restore
-- do bracket).
function f_previewTournamentMusic(n, which)
    n = math.floor(tonumber(n) or 1)
    if n < 1 then n = 1 end
    if n > (TOURNAMENT_MUSIC_COUNT or 5) then n = (TOURNAMENT_MUSIC_COUNT or 5) end
    TournamentSetMusic = f_getTournamentMusicFile(n)
    if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
        motif.Music.select[1].bgm = TournamentSetMusic
    end
    if motif and motif.select_info then
        motif.select_info.bgm = TournamentSetMusic
    end
    if tournament and tournament.musicEnabled == false then
        if stopBgm then pcall(stopBgm) end
        return n
    end
    if not playBgm then return n end
    local vol = 100
    if type(f_musicVolumeFor) == "function" then
        vol = tonumber(f_musicVolumeFor(which)) or 100
    elseif tournament then
        vol = tonumber(tournament.musicVolume) or 100
    end
    if vol < 0 then vol = 0 end
    if vol > 100 then vol = 100 end
    do
        local f = io.open(TournamentSetMusic, "r")
        if f then f:close()
        else
            if stopBgm then pcall(stopBgm) end
            return n
        end
    end
    pcall(function()
        playBgm({bgm = TournamentSetMusic, loop = 1, volume = vol, interrupt = true})
    end)
    print("[Tournament] Preview music -> " .. tostring(n) .. " (" .. tostring(TournamentSetMusic) .. ")")
    return n
end

-- Applies tournament music per tournament.musicEnabled / musicVolume.
-- which "menu" => MENU SCREEN MUSIC (setup menus)
-- | "bracketEdit" => BRACKET EDIT SCREEN MUSIC (cell-edit / seed edit)
-- | "results" => RESULTS SCREEN MUSIC (final screen only)
-- | "bracket" (default) => BRACKET SCREEN MUSIC (select, fights, bracket).
-- OFF => silence; missing file => silence (no music plays).
-- Per-track volumes: each SCREEN MUSIC has its own VOLUME row below it.
-- Legacy musicVolume seeds them on load (old saves) and stays as fallback.
-- (Global: the main chunk operates near the 200 locals limit.)
function f_musicVolumeFor(which)
    local legacy = 100
    if tournament then legacy = tonumber(tournament.musicVolume) or 100 end
    if tournament == nil then return 100 end
    if which == "menu" then return tonumber(tournament.menuMusicVolume) or legacy end
    if which == "bracketEdit" then return tonumber(tournament.bracketEditMusicVolume) or legacy end
    if which == "results" then return tonumber(tournament.resultsMusicVolume) or legacy end
    return tonumber(tournament.bracketMusicVolume) or legacy
end

local function f_playTournamentMusic(which)
    if which ~= "menu" and which ~= "results" and which ~= "bracketEdit" then
        which = "bracket"
    end
    if tournament and tournament.musicEnabled == false then
        if stopBgm then pcall(stopBgm) end
        return
    end
    if not playBgm then return end
    f_updateTournamentMusicPath(which)
    local vol = 100
    if type(f_musicVolumeFor) == "function" then
        vol = tonumber(f_musicVolumeFor(which)) or 100
    elseif tournament and tonumber(tournament.musicVolume) then
        vol = tonumber(tournament.musicVolume)
    end
    if vol < 0 then vol = 0 end
    if vol > 100 then vol = 100 end
    -- Without the selected track file: silence
    do
        local f = io.open(TournamentSetMusic, "r")
        if f then f:close()
        else
            if stopBgm then pcall(stopBgm) end
            return
        end
    end
    pcall(function()
        playBgm({bgm = TournamentSetMusic, loop = 1, volume = vol, interrupt = true})
    end)
end

-- Which track belongs on the live bracket view right now:
-- seeding (EDIT / START / MISC, including cell-edit) => bracketEdit
-- after START begins the tournament => bracket

-- =====================================================================
-- Status flash (SAVED / LOADED): lives OUTSIDE the menu so it keeps
-- showing on the bracket for the full duration after the overlay closes.
-- =====================================================================
tournamentStatusFlash = nil  -- { text = "SAVED"|"LOADED", frames = N }
tournamentStatusFlashTxt = nil

function f_setTournamentStatusFlash(msg, frames)
    tournamentStatusFlash = {
        text = tostring(msg or ""),
        frames = math.max(1, math.floor(tonumber(frames) or 90)),
    }
end

function f_drawTournamentStatusFlash()
    local flash = tournamentStatusFlash
    if type(flash) ~= "table" or (tonumber(flash.frames) or 0) <= 0 then
        tournamentStatusFlash = nil
        return
    end
    flash.frames = (tonumber(flash.frames) or 0) - 1
    if tournamentStatusFlashTxt == nil and type(textImgNew) == "function" then
        local t = textImgNew()
        if type(minhaFonte) ~= "nil" then pcall(textImgSetFont, t, minhaFonte) end
        if type(menuFontBank) ~= "nil" then pcall(textImgSetBank, t, menuFontBank) end
        tournamentStatusFlashTxt = t
    end
    local t = tournamentStatusFlashTxt
    if t == nil then return end
    pcall(textImgSetAlign, t, 0)
    pcall(textImgSetColor, t, 80, 255, 120)
    pcall(textImgSetPos, t,
        tonumber(TOURNAMENT_BRACKET_LOADING_X) or 160,
        tonumber(TOURNAMENT_BRACKET_LOADING_Y) or 120)
    local sc = tonumber(TOURNAMENT_BRACKET_LOADING_SCALE) or 0.3
    pcall(textImgSetScale, t, sc, sc)
    pcall(textImgSetText, t, tostring(flash.text or ""))
    pcall(textImgDraw, t)
end

function f_tournamentBracketViewMusic()
    if tournament and tournament.seeding then return "bracketEdit" end
    return "bracket"
end

-- Keys that skip/confirm the native versus ([VS Screen] from system.def:
-- skip.key = s (Start) | done.key = a, b, c, x, y, z, s). Skip does NOT require
-- releasing first (only done has doneKeyReady), so the bracket press
-- (A/Start/Enter) "passes through" and the versus is skipped.
-- (Global: the main chunk has a 200 locals limit.)
TOURNAMENT_VS_DRAIN_KEYS = { 'a', 'b', 'c', 'x', 'y', 'z', 's' }

-- Blocks until the player RELEASES the versus keys on both sides + keyboard.
-- Same effect as f_waitForRelease between tournament screens, but covering
-- the getInput(side) that the native screen uses (f_waitForRelease only watches P1).
-- (Global: the main chunk has a 200 locals limit.)
function f_waitVersusRelease()
    while true do
        if main and main.f_cmdInput then main.f_cmdInput() end
        local held = false
        if getInput then
            for _, side in ipairs({ 1, 2, -1 }) do
                for _, k in ipairs(TOURNAMENT_VS_DRAIN_KEYS) do
                    local ok, v = pcall(getInput, side, k)
                    if ok and v then held = true; break end
                    local ok2, v2 = pcall(getInput, side, '$' .. k)
                    if ok2 and v2 then held = true; break end
                end
                if held then break end
            end
        end
        if not held and main and main.t_cmd and commandGetState then
            for _, ci in ipairs({ 1, 2 }) do
                local cmd = main.t_cmd[ci]
                if cmd then
                    for _, k in ipairs(TOURNAMENT_VS_DRAIN_KEYS) do
                        local ok, v = pcall(commandGetState, cmd, k)
                        if ok and v then held = true; break end
                    end
                end
                if held then break end
            end
        end
        if not held and getKey then
            if getKey('RETURN') or getKey('KP_ENTER') or getKey('SPACE') or getKey('ESCAPE') then
                held = true
            end
        end
        if not held then break end
        refresh()
    end
end

-- Pause label swap (Character Change -> Skip Fight) while tournament runs.
-- Display strings live motif-side (system.base.def) and are COPIED into
-- built menu tables, so patch both the source (lazy builds) and the
-- built tables (boot builds). Training pause is left alone.
-- (Globals on purpose: the main chunk operates near the 200 locals limit.)
tournamentPauseLabelSaved = {}

-- (Global: the main chunk operates near the 200 locals limit.)
function f_applySkipPauseLabel()
    local function saveSwap(tbl, key, value)
        if type(tbl) ~= "table" or type(tbl[key]) ~= "string" then return end
        if tournamentPauseLabelSaved[tbl] == nil then
            tournamentPauseLabelSaved[tbl] = { key = key, value = tbl[key] }
        end
        tbl[key] = value
    end
    if motif ~= nil and type(motif.pause_menu) == "table" then
        for k, sec in pairs(motif.pause_menu) do
            if type(k) == "string" and k:sub(-11) == "_pause_menu" and k ~= "training_pause_menu"
               and type(sec) == "table" and type(sec.menu) == "table"
               and type(sec.menu.itemname) == "table" then
                saveSwap(sec.menu.itemname, "characterchange", "Skip Fight")
            end
        end
    end
    if menu ~= nil and type(menu) == "table" then
        local seen = {}
        local function walkItems(items)
            if type(items) ~= "table" or seen[items] then return end
            seen[items] = true
            for _, it in ipairs(items) do
                if type(it) == "table" and it.itemname == "characterchange" then
                    saveSwap(it, "displayname", "Skip Fight")
                end
            end
        end
        for id, menutbl in pairs(menu) do
            if id ~= "training" and type(menutbl) == "table" then
                walkItems(menutbl.items)
                if type(menutbl.submenu) == "table" then
                    for _, sub in pairs(menutbl.submenu) do
                        if type(sub) == "table" then walkItems(sub.items) end
                    end
                end
            end
        end
    end
end

-- (Global: the main chunk operates near the 200 locals limit.)
function f_restoreSkipPauseLabel()
    if type(tournamentPauseLabelSaved) ~= "table" then return end
    for tbl, entry in pairs(tournamentPauseLabelSaved) do
        if type(tbl) == "table" and type(entry) == "table"
           and type(entry.key) == "string" and type(entry.value) == "string" then
            tbl[entry.key] = entry.value
        end
    end
    tournamentPauseLabelSaved = {}
end

-- Interactive native stage select (Advanced > RANDOM STAGE = NO).
-- Runs BEFORE the fight, only for human-involved matches.
-- Returns the picked stage def path, or nil (random/cancel/unavailable).
-- Look/positions come from system.def via motif (native stage square + name).
-- (Global: the main chunk has a 200 locals limit.)
function f_pickTournamentStage()
    print("[Tournament] f_pickTournamentStage enter")
    if type(main) ~= "table" then print("[Tournament] stage: no main"); return nil end
    if type(main.t_selectableStages) ~= "table" or #main.t_selectableStages == 0 then
        if type(main.f_updateSelectableStages) == "function" then
            pcall(main.f_updateSelectableStages)
        end
    end
    local stages = main.t_selectableStages
    if type(stages) ~= "table" or #stages == 0 then
        print("[Tournament] stage: no selectable stages (" .. tostring(stages and #stages) .. ")")
        return nil
    end
    if type(motif) ~= "table" or type(motif.select_info) ~= "table"
        or type(motif.select_info.stage) ~= "table" then
        print("[Tournament] stage: motif has no select_info.stage")
        return nil
    end
    if type(start) ~= "table" or type(start.f_stageMenu) ~= "function" then
        print("[Tournament] stage: no start.f_stageMenu")
        return nil
    end
    print("[Tournament] stage picker open (" .. tostring(#stages) .. " stages)")
    print("[Tournament] stage entry states: startOnly="
        .. tostring(type(f_checkStartOnly) == "function" and f_checkStartOnly())
        .. " esc=" .. tostring(type(esc) == "function" and esc()))
    local stg = motif.select_info.stage

    local nameData = stg.active and stg.active.TextSpriteData or nil
    -- Stage name in the tournament font (own object: motif's sprite keeps
    -- its native font so nothing leaks into other modes).
    local nameTxt = textImgNew()
    textImgSetFont(nameTxt, minhaFonte); textImgSetBank(nameTxt, menuFontBank)
    textImgSetAlign(nameTxt, 0)
    textImgSetColor(nameTxt, 255, 255, 255)
    textImgSetScale(nameTxt, 0.30, 0.30)

    -- No background redraw: the frozen bracket frame stays behind and the
    -- stage UI draws on top of everything (portrait bg covers its area,
    -- name text resets each frame, so nothing trails).

    -- Own selection cursor: engine stageListNo is file-local to start.lua
    -- (unreadable here), so the picker drives pickIdx itself. Native
    -- randomselect rule mirrored (random on/off, init pos).
    local stageRandomMode = {
        [0] = { init = 1, min = 1 },
        [1] = { init = 0, min = 0 },
        [2] = { init = 1, min = 0 },
    }
    local sr = { init = 0, min = 0 }
    if motif.select_info and motif.select_info.stage_randomselect ~= nil
        and stageRandomMode[motif.select_info.stage_randomselect] then
        sr = stageRandomMode[motif.select_info.stage_randomselect]
    end
    local pickIdx, pickMinIdx, pickMaxIdx = sr.init, sr.min, #stages
    if pickIdx < pickMinIdx then pickIdx = pickMinIdx end
    if pickIdx > pickMaxIdx then pickIdx = pickMaxIdx end

    local function makeEdge(fn)
        local prevVal = true
        return function()
            local curDown = fn() and true or false
            local trig = curDown and not prevVal
            prevVal = curDown
            return trig
        end
    end
    local confirmEdge = makeEdge(function()
        if type(getInput) == "function" and motif.select_info.done
            and motif.select_info.done.key
            and getInput(-1, motif.select_info.done.key) then return true end
        if type(f_checkStartOnly) == "function" and f_checkStartOnly() then return true end
        return false
    end)
    local cancelEdge = makeEdge(function()
        if type(esc) == "function" and esc() then return true end
        if getKey and getKey("ESCAPE") then return true end
        return false
    end)
    -- Stage cursor movement (own edges; repeat like the menus).
    local function stageDirHeld(dir)
        return type(f_menuDirPressed) == "function" and f_menuDirPressed(dir)
    end
    local stageLeftEdge = f_makeRepeatEdge(function() return stageDirHeld("left") end, 18, 4)
    local stageRightEdge = f_makeRepeatEdge(function() return stageDirHeld("right") end, 18, 4)
    local stageUpEdge = f_makeRepeatEdge(function() return stageDirHeld("up") end, 18, 4)
    local stageDownEdge = f_makeRepeatEdge(function() return stageDirHeld("down") end, 18, 4)

    -- Entry reset for the initial cursor (guarded).
    do
        local ref0 = stages[pickIdx]
        if type(resetStagePortraitAnim) == "function" then
            pcall(resetStagePortraitAnim, ref0, "anim_data")
        end
    end

    while true do
        -- Bracket alive behind: one bg frame per picker frame (the engine
        -- clears every refresh, so the frozen frame can't persist).
        -- Visual-only: no input, no refresh (both stay with the picker).
        do
            local ctx = (type(tournament) == "table") and tournament.bracketViewCtx or nil
            if ctx ~= nil and ctx.bracket ~= nil
                and type(f_drawTournamentBracketBg) == "function" then
                f_drawTournamentBracketBg(ctx.bracket, ctx.size, ctx.round,
                    ctx.championMode, ctx.thirdPlaceFocus, ctx.p1Ref, ctx.playerAlive)
            end
        end
        -- Live nudge (stage group Y3): Y up / H down.
        if type(tournament) == "table" and type(f_makeRepeatEdge) == "function"
            and type(f_nudgeKeyDown) == "function" then
            local NE = tournament.nudgeEdges or {}
            tournament.nudgeEdges = NE
            if NE.py == nil then NE.py = f_makeRepeatEdge(function() return f_nudgeKeyDown("Y", "y") end, 18, 4) end
            if NE.hy == nil then NE.hy = f_makeRepeatEdge(function() return f_nudgeKeyDown("H", "h") end, 18, 4) end
            local dy3 = 0
            if NE.py() then dy3 = dy3 - 1 end
            if NE.hy() then dy3 = dy3 + 1 end
            if dy3 ~= 0 then TOURNAMENT_NUDGE_Y3 = (tonumber(TOURNAMENT_NUDGE_Y3) or 0) + dy3 end
        end
        -- Own cursor: arrows move, up/down jump 10, wraps (native behavior).
        local moved = false
        if stageLeftEdge() then pickIdx = pickIdx - 1; moved = true
        elseif stageRightEdge() then pickIdx = pickIdx + 1; moved = true
        elseif stageUpEdge() then pickIdx = pickIdx - 10; moved = true
        elseif stageDownEdge() then pickIdx = pickIdx + 10; moved = true end
        do
            local span = pickMaxIdx - pickMinIdx + 1
            if span > 0 then
                pickIdx = pickMinIdx + ((pickIdx - pickMinIdx) % span)
            end
        end
        if moved then
            local refMv = stages[pickIdx]
            if type(resetStagePortraitAnim) == "function" then
                pcall(resetStagePortraitAnim, refMv, "anim_data")
            end
            if stg.move and stg.move.snd and type(sndPlay) == "function" then
                pcall(sndPlay, motif.Snd, stg.move.snd[1], stg.move.snd[2])
            end
        end
        do
            local refBo = stages[pickIdx]
            if refBo ~= nil and type(main.f_preloadBoostStage) == "function" then
                pcall(main.f_preloadBoostStage, refBo)
            end
        end
        local ref = stages[pickIdx]
        local boxX = (stg.pos and stg.pos[1]) or 160
        local boxY = (stg.pos and stg.pos[2]) or 120
        -- Portrait box: motif stage.pos + portrait.bg.offset (system.def),
        -- or TOURNAMENT_STAGE_BG_X/Y when set (nil = motif). Module and
        -- screenpack paths share the same resolved origin.
        do
            local dY3 = (30)
            local bgX, bgY = boxX, boxY + dY3
            if type(f_stagePortraitBoxPos) == "function" then
                bgX, bgY = f_stagePortraitBoxPos(stg, "bg", dY3)
            end
            -- Module ignores the def origin (own MODULE_X/Y).
            if f_useModuleStageBg() and type(f_moduleStageBoxPos) == "function" then
                bgX, bgY = f_moduleStageBoxPos("bg", dY3)
            end
            if f_useModuleStageBg() then
                f_drawStageBgModule("bg", bgX, bgY)
            elseif type(main.f_animPosDraw) == "function"
                and stg.portrait and stg.portrait.bg then
                -- Motif AnimData embeds system.def offset; origin 0 + dY3.
                local mx = (type(TOURNAMENT_STAGE_BG_X) == "number") and TOURNAMENT_STAGE_BG_X or 0
                local my = ((type(TOURNAMENT_STAGE_BG_Y) == "number") and TOURNAMENT_STAGE_BG_Y or 0) + dY3
                pcall(main.f_animPosDraw, stg.portrait.bg.AnimData, mx, my)
            end
        end
        if pickIdx == 0 then
            local dY3 = (30)
            local rx, ry = boxX, boxY + dY3
            if type(f_stagePortraitBoxPos) == "function" then
                rx, ry = f_stagePortraitBoxPos(stg, "random", dY3)
            end
            -- Module ignores the def origin (own MODULE_X/Y).
            if f_useModuleStageBg() and type(f_moduleStageBoxPos) == "function" then
                rx, ry = f_moduleStageBoxPos("random", dY3)
            end
            if f_useModuleStageBg() then
                f_drawStageBgModule("random", rx, ry)
            elseif type(main.f_animPosDraw) == "function"
                and stg.portrait and stg.portrait.random then
                local mx = (type(TOURNAMENT_STAGE_BG_X) == "number") and TOURNAMENT_STAGE_BG_X or 0
                local my = ((type(TOURNAMENT_STAGE_BG_Y) == "number") and TOURNAMENT_STAGE_BG_Y or 0) + dY3
                pcall(main.f_animPosDraw, stg.portrait.random.AnimData, mx, my)
            end
        elseif ref ~= nil and type(main.t_selStages) == "table"
            and main.t_selStages[ref] ~= nil then
            local portrait, anim = stg.portrait, main.t_selStages[ref].anim_data
            local loadingPortrait = false
            if type(getStagePreloadStatus) == "function"
                and getStagePreloadStatus(ref) ~= "ready"
                and type(hasPortraitAnim) == "function" and portrait.loading
                and hasPortraitAnim(portrait.loading) then
                portrait = portrait.loading
                anim = portrait.AnimData
                loadingPortrait = true
            end
            local x = stg.pos and stg.pos[1] or 160
            local y = stg.pos and stg.pos[2] or 120
            if not loadingPortrait and portrait.offset then
                x = x + (portrait.offset[1] or 0)
                y = y + (portrait.offset[2] or 0)
            end
            boxX, boxY = x, y
            if f_useModuleStageBg() and loadingPortrait then
                local lx, ly = x, y + (30)
                -- Module ignores the def origin (own MODULE_X/Y).
                if type(f_moduleStageBoxPos) == "function" then
                    lx, ly = f_moduleStageBoxPos("loading", 30)
                end
                f_drawStageBgModule("loading", lx, ly)
            elseif type(main.f_animPosDraw) == "function" then
                pcall(main.f_animPosDraw, anim,
                    x + (tonumber(TOURNAMENT_STAGE_PICKER_SPRITE_DX) or 0),
                    y + (30) + (tonumber(TOURNAMENT_STAGE_PICKER_SPRITE_DY) or 0))
            end
        end
        -- Stage name (tournament font; ADJUST the +110 offset).
        do
            local txt = (stg.random and stg.random.text) or "RANDOM"
            if pickIdx ~= 0 and ref ~= nil
                and type(main.t_selStages) == "table"
                and main.t_selStages[ref] ~= nil then
                if type(main.f_formatBySpec) == "function" and stg.text then
                    local ok, t = pcall(main.f_formatBySpec, stg.text,
                        {i = pickIdx, s = main.t_selStages[ref].name})
                    if ok and t then txt = t end
                elseif main.t_selStages[ref].name then
                    txt = tostring(main.t_selStages[ref].name)
                end
            end
            textImgReset(nameTxt)
            textImgSetText(nameTxt, txt)
            -- Fixed text-space spot (motif stage.pos lives in another
            -- coordinate space, which made named stages vanish). ADJUST.
            textImgSetPos(nameTxt, 160, 210 + (30))
            textImgDraw(nameTxt)
        end
        if confirmEdge() then
            if pickIdx == 0 then return nil end
            if ref ~= nil then
                local ready = true
                if type(getStagePreloadStatus) == "function" then
                    ready = (getStagePreloadStatus(ref) == "ready")
                    if not ready and type(main.f_preloadBoostStage) == "function" then
                        pcall(main.f_preloadBoostStage, ref)
                    end
                end
                if ready then
                    if type(main.f_materializeStagePortrait) == "function" then
                        pcall(main.f_materializeStagePortrait, ref)
                    end
                    if stg.done and stg.done.snd and type(sndPlay) == "function"
                        and type(motif.Snd) ~= "nil" then
                        pcall(sndPlay, motif.Snd, stg.done.snd[1], stg.done.snd[2])
                    end
                    if type(f_dumpNudge) == "function" then f_dumpNudge() end
                    return ref
                end
            end
        end
        if cancelEdge() then
            if type(f_dumpNudge) == "function" then f_dumpNudge() end
            return nil
        end
        refresh()
    end
end

-- Runs launchFight with the bracket music also on the versus screen.
-- Same logic as the select screen: intercepts playBgm({source="motif.vs"})
-- and forces TournamentSetMusic (bracket). Fight/stage music (native, via
-- loadStart) does not go through playBgm in Lua, so it is not affected; for
-- safety, any other source goes straight to the original playBgm.
-- (Global: the main chunk has a 200 locals limit.)
-- "PLAYER N" label from a PLAYER key ("PLAYER"/"PLAYER3"/nil -> PLAYER 1/3/1).
-- Default ID text and empty-ID display fallback (IDs never render blank).
-- (Global: shared by the bracket ID lines and the versus hook.)
function f_defaultHumanIdLabel(key)
    local n = 1
    if type(key) == "string" then
        local d = key:match("^PLAYER(%d+)$")
        if d then n = tonumber(d) or 1 end
    end
    return "PLAYER " .. tostring(n)
end

-- Display ID of a tournament participant for the versus screen (same rules as
-- the bracket ID line: human custom ID if USE ID is on, CPU id if allowed).
-- Accepts tables ({id=...}) or "PLAYER[n]" strings. "" = show char name.
-- (Global: callers live across chunks.)
function f_tournamentDisplayId(p)
    if tournament == nil then return "" end
    local pid = nil
    if type(p) == "table" then
        pid = p.id
    elseif type(p) == "string" and (p == "PLAYER" or p:match("^PLAYER%d+$")) then
        pid = p
    else
        return ""
    end
    if pid == "PLAYER" or (type(pid) == "string" and pid:match("^PLAYER%d+$")) or p.isPlayer == true then
        local key = "PLAYER1"
        if type(pid) == "string" and pid:match("^PLAYER%d+$") then key = pid end
        if tournament.useHumanIds and tournament.humanIds then
            local hid = tournament.humanIds[key]
            if type(hid) == "string" and hid ~= "" then return hid end
        end
        -- Empty renders the default label (never blank, never char name).
        if type(f_defaultHumanIdLabel) == "function" then
            return f_defaultHumanIdLabel(key)
        end
        return ""
    else
        if tournament.allowRandomCpuIds ~= false and tournament.cpuIds then
            local cname = tournament.cpuIds[tostring(pid)]
            if type(cname) == "string" and cname ~= "" then return cname end
        end
        return ""
    end
end

-- Versus screen name hook: while a tournament fight is on screen,
-- start.f_getName returns the side ID instead of the char name.
-- Installed once (lazy: start may not exist at mod load).
tournamentVsSideIds = nil
function f_installTournamentVsIds()
    if tournamentVsIdsInstalled == true then return end
    if start == nil or type(start.f_getName) ~= "function" then return end
    tournamentVsIdsInstalled = true
    tournamentOrigGetName = start.f_getName
    start.f_getName = function(ref, side)
        if tournamentVsSideIds ~= nil and type(side) == "number" then
            local id = tournamentVsSideIds[side]
            if type(id) == "string" and id ~= "" then return id end
        end
        return tournamentOrigGetName(ref, side)
    end
end

-- =====================================================================
-- LIFEBAR NAME ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ ID OVERLAY (fight screen)
-- Engine draws displayname/lifebarname from the char .def with no Lua
-- setter. Workaround: cover the original name, then draw the tournament
-- ID on top. Lua draws in 320x240-stretched space while fight.def works in
-- 1280x720, so positions convert (X/4, Y/3) and scale is 0.25. Reference
-- (IKEMEN1 1280x720) fight.def [Name] values:
--   p1.pos = 13,145   p1.name.font = 3,0, 1   (left)
--   p2.pos = 1267,145 p2.name.font = 3,0,-1   (right)
-- Font 3 = ikemen1/fonts/Menu2Small.def
-- Active only while tournamentVsSideIds is set (during launchFight).
-- =====================================================================
TOURNAMENT_LIFEBAR_ID_ENABLED = false  -- PARKED (lifebar IDs off for now)
-- ID anchor: fight.def [Name] p1/p2.pos (nil = auto from data/fight.def;
-- set numbers to pin manually in Lua space). ID sits DY fight units below.
-- Lua space is 320-stretched: fight X/4, Y/3 (16:9).
TOURNAMENT_LIFEBAR_ID_P1_X = nil
TOURNAMENT_LIFEBAR_ID_P1_Y = nil
TOURNAMENT_LIFEBAR_ID_P2_X = nil
TOURNAMENT_LIFEBAR_ID_P2_Y = nil
TOURNAMENT_LIFEBAR_ID_DY = 10
TOURNAMENT_LIFEBAR_ID_P1_ALIGN = 1   -- 1 = left (p1.name.font third value)
TOURNAMENT_LIFEBAR_ID_P2_ALIGN = -1  -- -1 = right
-- Scale to match the fight name (font 3 scale 1,1 in 1280 space):
-- 320/1280 = 0.25. Height maps /3 (0.33); uniform 0.25 lands ~25% shorter,
-- close enough at this glyph size (split X/Y if it bothers).
TOURNAMENT_LIFEBAR_ID_SCALE = 0.25
TOURNAMENT_LIFEBAR_ID_COLOR = {255, 255, 255}
TOURNAMENT_LIFEBAR_ID_BANK = 0
-- Cover strip over the engine name (so char name does not show under ID)
TOURNAMENT_LIFEBAR_ID_COVER = true
TOURNAMENT_LIFEBAR_ID_COVER_W = 280   -- width of blackout strip
TOURNAMENT_LIFEBAR_ID_COVER_H = 22    -- height
TOURNAMENT_LIFEBAR_ID_COVER_DY = -16  -- vertical nudge from name Y (font baseline)
TOURNAMENT_LIFEBAR_ID_COVER_COLOR = {0, 0, 0}
TOURNAMENT_LIFEBAR_ID_COVER_ALPHA = 255

-- Globals (main chunk has a ~200 locals limit)
tournamentLifebarIdFont = nil
tournamentLifebarIdTxt = {nil, nil}
tournamentLifebarIdCover = {nil, nil}
tournamentLifebarIdHooked = false
tournamentFightNamePos = nil  -- {p1x,p1y,p2x,p2y} in fight.def units (nil/false = unread)

-- Reads fight.def [Name] p1/p2.pos once per session (data/fight.def).
-- The mod positions follow the lifebar in use instead of hardcoded numbers.
function f_readFightNamePos()
    if tournamentFightNamePos ~= nil then
        return tournamentFightNamePos or nil
    end
    local function parse(physPath)
        local f = io.open(physPath, "r")
        if not f then return nil end
        local inName = false
        local p1x, p1y, p2x, p2y = nil, nil, nil, nil
        for line in f:lines() do
            local t = line:match("^%s*(.-)%s*$") or ""
            t = (t:match("^(.-);") or t):match("^%s*(.-)%s*$") or ""
            local low = t:lower()
            if low:match("^%[.+%]$") then
                if inName then break end
                if low:gsub("%s+", "") == "[name]" then inName = true end
            elseif inName then
                local k, v = t:match("^([%w%.]+)%s*=%s*(.-)$")
                if k and v then
                    local lk = k:lower()
                    if lk == "p1.pos" or lk == "p2.pos" then
                        local nums = {}
                        for n in v:gmatch("(%d*%.?%d+)") do
                            nums[#nums + 1] = tonumber(n)
                        end
                        if nums[1] and nums[2] then
                            if lk == "p1.pos" and p1x == nil then
                                p1x, p1y = nums[1], nums[2]
                            elseif lk == "p2.pos" and p2x == nil then
                                p2x, p2y = nums[1], nums[2]
                            end
                        end
                    end
                end
                if p1x ~= nil and p2x ~= nil then break end
            end
        end
        pcall(function() f:close() end)
        if p1x ~= nil and p2x ~= nil then
            return { p1x = p1x, p1y = p1y, p2x = p2x, p2y = p2y }
        end
        return nil
    end
    tournamentFightNamePos = parse("data/fight.def") or false
    return tournamentFightNamePos or nil
end

function f_lifebarIdLoadFont()
    if tournamentLifebarIdFont ~= nil then return tournamentLifebarIdFont end
    local candidates = {
        "ikemen1/fonts/Menu2Small.def",
        "data/ikemen1/fonts/Menu2Small.def",
        "font/Menu2Small.def",
        "fonts/Menu2Small.def",
        "external/mods/TournamentMode/TournamentModeFont.def",
        "external/mods/TournamentModeFont.def",
    }
    for i = 1, #candidates do
        local ok, f = pcall(fontNew, candidates[i], -1)
        if ok and f ~= nil then
            tournamentLifebarIdFont = f
            -- TEMP: proves which font file actually loaded.
            print("[Tournament][LifebarID] font #" .. tostring(i) .. " OK: " .. tostring(candidates[i]))
            return f
        end
    end
    print("[Tournament][LifebarID] font FALLBACK (minhaFonte) - candidates failed")
    tournamentLifebarIdFont = minhaFonte
    return tournamentLifebarIdFont
end

function f_lifebarIdEnsureSprites()
    local font = f_lifebarIdLoadFont()
    if font == nil then return false end
    for side = 1, 2 do
        if tournamentLifebarIdTxt[side] == nil then
            local t = textImgNew()
            textImgSetFont(t, font)
            textImgSetBank(t, TOURNAMENT_LIFEBAR_ID_BANK or 0)
            textImgSetScale(t, TOURNAMENT_LIFEBAR_ID_SCALE or 1, TOURNAMENT_LIFEBAR_ID_SCALE or 1)
            local col = TOURNAMENT_LIFEBAR_ID_COLOR or {255, 255, 255}
            textImgSetColor(t, col[1] or 255, col[2] or 255, col[3] or 255)
            tournamentLifebarIdTxt[side] = t
        end
        if TOURNAMENT_LIFEBAR_ID_COVER and tournamentLifebarIdCover[side] == nil and type(rectNew) == "function" then
            local ok, r = pcall(rectNew)
            if ok and r ~= nil then
                tournamentLifebarIdCover[side] = r
            end
        end
    end
    return true
end

function f_tournamentLifebarIdDraw()
    if TOURNAMENT_LIFEBAR_ID_ENABLED == false then return end
    if tournamentVsSideIds == nil then return end
    -- Skip if not in a match phase
    if type(roundstate) == "function" then
        local rs = roundstate()
        if rs == nil or rs < 0 then return end
    end
    if not f_lifebarIdEnsureSprites() then return end

    local ids = tournamentVsSideIds
    -- Anchor: fight.def [Name] when readable (nil tunables = auto), else the
    -- tunables, else the IKEMEN1 fallbacks. ID sits DY fight units below.
    local fnp = nil
    if type(f_readFightNamePos) == "function" then
        local ok, r = pcall(f_readFightNamePos)
        if ok then fnp = r end
    end
    local idDy = tonumber(TOURNAMENT_LIFEBAR_ID_DY) or 10
    local qx1, qy1 = 3, 52
    local qx2, qy2 = 317, 52
    if type(fnp) == "table" then
        if tonumber(fnp.p1x) and tonumber(fnp.p1y) then
            qx1, qy1 = fnp.p1x / 4, (fnp.p1y + idDy) / 3
        end
        if tonumber(fnp.p2x) and tonumber(fnp.p2y) then
            qx2, qy2 = fnp.p2x / 4, (fnp.p2y + idDy) / 3
        end
    end
    if tonumber(TOURNAMENT_LIFEBAR_ID_P1_X) then qx1 = tonumber(TOURNAMENT_LIFEBAR_ID_P1_X) end
    if tonumber(TOURNAMENT_LIFEBAR_ID_P1_Y) then qy1 = tonumber(TOURNAMENT_LIFEBAR_ID_P1_Y) end
    if tonumber(TOURNAMENT_LIFEBAR_ID_P2_X) then qx2 = tonumber(TOURNAMENT_LIFEBAR_ID_P2_X) end
    if tonumber(TOURNAMENT_LIFEBAR_ID_P2_Y) then qy2 = tonumber(TOURNAMENT_LIFEBAR_ID_P2_Y) end
    local positions = {
        [1] = {
            x = qx1,
            y = qy1,
            align = TOURNAMENT_LIFEBAR_ID_P1_ALIGN or 1,
        },
        [2] = {
            x = qx2,
            y = qy2,
            align = TOURNAMENT_LIFEBAR_ID_P2_ALIGN or -1,
        },
    }
    local coverW = TOURNAMENT_LIFEBAR_ID_COVER_W or 280
    local coverH = TOURNAMENT_LIFEBAR_ID_COVER_H or 22
    local coverDy = TOURNAMENT_LIFEBAR_ID_COVER_DY or -16
    local coverCol = TOURNAMENT_LIFEBAR_ID_COVER_COLOR or {0, 0, 0}
    local coverA = TOURNAMENT_LIFEBAR_ID_COVER_ALPHA or 255

    for side = 1, 2 do
        local id = ids[side]
        if type(id) == "string" and id ~= "" then
            local p = positions[side]
            -- Cover strip: left-aligned from pos for P1, right-aligned for P2
            if TOURNAMENT_LIFEBAR_ID_COVER and tournamentLifebarIdCover[side] ~= nil then
                local x1, y1 = p.x, p.y + coverDy
                if p.align == -1 then
                    x1 = p.x - coverW
                elseif p.align == 0 then
                    x1 = p.x - coverW * 0.5
                end
                local x2, y2 = x1 + coverW, y1 + coverH
                local r = tournamentLifebarIdCover[side]
                pcall(function()
                    -- Match fight.def localcoord so strip sits on the name
                    if type(rectSetLocalcoord) == "function" then
                        rectSetLocalcoord(r, 1280, 720)
                    end
                    if type(rectSetWindow) == "function" then
                        rectSetWindow(r, x1, y1, x2, y2)
                    end
                    if type(rectSetColor) == "function" then
                        rectSetColor(r, coverCol[1] or 0, coverCol[2] or 0, coverCol[3] or 0)
                    end
                    if type(rectSetAlpha) == "function" then
                        rectSetAlpha(r, coverA, coverA)
                    end
                    -- Commits window/color/alpha (without this the strip
                    -- draws with stale state = cover does nothing).
                    if type(rectUpdate) == "function" then rectUpdate(r) end
                    if type(rectDraw) == "function" then rectDraw(r) end
                end)
            end
            local t = tournamentLifebarIdTxt[side]
            textImgSetAlign(t, p.align)
            textImgSetText(t, id)
            textImgSetPos(t, p.x, p.y)
            textImgDraw(t)
        end
    end
end

function f_installTournamentLifebarIdHook()
    if tournamentLifebarIdHooked then return end
    if type(hook) ~= "table" or type(hook.add) ~= "function" then return end
    tournamentLifebarIdHooked = true
    hook.add("loop", "tournamentLifebarIds", function()
        pcall(f_tournamentLifebarIdDraw)
    end)
end

-- Install as soon as scripts are ready (hook table exists after main.lua load).
if type(hook) == "table" and type(hook.add) == "function" then
    f_installTournamentLifebarIdHook()
else
    -- Defer: try again when versus hook installs / first fight launches
    local _prevInstallVs = f_installTournamentVsIds
    f_installTournamentVsIds = function()
        _prevInstallVs()
        f_installTournamentLifebarIdHook()
    end
end


function f_launchFightWithTournamentBgm(args)
    local savedPlayBgm = playBgm
    args = args or {}
    -- Engine launchFight() crashes (pairs(nil) in f_excludeChar) when
    -- main.t_availableChars was never built: native select is bypassed and,
    -- on a fresh boot straight into CONTINUE, the one-time setup rebuild
    -- never runs. Rebuild here covers every caller (human + CPU fights).
    if type(main) == "table" and type(main.t_availableChars) ~= "table" then
        if main.f_tableCopy and start and start.f_getOrderChars then
            local ok, chars = pcall(start.f_getOrderChars)
            if ok and type(chars) == "table" then
                main.t_availableChars = main.f_tableCopy(chars)
            end
        end
        if type(main.t_availableChars) ~= "table" then
            main.t_availableChars = {}
        end
    end
    -- launchFight() resets P1's t_selected itself (start.lua) but APPENDS
    -- P2's (no pre-reset there) and f_difficulty does ref + 1 on it.
    -- Stale entries poison fights: string refs from f_restorePlayerSelection
    -- (LOAD/title restores) crash f_difficulty, and even stale numerics
    -- mis-aim AI/pals and skew the fill count. Reset both sides here: the
    -- engine rebuilds them from the args below.
    if start and type(start.p) == "table" then
        for _, pn in ipairs({ 1, 2 }) do
            local sp = start.p[pn]
            if type(sp) == "table" then
                sp.t_selected = {}
                sp.t_selTemp = {}
            end
        end
    end
    -- main.f_restoreInput() (post-fight) indexes main.t_baseRemapInput,
    -- captured by the native select screen. Never overwritten here, only
    -- filled when missing (entries default to identity in f_restoreInput).
    if type(main) == "table" and type(main.t_baseRemapInput) ~= "table"
       and type(main.f_saveBaseRemapInput) == "function" then
        pcall(main.f_saveBaseRemapInput)
    end
    -- f_selectReset() (called inside launchFight) does math.min/max on
    -- start.p[side].numSimul/numTag/numTurns, initialized by native select
    -- (or hardReset). Fresh boot into CONTINUE leaves them nil.
    -- Mirror the engine hardReset defaults when missing.
    if start and type(start.p) == "table" and type(gameOption) == "function" then
        local numFields = {
            { "numSimul", "Options.Simul.Min" },
            { "numTag", "Options.Tag.Min" },
            { "numTurns", "Options.Turns.Min" },
        }
        for _, pn in ipairs({ 1, 2 }) do
            local sp = start.p[pn]
            if type(sp) == "table" then
                for _, f in ipairs(numFields) do
                    if tonumber(sp[f[1]]) == nil then
                        local okMin, vmin = pcall(gameOption, f[2])
                        sp[f[1]] = math.max(2, (okMin and tonumber(vmin)) or 2)
                    end
                end
            end
        end
    end
    -- ------------------------------------------------------------------
    -- Time Limit (tournament only): inject args.time for launchFight /
    -- start.f_setRounds. Menu OFF (0) maps to engine infinite (-1).
    -- Also mirrors into main.roundTime for any path that reads the fallback.
    -- Does NOT write Options.Time (main menu Options stays intact).
    -- ------------------------------------------------------------------
    local savedMainRoundTime = nil
    local timeApplied = false
    if args.time == nil and tournament and tournament.timeLimit ~= nil then
        local rt = math.floor(tonumber(tournament.timeLimit) or 99)
        if rt == 0 then rt = -1 end  -- OFF => infinite
        if rt < -1 then rt = -1 end
        args.time = rt
        timeApplied = true
        print("[Tournament] Time Limit (match-only) -> " .. tostring(rt) .. " (menu timeLimit=" .. tostring(tournament.timeLimit) .. ")")
    elseif args.time ~= nil then
        timeApplied = true
    end
    if timeApplied and main then
        savedMainRoundTime = main.roundTime
        main.roundTime = args.time
    end
    local function f_restoreTournamentTime()
        if savedMainRoundTime ~= nil and main then
            main.roundTime = savedMainRoundTime
            print("[Tournament] main.roundTime restored -> " .. tostring(savedMainRoundTime))
        end
    end
    -- Tournament Life: applies Options.Life only during the fight and restores afterwards.
    -- Does NOT persist in the game config (main menu Options stays intact).
    local savedLife = nil
    local lifeApplied = false
    if type(gameOption) == "function" and type(modifyGameOption) == "function" then
        local okGet, cur = pcall(gameOption, "Options.Life")
        if okGet then savedLife = cur end
        local lv = 100
        if tournament and tonumber(tournament.life) then lv = tonumber(tournament.life) end
        lv = math.floor(lv or 100)
        if lv < 10 then lv = 10 end
        if lv > 300 then lv = 300 end
        local okSet = pcall(modifyGameOption, "Options.Life", lv)
        lifeApplied = okSet and true or false
        if lifeApplied then
            print("[Tournament] Life (match-only) -> " .. tostring(lv) .. "% (saved Options.Life=" .. tostring(savedLife) .. ")")
        end
    end
    local function f_restoreTournamentLife()
        if lifeApplied and savedLife ~= nil and type(modifyGameOption) == "function" then
            pcall(modifyGameOption, "Options.Life", savedLife)
            print("[Tournament] Life restored -> Options.Life=" .. tostring(savedLife))
        end
        f_restoreTournamentTime()
    end
    -- Drains the bracket press before the native versus: without this the versus is
    -- skipped instantly (skip.key='s' does not require releasing first). Only waits when
    -- the versus will show (vsscreen=false => direct fight, nothing to skip).
    if args and args.vsscreen ~= false and type(f_waitVersusRelease) == "function" then
        pcall(f_waitVersusRelease)
    end
    if type(savedPlayBgm) == "function" and type(launchFight) == "function" then
        if type(f_updateTournamentMusicPath) == "function" then
            pcall(f_updateTournamentMusicPath, "bracket")
        end
        playBgm = function(arg)
            local src = nil
            if type(arg) == "table" then src = arg.source end
            if type(src) == "string" and (src == "motif.vs" or src == "motif.select") then
                if tournament and tournament.musicEnabled == false then
                    if stopBgm then pcall(stopBgm) end
                    return
                end
                do
                    local f = io.open(TournamentSetMusic, "r")
                    if f then f:close()
                    else
                        if stopBgm then pcall(stopBgm) end
                        return
                    end
                end
                -- Fights run under the forced file (bracket track): its volume.
                local vol = 100
                if type(f_musicVolumeFor) == "function" then
                    vol = tonumber(f_musicVolumeFor("bracket")) or 100
                elseif tournament then
                    vol = tonumber(tournament.musicVolume) or 100
                end
                if vol < 0 then vol = 0 end
                if vol > 100 then vol = 100 end
                return savedPlayBgm({bgm = TournamentSetMusic, loop = 1, volume = vol, interrupt = true})
            end
            return savedPlayBgm(arg)
        end
        if type(f_installTournamentVsIds) == "function" then pcall(f_installTournamentVsIds) end
        tournamentVsSideIds = args.vsIds
        local res = launchFight(args)
        tournamentVsSideIds = nil
        playBgm = savedPlayBgm
        f_restoreTournamentLife()
        return res
    end
    if type(launchFight) == "function" then
        if type(f_installTournamentVsIds) == "function" then pcall(f_installTournamentVsIds) end
        tournamentVsSideIds = args.vsIds
        local res = launchFight(args)
        tournamentVsSideIds = nil
        f_restoreTournamentLife()
        return res
    end
    f_restoreTournamentLife()
    return false
end

-- Runtime screen size for SD/HD detection.
-- NOTE: icon scaling does NOT use these (it needs render HEIGHT).
-- Source of truth is gameOption Video.* (render size): gameHeight()
-- returned 319 at 640x480 render, gameWidth() is nil here, and motif
-- localcoord is design space.
-- Screen height = RENDER height (Video.GameHeight). GLOBAL on purpose: the
-- reset function above calls it textually before this point (a local would
-- be invisible there, forcing the 480 fallback and wrong SD defaults).
-- (gameHeight() is ignored: returned 319 at 640x480 render.)
function f_getScreenHeight()
    if type(gameOption) == "function" then
        local ok, v = pcall(gameOption, "Video.GameHeight")
        if ok and tonumber(v) and tonumber(v) > 0 then
            return tonumber(v)
        end
    end
    return 480
end

-- Largura de tela = largura de RENDER (Video.GameWidth). GLOBAL pelo mesmo
-- motivo acima (usada antes desta linha em alguns fluxos).
-- (gameWidth() ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â© nil neste ambiente; motif ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â© design space, nÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o render.)
function f_getScreenWidth()
    if type(gameOption) == "function" then
        local ok, v = pcall(gameOption, "Video.GameWidth")
        if ok and tonumber(v) and tonumber(v) > 0 then
            return tonumber(v)
        end
    end
    return 640
end

-- =====================================================================
-- FIXED TOURNAMENT MODULE REFERENCE SPACE
-- All layout params (columns, pool, brackets, cursors,
-- boxes) are authored in THIS virtual space, never in the
-- screenpack localcoord. The engine scales it to the real screen, so the same
-- numbers hold for any localcoord and any resolution.
-- (Trophy and menu texts do not call SetLocalcoord so they already
--  used the engine default space -- hence they were invariant.)
-- =====================================================================
-- Tournament reference space. GLOBALS (not locals) on purpose: helpers
-- defined above this point (e.g. f_applyCharLocalcoord) also need them,
-- and Lua upvalues only see locals declared BEFORE the function.
TOURNAMENT_REFERENCE_WIDTH  = 1280
TOURNAMENT_REFERENCE_HEIGHT = 720

-- TEST ONLY (giant portraits): portrait scale reference override.
-- 1280 = current (matches HD native); 320 = shrinks every portrait 4x
-- uniformly (relative sizes between chars DO NOT change: global factor).
-- Only the ws divisor uses it (positions stay in 1280 space).
TOURNAMENT_PORTRAIT_REF_W = 320

-- Gets the native motif/screenpack localcoord
local lcX = (motif and motif.info and motif.info.localcoord and motif.info.localcoord[1])
         or (motif and motif.localcoord and motif.localcoord[1]) or 1280
local lcY = (motif and motif.info and motif.info.localcoord and motif.info.localcoord[2])
         or (motif and motif.localcoord and motif.localcoord[2]) or 720

-- Native motif localcoord, used ONLY to return the anims
-- shared ones (select screen cache portraits) to original state.
local motifLocalcoordWidth  = lcX
local motifLocalcoordHeight = lcY

-- =====================================================================
-- KEYCAP SPRITES ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â uses the Keys module (inputhints.lua ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ inputhints.sff)
-- when available; does NOT own the SFF as a primary dependency.
--
-- Intended layout:
--   external/mods/Keys/inputhints.lua   ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â Ãƒâ€šÃ‚Â loads sprInputHints (global)
--   external/mods/Keys/inputhints.sff
--   external/mods/TournamentMode/...    ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â Ãƒâ€šÃ‚Â only consumes sprInputHints
--
-- Resolution order in f_tournamentKeycapSff():
--   1) global sprInputHints (Keys mod already loaded)
--   2) dofile common Keys paths (if sprInputHints still nil)
--   3) sffNew fallback paths (last resort if Keys is missing)
-- Flow layout (f_drawHintSegments) stays in TournamentMode because
-- inputhints.lua draws at absolute (x,y), not inline with measured text.
-- Key names follow inputhints / SDL ids: a-z, RETURN, SPACE, ESCAPE,
-- UP/DOWN/LEFT/RIGHT. Missing SFF => helpers no-op, text hints stay whole.
-- (Globals on purpose: the main chunk operates near the 200 locals limit.)
-- =====================================================================
TOURNAMENT_USE_KEYCAPS = true
-- TOURNAMENT_KEYCAP_SCALE lives at the top ADJUST block (with PADCAP_SCALE).
TOURNAMENT_KEYCAP_TEXT_DX = 0  -- (legacy, unused by PRESS [key] TO labels)
-- Legacy manual gaps kept only for backwards compatibility with old code.
-- All current inline key hints use f_drawHintSegments(), so these are no
-- longer needed for PRESS [KEY] TO ... positioning.
TOURNAMENT_KEYCAP_GAP1 = 4
TOURNAMENT_KEYCAP_GAP2 = 11
TOURNAMENT_KEYCAP_GAP3 = 11
TOURNAMENT_KEYCAP_GAP3_BY_KEY = {}
TOURNAMENT_KEYCAP_GAP2_BY_KEY = {}
TOURNAMENT_KEYCAP_DY = -8  -- LEGACY fallback (usado sÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³ se SIDE/BOTTOM do topo estiverem nil)
TOURNAMENT_KEYCAP_DX = 0  -- keep 0 for flow layout; non-zero desyncs sprite vs text slot
-- Paths only used if Keys mod did not expose sprInputHints.
TOURNAMENT_KEYCAP_SFF_PATHS = {
    "external/mods/Keys/inputhints.sff",
    "external/mods/inputhints.sff",
    "data/inputhints.sff",
}
-- Optional: try to load the Keys Lua if it was not run yet (order-independent).
TOURNAMENT_KEYS_LUA_PATHS = {
    "external/mods/Keys/inputhints.lua",
    "external/mods/Keys/Keys.lua",
    "external/mods/inputhints.lua",  -- fallback: raiz dos mods
}
tournamentKeycapSff = nil
tournamentKeycapTried = false
tournamentKeycapFromKeysMod = false  -- true when handle came from sprInputHints
tournamentKeycapAnimCache = {}  -- "x_0.5" -> anim | false
-- TEMP diagnostic: dumps animGetSpriteInfo shape once per key so we can
-- auto-center sprites on real numbers. Set false (or delete block) after.
TOURNAMENT_KEYCAP_DEBUG_SPRITE = false
tournamentKeycapDebugDone = {}

-- Reads one binding from the native Key Config (Options) for an explicit
-- side (Keys_P1 vs Keys_P2, fields up/down/left/right/a/b/c/x/y/z/start/...).
-- Returns the configured key text (e.g. "q", "KP_9") or nil when
-- unreadable/unbound. Never errors: full fallback to hardcoded button
-- letters at call sites.
-- (Globals on purpose: the main chunk operates near the 200 locals limit.)
function f_getMenuKeyNameSide(cmd, side)
    if type(cmd) ~= "string" or cmd == "" then return nil end
    local pn = math.floor(tonumber(side) or 1)
    if pn < 1 then pn = 1 end
    if type(gameOption) ~= "function" then return nil end
    local cfg = nil
    do
        local ok, t = pcall(gameOption, "Keys_P" .. tostring(pn))
        if ok and type(t) == "table" then cfg = t end
    end
    if cfg == nil and pn ~= 1 then
        local ok, t = pcall(gameOption, "Keys_P1")
        if ok and type(t) == "table" then cfg = t end
    end
    if type(cfg) ~= "table" then return nil end
    local v = cfg[cmd]
    if type(v) ~= "string" or v == "" then return nil end
    if v == "nil" or v == "__UNBIND__" then return nil end
    local nokey = motif and motif.option_info and motif.option_info.menu and motif.option_info.menu.valuename and motif.option_info.menu.valuename.nokey
    if nokey ~= nil and v == tostring(nokey) then return nil end
    return v
end

-- Entrant-side wrapper (the player who opened the tournament menu).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_getMenuKeyName(cmd)
    local pn = 1
    if tournament and tonumber(tournament.enterPlayer) then
        pn = math.floor(tonumber(tournament.enterPlayer))
        if pn < 1 then pn = 1 end
    end
    if type(f_getMenuKeyNameSide) == "function" then
        return f_getMenuKeyNameSide(cmd, pn)
    end
    return nil
end

-- { key, disp, pat, w } for one menu key: sprite id (lower), display text
-- (upper) and inline-hint pattern, all from the player's Key Config with a
-- hardcoded button-letter fallback (e.g. "x" -> "X").
function f_menuKeySpec(cmd, fallback, side)
    local raw = nil
    if side ~= nil and type(f_getMenuKeyNameSide) == "function" then
        raw = f_getMenuKeyNameSide(cmd, side)
    elseif type(f_getMenuKeyName) == "function" then
        raw = f_getMenuKeyName(cmd)
    end
    if type(raw) ~= "string" or raw == "" then raw = tostring(fallback or cmd or "") end
    local disp = string.upper(raw)
    return { key = string.lower(raw), disp = disp, pat = disp .. ":", w = #disp }
end

tournamentDualKeyMemo = tournamentDualKeyMemo or {} -- "enterSide|lowerkey" -> other-side key | false
-- Other side's keyboard key for the same command (1P+2P dual hints).
-- Reverse-maps the entrant physical key -> cmd via Keys_Pn, then reads the
-- other side's binding. nil = single icon (unbound or same key both sides).
-- Memoized (bindings are static mid-tournament; cleared on tournament start).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_dualKeyFor(keyName)
    if type(keyName) ~= "string" or keyName == "" then return nil end
    tournamentDualKeyMemo = tournamentDualKeyMemo or {}
    local entrant = 1
    if type(f_menuSide) == "function" then entrant = tonumber(f_menuSide()) or 1 end
    if entrant ~= 2 then entrant = 1 end
    local other = (entrant == 2) and 1 or 2
    local lk = string.lower(keyName)
    local mk = tostring(entrant) .. "|" .. lk
    local hit = tournamentDualKeyMemo[mk]
    if hit ~= nil then return hit or nil end
    local cmd = nil
    if type(gameOption) == "function" then
        local ok, cfg = pcall(gameOption, "Keys_P" .. tostring(entrant))
        if ok and type(cfg) == "table" then
            for field, val in pairs(cfg) do
                if type(field) == "string" and type(val) == "string" and val ~= ""
                   and string.lower(val) == lk then
                    cmd = field
                    break
                end
            end
        end
    end
    local res = nil
    if cmd ~= nil and type(f_getMenuKeyNameSide) == "function" then
        local ok2, k2 = pcall(f_getMenuKeyNameSide, cmd, other)
        if ok2 and type(k2) == "string" and k2 ~= "" then
            local l2 = string.lower(k2)
            if l2 ~= lk then res = l2 end
        end
    end
    tournamentDualKeyMemo[mk] = res or false
    return res
end

-- Effective second key of a hint segment: explicit seg.key2 (string) wins,
-- seg.key2 == false forces single icon, otherwise auto (other side's key).
function f_dualSegKey2(seg)
    if type(seg) ~= "table" or seg.key == nil then return nil end
    if seg.key2 == false then return nil end
    if type(seg.key2) == "string" and seg.key2 ~= "" then
        return string.lower(seg.key2)
    end
    if type(f_dualKeyFor) == "function" then return f_dualKeyFor(seg.key) end
    return nil
end

-- inputhints group-0 index for a key text id.
-- Reads t_sdlInputConvert (Keys mod) when available, so SFF reindexing
-- flows automatically; legacy hardcoded SDL map only if Keys is missing.
function f_tournamentKeycapNum(keyText)
    if type(keyText) ~= "string" then return nil end
    local t = string.lower(keyText)
    -- Virtual keyboard hyphen cell ("-") -> SDL MINUS (num 45, inputhints.lua).
    if t == "-" or t == "hyphen" then t = "minus" end
    if type(t_sdlInputConvert) == "table" then
        for _, v in ipairs(t_sdlInputConvert) do
            if type(v.text) == "string" and string.lower(v.text) == t then
                return tostring(v.num)
            end
        end
        -- kp_1 -> _1 style rows.
        local kpd = t:match("^kp_(.+)$")
        if kpd then
            for _, v in ipairs(t_sdlInputConvert) do
                if type(v.text) == "string" and string.lower(v.text) == "_" .. kpd then
                    return tostring(v.num)
                end
            end
        end
        -- bare key -> underscore rows ("1" -> "_1", "a" -> "_a").
        for _, v in ipairs(t_sdlInputConvert) do
            if type(v.text) == "string" and string.lower(v.text) == "_" .. t then
                return tostring(v.num)
            end
        end
        return nil
    end
    if #t == 1 and t >= "a" and t <= "z" then
        return tostring(string.byte(t) - 93)
    end
    local special = {
        space = "44", ["return"] = "40", escape = "41",
        backspace = "42", minus = "45",
        up = "82", down = "81", left = "80", right = "79",
    }
    -- Numpad digits (inputhints group-0): KP_1=89 .. KP_9=97, KP_0=98.
    local kpd = t:match("^kp_([0-9])$")
    if kpd then
        local kpmap = { ["1"] = "89", ["2"] = "90", ["3"] = "91", ["4"] = "92", ["5"] = "93", ["6"] = "94", ["7"] = "95", ["8"] = "96", ["9"] = "97", ["0"] = "98" }
        return kpmap[kpd]
    end
    if t == "kp_period" then return "99" end
    return special[t]
end

-- Keycap SFF handle (loaded once; nil when missing).
-- Prefers Keys mod global sprInputHints; only opens the .sff itself as fallback.
function f_tournamentKeycapSff()
    if tournamentKeycapTried then return tournamentKeycapSff end
    tournamentKeycapTried = true

    -- 1) Keys module already loaded ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ reuse its handle (single SFF, one owner)
    if sprInputHints ~= nil then
        tournamentKeycapSff = sprInputHints
        tournamentKeycapFromKeysMod = true
        print("[Tournament] Keycaps: using Keys mod sprInputHints")
        return tournamentKeycapSff
    end

    -- 2) Try to load Keys Lua so it defines sprInputHints (load-order independent)
    if type(TOURNAMENT_KEYS_LUA_PATHS) == "table" then
        for _, p in ipairs(TOURNAMENT_KEYS_LUA_PATHS) do
            local ok = pcall(function()
                if type(dofile) == "function" then dofile(p)
                elseif type(loadfile) == "function" then
                    local chunk = loadfile(p)
                    if chunk then chunk() end
                end
            end)
            if ok and sprInputHints ~= nil then
                tournamentKeycapSff = sprInputHints
                tournamentKeycapFromKeysMod = true
                print("[Tournament] Keycaps: loaded Keys Lua ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ " .. tostring(p))
                return tournamentKeycapSff
            end
        end
    end

    -- 3) Last resort: open the SFF ourselves (Keys missing / path differs)
    if type(TOURNAMENT_KEYCAP_SFF_PATHS) == "table" then
        for _, p in ipairs(TOURNAMENT_KEYCAP_SFF_PATHS) do
            local ok, s = pcall(sffNew, p)
            if ok and s then
                tournamentKeycapSff = s
                tournamentKeycapFromKeysMod = false
                print("[Tournament] Keycaps: fallback sffNew ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ " .. tostring(p))
                break
            end
        end
    end
    if not tournamentKeycapSff then
        print("[Tournament] Keycaps: no SFF (install Keys mod or set TOURNAMENT_KEYCAP_SFF_PATHS)")
    end
    return tournamentKeycapSff
end

-- True when key pictures can draw (switch ON + SFF found).
function f_tournamentKeycapsReady()
    if TOURNAMENT_USE_KEYCAPS == false then return false end
    return f_tournamentKeycapSff() ~= nil
end

-- Draws one key picture at (x, y).
-- refSpace = true draws in tournament reference space (1280x720);
-- default (nil/false) draws in the engine default space, WITHOUT forcing
-- localcoord -- the same space as the hint texts (like inputhints, which
-- never calls animSetLocalcoord). Forcing 1280 numbers onto motif-space
-- labels is what threw pictures to the top-left corner.
-- Returns false (draws nothing) when unavailable: caller keeps full text.
-- (Space is part of the cache key: each cached anim keeps its birth space.)
function f_drawTournamentKeycap(keyText, x, y, scaleOverride, refSpace, dyOverride)
    if not f_tournamentKeycapsReady() then return false end
    local num = nil
    if type(f_tournamentKeycapNum) == "function" then
        num = f_tournamentKeycapNum(keyText)
    end
    if not num then return false end
    local sff = f_tournamentKeycapSff()
    if not sff then return false end
    local sc = tonumber(scaleOverride) or tonumber(TOURNAMENT_KEYCAP_SCALE) or 1.0
    local scaleOn = (TOURNAMENT_KEYCAP_SCALE_ENABLED ~= false)
    local kbGroup = 0
    if type(f_keycapGroupOffset) == "function" then
        kbGroup = tonumber(f_keycapGroupOffset()) or 0
    end
    local ck = tostring(keyText) .. "_" .. tostring(sc) .. "_" .. ((refSpace and "ref") or "motif") .. "_" .. (scaleOn and "s" or "n") .. "_g" .. tostring(kbGroup)
    local anim = tournamentKeycapAnimCache[ck]
    if anim == nil then
        local ok, a = pcall(animNew, sff, tostring(kbGroup) .. "," .. tostring(num) .. ", 0,0, -1")
        if ok and a and type(a) == "userdata" then
            anim = a
        else
            anim = false
        end
        tournamentKeycapAnimCache[ck] = anim
    end
    if not anim then return false end
    if TOURNAMENT_KEYCAP_DEBUG_SPRITE and not tournamentKeycapDebugDone[ck] then
        tournamentKeycapDebugDone[ck] = true
        if type(animGetSpriteInfo) == "function" then
            local ok, info = pcall(animGetSpriteInfo, anim)
            print("[Tournament][KeycapDbg] key=" .. tostring(ck) .. " ok=" .. tostring(ok) .. " type=" .. type(info))
            if ok and type(info) == "table" then
                for k, v in pairs(info) do
                    print("[Tournament][KeycapDbg]   " .. tostring(k) .. " = " .. tostring(v) .. " (" .. type(v) .. ")")
                    if type(v) == "table" then
                        for k2, v2 in pairs(v) do
                            print("[Tournament][KeycapDbg]     " .. tostring(k2) .. " = " .. tostring(v2))
                        end
                    end
                end
            end
        else
            print("[Tournament][KeycapDbg] animGetSpriteInfo MISSING")
        end
    end
    if refSpace and type(animSetLocalcoord) == "function" then
        animSetLocalcoord(anim, TOURNAMENT_REFERENCE_WIDTH, TOURNAMENT_REFERENCE_HEIGHT)
    end
    if scaleOn and animSetScale then animSetScale(anim, sc, sc) end
    local dyFinal = tonumber(dyOverride)
    if dyFinal == nil then dyFinal = tonumber(TOURNAMENT_KEYCAP_DY) or 0 end
    if animSetPos then animSetPos(anim, x + (tonumber(TOURNAMENT_KEYCAP_DX) or 0), y + dyFinal) end
    if animUpdate then animUpdate(anim) end
    pcall(animDraw, anim)
    return true
end

-- Renderer helpers above still use the keycap cache.

-- =====================================================================
-- INLINE HINTS (bottom hint lines with key pictures instead of letters)
-- Preferred API: f_drawHintSegments(txtObj, segments, cx, cy [, origAlign])
--   segments = { {text="..."}, {key="x"}, {text=": DEFAULT  "}, ... }
--   Each {key=} is drawn exactly at that point in the flow ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â no manual
--   pixel offsets between the 1st and 2nd key.
-- Legacy API: f_drawHintWithKeys(txtObj, fullText, keys, cx, cy) still
--   works (parses patterns ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ segments ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ same drawer).
-- MEASURE_SCALE defaults to the hint text scale (0.21). textImgGetTextWidth
--   in many builds returns unscaled glyph width; multiply by the draw scale
--   so totalW matches what actually appears on screen.
-- (Globals on purpose: the main chunk operates near the 200 locals limit.)
-- =====================================================================
-- On-screen keyboard: false for cells with no drawable sprite (missing
-- keycap), so the cursor skips them. SPACE/DEL resolve like other keys.
-- (Global: used by both typing screens.)
function kbCellDrawable(cell)
    if cell == nil or cell == "" then return false end
    local key = cell
    if key == "SPACE" then key = "space" end
    if key == "DEL" then key = "backspace" end
    if type(f_tournamentKeycapNum) ~= "function" then return true end
    return f_tournamentKeycapNum(key) ~= nil
end
-- Keycap scale basis for custom grids (mirrors f_drawHintSegments' kbScale:
-- SFF px -> Lua units; keep in sync if that formula changes).
-- (Global: called from prompt screens.)
function f_hintKbScale()
    local screenH = nil
    local forced = tonumber(TOURNAMENT_SCREEN_H)
    if forced ~= nil and forced > 0 then screenH = forced end
    if screenH == nil and type(gameOption) == "function" then
        local ok, v = pcall(gameOption, "Video.GameHeight")
        if ok and tonumber(v) and tonumber(v) > 0 then screenH = tonumber(v) end
    end
    screenH = screenH or 480
    local ratioH = screenH
    if TOURNAMENT_KEYCAP_FOLLOW_RESOLUTION ~= false and screenH > 480 then
        ratioH = tonumber(TOURNAMENT_REFERENCE_HEIGHT) or 720
    end
    return (240 / ratioH) * (tonumber(TOURNAMENT_KEYCAP_SCALE) or 1)
end
TOURNAMENT_HINT_KEYCAP_WIDTH = 8  -- LEGADO: slots agora seguem o desenho (nativo ÃƒÆ’Ã†--  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â ratio ÃƒÆ’Ã†--  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â VAR)
-- Default 0.21 = MENU_CONFIG.hint.scaleX. If the line is too short, raise;
-- if it overflows the screen, lower. Nil ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ falls back to hint scale or 0.21.
TOURNAMENT_HINT_MEASURE_SCALE = 0.21 --0.21
TOURNAMENT_HINT_KEY_DX = {}  -- optional per-key nudge by sprite id (lowercase);
-- numeric ids nudge word icons the same way (e.g. { [5] = 4 })
TOURNAMENT_HINT_SPRITE_DY = 2  -- LEGACY fallback (somado ao KEYCAP_DY sÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³ se SIDE/BOTTOM do topo estiverem nil)

-- =====================================================================
-- GAMEPAD ICONS (dual hints: teclado + joystick lado a lado, sempre)
-- Pad bindings vÃƒÆ’Ã†--  Ãƒâ€šÃ‚Âªm do Joystick_Pn (mesmo side do Keys_Pn via f_menuSide);
-- valores sÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o os button ids gravados pelo getJoystickKey.
-- Fallback quando ilegÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­vel/desbindado: TOURNAMENT_PAD_DEFAULTS (ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­ndices
-- dos sprites do grupo 1 do inputhints.sff). Ids fora de 0..15 e nomes
-- resolvem via t_xboxInputConvert (mod Keys); id desconhecido nÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o
-- desenha nada (nunca um ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­cone errado).
-- (Globals on purpose: the main chunk operates near the 200 locals limit.)
-- =====================================================================
TOURNAMENT_PAD_DEFAULTS = {
    up = "7", down = "4", left = "5", right = "6",
    a = "0", b = "1", x = "2", y = "3",
    start = "12", menu = "13",
}
-- Option fields na ordem do engine (options.lua setKeyConfig).
TOURNAMENT_PAD_CMDS = { "up", "down", "left", "right", "a", "b", "c", "x", "y", "z", "start", "d", "w", "menu" }
tournamentPadKbCache = {} -- "side:kbkey" -> padId (string) | false
tournamentPadAnimCache = {} -- "num_scale" -> anim | false

-- Reads one binding from the Joystick Config (Options) for an explicit side.
-- Mirror of f_getMenuKeyNameSide, but accepts number or text.
-- (Global: the main chunk operates near the 200 locals limit.)
function f_getPadKeyNameSide(cmd, side)
    if type(cmd) ~= "string" or cmd == "" then return nil end
    local pn = math.floor(tonumber(side) or 1)
    if pn < 1 then pn = 1 end
    if type(gameOption) ~= "function" then return nil end
    local cfg = nil
    do
        local ok, t = pcall(gameOption, "Joystick_P" .. tostring(pn))
        if ok and type(t) == "table" then cfg = t end
    end
    if cfg == nil and pn ~= 1 then
        local ok, t = pcall(gameOption, "Joystick_P1")
        if ok and type(t) == "table" then cfg = t end
    end
    if type(cfg) ~= "table" then return nil end
    local v = cfg[cmd]
    if type(v) ~= "string" and type(v) ~= "number" then return nil end
    v = tostring(v)
    if v == "" then return nil end
    if v == "nil" or v == "__UNBIND__" then return nil end
    local nokey = motif and motif.option_info and motif.option_info.menu and motif.option_info.menu.valuename and motif.option_info.menu.valuename.nokey
    if nokey ~= nil and v == tostring(nokey) then return nil end
    return v
end

-- LÃƒÆ’Ã†--  Ãƒâ€šÃ‚Âª um binding do Joystick Config (Options) do entrant side.
-- Espelho do f_getMenuKeyName, mas aceita nÃƒÆ’Ã†--  Ãƒâ€šÃ‚Âºmero ou texto.
-- (Global: the main chunk operates near the 200 locals limit.)
function f_getPadKeyName(cmd)
    local pn = 1
    if tournament and tonumber(tournament.enterPlayer) then
        pn = math.floor(tonumber(tournament.enterPlayer))
        if pn < 1 then pn = 1 end
    end
    if type(f_getPadKeyNameSide) == "function" then
        return f_getPadKeyNameSide(cmd, pn)
    end
    return nil
end

-- Resolve um pad id para o ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­ndice do sprite no grupo 1 (ou nil).
-- Aceita '0'..'13' ou nomes ('A', 'LB'...).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_tournamentPadNum(padId)
    if padId == nil then return nil end
    local k = tostring(padId)
    if k == "" then return nil end
    if k:match("^%d+$") then
        local n = tonumber(k)
        if n ~= nil and n >= 0 and n <= 15 then return tostring(n) end
        return nil
    end
    local kl = string.lower(k)
    -- SDL/common aliases -> canonical table text (BACK = MENU button,
    -- DP_U = D-pad up, shoulders/triggers by full name, ...).
    local aliases = {
        dp_u = "up", dpup = "up",
        dp_d = "down", dpdown = "down",
        dp_l = "left", dpleft = "left",
        dp_r = "right", dpright = "right",
        back = "menu", select = "menu",
        leftshoulder = "lb", rightshoulder = "rb",
        lefttrigger = "lt", righttrigger = "rt",
        leftstick = "l3", rightstick = "r3",
    }
    local want = { kl }
    if aliases[kl] ~= nil then want[#want + 1] = aliases[kl] end
    if type(t_xboxInputConvert) == "table" then
        for _, w in ipairs(want) do
            for _, v in ipairs(t_xboxInputConvert) do
                if type(v) == "table" and type(v.text) == "string" and v.num ~= nil then
                    if string.lower(v.text) == w then return tostring(v.num) end
                end
            end
        end
    else
        local names = { a = "0", b = "1", x = "2", y = "3", down = "4", left = "5", right = "6", up = "7", lb = "8", lt = "9", rb = "10", rt = "11", start = "12", menu = "13" }
        for _, w in ipairs(want) do
            if names[w] ~= nil then return names[w] end
        end
    end
    return nil
end

-- Acha o botÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o do joystick gÃƒÆ’Ã†--  Ãƒâ€šÃ‚Âªmeo de uma key do teclado (lowercase).
-- Literais das setas resolvem pelo prÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³prio campo; "escape" usa o botÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o
-- MENU (ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â© ele que volta junto com B/ESC no cancelEdge); resto por
-- reverse-lookup do Keys_Pn. Sem par -> nil (sÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³ teclado).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_autoPadId(kbKey)
    if type(kbKey) ~= "string" or kbKey == "" then return nil end
    local side = 1
    if type(f_menuSide) == "function" then
        local s = tonumber(f_menuSide())
        if s ~= nil and s >= 1 then side = math.floor(s) end
    end
    local low = string.lower(kbKey)
    local ck = tostring(side) .. ":" .. low
    local cached = tournamentPadKbCache[ck]
    if cached ~= nil then
        if cached == false then return nil end
        return cached
    end
    local padId = nil
    if low == "escape" then
        if type(f_getPadKeyName) == "function" then padId = f_getPadKeyName("menu") end
        if padId == nil and type(TOURNAMENT_PAD_DEFAULTS) == "table" then padId = TOURNAMENT_PAD_DEFAULTS["menu"] end
    else
        if type(f_getMenuKeyName) == "function" and type(f_getPadKeyName) == "function" then
            for _, cmd in ipairs(TOURNAMENT_PAD_CMDS) do
                local kb = f_getMenuKeyName(cmd)
                if type(kb) == "string" and string.lower(kb) == low then
                    padId = f_getPadKeyName(cmd)
                    break
                end
            end
        end
        if padId == nil and type(TOURNAMENT_PAD_DEFAULTS) == "table" then
            padId = TOURNAMENT_PAD_DEFAULTS[low]
        end
    end
    if padId == nil then
        tournamentPadKbCache[ck] = false
        return nil
    end
    padId = tostring(padId)
    tournamentPadKbCache[ck] = padId
    return padId
end

-- Desenha um ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­cone do joystick (grupo 1) em (x, y). Espelho do
-- f_drawTournamentKeycap com escala prÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³pria (TOURNAMENT_PADCAP_SCALE).
-- Retorna false (desenha nada) quando indisponÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­vel.
-- (Global: the main chunk operates near the 200 locals limit.)
-- Joystick icon set: 1 = Xbox, 2 = PlayStation (Misc Settings first item).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_padIconGroup()
    if tournament and tostring(tournament.padIcons or ""):lower() == "playstation" then return 2 end
    return 1
end

-- SFF group offset for the SD icon sets (groups 10/11/12 instead of 0/1/2).
-- Same indices; screenMode comes from f_applyLayoutMode (SD = height 480).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_keycapGroupOffset()
    if tournament and tostring(tournament.screenMode or ""):upper() == "SD" then return 10 end
    return 0
end

function f_drawTournamentPadCap(padId, x, y, scaleOverride, dyOverride)
    if type(f_tournamentKeycapsReady) == "function" then
        if not f_tournamentKeycapsReady() then return false end
    elseif sprInputHints == nil then
        return false
    end
    local num = nil
    if type(f_tournamentPadNum) == "function" then
        num = f_tournamentPadNum(padId)
    end
    if not num then return false end
    local sff = nil
    if type(f_tournamentKeycapSff) == "function" then
        sff = f_tournamentKeycapSff()
    end
    if not sff then return false end
    local sc = tonumber(scaleOverride) or tonumber(TOURNAMENT_PADCAP_SCALE) or 1.0
    local padGroup = 1
    if type(f_padIconGroup) == "function" then
        local g = tonumber(f_padIconGroup())
        if g == 1 or g == 2 then padGroup = g end
    end
    -- SD icon sets (groups 11/12 instead of 1/2).
    if type(f_keycapGroupOffset) == "function" then
        padGroup = padGroup + (tonumber(f_keycapGroupOffset()) or 0)
    end
    local ck = "pad_g" .. tostring(padGroup) .. "_" .. tostring(num) .. "_" .. tostring(sc) .. "_" .. ((TOURNAMENT_KEYCAP_SCALE_ENABLED ~= false) and "s" or "n")
    local anim = tournamentPadAnimCache[ck]
    if anim == nil then
        local ok, a = pcall(animNew, sff, tostring(padGroup) .. "," .. tostring(num) .. ", 0,0, -1")
        if ok and a and type(a) == "userdata" then
            anim = a
        else
            anim = false
        end
        tournamentPadAnimCache[ck] = anim
    end
    if not anim then return false end
    if TOURNAMENT_KEYCAP_SCALE_ENABLED ~= false and animSetScale then animSetScale(anim, sc, sc) end
    local dyFinal = tonumber(dyOverride)
    if dyFinal == nil then dyFinal = tonumber(TOURNAMENT_KEYCAP_DY) or 0 end
    if animSetPos then animSetPos(anim, x + (tonumber(TOURNAMENT_KEYCAP_DX) or 0), y + dyFinal) end
    if animUpdate then animUpdate(anim) end
    pcall(animDraw, anim)
    return true
end

-- (Debug temporÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â¡rio do pad removido apÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³s o diagnÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³stico.)

-- Poll fÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­sico de um botÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o do joystick (via getJoystickKey), comparado
-- com o binding do Joystick_Pn (ex. "menu", "up", "a").
-- Motivo: main.t_cmd ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â© nil nos menus Lua do torneio, entÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o os
-- commandGetState nÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o enxergam o controle; as setas sÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³ tinham esse
-- caminho + teclado, e a aÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o MENU nÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o tem comando algum. Edge jÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â¡
-- tratado pelos makeEdge dos chamadores.
-- (Global: the main chunk operates near the 200 locals limit.)
function f_joystickCmdDown(cmd)
    if cmd == nil then cmd = "menu" end
    if type(cmd) ~= "string" or cmd == "" then return false end
    if type(getJoystickKey) ~= "function" then return false end
    if type(gameOption) ~= "function" then return false end
    -- Either side's stick (same sprite for both; bindings may differ).
    for _, side in ipairs({1, 2}) do
        local joyIdx = nil
        local ok, v = pcall(gameOption, "Joystick_P" .. tostring(side) .. ".Joystick")
        if ok then joyIdx = tonumber(v) end
        if joyIdx ~= nil and joyIdx >= 0 then
            local bound = nil
            if type(f_getPadKeyNameSide) == "function" then bound = f_getPadKeyNameSide(cmd, side) end
            if bound ~= nil then
                local okJ, pressed = pcall(getJoystickKey, joyIdx)
                if okJ and pressed ~= nil and tostring(pressed) ~= ""
                   and tostring(pressed) == tostring(bound) then
                    return true
                end
            end
        end
    end
    return false
end

-- Measures one text segment's on-screen width (scale-aware).
local function f_hintMeasureTextWidth(txtObj, text)
    if type(text) ~= "string" or text == "" then return 0 end
    textImgSetText(txtObj, text)
    local w = nil
    if type(textImgGetTextWidth) == "function" then
        local ok, v = pcall(textImgGetTextWidth, txtObj, text)
        if ok then w = tonumber(v) end
        if not w then
            ok, v = pcall(textImgGetTextWidth, txtObj)
            if ok then w = tonumber(v) end
        end
    end
    w = w or 0
    local ms = tonumber(TOURNAMENT_HINT_MEASURE_SCALE)
    if not ms then
        ms = (MENU_CONFIG and MENU_CONFIG.hint and tonumber(MENU_CONFIG.hint.scaleX)) or 0.21
    end
    return w * ms
end

-- WORD ICONS (TournamentMode.sff group 7 = HD, 8 = SD, same indices).
-- Sprites replacing hint/menu words: 0 SLOT, 1 ALL, 2 MISC, 3 SETTINGS,
-- 4 ERASE, 5 PREVIEW, 6 PLAYSTATION, 7 DEFAULT SETTINGS, 8 ADJUST, 9 SAVE,
-- 10 OFF, 11 ON, 12 TOGGLE, 13 XBOX. Group rides the resolution, so no
-- cache invalidation on HD/SD switch.
-- (Globals on purpose: the main chunk operates near the 200 locals limit.)
tournamentWordIconCache = {}
tournamentWordIconMissDbg = {}  -- "g_idx" -> true (1 MISSING line each)
function f_wordIconGroup()
    if tournament and tostring(tournament.screenMode or ""):upper() == "SD" then
        return tonumber(TOURNAMENT_WORDICON_GROUP_SD) or 8
    end
    return tonumber(TOURNAMENT_WORDICON_GROUP_HD) or 7
end
function f_getWordIconAnim(idx)
    idx = tonumber(idx)
    if idx == nil then return nil end
    local g = 7
    if type(f_wordIconGroup) == "function" then g = f_wordIconGroup() end
    local ck = tostring(g) .. "_" .. tostring(idx)
    local c = tournamentWordIconCache[ck]
    if c ~= nil then return c or nil end
    local sff = nil
    if type(f_loadTournamentSff) == "function" then
        local ok, s = pcall(f_loadTournamentSff)
        if ok then sff = s end
    end
    if sff == nil or type(animNew) ~= "function" then
        tournamentWordIconCache[ck] = false
        if not tournamentWordIconMissDbg[ck] then
            tournamentWordIconMissDbg[ck] = true
            print("[Tournament][WordIcon] MISSING group=" .. tostring(g) .. " idx=" .. tostring(idx) .. " (sff/animNew)")
        end
        return nil
    end
    local ok, anim = pcall(animNew, sff, tostring(g) .. "," .. tostring(idx) .. ", 0,0, -1")
    if ok and anim and type(anim) == "userdata" then
        tournamentWordIconCache[ck] = anim
        return anim
    end
    tournamentWordIconCache[ck] = false
    if not tournamentWordIconMissDbg[ck] then
        tournamentWordIconMissDbg[ck] = true
        print("[Tournament][WordIcon] MISSING group=" .. tostring(g) .. " idx=" .. tostring(idx) .. " (no sprite)")
    end
    return nil
end
-- Slot width in drawer units: icon native px (28 HD / 18 SD) ÃƒÆ’Ã†--  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â keycap basis.
-- (Basis is kbScale itself ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â NOT kbSlotW/28, which bakes buttonspace in and
-- shrank SD icons to 64%. Scale below uses the same kbScale as the keys.)
function f_wordIconSlotW(idx, scaleBasis)
    local px = tonumber(TOURNAMENT_WORDICON_PX_HD) or 28
    if tournament and tostring(tournament.screenMode or ""):upper() == "SD" then
        px = tonumber(TOURNAMENT_WORDICON_PX_SD) or 18
    end
    return px * (tonumber(scaleBasis) or 0)
end
function f_drawWordIcon(idx, x, y, scaleBasis, dy)
    local anim = nil
    if type(f_getWordIconAnim) == "function" then anim = f_getWordIconAnim(idx) end
    if anim == nil then return false end
    -- Engine default space, WITHOUT forcing localcoord: exactly like the
    -- keycaps (forcing 1280x720 here drew a different apparent scale).
    -- Scale = keycap basis ÃƒÆ’Ã†--  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â WORDICON_SCALE (byte-identical to the keys).
    local sc = (tonumber(scaleBasis) or 0) * (tonumber(TOURNAMENT_WORDICON_SCALE) or 1)
    if animSetScale then animSetScale(anim, sc, sc) end
    if animSetPos then animSetPos(anim, (tonumber(x) or 0),
        (tonumber(y) or 0) + (tonumber(dy) or 0) + (tonumber(TOURNAMENT_WORDICON_DY) or 0)) end
    if animUpdate then animUpdate(anim) end
    if animDraw then animDraw(anim) end
    return true
end
-- Menu value overriden by a word icon, or nil (draw text normally).
function f_menuValueIconIdx(label, vtext)
    if vtext == "ON" then return 11 end
    if vtext == "OFF" then return 10 end
    if vtext == "YES" then return 11 end
    if vtext == "NO" then return 10 end
    if vtext == "Xbox" then return 13 end
    if vtext == "Playstation" then return 6 end
    return nil
end
-- Menu row value: word icon (single segment, left-anchored at the value
-- slot) or plain text when the value has no icon mapping.
function f_drawMenuValueIconOrText(txtObj, it, vtext, vx, vy)
    local vi = nil
    if type(f_menuValueIconIdx) == "function" then
        vi = f_menuValueIconIdx(it and it.label, vtext)
    end
    if vi ~= nil then
        f_drawHintSegments(txtObj, {{icon = vi}}, vx, vy, 1)
        -- Drawer leaves align=1, same as the value preset; restore anyway so
        -- a future preset change can't strand later text draws shifted.
        textImgSetAlign(txtObj, 1)
    else
        textImgDraw(txtObj)
    end
end

-- Core drawer: explicit segments. Each {key="x"} is already the slot.
-- segments: list of { text = "..." } and/or { key = "x" } (lowercase sprite id).
--   { key } draws keyboard icon + joystick twin side by side (auto via
--   Joystick_Pn, same Y); { key, pad = "3" } forces the pad id;
--   { key, pad = false } draws keyboard only.
-- origAlign = 0 centers the complete hint around cx; origAlign = -1 uses cx
-- as the left edge, so inline hints can start exactly at a chosen position.
function f_drawHintSegments(txtObj, segments, cx, cy, origAlign)
    if txtObj == nil or type(segments) ~= "table" then return end
    if #segments == 0 then return end

    local align = tonumber(origAlign) or 0

    if not f_tournamentKeycapsReady() then
        -- Flatten to plain text fallback. In this helper, origAlign = -1
        -- means LEFT-anchored inline text (not the engine's native -1/right
        -- alignment). Native convention throughout: 0=center, 1=left, -1=right.
        local buf = {}
        for _, seg in ipairs(segments) do
            if seg.text then buf[#buf + 1] = seg.text
            elseif seg.icon ~= nil then
                local fb = nil
                if type(TOURNAMENT_WORDICON_FALLBACK) == "table" then
                    fb = TOURNAMENT_WORDICON_FALLBACK[tonumber(seg.icon)]
                end
                buf[#buf + 1] = tostring(fb or "")
            elseif seg.key then
                buf[#buf + 1] = string.upper(tostring(seg.key))
                local k2fb = nil
                if type(f_dualSegKey2) == "function" then k2fb = f_dualSegKey2(seg) end
                if k2fb ~= nil then buf[#buf + 1] = "/" .. string.upper(tostring(k2fb)) end
            end
        end
        local full = table.concat(buf)
        local drawAlign = align -- native convention (0=center, 1=left, -1=right)
        textImgSetAlign(txtObj, drawAlign)
        textImgSetText(txtObj, full)
        textImgSetPos(txtObj, cx, cy)
        textImgDraw(txtObj)
        return
    end

    local widths, totalW, padIds, key2s = {}, 0, {}, {}
    -- Extra advance between segments (TOURNAMENT_HINT_SEG_GAP, negative
    -- tightens word<->key). Applied between (never after the last), in both
    -- measure and draw, so centering stays exact.
    local segGap = tonumber(TOURNAMENT_HINT_SEG_GAP) or 0
    -- Slots acompanham o desenho: nativo do sprite ÃƒÆ’Ã†--  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â (240/telaH) ÃƒÆ’Ã†--  ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â VAR.
    -- 1.0 nas escalas = pixels exatos do SFF em qualquer resoluÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o.
    -- (espaÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â§o Lua tem altura fixa ~240 e escala uniforme pela altura;
    -- denominador = altura de RENDER: override > Video.GameHeight > 480.
    -- gameHeight() ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â© ignorado de propÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³sito: devolveu 319 com render 480.)
    local screenH = nil
    do
        local forced = tonumber(TOURNAMENT_SCREEN_H)
        if forced ~= nil and forced > 0 then screenH = forced end
    end
    local goVal = nil
    if screenH == nil and type(gameOption) == "function" then
        local ok, v = pcall(gameOption, "Video.GameHeight")
        if ok and tonumber(v) then goVal = tonumber(v) end
        if goVal and goVal > 0 then screenH = goVal end
    end
    screenH = screenH or 480
    -- spaceRatio compensates the Lua space (fixed ~240 high, scaled by render
    -- height). Dividing by the REAL height pins keys to exact SFF pixels (they
    -- never grow). HD: divide by the reference height instead, so keys scale
    -- with the screen exactly like text, flags and portraits. SD (480) keeps
    -- its own 1:1 sprite set (groups 10/11/12).
    local ratioH = screenH
    if TOURNAMENT_KEYCAP_FOLLOW_RESOLUTION ~= false and screenH > 480 then
        ratioH = tonumber(TOURNAMENT_REFERENCE_HEIGHT) or 720
    end
    local spaceRatio = 240 / ratioH
    -- TEMP DEBUG (ver console): imprime 1x por combinaÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o de valores.
    do
        local dbgKey = tostring(screenH) .. "|" .. tostring(TOURNAMENT_SCREEN_H)
            .. "|" .. tostring(goVal) .. "|" .. tostring(TOURNAMENT_KEYCAP_SCALE)
            .. "|" .. tostring(TOURNAMENT_PADCAP_SCALE)
        if dbgKey ~= tournamentSpaceRatioDbgLast then
            tournamentSpaceRatioDbgLast = dbgKey
            print(string.format("[Tournament][ratio] screenH=%s forced=%s gameOption=%s spaceRatio=%.4f kbScale=%.4f padScale=%.4f",
                tostring(screenH), tostring(TOURNAMENT_SCREEN_H), tostring(goVal),
                tonumber(spaceRatio) or 0,
                tonumber(spaceRatio) * (tonumber(TOURNAMENT_KEYCAP_SCALE) or 1),
                tonumber(spaceRatio) * (tonumber(TOURNAMENT_PADCAP_SCALE) or 1)))
        end
    end -- spaceRatio 480: 0.5 / spaceRatio 720: 0.3333
    local kbScale = spaceRatio * (tonumber(TOURNAMENT_KEYCAP_SCALE) or 1)
    local padScale = spaceRatio * (tonumber(TOURNAMENT_PADCAP_SCALE) or 1)
    -- Tamanho nativo via espelho global (o `local layout` nasce depois desta funÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â§ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o).
    local nativeSize = tonumber(TOURNAMENT_HINT_NATIVE) or 28
    local kbSlotW, padSlotW = nativeSize * kbScale, nativeSize * padScale
    if TOURNAMENT_KEYCAP_SCALE_ENABLED == false then
        kbSlotW, padSlotW = nativeSize, nativeSize
    end
    for i, seg in ipairs(segments) do
        local w = 0
        if seg.text and seg.text ~= "" then
            w = f_hintMeasureTextWidth(txtObj, seg.text)
        elseif seg.icon ~= nil then
            -- Word icon (TournamentMode.sff 7/8): native-px slot on the
            -- keycap basis (NOT kbSlotW: that bakes buttonspace in).
            w = kbSlotW
            if type(f_wordIconSlotW) == "function" then
                w = f_wordIconSlotW(seg.icon, kbScale) or w
            end
        elseif seg.key then
            w = kbSlotW
            -- Second keyboard key (1P+2P): reserves its own slot + gap.
            local k2 = nil
            if type(f_dualSegKey2) == "function" then k2 = f_dualSegKey2(seg) end
            if type(k2) == "string" and k2 ~= "" and k2 ~= string.lower(tostring(seg.key)) then
                local dgap = tonumber(TOURNAMENT_HINT_DUALKEY_GAP)
                if dgap == nil then dgap = 4 end
                if dgap < 0 then dgap = 0 end
                w = w + dgap + kbSlotW
                key2s[i] = k2
            end
            -- Dual icon: reserva o slot do joystick + gap quando houver par.
            local padId = nil
            if seg.pad == false then
                padId = nil
            elseif seg.pad ~= nil then
                padId = tostring(seg.pad)
            elseif type(f_autoPadId) == "function" then
                padId = f_autoPadId(seg.key)
            end
            -- SÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³ reserva o slot se o id vira sprite (fora de 0..15 ou
            -- nome desconhecido = sÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³ teclado, sem buraco vazio).
            if padId ~= nil and type(f_tournamentPadNum) == "function" then
                if f_tournamentPadNum(padId) == nil then padId = nil end
            end
            if padId ~= nil then
                local gap = tonumber(TOURNAMENT_HINT_PAD_GAP) or 0
                if gap < 0 then gap = 0 end
                w = w + gap + padSlotW
                padIds[i] = padId
            end
        elseif seg.pad ~= nil then
            -- Pad icon alone (no keyboard): reserves the pad slot when the
            -- id resolves to a sprite (same rule as auto twins).
            w = 0
            local padOk = true
            if type(f_tournamentPadNum) == "function" then
                padOk = (f_tournamentPadNum(seg.pad) ~= nil)
            end
            if padOk then w = padSlotW end
        end
        widths[i] = w
        totalW = totalW + w
        if i < #segments then totalW = totalW + segGap end
    end

    -- IMPORTANT: Ikemen GO's native alignment is: 0 = center,
    -- negative = RIGHT, positive = LEFT. This helper mirrors it for the
    -- composed hint: origAlign 0 centers it on cx, 1 anchors its LEFT
    -- edge at cx, -1 anchors its RIGHT edge at cx.
    -- Every individual text segment MUST still be drawn with native
    -- align = 1 (left). Using native -1 here makes each segment end at x
    -- instead of starting at x, which causes exactly the overlap seen
    -- when a keycap is inserted between words.
    textImgSetAlign(txtObj, 1)
    local x = (tonumber(cx) or 0)
    if align == 0 then x = x - totalW / 2
    elseif align < 0 then x = x - totalW end
    local y = tonumber(cy) or 0
    -- Icon/keycap lane Y (loop-invariant): align ~= 0 = side labels,
    -- align 0 = bottom hints. Word icons ride the same lane as keycaps.
    local dyUse = nil
    if align ~= 0 then
        dyUse = tonumber(TOURNAMENT_KEYCAP_DY_SIDE)
    else
        dyUse = tonumber(TOURNAMENT_KEYCAP_DY_BOTTOM)
    end
    if dyUse == nil then
        dyUse = (tonumber(TOURNAMENT_KEYCAP_DY) or 0) + (tonumber(TOURNAMENT_HINT_SPRITE_DY) or 0)
    end
    for i, seg in ipairs(segments) do
        if seg.text and seg.text ~= "" then
            textImgSetText(txtObj, seg.text)
            textImgSetPos(txtObj, x, y)
            textImgDraw(txtObj)
        elseif seg.icon ~= nil then
            -- Per-icon X nudge (same table as the keys, numeric ids, e.g.
            -- TOURNAMENT_HINT_KEY_DX = { [5] = 4 }). Slot/width unchanged,
            -- like the keycap dx.
            local dxI = 0
            if type(TOURNAMENT_HINT_KEY_DX) == "table" then
                dxI = tonumber(TOURNAMENT_HINT_KEY_DX[tonumber(seg.icon)]) or 0
            end
            if type(f_drawWordIcon) == "function" then
                f_drawWordIcon(seg.icon, x + dxI, y, kbScale, dyUse)
            end
        elseif seg.key then
            local dx = 0
            if type(TOURNAMENT_HINT_KEY_DX) == "table" then
                dx = tonumber(TOURNAMENT_HINT_KEY_DX[seg.key]) or 0
            end
            -- Slot left edge (NOT center): keycap axis is top-left, and the
            -- slot already reserves KEYCAP_WIDTH for it. Center-drawing here
            -- pushes every sprite half its width right, into the next text.
            -- Y lane: dyUse hoisted above the loop (side vs bottom).
            f_drawTournamentKeycap(seg.key, x + dx, y, kbScale, nil, dyUse)
            -- Second keyboard key (2P): own slot right after the first.
            local padX = x + dx + kbSlotW
            local k2 = key2s[i]
            if k2 ~= nil then
                local dgap = tonumber(TOURNAMENT_HINT_DUALKEY_GAP)
                if dgap == nil then dgap = 4 end
                if dgap < 0 then dgap = 0 end
                local dx2 = dx
                if type(TOURNAMENT_HINT_KEY_DX) == "table" then
                    dx2 = tonumber(TOURNAMENT_HINT_KEY_DX[k2]) or dx
                end
                f_drawTournamentKeycap(k2, x + dx2 + kbSlotW + dgap, y, kbScale, nil, dyUse)
                padX = x + dx2 + kbSlotW + dgap + kbSlotW
            end
            -- Joystick twin: mesmo Y (+ nudge prÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³prio), slot prÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â³prio + gap (sem "/" no meio).
            local padId = padIds[i]
            if padId ~= nil and type(f_drawTournamentPadCap) == "function" then
                local gap = tonumber(TOURNAMENT_HINT_PAD_GAP) or 0
                if gap < 0 then gap = 0 end
                local padDy = dyUse + (tonumber(TOURNAMENT_PADCAP_DY) or 0)
                f_drawTournamentPadCap(padId, padX + gap, y, padScale, padDy)
            end
        elseif seg.pad ~= nil then
            local showPad = true
            if type(f_tournamentPadNum) == "function" then
                showPad = (f_tournamentPadNum(seg.pad) ~= nil)
            end
            if showPad and type(f_drawTournamentPadCap) == "function" then
                local padDySolo = dyUse + (tonumber(TOURNAMENT_PADCAP_DY) or 0)
                f_drawTournamentPadCap(seg.pad, x, y, padScale, padDySolo)
            end
        end
        x = x + widths[i]
        if i < #segments then x = x + segGap end
    end
    textImgSetAlign(txtObj, align)
    textImgSetText(txtObj, "")  -- kill trailing textImgDraw(txtObj) in callers
end

-- Legacy: fullText + pattern keys ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ segments ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ f_drawHintSegments.
-- keys: { {key="x", pat="X:", at=1, w=1, span=nil}, ... }
function f_drawHintWithKeys(txtObj, fullText, keys, cx, cy, origAlign)
    if txtObj == nil or type(fullText) ~= "string" then return end
    local n = #fullText

    local pos = {}
    if type(keys) == "table" then
        local searchFrom = 1
        for _, k in ipairs(keys) do
            if type(k) == "table" and type(k.pat) == "string" and type(k.key) == "string" then
                local s = string.find(fullText, k.pat, searchFrom, true)
                if not s then s = string.find(fullText, k.pat, 1, true) end
                if s then
                    local atOff = tonumber(k.at) or 1
                    if atOff < 1 then atOff = 1 end
                    local at = math.floor(s + atOff - 1)
                    local span = tonumber(k.span)
                    if span == nil then span = tonumber(k.w) or 1 end
                    span = math.max(0, math.floor(span))
                    if span > 0 then
                        pos[#pos + 1] = { key = k.key, idx = at, span = span }
                        searchFrom = at + span
                    end
                end
            end
        end
    end
    table.sort(pos, function(a, b) return a.idx < b.idx end)
    -- Drop overlapping matches (keep earliest)
    do
        local cleaned, lastEnd = {}, 0
        for _, p in ipairs(pos) do
            if p.idx >= lastEnd then
                cleaned[#cleaned + 1] = p
                lastEnd = p.idx + p.span
            end
        end
        pos = cleaned
    end

    if not f_tournamentKeycapsReady() or #pos == 0 then
        textImgSetText(txtObj, fullText)
        textImgSetPos(txtObj, cx, cy)
        textImgDraw(txtObj)
        return
    end

    local segments = {}
    local cursor = 1
    for _, p in ipairs(pos) do
        if p.idx > cursor then
            segments[#segments + 1] = { text = fullText:sub(cursor, p.idx - 1) }
        end
        segments[#segments + 1] = { key = p.key }
        cursor = p.idx + p.span
    end
    if cursor <= n then
        segments[#segments + 1] = { text = fullText:sub(cursor, n) }
    end

    f_drawHintSegments(txtObj, segments, cx, cy, origAlign)
end

-- =====================================================================
-- LOADS DEDICATED TOURNAMENT SFF (overlays, brackets, trophy)
-- =====================================================================
local tournamentSff = nil
local TOURNAMENT_SFF_PATH = "external/mods/TournamentMode/TournamentMode.sff"

function f_loadTournamentSff()
    if tournamentSff ~= nil then return tournamentSff end
    local path = TOURNAMENT_SFF_PATH
    if type(f_findModFile) == "function" then
        path = f_findModFile("TournamentMode.sff") or path
    end
    local ok, s = pcall(sffNew, path)
    if ok and s then
        tournamentSff = s
        return s
    end
    print("[Tournament ERROR] Could not load " .. tostring(path))
    return nil
end

-- Native-style scroll arrows (up: sff 400,0 | down: 401,0).
-- Draws only the needed ones; silently skips if sprites are missing.
-- (Global: zero chunk locals ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â cache lives in the tournament table.)
function f_drawMenuScrollArrows(canUp, canDown, x, upY, downY, scale)
    if not canUp and not canDown then return end
    if type(tournament) ~= "table" then return end
    tournament.scrollArrowCache = tournament.scrollArrowCache or {}
    local sff = nil
    if type(f_loadTournamentSff) == "function" then
        local ok, s = pcall(f_loadTournamentSff)
        if ok then sff = s end
    end
    if sff == nil or type(animNew) ~= "function" then return end
    -- Scale comes as a parameter (this helper is defined before MENU_CONFIG
    -- in the file, so it cannot see that table; callers pass it).
    local arrowScale = tonumber(scale) or 0.5
    local function getAnim(group)
        local key = "scroll" .. tostring(group)
        if tournament.scrollArrowCache[key] == nil then
            local ok, anim = pcall(animNew, sff, tostring(group) .. ",0, 0,0, -1")
            tournament.scrollArrowCache[key] = (ok and anim) or false
        end
        return tournament.scrollArrowCache[key] or nil
    end
    if canUp then
        local a = getAnim(400)
        if a then
            if animUpdate then animUpdate(a) end
            if animSetScale then animSetScale(a, arrowScale, arrowScale) end
            if animSetPos then animSetPos(a, x, upY) end
            if animDraw then animDraw(a) end
        end
    end
    if canDown then
        local a = getAnim(401)
        if a then
            if animUpdate then animUpdate(a) end
            if animSetScale then animSetScale(a, arrowScale, arrowScale) end
            if animSetPos then animSetPos(a, x, downY) end
            if animDraw then animDraw(a) end
        end
    end
end

-- Black box behind menu rows (native options style). Same 320x240 space
-- as the cursor box (no localcoord call). ALPHA 0 = off.
-- (Global: zero chunk locals.)
function f_drawMenuBox(full)
    local a = tonumber(TOURNAMENT_MENU_BOX_ALPHA) or 0
    if a <= 0 then return end
    if full == nil then full = TOURNAMENT_MENU_BOX_FULLSCREEN end
    local r = nil
    if type(f_getOrCreateRect) == "function" then r = f_getOrCreateRect("tournamentMenuBox") end
    if r == nil then return end
    local x1, y1, x2, y2
    if full then
        -- Full-screen dim: default Lua space + symmetric overscan (same as
        -- f_drawBlackOverlay). A 0,0-based window starts at the space origin
        -- and only stretches right, leaving the left side bare.
        x1, y1, x2, y2 = -1000, -1000, 2000, 2000
    else
        local w = tonumber(TOURNAMENT_MENU_BOX_W) or 0
        local h = tonumber(TOURNAMENT_MENU_BOX_H) or 0
        if w <= 0 or h <= 0 then return end
        local cx = tonumber(TOURNAMENT_MENU_BOX_X) or 160
        local cy = tonumber(TOURNAMENT_MENU_BOX_Y) or 140
        x1, y1 = math.floor(cx - w / 2), math.floor(cy - h / 2)
        x2, y2 = math.floor(cx + w / 2), math.floor(cy + h / 2)
    end
    if type(tournament) == "table" and not tournament.menuBoxLogged then
        tournament.menuBoxLogged = true
        print(string.format("[Tournament] menuBox fullscreen=%s x1=%d y1=%d x2=%d y2=%d a=%s",
            tostring(TOURNAMENT_MENU_BOX_FULLSCREEN), x1, y1, x2, y2, tostring(a)))
    end
    local ok, err = pcall(function()
        -- Boxed: 320x240 menu space (cursor box / menu rows), X/Y/W/H are
        -- authored in it. Fullscreen: default space on purpose (NO
        -- SetLocalcoord) so the symmetric overscan above reaches both sides.
        if not full and rectSetLocalcoord then
            rectSetLocalcoord(r, 320, 240)
        end
        if rectSetWindow then rectSetWindow(r, x1, y1, x2, y2) end
        if rectSetColor then rectSetColor(r, 0, 0, 0) end
        if rectSetAlpha then rectSetAlpha(r, a, a) end
        if rectUpdate then rectUpdate(r) end
    end)
    if not ok then
        print("[Tournament] menuBox setup failed: " .. tostring(err))
        return
    end
    if rectDraw then rectDraw(r) end
end

-- getKey polling with case variants (for the live nudge keys).
-- (Global: zero chunk locals.)
function f_nudgeKeyDown(...)
    if not getKey then return false end
    for i = 1, select("#", ...) do
        local kn = select(i, ...)
        if type(kn) == "string" and kn ~= "" then
            local ok, down = pcall(getKey, kn)
            if ok and down then return true end
        end
    end
    return false
end

-- Prints nonzero group offsets (copy them back to the top vars).
-- P: writes live-tuned numeric vars back into TournamentMode.lua.
-- Only the listed keys; rest of each line (comments) preserved.
function f_persistTuning()
    local keys = {
        "TOURNAMENT_NUDGE_Y1", "TOURNAMENT_NUDGE_Y2", "TOURNAMENT_NUDGE_Y3",
        "TOURNAMENT_NUDGE_Y4", "TOURNAMENT_NUDGE_Y5", "TOURNAMENT_TROPHY_SCALE",
        "TOURNAMENT_STAGE_TITLE_X", "TOURNAMENT_STAGE_TITLE_Y",
        "TOURNAMENT_STAGE_NAME_X", "TOURNAMENT_STAGE_NAME_Y",
        "TROPHY_FINAL_DARKEN",
    }
    local map = {}
    for _, k in ipairs(keys) do
        local n = tonumber(_G[k])
        if n ~= nil then map[k] = n end
    end
    if next(map) == nil then print("[Tournament] persist: nothing to save"); return false end
    local path = "external/mods/TournamentMode/TournamentMode.lua"
    local f = io.open(path, "r")
    if not f then print("[Tournament] persist: cannot open " .. tostring(path)); return false end
    local content = f:read("*a")
    f:close()
    if not content or content == "" then print("[Tournament] persist: empty file"); return false end
    -- NOTE: no table.concat here (12k lines overflow the engine registry);
    -- stream line by line instead.
    local w = io.open(path, "w")
    if not w then print("[Tournament] persist: cannot write " .. tostring(path)); return false end
    local count = 0
    local first = true
    for line in (content .. "\n"):gmatch("([^\n]*)\n") do
        for k, n in pairs(map) do
            local pre, _, post = line:match("^(" .. k .. "%s*=%s*)(%S+)(.*)$")
            if pre then line = pre .. tostring(n) .. post; count = count + 1; break end
        end
        if not first then w:write("\n") end
        w:write(line)
        first = false
    end
    w:close()
    print("[Tournament] persist: " .. tostring(count) .. " vars saved to " .. path)
    return true
end

function f_dumpNudge()
    if type(tournament) ~= "table" then return end
    local y1 = tonumber(TOURNAMENT_NUDGE_Y1) or 0
    local y2 = tonumber(TOURNAMENT_NUDGE_Y2) or 0
    local y3 = tonumber(TOURNAMENT_NUDGE_Y3) or 0
    local y4 = tonumber(TOURNAMENT_NUDGE_Y4) or 0
    local y5 = tonumber(TOURNAMENT_NUDGE_Y5) or 0
    if y1 == 0 and y2 == 0 and y3 == 0 and y4 == 0 and y5 == 0 then return end
    print(string.format("[Tournament] nudge Y1=%d Y2=%d Y3=%d Y4=%d Y5=%d",
        y1, y2, y3, y4, y5))
    local ts = tonumber(TOURNAMENT_TROPHY_SCALE) or 1.0
    if ts ~= 1.0 then
        print(string.format("[Tournament] trophy scale=%.2f", ts))
    end
    local td = tonumber(TROPHY_FINAL_DARKEN)
    if td ~= nil and td ~= 128 then
        print(string.format("[Tournament] trophy darken=%d", math.floor(td)))
    end
end

-- =====================================================================
-- WAIT FOR THE BUTTON TO BE RELEASED (prevents a click from "passing through" to
-- the next screen) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â must come early in the file, it is used by several menus
-- =====================================================================
function f_waitForRelease(drawFn)
    -- Blocks until all menu buttons are released (keyboard + joystick).
    -- drawFn (optional): redraws the screen every frame so it does NOT flash black.
    while true do
        if main and main.f_cmdInput then main.f_cmdInput() end
        local stillPressed = false
        -- Drains the entrant press on both command tables (P2 must not leak
        -- through either, but a press held on either side must still release).
        if main and main.t_cmd and commandGetState then
            for _, ci in ipairs({ 1, 2 }) do
                local cmd = main.t_cmd[ci]
                if cmd and (commandGetState(cmd, 'a')
                    or commandGetState(cmd, 'b')
                    or commandGetState(cmd, 's')
                    or commandGetState(cmd, 'c')
                    or commandGetState(cmd, 'x')
                    or commandGetState(cmd, 'y')
                    or commandGetState(cmd, 'z')) then
                    stillPressed = true
                end
            end
        end
        if getKey and (getKey('RETURN') or getKey('KP_ENTER') or getKey('SPACE') or getKey('ESCAPE')) then
            stillPressed = true
        end
        -- Menu bindings (keyboard + joystick): engine commands don't cover
        -- the MENU action and t_cmd is nil in Lua menus, so poll them live.
        -- Prevents a held BACK/confirm leaking into the parent menu
        -- (pool/overlay exit with the button still down).
        if not stillPressed and type(f_menuKeyDown) == "function" and type(TOURNAMENT_PAD_CMDS) == "table" then
            for _, cmd in ipairs(TOURNAMENT_PAD_CMDS) do
                if f_menuKeyDown(cmd) then stillPressed = true; break end
            end
        end
        if not stillPressed and type(f_joystickCmdDown) == "function" and type(TOURNAMENT_PAD_CMDS) == "table" then
            for _, cmd in ipairs(TOURNAMENT_PAD_CMDS) do
                if f_joystickCmdDown(cmd) then stillPressed = true; break end
            end
        end
        if not stillPressed then break end
        if type(drawFn) == "function" then
            drawFn()
        end
        refresh()
    end
end

-- =====================================================================
-- Rectangle API
-- =====================================================================
local rectCache = {}
-- Virtual-keyboard cursor box basis: keycap native px (28 HD / 18 SD), so
-- the box hugs the cell on both modes (a fixed 28 overshoots ~1.55x on SD).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_kbCursorBoxPx()
    if tournament and tostring(tournament.screenMode or ""):upper() == "SD" then
        return tonumber(TOURNAMENT_WORDICON_PX_SD) or 18
    end
    return tonumber(TOURNAMENT_WORDICON_PX_HD) or 28
end
function f_getOrCreateRect(cacheKey)
    local r = rectCache[cacheKey]
    if r then return r end
    if type(rectNew) ~= "function" then return nil end
    local ok, newRect = pcall(rectNew)
    if not ok or not newRect then return nil end
    rectCache[cacheKey] = newRect
    return newRect
end

local rectErrorPrinted = false
function f_configureRect(cacheKey, x1, y1, x2, y2, r, g, b, alphaSrc, alphaDst)
    local rect = f_getOrCreateRect(cacheKey)
    if not rect then return nil end
    local ok, err = pcall(function()
        rectSetWindow(rect, x1, y1, x2, y2)
        rectSetColor(rect, r, g, b)
        rectSetAlpha(rect, alphaSrc or 255, alphaDst or 0)
        if rectUpdate then rectUpdate(rect) end
    end)
    if not ok and not rectErrorPrinted then
        rectErrorPrinted = true
        print("[Tournament][DEBUG] rect setup failed: " .. tostring(err))
        return nil
    end
    return rect
end

function f_drawRect(rect)
    if not rect then return end
    pcall(rectDraw, rect)
end

