-- =====================================================================
-- ESCALAS DO SELECT (lidas do system.def / motif.select_info)
-- In system.def ([Select Info] section):
--   portrait.scale          ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ motif.select_info.portrait.scale   (portraits da grade)
--   cell.bg.scale           ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ motif.select_info.cell.bg.scale
--   p1.cursor.active.scale  ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ motif.select_info.p1.cursor.active.scale
-- (values usually come as {x, y} table; we use the 1st component)
-- =====================================================================
function f_motifScale(val, default)
    default = default or 1
    if type(val) == "number" then return val end
    if type(val) == "table" then
        local n = tonumber(val[1]) or tonumber(val[2])
        if n then return n end
    end
    return default
end

function f_getSelectScales()
    local si = motif and motif.select_info
    local pScale, bgScale, cScale = 1, 1, 1
    if si then
        -- Grid / cell portraits (NOT the side big face)
        pScale = f_motifScale(si.portrait and si.portrait.scale, 1)
        if (not si.portrait or si.portrait.scale == nil) and si.p1 and si.p1.face then
            pScale = f_motifScale(si.p1.face.scale, 1)
        end
        bgScale = f_motifScale(si.cell and si.cell.bg and si.cell.bg.scale, 1)
        local cur = si.p1 and si.p1.cursor and si.p1.cursor.active.default
        cScale = f_motifScale(cur and cur.scale, 1)
    end
    return pScale, bgScale, cScale
end

-- Scales READ from system.def (used only to RESTORE the native select)
local _portraitScale, _portraitBgScale, _cursorScale = f_getSelectScales()

-- In tournament, bracket/pool portraits draw at scale 1, regardless of
-- portrait.scale = 0.25 / 0.33 / etc. in system.def (otherwise they stay tiny).
-- The real motif value stays in _portraitScale and is reapplied on screen exit.
local TOURNAMENT_PORTRAIT_DRAW_SCALE = _portraitScale

local function f_getRandomScaleFromMotif()
    local si = motif and motif.select_info
    if not si or not si.cell or not si.cell.random then return 1 end
    return f_motifScale(si.cell.random.scale, 1)
end
local _randomScale = f_getRandomScaleFromMotif()

-- ----------------------------------------------------------------------
-- Misc Settings helpers (in-memory motif + JSON; does NOT write system.def)
-- ----------------------------------------------------------------------
local function f_setScaleField(obj, scale)
    if type(obj) ~= "table" then return end
    local s = tonumber(scale) or 1
    if type(obj.scale) == "table" then
        obj.scale[1] = s
        obj.scale[2] = s
    else
        obj.scale = { s, s }
    end
end

local function f_buildScaleOptions()
    local t = {}
    for i = 0, 300 do t[#t + 1] = i / 100 end
    return t
end

local function f_idxOfScale(options, val)
    local v = tonumber(val) or 1
    local best, bestDiff = 1, math.huge
    for i, o in ipairs(options) do
        local d = math.abs((tonumber(o) or 0) - v)
        if d < bestDiff then best, bestDiff = i, d end
    end
    return best
end

local function f_formatScale(v)
    return string.format("%.2f", tonumber(v) or 0)
end

