-- Applies SD or HD over the `tournament` table ONLY without save.
-- (do...end block: no new variables under the 200 chunk locals limit.)
do
    -- Unified file counts as "has save" too (legacy renamed to .bak after
    -- migration, so checking only tournament_config.json would misfire).
    local sf = io.open("save/tournament_data.json", "r")  -- unified
    if not sf then sf = io.open("save/tournament_config.json", "r") end  -- legacy
    local hasSave = (sf ~= nil)
    if sf then sf:close() end
    if not hasSave then
        local h = 480
        if type(f_getScreenHeight) == "function" then
            local ok, v = pcall(f_getScreenHeight)
            if ok and tonumber(v) then h = tonumber(v) end
        end
        local defs = (h == 480) and TOURNAMENT_DEFAULTS_SD or TOURNAMENT_DEFAULTS_HD
        if type(defs) == "table" and type(tournament) == "table" then
            for k, v in pairs(defs) do tournament[k] = v end
        end
        print("[Tournament] Defaults applied: " .. ((h == 480) and "SD" or "HD") .. " (no save)")
    end
end
