f_applyVisualSettingsToMotif = function()
    local si = motif and motif.select_info
    if not si then return end
    local p = tonumber(layout.portraitScale) or _portraitScale or 1
    local bg = tonumber(layout.portraitBgScale) or _portraitBgScale or 1
    local cur = tonumber(layout.cursorScale) or _cursorScale or 1
    local rnd = tonumber(tournament.randomScale) or _randomScale or 1
    if si.portrait then
        f_setScaleField(si.portrait, p)
        if type(si.portrait.loading) == "table" then f_setScaleField(si.portrait.loading, p) end
    end
    if type(si.loading) == "table" then f_setScaleField(si.loading, p) end
    if si.cell then
        if type(si.cell.bg) == "table" then f_setScaleField(si.cell.bg, bg) end
        if type(si.cell.random) == "table" then f_setScaleField(si.cell.random, rnd) end
    end
    for pn = 1, 4 do
        local side = si["p" .. pn]
        local cursor = side and side.cursor
        if type(cursor) == "table" then
            local active, done = cursor.active, cursor.done
            if type(active) == "table" then
                if type(active.default) == "table" then f_setScaleField(active.default, cur)
                else f_setScaleField(active, cur) end
            end
            if type(done) == "table" then
                if type(done.default) == "table" then f_setScaleField(done.default, cur)
                else f_setScaleField(done, cur) end
            end
        end
    end
end

