-- active layout (mutable via TOURNAMENT SCREEN menu)
local layout = {}
-- forward: used in f_applyLayoutMode before the caches block
local skeletonCache = nil
local cellBgAnim = nil
local moduleCellBgAnim = nil  -- pool/scales always-Module bg (never pollutes cellBgAnim)
local bracketAnimCache = {}
local trophyAnimCache = {}

-- Dependentes do layout (recomputados em f_applyLayoutMode)
local COLS_LEFT_X = {}
local COLS_RIGHT_X = {}
local R128_INNER_OFFSET_X = 0
local R128_GROUP_GAP_Y = 0
local R128_INNER_OFFSET_Y = 0
local FIRST_COL = { x = 0, pairGap = 2, rowGap = 3, slotSize = 27, startY = 0, lines = 32 }
local RIGHT_COL = { x = 0, pairGap = 2, rowGap = 3, slotSize = 27, startY = 0, lines = 32 }
local FINAL_COL = 7

function f_copyLayoutInto(dst, src)
    if type(dst) ~= "table" or type(src) ~= "table" then return end
    for k in pairs(dst) do dst[k] = nil end
    for k, v in pairs(src) do dst[k] = v end
end

-- Applies HD/SD: fills `layout` + skeleton columns IN-PLACE
-- (without reassigning local tables ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â closures/caches stay valid).
-- Also invalidates skeleton + anims that depend on bracketGroup/scale.
function f_applyLayoutMode()
    -- Refresh of current resolution (covers Options switch without restart).
    if type(f_getScreenHeight) == "function" then
        local okH, curH = pcall(f_getScreenHeight)
        if okH and tonumber(curH) then _screenH = tonumber(curH) end
    end
    if type(f_getScreenWidth) == "function" then
        local okW, curW = pcall(f_getScreenWidth)
        if okW and tonumber(curW) then _screenV = tonumber(curW) end
    end
    -- Automatic: 480p height = SD; any other height = HD.
    -- (Manual switch menu is voided; screenMode only reflects auto.)
    local mode = (_screenH == 480) and "SD" or "HD"
    local prevMode = tournament and tournament.screenMode or mode
    if tournament then tournament.screenMode = mode end
    -- Session SD->HD reset (no restart): forced SD OFF must not leak to HD.
    if tournament and prevMode == "SD" and mode == "HD" then
        tournament.showAnimatedPortraits = true
        tournament.showAnimatedPortraitsBg = true
        tournament.nextFightArrows = "Blue"
        tournament.size = 128
        print("[Tournament] Resolution SD->HD (session): SHOW ANIMATED PORTRAITS/BGS reset to ON, ARROWS reset to Blue, SIZE reset to 128")
    end
    -- Animated portraits: unavailable in SD (forces OFF; menu shows gray + hint)
    if tournament and mode == "SD" then tournament.showAnimatedPortraits = false end
    if tournament and mode == "SD" then tournament.showAnimatedPortraitsBg = false end
    -- Next Fight Arrows: unavailable in SD (forces None; menu shows gray + hint)
    if tournament and mode == "SD" then tournament.nextFightArrows = "None" end

    local src = (mode == "SD") and LAYOUT_SD or LAYOUT_HD
    f_copyLayoutInto(layout, src)
    -- Espelho global do tamanho nativo (drawers definidos antes do
    -- `local layout` nÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o o enxergam por escopo lÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â©xico).
    TOURNAMENT_HINT_NATIVE = tonumber(layout.buttonspace) or 28

    -- Skeleton columns (in-place mutation)
    for k in pairs(COLS_LEFT_X) do COLS_LEFT_X[k] = nil end
    for k in pairs(COLS_RIGHT_X) do COLS_RIGHT_X[k] = nil end
    COLS_LEFT_X[1] = layout.ExternalColumnLeft
    COLS_RIGHT_X[1] = layout.ExternalColumnRight
    for i = 2, 6 do
        COLS_LEFT_X[i] = layout.columnLeft + (i - 2) * layout.columnSpacing
        COLS_RIGHT_X[i] = layout.columnRight - (i - 2) * layout.columnSpacing
    end
    COLS_LEFT_X[FINAL_COL] = layout.finalColX
    COLS_RIGHT_X[FINAL_COL] = layout.finalColX

    R128_INNER_OFFSET_X = layout.SpacingBTwoExternalColumns
    R128_GROUP_GAP_Y    = layout.linesDistance
    R128_INNER_OFFSET_Y = R128_GROUP_GAP_Y / 2

    FIRST_COL.x = COLS_LEFT_X[1]
    FIRST_COL.startY = layout.columnStartY
    RIGHT_COL.x = COLS_RIGHT_X[1]
    RIGHT_COL.startY = layout.columnStartY

    -- Invalidate layout-dependent caches
    skeletonCache = nil
    cellBgAnim = nil
    tournamentPortraitPlaced = {} -- cell portrait fast-path (pos/scale baked per layout)
    -- bracketAnimCache / trophy: clear if they already exist (declared further below)
    if type(bracketAnimCache) == "table" then
        for k in pairs(bracketAnimCache) do bracketAnimCache[k] = nil end
    end
    if type(trophyAnimCache) == "table" then
        for k in pairs(trophyAnimCache) do trophyAnimCache[k] = nil end
    end

    print(string.format("[Tournament] Layout applied: screenMode=%s | portraitScale=%.2f | bracketGroup=%s | colL=%s | screen=%dx%d",
        tostring(mode),
        tonumber(layout.portraitScale) or 0,
        tostring(layout.bracketGroup),
        tostring(layout.columnLeft),
        tonumber(_screenV) or 0, tonumber(_screenH) or 0))
end

-- Automatic default by height (load must NOT force saved HD/SD from JSON)
if tournament then
    tournament.screenMode = (_screenH == 480) and "SD" or "HD"
end
f_applyLayoutMode()

print(string.format("[Tournament] Slot adjustments: screenHeight=%d, hdAvailable=%s, widescreen=%s",
    _screenH, tostring(_hdAvailable), tostring(_widescreen)))

print(string.format("[Tournament] localcoord: lcX=%s lcY=%s | screenHeight=%s | screenMode=%s",
    tostring(lcX), tostring(lcY),
    tostring(f_getScreenHeight()),
    tostring(tournament and tournament.screenMode)
))

