local saveFilePath = "save/tournament_config.json"
local tournamentSavePath = "save/tournament_state.json" -- legacy (slot 1): fallback read-only
local TOURNAMENT_STATE_SLOTS = 50
-- Max chars of a human player ID (Basic Settings > USE ID FOR HUMAN PLAYERS).
-- v1: fixed 30 (tune here later).
local TOURNAMENT_HUMAN_ID_MAXLEN = 20
-- Random CPU ID pool (Basic Settings > ALLOW RANDOM ID FOR CPU PLAYERS).
-- Lives in tournament_cpu_ids.txt (same folder): one name per line, lines
-- starting with -- and empty lines are ignored, no need to touch this file.
-- Loaded once at boot (restart to reload). Assigned WITHOUT replacement,
-- so no two CPUs share a name (refills reshuffled if CPUs outnumber names).
-- Empty/missing file = no CPU IDs.
-- (Plain .txt on purpose: a .lua table this size must be COMPILED at boot,
-- which hangs weak machines. Text is only read, never compiled.)
-- Global (no `local`) on purpose: easy to extend/replace from elsewhere.
TOURNAMENT_CPU_ID_POOL = {}
do
    local cpuIdsPath = "external/mods/TournamentMode/tournament_cpu_ids.txt"
    if type(f_findModFile) == "function" then
        cpuIdsPath = f_findModFile("tournament_cpu_ids.txt") or cpuIdsPath
    end
    local txtFile = io.open(cpuIdsPath, "r")
    if txtFile then
        local okRead, list = pcall(function()
            local t = {}
            local seen = {}
            for line in txtFile:lines() do
                local name = line:match("^%s*(.-)%s*$") or ""
                if name ~= "" and not name:match("^%-%-") then
                    -- Uppercase-only tournament font: typed human IDs are
                    -- always upper, so CPUs normalize here too (versus screen
                    -- included). Dedupe: casing variants collapse to one.
                    local up = string.upper(name)
                    if not seen[up] then
                        seen[up] = true
                        t[#t + 1] = up
                    end
                end
            end
            return t
        end)
        pcall(function() txtFile:close() end)
        if okRead and type(list) == "table" and #list > 0 then
            TOURNAMENT_CPU_ID_POOL = list
        end
    end
    -- Legacy fallback: tournament_cpu_ids.lua (same folder, return { ... }).
    if #TOURNAMENT_CPU_ID_POOL == 0 then
        local okLoad, chunk = pcall(loadfile, "external/mods/TournamentMode/tournament_cpu_ids.lua")
        if okLoad and type(chunk) == "function" then
            local okRun, list = pcall(chunk)
            if okRun and type(list) == "table" then
                local norm = {}
                local seen = {}
                for _, nm in ipairs(list) do
                    if type(nm) == "string" and nm ~= "" then
                        local up = string.upper(nm)
                        if not seen[up] then
                            seen[up] = true
                            norm[#norm + 1] = up
                        end
                    end
                end
                TOURNAMENT_CPU_ID_POOL = norm
            end
        end
    end
end
print("[Tournament] CPU ID pool: " .. tostring(#TOURNAMENT_CPU_ID_POOL) .. " names")
-- Country flags (type-a-country UI later): tournament_country_flags.lua,
-- same folder. ORDER = sff group 6 (entry i <-> sprite 6,(i-1)).
TOURNAMENT_COUNTRY_FLAGS = {}
do
