-- =====================================================================
-- LANGUAGE SYSTEM (i18n): one dict file per language, same folder.
--   tournament_lang_en.lua   -> return { ... } (default, always loaded)
--   tournament_lang_ptBR.lua -> return { ... } (copy EN, translate values)
-- tournament.language = "en" | "ptBR" (saved in tournament_config.json).
-- T(key) returns LANG value or EN fallback or key. f_loadTournamentLang()
-- also syncs the legacy bracket globals so the bracket screen translates
-- without touching every draw call site.
-- =====================================================================
TOURNAMENT_LANG_CODES = { "en", "ptBR" }
TOURNAMENT_LANG_FILES = {
    en = "external/mods/TournamentMode/tournament_lang_en.lua",
    ptBR = "external/mods/TournamentMode/tournament_lang_ptBR.lua",
}
TOURNAMENT_LANG_LABELS = { "English", "Portuguese-BR" }
TOURNAMENT_LANG_EN = {}
TOURNAMENT_LANG = {}
do
    local enPath = TOURNAMENT_LANG_FILES.en
    if type(f_findModFile) == "function" then
        enPath = f_findModFile("tournament_lang_en.lua") or enPath
    end
    local okLoad, chunk = pcall(loadfile, enPath)
    if okLoad and type(chunk) == "function" then
        local okRun, tbl = pcall(chunk)
        if okRun and type(tbl) == "table" then TOURNAMENT_LANG_EN = tbl end
    end
end
function f_loadTournamentLang(code)
    if code ~= "ptBR" then code = "en" end
    if type(tournament) == "table" then tournament.language = code end
    local tbl = nil
    local path = TOURNAMENT_LANG_FILES[code]
    if type(f_findModFile) == "function" and (code == "en" or code == "ptBR") then
        path = f_findModFile("tournament_lang_" .. code .. ".lua") or path
    end
    if path then
        local okLoad, chunk = pcall(loadfile, path)
        if okLoad and type(chunk) == "function" then
            local okRun, res = pcall(chunk)
            if okRun and type(res) == "table" then tbl = res end
        end
    end
    if type(tbl) ~= "table" then tbl = TOURNAMENT_LANG_EN end
    TOURNAMENT_LANG = tbl or {}
    -- Sync legacy bracket globals (declared at top of file) so existing
    -- draw code picks up the language with zero call-site changes.
    local function pick(k, fb)
        local v = TOURNAMENT_LANG[k]
        if type(v) == "string" and v ~= "" then return v end
        v = TOURNAMENT_LANG_EN[k]
        if type(v) == "string" and v ~= "" then return v end
        return fb
    end
    NEXTMATCH_TITLE_TEXT = pick("next_match", "- NEXT MATCH -")
    NEXTMATCH_STAGE_TITLE_TEXT = pick("stage_select", "Stage Select:")
    NEXTMATCH_FIGHT_PREFIX = pick("fight_prefix", "Fight ")
    NEXTMATCH_VS_TEXT = pick("vs", "vs")
    NEXTMATCH_TYPE_CPU = pick("cpu", "CPU")
    NEXTMATCH_TYPE_PLAYER_PREFIX = pick("player_prefix", "Player ")
    NEXTMATCH_TYPE_TEAM_PREFIX = pick("team_prefix", "team ")
    print("[Tournament] Language: " .. tostring(code))
    return code
end
function T(k)
    if type(k) ~= "string" then return "" end
    local v = TOURNAMENT_LANG and TOURNAMENT_LANG[k]
    if type(v) == "string" then return v end
    v = TOURNAMENT_LANG_EN and TOURNAMENT_LANG_EN[k]
    if type(v) == "string" then return v end
    return k
end
function f_tournamentLangIdx()
    if tournament and tournament.language == "ptBR" then return 2 end
    return 1
end
function f_applyTournamentLangLabel(v)
    local s = tostring(v or "")
    if s == "Portuguese-BR" then f_loadTournamentLang("ptBR")
    else f_loadTournamentLang("en") end
    -- Persisted by the menu-exit save (f_saveTournamentConfig saves
    -- tournament.language); no direct call here (local is defined later).
end
-- Stable English label -> lang key. Menu items keep hardcoded EN labels;
-- refresh swaps it.label to T(key) every frame, so switching LANGUAGE
-- relabels the OPEN menu instantly. _en stores the original label once,
-- so switching back and forth (and RESET DEFAULTS) keeps working.
