    ["RESTORE DEFAULTS:"] = "menu_restore_defaults",
}
function f_refreshMenuItemsLang(list)
    if type(list) ~= "table" then return end
    for _, entry in ipairs(list) do
        local it = nil
        if type(entry) == "table" then it = entry.item or entry end
        if type(it) == "table" and type(it.label) == "string" then
            if type(it._en) ~= "string" then it._en = it.label end
            local key = TOURNAMENT_LABEL_TO_KEY[it._en] or TOURNAMENT_LABEL_TO_KEY[it.label]
            if key ~= nil and type(T) == "function" then
                local translated = T(key)
                -- T() returns the key itself on a miss (e.g. menu_bracket_edit_music).
                -- Never show that underscore form: keep the English label with spaces + ":".
                if type(translated) == "string" and translated ~= "" and translated ~= key then
                    it.label = translated
                else
                    it.label = it._en
                end
            end
        end
    end
end
