-- =====================================================================
-- CPU FLAG POOL (which country flags CPUs may draw). Same scheme as the
-- character pool, minus slots: name -> true/false, new flags default ON,
-- ghosts purged on sync. Empty pool = draw falls back to the full list
-- (flags are cosmetic; the tournament never blocks on them).
-- (Globals: the main chunk has a 200 locals limit.)
-- =====================================================================
cpuFlagPoolInitialized = false
function f_initializeFlagPool()
    if type(TOURNAMENT_COUNTRY_FLAGS) ~= "table" then return end
    if tournament == nil then return end
    if type(tournament.cpuFlagPool) ~= "table" then tournament.cpuFlagPool = {} end
    local pool = tournament.cpuFlagPool
    local valid = {}
    for _, nm in ipairs(TOURNAMENT_COUNTRY_FLAGS) do
        if type(nm) == "string" and nm ~= "" then valid[nm] = true end
    end
    for nm, _ in pairs(pool) do
        if not valid[nm] then pool[nm] = nil end
    end
    for nm, _ in pairs(valid) do
        if pool[nm] == nil then pool[nm] = true end
    end
    cpuFlagPoolInitialized = true
end
function f_isFlagEnabled(name)
    if type(TOURNAMENT_COUNTRY_FLAGS) ~= "table" or #TOURNAMENT_COUNTRY_FLAGS == 0 then return true end
    if not cpuFlagPoolInitialized then
        if type(f_initializeFlagPool) == "function" then f_initializeFlagPool() end
    end
    if tournament == nil or type(tournament.cpuFlagPool) ~= "table" then return true end
    local v = tournament.cpuFlagPool[name]
    if v == nil then return true end
    return v ~= false
end
function f_toggleFlag(name)
    if not cpuFlagPoolInitialized then
        if type(f_initializeFlagPool) == "function" then f_initializeFlagPool() end
    end
    if tournament == nil or type(tournament.cpuFlagPool) ~= "table" then return nil end
    if type(name) ~= "string" or name == "" then return nil end
    tournament.cpuFlagPool[name] = not f_isFlagEnabled(name)
    return tournament.cpuFlagPool[name]
end
function f_toggleAllFlags()
    if not cpuFlagPoolInitialized then
        if type(f_initializeFlagPool) == "function" then f_initializeFlagPool() end
    end
    if tournament == nil or type(tournament.cpuFlagPool) ~= "table" then return end
    local anyOff = false
    for _, nm in ipairs(TOURNAMENT_COUNTRY_FLAGS or {}) do
        if tournament.cpuFlagPool[nm] == false then anyOff = true break end
    end
    local newVal = false
    if anyOff then newVal = true end
    for _, nm in ipairs(TOURNAMENT_COUNTRY_FLAGS or {}) do
        if type(nm) == "string" and nm ~= "" then tournament.cpuFlagPool[nm] = newVal end
    end
end
function f_getEnabledFlagCount()
    if not cpuFlagPoolInitialized then
        if type(f_initializeFlagPool) == "function" then f_initializeFlagPool() end
    end
    local n = 0
    if tournament ~= nil and type(tournament.cpuFlagPool) == "table" then
        for _, v in pairs(tournament.cpuFlagPool) do
            if v ~= false then n = n + 1 end
        end
    end
    return n
end
function f_getTotalFlagCount()
    if type(TOURNAMENT_COUNTRY_FLAGS) ~= "table" then return 0 end
    return #TOURNAMENT_COUNTRY_FLAGS
end
-- Enabled flag names, file order (sff group 6 order). Empty when all off.
function f_enabledFlagNames()
    if not cpuFlagPoolInitialized then
        if type(f_initializeFlagPool) == "function" then f_initializeFlagPool() end
    end
    local out = {}
    if type(TOURNAMENT_COUNTRY_FLAGS) ~= "table" then return out end
    for _, nm in ipairs(TOURNAMENT_COUNTRY_FLAGS) do
        if type(nm) == "string" and nm ~= "" and f_isFlagEnabled(nm) then
            out[#out + 1] = nm
        end
    end
    return out
end

-- =====================================================================
-- UNIFIED SAVE FILE (save/tournament_data.json)
-- { config = {...}, characterPools = {active=, slots=}, states = {["0"]=...} }
-- Single reader/writer: config+pools+states live in memory (tournamentData),
-- disk is touched once per save. Legacy files (tournament_config.json,
-- character_pools.json, tournament_state_XX.json) are migrated on first
-- boot and renamed to .bak. This also fixes the Save/Load preview reading
-- 50 files per refresh (now table lookups) and the "same content in every
-- slot" class of bugs (no per-slot path to get wrong).
-- =====================================================================
local tournamentDataPath = "save/tournament_data.json"
local tournamentData = nil  -- {config=, characterPools=, states=} (in-memory)
local tournamentDataDirty = false

function f_normalizeStateSlot(slot)
    slot = tonumber(slot)
    if not slot and tournament then slot = tonumber(tournament.saveSlot) end
    slot = slot or 1
    if slot < 0 then slot = 0 end
    if slot > TOURNAMENT_STATE_SLOTS then slot = TOURNAMENT_STATE_SLOTS end
    return slot
end

local function f_decodeJsonContent(content, pathForAlt)
    if not content or content == "" then return nil end
    local data = nil
    if type(jsonDecode) == "function" then
        local ok, res = pcall(jsonDecode, content)
        if ok and type(res) == "table" then data = res end
        if not data and pathForAlt then
            ok, res = pcall(jsonDecode, pathForAlt)
            if ok and type(res) == "table" then data = res end
        end
    end
    if not data and json and type(json.decode) == "function" then
        local ok, res = pcall(json.decode, content)
        if ok and type(res) == "table" then data = res end
    end
    return data
end

local function f_readJsonFile(path)
    local file = io.open(path, "r")
    if not file then return nil end
    local content = file:read("*a")
    pcall(function() file:close() end)
    return f_decodeJsonContent(content, path)
end

local function f_renameToBak(path)
    if not (os and os.rename) then return false end
    local ok = pcall(os.rename, path, path .. ".bak")
    return ok == true
end

-- Migrates legacy files into tournamentData (once). Returns true if it
-- migrated anything (caller saves the unified file right after).
local function f_migrateLegacySaves()
    local migrated = false
    tournamentData = tournamentData or { config = nil, characterPools = nil, states = {} }
    -- 1) config
    if tournamentData.config == nil then
        local legacy = f_readJsonFile(saveFilePath)
        if type(legacy) == "table" then
            tournamentData.config = legacy
            migrated = true
            f_renameToBak(saveFilePath)
            print("[Tournament] Migrated " .. saveFilePath .. " -> tournament_data.json")
        end
    end
    -- 2) character pools
    if tournamentData.characterPools == nil then
        local legacy = f_readJsonFile(characterPoolsPath)
        if type(legacy) == "table" then
            tournamentData.characterPools = legacy
            migrated = true
            f_renameToBak(characterPoolsPath)
            print("[Tournament] Migrated " .. characterPoolsPath .. " -> tournament_data.json")
        end
    end
    -- 3) states 0..50 (+ legacy single file as slot 1)
    if type(tournamentData.states) ~= "table" then tournamentData.states = {} end
    local anyState = false
    for _, v in pairs(tournamentData.states) do if v ~= nil then anyState = true break end end
    if not anyState then
        for slot = 0, TOURNAMENT_STATE_SLOTS do
            local oldPath = string.format("save/tournament_state_%02d.json", slot)
            local st = f_readJsonFile(oldPath)
            if type(st) == "table" and st.bracket then
                tournamentData.states[tostring(slot)] = st
                migrated = true
                f_renameToBak(oldPath)
            end
        end
        local single = f_readJsonFile(tournamentSavePath)
        if type(single) == "table" and single.bracket
            and tournamentData.states["1"] == nil then
            tournamentData.states["1"] = single
            migrated = true
            f_renameToBak(tournamentSavePath)
        end
        if migrated then
            print("[Tournament] Migrated tournament_state_XX.json -> tournament_data.json")
        end
    end
    return migrated
end

local function f_ensureTournamentData()
    if tournamentData ~= nil then return tournamentData end
    tournamentData = { config = nil, characterPools = nil, states = {} }
    local unified = f_readJsonFile(tournamentDataPath)
    if type(unified) == "table" then
        if type(unified.config) == "table" then tournamentData.config = unified.config end
        if type(unified.characterPools) == "table" then
            tournamentData.characterPools = unified.characterPools
        end
        if type(unified.states) == "table" then tournamentData.states = unified.states end
    end
    if f_migrateLegacySaves() then
        tournamentDataDirty = true
        f_flushTournamentData()
    end
    return tournamentData
end

-- Writes the whole unified file. Callers set tournamentDataDirty instead
-- and flush on menu exit / after state saves; direct call also fine.
function f_flushTournamentData()
    f_ensureTournamentData()
    if createDir then createDir("save") end
    local file = io.open(tournamentDataPath, "w")
    if file then
        file:write(f_serializeTable(tournamentData))
        file:close()
        tournamentDataDirty = false
        print("[Tournament] Saved " .. tournamentDataPath)
    else
        print("[Tournament ERROR] Could not open " .. tournamentDataPath .. " for writing.")
    end
end

function f_markTournamentDataDirty()
    tournamentDataDirty = true
end

-- Tournament save path per slot (save/tournament_state_01.json ... _50.json).
-- omitted slot => uses current tournament.saveSlot.
function f_getTournamentSavePath(slot)
    slot = tonumber(slot)
    if not slot and tournament then slot = tonumber(tournament.saveSlot) end
    slot = slot or 1
    if slot < 0 then slot = 0 end
    if slot > TOURNAMENT_STATE_SLOTS then slot = TOURNAMENT_STATE_SLOTS end
    return string.format("save/tournament_state_%02d.json", slot), slot
end

function f_serializeTable(val)
    local t = type(val)
    if t == "number" or t == "boolean" then
        return tostring(val)
    elseif t == "string" then
        return '"' .. val:gsub('\\', '\\\\'):gsub('"', '\\"') .. '"'
    elseif t == "table" then
        local isArray = true
        local count = 0
        for k, v in pairs(val) do
            count = count + 1
            if type(k) ~= "number" or k ~= count then isArray = false end
        end
        local parts = {}
        if isArray then
            for _, v in ipairs(val) do table.insert(parts, f_serializeTable(v)) end
            return '[' .. table.concat(parts, ',') .. ']'
        else
            for k, v in pairs(val) do
                table.insert(parts, '"' .. tostring(k) .. '":' .. f_serializeTable(v))
            end
            return '{' .. table.concat(parts, ',') .. '}'
        end
    end
    return "null"
end

local function f_buildTournamentConfigData()
    local data = {
