        thirdPlacePlayoff = tournament.thirdPlacePlayoff,
        allowDuplicateChars = tournament.allowDuplicateChars,
        allowRandomCpuPalette = tournament.allowRandomCpuPalette,
        humanPlayers = tournament.humanPlayers,
        humanIds = tournament.humanIds,
        humanFlags = tournament.humanFlags,
        useHumanIds = tournament.useHumanIds,
        randomStage = tournament.randomStage,
        allowRandomCpuIds = tournament.allowRandomCpuIds,
        randomHumanIds = tournament.randomHumanIds,
        randomCharsForHumans = tournament.randomCharsForHumans,
        showPlayerCursors = tournament.showPlayerCursors,
        showCpuCursors = tournament.showCpuCursors,
        startMode = tournament.startMode,
        saveSlot = tournament.saveSlot,
        timeLimit = tournament.timeLimit,
        life = tournament.life,
        difficulty = tournament.difficulty,
        showVsScreen = tournament.showVsScreen,
        teamMode = tournament.teamMode,
        teamSize = tournament.teamSize,
        title = tournament.title,
        subtitle = tournament.subtitle,
        format = tournament.format,
        characterPool = characterPool,
        cpuFlagPool = tournament.cpuFlagPool or {},
        bgOpacity = tournament.bgOpacity,
        bgChoice = tournament.bgChoice,
        useOriginalPortraitBg = tournament.useOriginalPortraitBg,
        --portraitScale = tournament.portraitScale,
        --portraitBgScale = tournament.portraitBgScale,
        --cursorScale = tournament.cursorScale,
        randomScale = tournament.randomScale,
        --musicEnabled = tournament.musicEnabled,
        musicVolume = tournament.musicVolume,
        menuMusicVolume = tournament.menuMusicVolume,
        bracketEditMusicVolume = tournament.bracketEditMusicVolume,
        bracketMusicVolume = tournament.bracketMusicVolume,
        resultsMusicVolume = tournament.resultsMusicVolume,
        showRemaining = (tournament.showRemaining == true),
        menuMusicTrack = tournament.menuMusicTrack,
        bracketEditMusicTrack = tournament.bracketEditMusicTrack,
        bracketMusicTrack = tournament.bracketMusicTrack,
        resultsMusicTrack = tournament.resultsMusicTrack,
        trophySprite = tournament.trophySprite,
        portraitBgSprite = tournament.portraitBgSprite,
        screenpackBgScale = tournament.screenpackBgScale,
        stagePortraitScale = tournament.stagePortraitScale,
        charPortraitScales = tournament.charPortraitScales,
