        showAnimatedPortraitsBg = tournament.showAnimatedPortraitsBg,
        showBigPortraits = tournament.showBigPortraits,
        autoSave = tournament.autoSave,
        padIcons = tournament.padIcons,
        screenMode = tournament.screenMode,
        language = tournament.language,
        nextFightArrows = tournament.nextFightArrows,
    }
    return data
end

local function f_saveTournamentConfig()
    local data = f_buildTournamentConfigData()
    -- Unified file: config section updated in memory, single disk write.
    -- Legacy tournament_config.json is NOT written anymore (migrated to .bak).
    local td = nil
    if type(f_ensureTournamentData) == "function" then
        td = f_ensureTournamentData()
    else
        td = tournamentData
    end
    if td then
        td.config = data
        f_flushTournamentData()
    else
        -- Fallback (should never happen): legacy direct write.
        local jsonString = f_serializeTable(data)
        if createDir then createDir("save") end
        local file = io.open(saveFilePath, "w")
        if file then
            file:write(jsonString)
            file:close()
            print("[Tournament] Settings saved to " .. saveFilePath)
        else
            print("[Tournament ERROR] Could not open " .. saveFilePath .. " for writing.")
        end
    end
    -- f_serializeTable trata boolean/number/string/table aninhada (characterPool)
    tournamentConfigDirty = false
    tournamentConfigSaveCooldown = 0
end

-- Auto-save config on every option change (dirty + debounced flush: a full
-- serialize+write per tick while holding LEFT/RIGHT would hitch, same lesson
-- as the portrait-scales screen). Menus mark dirty inside it.apply; loops
-- tick the flush (<=90 frames late); any direct f_saveTournamentConfig
-- clears it. (Globals: zero chunk-local slots.)
tournamentConfigDirty = false
tournamentConfigSaveCooldown = 0
TOURNAMENT_CONFIG_SAVE_COOLDOWN_FRAMES = 90
function f_markTournamentConfigDirty()
    tournamentConfigDirty = true
end
function f_flushTournamentConfigTick()
    if tournamentConfigSaveCooldown > 0 then
        tournamentConfigSaveCooldown = tournamentConfigSaveCooldown - 1
        return
    end
    if tournamentConfigDirty then
        tournamentConfigDirty = false
        tournamentConfigSaveCooldown = TOURNAMENT_CONFIG_SAVE_COOLDOWN_FRAMES
        if type(f_saveTournamentConfig) == "function" then
            f_saveTournamentConfig()
        end
    end
end

local function f_loadTournamentConfig()
    -- Unified file first (migrates legacy on first boot); falls back to
    -- legacy tournament_config.json only if unified has no config section.
    local data = nil
    if type(f_ensureTournamentData) == "function" then
        local td = f_ensureTournamentData()
        if td and type(td.config) == "table" then data = td.config end
    end
    if data == nil then
        data = f_readJsonFile(saveFilePath)
    end
    if type(data) ~= "table" then
        print("[Tournament] No config save found (" .. tournamentDataPath .. ").")
        return
    end

    if data.size ~= nil then tournament.size = data.size end
    if data.rounds ~= nil then
        -- Rounds to Win (1..10), isolado do Options.Match.Wins do jogo.
        local r = math.floor(tonumber(data.rounds) or 2)
        if r < 1 then r = 1 end
        if r > 10 then r = 10 end
        tournament.rounds = r
    end
    if data.watchCpuFights ~= nil then tournament.watchCpuFights = data.watchCpuFights end
    if data.cpuSpeedMultiplier ~= nil then tournament.cpuSpeedMultiplier = data.cpuSpeedMultiplier end
    if data.continueAfterPlayerElimination ~= nil then tournament.continueAfterPlayerElimination = data.continueAfterPlayerElimination end
    if data.showBracketBetweenMatches ~= nil then tournament.showBracketBetweenMatches = data.showBracketBetweenMatches end
    if data.startMode ~= nil then tournament.startMode = data.startMode end
    if data.saveSlot ~= nil then
        local ss = tonumber(data.saveSlot) or 1
        if ss < 0 then ss = 0 end
        if ss > TOURNAMENT_STATE_SLOTS then ss = TOURNAMENT_STATE_SLOTS end
        tournament.saveSlot = ss
    end
    if data.thirdPlacePlayoff ~= nil then tournament.thirdPlacePlayoff = data.thirdPlacePlayoff end
    if data.allowDuplicateChars ~= nil then tournament.allowDuplicateChars = data.allowDuplicateChars end
    if data.allowRandomCpuPalette ~= nil then tournament.allowRandomCpuPalette = data.allowRandomCpuPalette end
    if data.humanPlayers ~= nil then
        local hp = tonumber(data.humanPlayers) or 1
        if hp < 0 then hp = 0 end
        local maxHP = 128
        if type(f_maxHumanPlayers) == "function" then maxHP = f_maxHumanPlayers() end
        if hp > maxHP then hp = maxHP end
        tournament.humanPlayers = hp
    end
    tournament.useHumanIds = true  -- VOIDED menu; always ON (saved value ignored)
    tournament.randomStage = false  -- forced NO (menu voided; saved value ignored)
    tournament.allowRandomCpuIds = true  -- VOIDED menu; always ON (saved value ignored)
    if data.randomHumanIds ~= nil then tournament.randomHumanIds = (data.randomHumanIds == true) end
    if data.randomCharsForHumans ~= nil then tournament.randomCharsForHumans = (data.randomCharsForHumans == true) end
    -- Per-player IDs/flags persist here (tournament_config.json): entering
    -- any ID/flag screen pre-fills from these; select only prompts unset slots.
    if type(data.humanIds) == "table" then tournament.humanIds = data.humanIds end
    if type(data.humanFlags) == "table" then tournament.humanFlags = data.humanFlags end
    if data.showPlayerCursors ~= nil then tournament.showPlayerCursors = (data.showPlayerCursors ~= false) end
    if data.showCpuCursors ~= nil then tournament.showCpuCursors = (data.showCpuCursors == true) end
    if data.timeLimit ~= nil then tournament.timeLimit = data.timeLimit end
    if data.life ~= nil then
        -- Life % (10..300 step 10), isolado do Options.Life do jogo.
        local lv = math.floor(tonumber(data.life) or 100)
        if lv < 10 then lv = 10 end
        if lv > 300 then lv = 300 end
        -- rounds to multiple of 10 (same as Options)
        lv = math.floor((lv + 5) / 10) * 10
        if lv < 10 then lv = 10 end
        if lv > 300 then lv = 300 end
        tournament.life = lv
    end
    if data.difficulty ~= nil then tournament.difficulty = data.difficulty end
    if data.showVsScreen ~= nil then tournament.showVsScreen = data.showVsScreen end
    if data.teamMode ~= nil then tournament.teamMode = data.teamMode end
    if data.teamSize ~= nil then tournament.teamSize = data.teamSize end
    if type(data.title) == "string" and data.title ~= "" then tournament.title = data.title end
    if data.subtitle == "Championship" or data.subtitle == "Cup" then tournament.subtitle = data.subtitle end
    if data.format ~= nil then tournament.format = data.format end
    if data.bgOpacity ~= nil then tournament.bgOpacity = data.bgOpacity end
    if data.bgChoice ~= nil then
        -- Accepts canonical keys ("select", "original", ...) and the menu
        -- display labels ("Module", "Screenpack Select", ...), incl. legacy
        -- "Module2". Anything else keeps the current value.
        local c = tostring(data.bgChoice):lower()
        local keyOf = {
            select = "select", versus = "versus", title = "title",
            options = "options", original = "original", original2 = "original2",
            module2 = "original2",
            ["module"] = "original", ["module 2"] = "original2",
            ["screenpack select"] = "select", ["screenpack versus"] = "versus",
            ["screenpack title"] = "title", ["screenpack options"] = "options",
        }
        if keyOf[c] ~= nil then tournament.bgChoice = keyOf[c] end
    end
    if data.useOriginalPortraitBg ~= nil then
        tournament.useOriginalPortraitBg = (data.useOriginalPortraitBg == true)
    end
    if data.portraitScale ~= nil then tournament.portraitScale = tonumber(data.portraitScale) or tournament.portraitScale end
    if data.portraitBgScale ~= nil then tournament.portraitBgScale = tonumber(data.portraitBgScale) or tournament.portraitBgScale end
    if data.cursorScale ~= nil then tournament.cursorScale = tonumber(data.cursorScale) or tournament.cursorScale end
    if data.randomScale ~= nil then tournament.randomScale = tonumber(data.randomScale) or tournament.randomScale end
    if data.musicEnabled ~= nil then tournament.musicEnabled = (data.musicEnabled == true) end
    if data.padIcons ~= nil then
        if tostring(data.padIcons):lower() == "playstation" then tournament.padIcons = "Playstation"
        else tournament.padIcons = "Xbox" end
    end
    if data.language ~= nil then
        local lg = tostring(data.language)
        if lg == "ptBR" or lg == "pt-BR" or lg == "pt" then tournament.language = "ptBR"
        else tournament.language = "en" end
    end
    if data.nextFightArrows ~= nil then
        local na = tostring(data.nextFightArrows):lower()
        if na == "red" then tournament.nextFightArrows = "Red"
        elseif na == "none" then tournament.nextFightArrows = "None"
        else tournament.nextFightArrows = "Blue" end
    end
    if data.trophySprite ~= nil then
        local ts = math.floor(tonumber(data.trophySprite) or 0)
        if ts < -1 then ts = -1 end
        if ts > 2 then ts = 2 end
        tournament.trophySprite = ts
    end
    if data.portraitBgSprite ~= nil then
        local ps = tonumber(data.portraitBgSprite) or 1
        if ps < 1 then ps = 1 end
        if ps > 3 then ps = 3 end
        tournament.portraitBgSprite = ps
        cellBgAnim = nil  -- forces reload of the bg anim
    end
    if data.screenpackBgScale ~= nil then
        local ss = tonumber(data.screenpackBgScale) or 1
        if ss < 0.01 then ss = 0.01 end
        if ss > 5 then ss = 5 end
        tournament.screenpackBgScale = ss
    end
    if data.stagePortraitScale ~= nil then
        local sps = tonumber(data.stagePortraitScale) or 1
        if sps < 0.01 then sps = 0.01 end
        if sps > 5 then sps = 5 end
        tournament.stagePortraitScale = sps
    end
    if type(data.charPortraitScales) == "table" then
        -- Compact: older multi-key saves could hold 8+ entries per char and
        -- crash f_serializeTable (registry overflow). Keep one key per
        -- normalized basename (prefer canon "chars/.../*.def").
        local compact, bestKey = {}, {}
        for k, v in pairs(data.charPortraitScales) do
            local n = tonumber(v)
            if type(k) == "string" and n and n > 0 then
                local b = nil
                if type(f_charPortraitScaleNormBase) == "function" then
                    b = f_charPortraitScaleNormBase(k)
                end
                if not b then b = k end
                local prev = bestKey[b]
                local prefer = (type(k) == "string" and k:find("chars/", 1, true) and k:lower():find("%.def", 1, true))
                if prev == nil or prefer then
                    if prev and compact[prev] then compact[prev] = nil end
                    bestKey[b] = k
                    compact[k] = n
                end
            end
        end
        tournament.charPortraitScales = compact
        tournamentCharPortraitScaleBaseIndex = nil
    end
    -- Anim store (Action 0 + win poses): same one-key discipline (canon key
    -- written by the editor, so no compact pass needed on load).
    if type(data.charAnimPortraitScales) == "table" then
        tournament.charAnimPortraitScales = data.charAnimPortraitScales
        tournamentCharAnimPortraitScaleBaseIndex = nil
    end
    -- NOTE: data.charLocalcoordCache (older saves) is deliberately ignored: the
    -- char .def values (localcoord, portraitscale) are read live each boot and
    -- never stored; the JSON keeps only the user's own charPortraitScales.
    -- screenMode in JSON: used ONLY to detect SD->HD switch (anims reset).
    -- Layout stays automatic by height.
    local savedMode = nil
    if data.screenMode ~= nil then
        local sm = tostring(data.screenMode):upper()
        if sm == "SD" or sm == "HD" then savedMode = sm end
    end
    if data.musicVolume ~= nil then
        local mv = tonumber(data.musicVolume) or tournament.musicVolume
        if mv < 0 then mv = 0 end
        if mv > 100 then mv = 100 end
        tournament.musicVolume = mv
    end
    -- Per-track volumes (old saves: seed from the single legacy volume).
    do
        local legacyVol = tonumber(tournament.musicVolume) or 100
        local function loadTrackVolume(key, field)
            local v = tonumber(data[key])
            if v == nil then v = legacyVol end
            if v < 0 then v = 0 end
            if v > 100 then v = 100 end
            tournament[field] = v
        end
        loadTrackVolume("menuMusicVolume", "menuMusicVolume")
        loadTrackVolume("bracketEditMusicVolume", "bracketEditMusicVolume")
        loadTrackVolume("bracketMusicVolume", "bracketMusicVolume")
        loadTrackVolume("resultsMusicVolume", "resultsMusicVolume")
    end
    if data.menuMusicTrack ~= nil then
        local mt = math.floor(tonumber(data.menuMusicTrack) or 1)
        if mt < 1 then mt = 1 end
        if mt > (TOURNAMENT_MUSIC_COUNT or 5) then mt = (TOURNAMENT_MUSIC_COUNT or 5) end
        tournament.menuMusicTrack = mt
    end
    if data.bracketEditMusicTrack ~= nil then
        local et = math.floor(tonumber(data.bracketEditMusicTrack) or 2)
        if et < 1 then et = 1 end
        if et > (TOURNAMENT_MUSIC_COUNT or 5) then et = (TOURNAMENT_MUSIC_COUNT or 5) end
        tournament.bracketEditMusicTrack = et
    end
    if data.bracketMusicTrack ~= nil then
        local bt = math.floor(tonumber(data.bracketMusicTrack) or 3)
        if bt < 1 then bt = 1 end
        if bt > (TOURNAMENT_MUSIC_COUNT or 5) then bt = (TOURNAMENT_MUSIC_COUNT or 5) end
        tournament.bracketMusicTrack = bt
    end
    if data.resultsMusicTrack ~= nil then
        local rt = math.floor(tonumber(data.resultsMusicTrack) or 4)
        if rt < 1 then rt = 1 end
        if rt > (TOURNAMENT_MUSIC_COUNT or 5) then rt = (TOURNAMENT_MUSIC_COUNT or 5) end
        tournament.resultsMusicTrack = rt
    end
    if data.showAnimatedPortraitsBg ~= nil then
        tournament.showAnimatedPortraitsBg = (data.showAnimatedPortraitsBg ~= false)
    end
    if data.musicTrack ~= nil and data.menuMusicTrack == nil and data.bracketMusicTrack == nil then
        -- Old save (single track): preserves the choice in both
        local mt = math.floor(tonumber(data.musicTrack) or 1)
        if mt < 1 then mt = 1 end
        if mt > (TOURNAMENT_MUSIC_COUNT or 5) then mt = (TOURNAMENT_MUSIC_COUNT or 5) end
        tournament.menuMusicTrack = mt
        tournament.bracketMusicTrack = mt
    end
    if data.showAnimatedPortraits ~= nil then
        tournament.showAnimatedPortraits = (data.showAnimatedPortraits == true)
    end
    if data.showBigPortraits ~= nil then
        tournament.showBigPortraits = (data.showBigPortraits == true)
    end
    if data.autoSave ~= nil then
        tournament.autoSave = (data.autoSave ~= false)
    end
    if data.showRemaining ~= nil then
        tournament.showRemaining = (data.showRemaining == true)
    end
    -- Save-based SD->HD reset: save made at 480 forces OFF and saves; when opening at 720+,
    -- saved OFF must not leak. Back to ON (HD default) + SIZE 128 (HD default).
    do
        local curH = nil
        if type(f_getScreenHeight) == "function" then
            local okH, vH = pcall(f_getScreenHeight)
            if okH and tonumber(vH) then curH = tonumber(vH) end
        end
        if curH == nil then curH = _screenH end
        local curMode = (curH == 480) and "SD" or "HD"
        if savedMode == "SD" and curMode == "HD" then
            tournament.showAnimatedPortraits = true
            tournament.showAnimatedPortraitsBg = true
            tournament.nextFightArrows = "Blue"
            tournament.size = 128
            print("[Tournament] Resolution SD->HD (save): SHOW ANIMATED PORTRAITS/BGS reset to ON, ARROWS reset to Blue, SIZE reset to 128")
        end
    end
    if type(f_updateTournamentMusicPath) == "function" then
        pcall(f_updateTournamentMusicPath, "menu")
    end
    if data.characterPool ~= nil then
        -- Purges stale "randomselect" entries from old saves (not a real char).
        -- Inline check (no helper: this load runs before helpers below are defined).
        if type(data.characterPool) == "table" then
            for k, _ in pairs(data.characterPool) do
                if type(k) == "string" then
                    local low = string.lower(k:gsub("\\", "/"))
                    if low == "randomselect" or (low:match("([^/]+)$") or low) == "randomselect" then
                        data.characterPool[k] = nil
                    end
                end
            end
        end
        characterPool = data.characterPool
        characterPoolInitialized = false
        if main and main.t_selGrid and type(main.t_selGrid) == "table" and #main.t_selGrid > 0 then
            pcall(function()
                if type(f_initializeCharacterPool) == "function" then
                    f_initializeCharacterPool()
                end
            end)
        end
    end
    if type(data.cpuFlagPool) == "table" then
        tournament.cpuFlagPool = data.cpuFlagPool
        cpuFlagPoolInitialized = false
    end
    --if type(f_applyVisualSettingsToMotif) == "function" then
    --    pcall(f_applyVisualSettingsToMotif)
    --end
    -- Ensures HD/SD layout consistent with tournament.screenMode
    if type(f_applyLayoutMode) == "function" then
        pcall(f_applyLayoutMode)
    end
    print("[Tournament] Settings loaded successfully.")
end

local function f_saveTournamentState(bracket, roundNum, p1Ref, playerAlive)
    local state = {
        size = tournament.size,
        rounds = tournament.rounds,
        roundNum = roundNum,
        p1Ref = p1Ref,
        playerAlive = playerAlive,
        bracket = bracket,
        teamMode = tournament.teamMode,
        teamSize = tournament.teamSize,
        playerTeam = tournament.playerTeam,
        cpuTeams = tournament.cpuTeams,
        playerPals = tournament.playerPals,
        cpuPals = tournament.cpuPals,
        humanTeams = tournament.humanTeams,
        humanPals = tournament.humanPals,
        humanPlayers = tournament.humanPlayers,
        humanIds = tournament.humanIds,
        humanFlags = tournament.humanFlags,
        cpuFlags = tournament.cpuFlags,
        useHumanIds = tournament.useHumanIds,
        cpuIds = tournament.cpuIds,
        allowRandomCpuIds = tournament.allowRandomCpuIds,
        randomHumanIds = tournament.randomHumanIds,
        randomCharsForHumans = tournament.randomCharsForHumans,
        -- Extra fields for the Main Settings panel (SLOT/CONTINUE)
        title = tournament.title,
        subtitle = tournament.subtitle,
        format = tournament.format,
        thirdPlacePlayoff = tournament.thirdPlacePlayoff,
        allowDuplicateChars = tournament.allowDuplicateChars,
        allowRandomCpuPalette = tournament.allowRandomCpuPalette,
        -- Summary ready for display (names resolved at save time)
        summary = (type(f_buildTournamentSummary) == "function")
            and f_buildTournamentSummary(bracket, roundNum, tournament.size) or nil,
        -- Finished save (champion decided): panel shows FINISHED + podium
        finished = (bracket ~= nil and bracket.champion ~= nil) or nil,
    }
    if createDir then createDir("save") end
    -- Unified file: state stored in memory under states["<slot>"], one write.
    local slotNum = f_normalizeStateSlot()
    local td = f_ensureTournamentData()
    if type(td.states) ~= "table" then td.states = {} end
    td.states[tostring(slotNum)] = state
    f_flushTournamentData()
    print("[Tournament] Tournament state saved (slot " .. tostring(slotNum) .. ").")
end

-- Bracket auto-save: respects Advanced Settings > AUTO-SAVE.
-- OFF => does not auto-save (manual save via key in bracket).
-- (Global: the main chunk has a 200 locals limit.)
function f_autoSaveTournamentState(bracket, roundNum, p1Ref, playerAlive)
    -- Auto-save ALWAYS (no toggle): every bracket screen writes slot 0.
    -- tournament.saveSlot (manual slot) is preserved across the write.
    local prevSlot = tournament and tournament.saveSlot
    if tournament then tournament.saveSlot = 0 end
    f_saveTournamentState(bracket, roundNum, p1Ref, playerAlive)
    if tournament then tournament.saveSlot = prevSlot end
end

local function f_hasSavedTournament(slot)
    -- Unified: in-memory lookup, no file IO per slot (fixes preview cost +
    -- wrong-path class of bugs). Legacy files still count until migrated.
    local slotNum = f_normalizeStateSlot(slot)
    local td = f_ensureTournamentData()
    if td and type(td.states) == "table" then
        local st = td.states[tostring(slotNum)]
        if type(st) == "table" and st.bracket then return true end
    end
    local savePath = f_getTournamentSavePath(slotNum)
    local file = io.open(savePath, "r")
    if file then file:close(); return true end
    -- Legacy fallback: old single save counts as slot 1
    if slotNum == 1 then
        local legacy = io.open(tournamentSavePath, "r")
        if legacy then legacy:close(); return true end
    end
    return false
end

local function f_clearSavedTournament(slot)
    -- Unified: drop from memory + one write. Also removes legacy files.
    local slotNum = f_normalizeStateSlot(slot)
    local td = f_ensureTournamentData()
    if td and type(td.states) == "table" then
        td.states[tostring(slotNum)] = nil
    end
    f_flushTournamentData()
    local savePath = f_getTournamentSavePath(slotNum)
    if os and os.remove then
        os.remove(savePath)
        if slotNum == 1 then os.remove(tournamentSavePath) end -- clears legacy too
    else
        local file = io.open(savePath, "w")
        if file then file:write(""); file:close() end
    end
    print("[Tournament] In-progress tournament save removed/cleared.")
end

local function f_loadTournamentState(slot)
    -- Unified: in-memory lookup (no per-slot path to get wrong).
    local slotNum = f_normalizeStateSlot(slot)
    local td = f_ensureTournamentData()
    if td and type(td.states) == "table" then
        local st = td.states[tostring(slotNum)]
        if type(st) == "table" and st.bracket then return st end
    end
    -- Legacy fallback (pre-migration files still on disk).
    local savePath = f_getTournamentSavePath(slotNum)
    local data = f_readJsonFile(savePath)
    if type(data) == "table" and data.bracket then return data end
    if slotNum == 1 then
        data = f_readJsonFile(tournamentSavePath)
        if type(data) == "table" and data.bracket then return data end
    end
    return nil
end

-- Normalizes char path for comparison (select.def vs save)
-- E.g.: "05 - Marvel\CapAmerica\CapAmerica.def"
--   == "chars/05 - Marvel/CapAmerica/CapAmerica.def"
local function f_normalizeCharPath(p)
    if type(p) == "table" then p = p.path end
    if type(p) ~= "string" then return "" end
    -- swaps any backslash to /
    p = string.gsub(p, "\\", "/")
    p = string.gsub(p, "^%s+", "")
    p = string.gsub(p, "%s+$", "")
    p = string.gsub(p, "^%./", "")
    local lower = string.lower(p)
    if string.sub(lower, 1, 6) == "chars/" then
        p = string.sub(p, 7)
        lower = string.lower(p)
    end
    return lower
end

local function f_charPathMatchKeys(p)
    local n = f_normalizeCharPath(p)
    local keys = {}
    if n == "" then return keys end
    keys[n] = true
    local base = n:match("([^/]+)$")
    if base and base ~= "" then keys[base] = true end
    -- no extension
    if base then
        local noext = base:gsub("%.[^%.]+$", "")
        if noext ~= "" then keys[noext] = true end
    end
    return keys
end

local function f_collectPathsFromSaveData(data)
    local paths = {}
    local function add(p)
        if type(p) == "table" then p = p.path end
        if type(p) ~= "string" or p == "" then return end
        if p == "PLAYER" or p == "PLAYER1" or p == "PLAYER2" or p == "PLAYER3" or p == "PLAYER4" then return end
        -- numeric CPU participant ids are not paths
        if tonumber(p) then return end
        paths[p] = true
    end
    if type(data) ~= "table" then return paths end
    if type(data.playerTeam) == "table" then
        for _, p in ipairs(data.playerTeam) do add(p) end
    end
    if type(data.humanTeams) == "table" then
        for _, team in pairs(data.humanTeams) do
            if type(team) == "table" then
                for _, p in ipairs(team) do add(p) end
            end
        end
    end
    if type(data.cpuTeams) == "table" then
        for _, team in pairs(data.cpuTeams) do
            if type(team) == "table" then
                for _, p in ipairs(team) do add(p) end
            end
        end
    end
    local br = data.bracket
    if type(br) == "table" and type(br.rounds) == "table" then
        for _, rd in pairs(br.rounds) do
            for _, side in ipairs({ "left", "right" }) do
                for _, m in ipairs((rd and rd[side]) or {}) do
                    if m then add(m.a); add(m.b); add(m.winner) end
                end
            end
        end
        if br.champion then add(br.champion) end
        if br.thirdPlaceMatch then
            add(br.thirdPlaceMatch.a); add(br.thirdPlaceMatch.b); add(br.thirdPlaceMatch.winner)
        end
        if br.thirdPlaceWinner then add(br.thirdPlaceWinner) end
    end
    return paths
end

local function f_buildValidCharKeySet()
    local keySet = {}
    local nValid = 0
    if type(f_getValidCharData) == "function" and main and main.t_selGrid then
        local ok, chars = pcall(f_getValidCharData, true)
        if ok and type(chars) == "table" then
            for _, c in ipairs(chars) do
                if c and type(c.path) == "string" then
                    nValid = nValid + 1
                    for k, _ in pairs(f_charPathMatchKeys(c.path)) do
                        keySet[k] = true
                    end
                end
            end
        end
    end
    -- Fallback: scans t_selGrid directly if list came empty
    -- (all refs per cell: multi-char slots list every char).
    if nValid == 0 and main and type(main.t_selGrid) == "table" and start and type(start.f_selGrid) == "function" then
        for i = 1, #main.t_selGrid do
            local entry = start.f_selGrid(i)
            if entry and entry.char ~= nil then
                local refs = {}
                local cell = main.t_selGrid[i]
                if type(cell) == "table" and type(cell.chars) == "table" then
                    for _, r in ipairs(cell.chars) do
                        local n = tonumber(r)
                        if n ~= nil then refs[#refs + 1] = n end
                    end
                end
                if entry.char_ref ~= nil then
                    local n = tonumber(entry.char_ref)
                    if n ~= nil then refs[#refs + 1] = n end
                end
                for _, cref in ipairs(refs) do
                    local charData = start.f_getCharData and start.f_getCharData(cref) or nil
                    local rawPath = (charData and charData.char) or tostring(entry.char)
                    nValid = nValid + 1
                    for k, _ in pairs(f_charPathMatchKeys(rawPath)) do
                        keySet[k] = true
                    end
                end
            end
        end
    end
    return keySet, nValid
end

local function f_pathExistsInSelect(path, keySet)
    if not path or path == "" then return true end
    for k, _ in pairs(f_charPathMatchKeys(path)) do
        if keySet[k] then return true end
    end
    -- suffix match: save "a/b/c.def" vs valid "chars/a/b/c.def" already covered by normalization;
    -- still tries ends-with on full normalized path
    local n = f_normalizeCharPath(path)
    if n ~= "" then
        for vk, _ in pairs(keySet) do
            if type(vk) == "string" and (#vk > 4) and (vk:sub(-#n) == n or n:sub(-#vk) == vk) then
                return true
            end
        end
    end
    return false
end

local function f_validateTournamentSave(data)
    if type(data) ~= "table" or type(data.bracket) ~= "table" then
        return false, { "(no bracket data)" }
    end
    local keySet, nValid = f_buildValidCharKeySet()
    -- If select has not loaded chars yet, do not block (avoids false positive)
    if nValid == 0 then
        print("[Tournament] Save validation: select grid empty ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â skipping path check.")
        return true, {}
    end
    local missing = {}
    for path, _ in pairs(f_collectPathsFromSaveData(data)) do
        if not f_pathExistsInSelect(path, keySet) then
            missing[#missing + 1] = path
        end
    end
    table.sort(missing)
    if #missing > 0 then
        print(string.format("[Tournament] Save: %d path(s) not found in select.def (ex: %s)",
            #missing, tostring(missing[1])))
    end
    return #missing == 0, missing
end

local function f_getSaveValidationStatus(slot)
    if not f_hasSavedTournament(slot) then
        return false, false, {}
    end
    local data = f_loadTournamentState(slot)
    if not data then return true, false, { "(corrupt save)" } end
    local ok, missing = f_validateTournamentSave(data)
    return true, ok, missing
end

