-- =====================================================================
-- GLOBAL CACHE VARIABLES
-- =====================================================================
local cellBgSff = nil
-- cellBgAnim / skeletonCache / bracketAnimCache / trophyAnimCache: forward no bloco de layout
local cellDataCache = {}
local originalAnimStates = {}

-- =====================================================================
-- NATIVE BACKGROUND (choice: Select / Versus / Title / Options)
-- Everything in ONE local table to avoid blowing the Lua locals limit (~200).
-- =====================================================================
local tournamentBgSys = {
    lastDrawn = nil,
    order = { "select", "versus", "title", "options", "original", "original2" },
    label = {
        select = "Screenpack Select",
        versus = "Screenpack Versus",
        title = "Screenpack Title",
        options = "Screenpack Options",
        original = "Module",
        original2 = "Module 2",
    },
    -- Menu display order + display->canonical map (UI shows pretty names,
    -- engine always stores the canonical key).
    choices = { "Module", "Module 2", "Screenpack Select", "Screenpack Versus", "Screenpack Title", "Screenpack Options" },
    choiceKey = {
        ["Module"] = "original",
        ["Module 2"] = "original2",
        ["Screenpack Select"] = "select",
        ["Screenpack Versus"] = "versus",
        ["Screenpack Title"] = "title",
        ["Screenpack Options"] = "options",
    },
    defs = {
        select = motif.selectbgdef and motif.selectbgdef.BGDef,
        options = motif.optionbgdef and motif.optionbgdef.BGDef,
        title = (motif.titlebgdef and motif.titlebgdef.BGDef)
            or (motif.title_info and motif.title_info.BGDef),
        versus = (motif.versusbgdef and motif.versusbgdef.BGDef)
            or (motif.vsbgdef and motif.vsbgdef.BGDef)
            or (motif.vs_info and motif.vs_info.BGDef),
    },
    -- Sprites dedicados (TournamentMode.sff group 5: index 0 and 1)
    originalSprites = { original = "5,0", original2 = "5,1" },
    originalAnims = {},  -- choice -> anim | false (cache por sprite)
}
do
    for _, bg in pairs(tournamentBgSys.defs) do
        if bg and bgReset then pcall(bgReset, bg) end
    end
end
-- Canonical key for anything the user/saves may carry: canonical keys pass
-- through, menu labels map back, legacy "Module2" (no space) included.
tournamentBgSys.toKey = function(v)
    if type(v) ~= "string" then return nil end
    local low = v:lower()
    for _, key in ipairs(tournamentBgSys.order) do
        if key == low then return key end
    end
    for label, key in pairs(tournamentBgSys.choiceKey) do
        if label:lower() == low then return key end
    end
    if low == "module2" then return "original2" end
    return nil
end
tournamentBgSys.toLabel = function(key)
    key = tournamentBgSys.toKey(key) or "original"
    for label, k in pairs(tournamentBgSys.choiceKey) do
        if k == key then return label end
    end
    return key
end
tournamentBgSys.getDef = function(choice)
    choice = tournamentBgSys.toKey(choice) or "select"
    if choice == "original" or choice == "original2" then return nil end  -- own sprites, not BGDef
    local d = tournamentBgSys.defs
    local bg = d[choice]
    if bg then return bg end
    if choice == "versus" then
        return (motif and motif.versusbgdef and motif.versusbgdef.BGDef)
            or (motif and motif.vsbgdef and motif.vsbgdef.BGDef)
    elseif choice == "title" then
        return motif and motif.titlebgdef and motif.titlebgdef.BGDef
    elseif choice == "options" then
        return motif and motif.optionbgdef and motif.optionbgdef.BGDef
    end
    return d.select or (motif and motif.selectbgdef and motif.selectbgdef.BGDef)
end

tournamentBgSys.getOriginalAnim = function(choice)
    choice = tostring(choice or "original"):lower()
    local spr = tournamentBgSys.originalSprites[choice]
    if not spr then return nil end
    if tournamentBgSys.originalAnims[choice] ~= nil then
        return tournamentBgSys.originalAnims[choice] or nil
    end
    local sff = f_loadTournamentSff()
    if not sff then tournamentBgSys.originalAnims[choice] = false; return nil end
    local air = spr .. ", 0,0, -1"
    local ok, anim = pcall(animNew, sff, air)
    if ok and anim and type(anim) == "userdata" then
        tournamentBgSys.originalAnims[choice] = anim
        -- module reference space (1280x720)
        if animSetLocalcoord then
            pcall(animSetLocalcoord, anim, TOURNAMENT_REFERENCE_WIDTH, TOURNAMENT_REFERENCE_HEIGHT)
        end
        if animSetScale then pcall(animSetScale, anim, layout.TournamentOriginalBGScale, layout.TournamentOriginalBGScale) end
        if animSetPos then pcall(animSetPos, anim, 0, 0) end
    else
        tournamentBgSys.originalAnims[choice] = false
    end
    return tournamentBgSys.originalAnims[choice] or nil
end

tournamentBgSys.draw = function()
    local choice = tournamentBgSys.toKey(tournament.bgChoice) or "select"

    -- Own mod backgrounds (SFF sprites 5,0 and 5,1)
    if tournamentBgSys.originalSprites[choice] then
        local anim = tournamentBgSys.getOriginalAnim(choice)
        if anim then
            if animUpdate then pcall(animUpdate, anim) end
            if animSetPos then pcall(animSetPos, anim, 0, 0) end
            pcall(animDraw, anim)
        end
        tournamentBgSys.lastDrawn = choice
        return
    end

    local bg = tournamentBgSys.getDef(choice)
    if not bg then
        for _, c in ipairs(tournamentBgSys.order) do
            if not tournamentBgSys.originalSprites[c] then
                bg = tournamentBgSys.getDef(c)
                if bg then choice = c; break end
            end
        end
    end
    if not bg then return end
    if choice ~= tournamentBgSys.lastDrawn then
        if bgReset then pcall(bgReset, bg) end
        tournamentBgSys.lastDrawn = choice
    end
    pcall(bgDraw, bg, 0)
end


-- =====================================================================
-- LOADS SYSTEM SFF
-- =====================================================================
local function f_loadSystemSff()
    if cellBgSff ~= nil then return cellBgSff end
    if motif.files and motif.files.spr_data then
        cellBgSff = motif.files.spr_data
        return cellBgSff
    end
    local candidates = {}
    if motif.files and motif.files.spr then table.insert(candidates, motif.files.spr) end
    table.insert(candidates, "system.sff")
    table.insert(candidates, "data/system.sff")
    for _, p in ipairs(candidates) do
        local ok, s = pcall(sffNew, p)
        if ok and s then cellBgSff = s; return s end
    end
    return nil
end

