local _overlay = { anim = nil, tried = false, bgAnim = nil, bgTried = false }
local function f_getOverlayAnim()
    if _overlay.tried then return _overlay.anim end
    _overlay.tried = true
    local sff = f_loadTournamentSff()
    if not sff then return nil end
    local air = TOURNAMENT_OVERLAY.group .. "," .. TOURNAMENT_OVERLAY.number .. ", 0,0, -1"
    local ok, anim = pcall(animNew, sff, air)
    if ok and anim and type(anim) == "userdata" then _overlay.anim = anim end
    return _overlay.anim
end
