    if _overlay.bgTried then return _overlay.bgAnim end
    _overlay.bgTried = true
    local sff = f_loadTournamentSff()
    if not sff then return nil end
    local air = TOURNAMENT_OVERLAY_BG.group .. "," .. TOURNAMENT_OVERLAY_BG.number .. ", 0,0, -1, , A1"
    local ok, anim = pcall(animNew, sff, air)
    if ok and anim and type(anim) == "userdata" then _overlay.bgAnim = anim end
