-- Bracket trophy (TournamentMode.sff group 3, sprites 0/1/2).
-- One cached anim per sprite; choice comes from tournament.trophySprite.
-- trophyAnimCache: declarado no bloco de layout (f_applyLayoutMode clears when switching HD/SD)
local function f_getTrophyBgAnim(spriteNum, trans)
    spriteNum = tonumber(spriteNum) or 0
    if spriteNum < 0 then spriteNum = 0 end
    if spriteNum > 2 then spriteNum = 2 end
    -- optional trans (e.g.: final screen): separate cache to avoid mixing
    local key = spriteNum
    if trans == "A" or trans == "A1" or trans == "S" then
        key = trans .. spriteNum
    else
        trans = nil
    end
    local cached = trophyAnimCache[key]
    if cached ~= nil then return cached or nil end
    local sff = f_loadTournamentSff()
    if not sff then trophyAnimCache[key] = false; return nil end
    local air = "3," .. tostring(spriteNum) .. ", 0,0, -1"
    if trans then air = air .. ", , " .. trans end
    local ok, anim = pcall(animNew, sff, air)
    if ok and anim and type(anim) == "userdata" then
        trophyAnimCache[key] = anim
    else
        trophyAnimCache[key] = false
    end
    return trophyAnimCache[key] or nil
end

-- bracketAnimCache: declarado no bloco de layout (f_applyLayoutMode clears when switching HD/SD)
local function f_getBracketAnimByNumber(number)
    if bracketAnimCache[number] ~= nil then return bracketAnimCache[number] or nil end
    local sff = f_loadTournamentSff()
    if not sff then bracketAnimCache[number] = false; return nil end
    local group = tonumber(layout.bracketGroup) or 2
    local air = group .. "," .. number .. ", 0,0, -1"
    local ok, anim = pcall(animNew, sff, air)
    if ok and anim and type(anim) == "userdata" then
        bracketAnimCache[number] = anim
    else
        bracketAnimCache[number] = false
    end
    return bracketAnimCache[number] or nil
end

-- =====================================================================
-- TEAM MODE ICONS (from the tournament SFF: TournamentMode.sff)
-- Sprites: 0,0 = normal icon (filled) | 0,1 = empty icon (empty)
-- =====================================================================
local TEAM_ICON_SPR_FILLED = {0, 0}  -- normal icon
local TEAM_ICON_SPR_EMPTY  = {0, 1}  -- empty icon
local teamIconCache = nil
local function f_getTeamIcons()
    if teamIconCache then return teamIconCache.red, teamIconCache.white, teamIconCache.scale end
    local scale = 1  -- tournament SFF icons already come at final size
    local redAnim, whiteAnim = nil, nil
    local sff = f_loadTournamentSff()
    if sff then
        local ok1, a1 = pcall(animNew, sff, TEAM_ICON_SPR_FILLED[1] .. "," .. TEAM_ICON_SPR_FILLED[2] .. ", 0,0, -1")
        if ok1 and a1 and type(a1) == "userdata" then redAnim = a1 end
        local ok2, a2 = pcall(animNew, sff, TEAM_ICON_SPR_EMPTY[1] .. "," .. TEAM_ICON_SPR_EMPTY[2] .. ", 0,0, -1")
        if ok2 and a2 and type(a2) == "userdata" then whiteAnim = a2 end
    end
    teamIconCache = { red = redAnim, white = whiteAnim, scale = scale }
    return redAnim, whiteAnim, scale
end

-- =====================================================================
-- POSITION RESTORE
-- =====================================================================
-- kind: "portrait" | "bg" | "cursor" ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â defines which scale to restore
local function f_resetWarp(anim)
    if not anim then return end
    if animSetAngle then pcall(animSetAngle, anim, 0) end
    if animSetXAngle then pcall(animSetXAngle, anim, 0) end
    if animSetYAngle then pcall(animSetYAngle, anim, 0) end
    if animSetXShear then pcall(animSetXShear, anim, 0) end
end

local function f_backupOriginalState(anim, kind)
    if not anim or originalAnimStates[anim] then return end
    kind = kind or "portrait"
    local scale
    if kind == "bg" then
        scale = tournament.portraitBgScale or _portraitBgScale or 1
    elseif kind == "cursor" then
        scale = tournament.cursorScale or _cursorScale or 1
    else
        -- Native motif (e.g.: 0.25) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â select grid needs it back
        scale = _portraitScale or 1
    end
    originalAnimStates[anim] = {
        x = 0, y = 0, facing = 1,
        scaleX = scale, scaleY = scale,
        kind = kind,
    }
end

local function f_restoreOriginalAnimStates()
    -- Bracket cell fast-path baked the pre-restore transforms (pool/scales
    -- screens mutate + restore the same anims): drop it, so the next bracket
    -- draw re-runs the full setup once and re-marks.
    tournamentPortraitPlaced = {}
    -- Restaura pos/facing/scale/PalFX (escalas nativas do system.def / motif)
    local pScale  = _portraitScale or 1
    local bgScale = tournament.portraitBgScale or _portraitBgScale or 1
    local cScale  = tournament.cursorScale or _cursorScale or 1

    for anim, state in pairs(originalAnimStates) do
        if anim and type(anim) == "userdata" then
            pcall(animSetPos, anim, state.x or 0, state.y or 0)
            if animSetFacing then pcall(animSetFacing, anim, state.facing or 1) end
            if animSetScale then
                local sx, sy
                if state.kind == "bg" then
                    sx, sy = bgScale, bgScale
                elseif state.kind == "cursor" then
                    sx, sy = cScale, cScale
                else
                    -- portrait: always restores the motif scale (not the tournament one)
                    sx = state.scaleX or pScale
                    sy = state.scaleY or pScale
                end
                pcall(animSetScale, anim, sx, sy)
            end
            -- Returns the native motif localcoord (live, not the load-time
            -- capture): these anims are the same that the native select
            -- screen reuses later.
            if animSetLocalcoord and type(f_motifLocalcoordNow) == "function" then
                local mw, mh = f_motifLocalcoordNow()
                if mw and mh then pcall(animSetLocalcoord, anim, mw, mh) end
            end
            if animSetPalFX then
                pcall(animSetPalFX, anim, normalPalFX or {
                    time = -1, add = {0,0,0}, mul = {256,256,256},
                    sinadd = {0,0,0,0}, invertall = 0, color = 256
                })
            end
        end
    end
    originalAnimStates = {}
end

-- =====================================================================
-- GERENCIAMENTO DO CHARACTER POOL
-- =====================================================================
-- 1. Forward declaration so functions can reference each other
local f_initializeCharacterPool
local f_isCharacterEnabled
local f_getValidCharData

-- Syncs characterPool with select.def / t_selGrid (removes JSON ghosts).
local function f_syncCharacterPoolWithSelectGrid()
    if type(f_getValidCharData) ~= "function" then return false end
    if not (main and main.t_selGrid and type(main.t_selGrid) == "table") then return false end
    local ok, validChars = pcall(f_getValidCharData, true)
    if not ok or type(validChars) ~= "table" then return false end

    local oldByLower = {}
    for path, enabled in pairs(characterPool) do
        if type(path) == "string" then
            oldByLower[string.lower(path)] = (enabled ~= false)
        end
    end

    local newPool = {}
    local kept, added, seenLower = 0, 0, {}
    for _, char in ipairs(validChars) do
        local path = char and char.path
        if type(path) == "string" and path ~= "" then
            local low = string.lower(path)
            if not seenLower[low] then
                seenLower[low] = true
                if oldByLower[low] ~= nil then
                    newPool[path] = oldByLower[low]
                    kept = kept + 1
                else
                    newPool[path] = true
                    added = added + 1
                end
            end
        end
    end

    local removed = 0
    for path, _ in pairs(characterPool) do
        if type(path) == "string" and not seenLower[string.lower(path)] then
            removed = removed + 1
        end
    end

    characterPool = newPool
    characterPoolInitialized = true
    -- Log only when the roster actually changed (counts call init every frame).
    if added > 0 or removed > 0 then
        print(string.format(
            "[Tournament] Pool sync select.def: total=%d kept=%d added=%d removed=%d",
            kept + added, kept, added, removed
        ))
    end
    return true
end

f_initializeCharacterPool = function(force)
    if type(f_getValidCharData) ~= "function" then return end
    if not (main and main.t_selGrid and type(main.t_selGrid) == "table") then return end
    -- Lazy sync: menu counters call this EVERY frame, so a full 400+ entry
    -- rebuild per frame is pure waste. Rebuilds only when forced, never
    -- synced, or the grid changed (count + first/last refs fingerprint).
    -- (Slot switches/loads reset characterPoolInitialized, so they resync.)
    local g = main.t_selGrid
    local r1, rN = g[1], g[#g]
    if type(r1) == "table" then r1 = r1.char_ref end
    if type(rN) == "table" then rN = rN.char_ref end
    local fp = #g .. ":" .. tostring(r1) .. ":" .. tostring(rN)
    if characterPoolInitialized and force ~= true and fp == characterPoolGridFingerprint then return end
    if f_syncCharacterPoolWithSelectGrid() then
        characterPoolGridFingerprint = fp
    end
end

f_isCharacterEnabled = function(charPath)
    if not characterPoolInitialized then
        f_initializeCharacterPool()
    end
    if type(charPath) ~= "string" then return false end
    local v = characterPool[charPath]
    if v ~= nil then return v ~= false end
    local low = string.lower(charPath)
    for path, enabled in pairs(characterPool) do
        if type(path) == "string" and string.lower(path) == low then
            return enabled ~= false
        end
    end
    return false
end

local function f_toggleCharacter(charPath)
    if not characterPoolInitialized then
        f_initializeCharacterPool()
    end
    characterPool[charPath] = not f_isCharacterEnabled(charPath)
end

local function f_toggleAllCharacters()
    f_initializeCharacterPool()
    local anyEnabled = false
    for _, enabled in pairs(characterPool) do
        if enabled then anyEnabled = true; break end
    end
    local newVal = not anyEnabled
    for path, _ in pairs(characterPool) do
        characterPool[path] = newVal
    end
    return newVal
end

local function f_getEnabledCharacterCount()
    f_initializeCharacterPool()
    local count = 0
    for _, enabled in pairs(characterPool) do
        if enabled then count = count + 1 end
    end
    return count
end

local function f_getTotalCharacterCount()
    f_initializeCharacterPool()
    local count = 0
    for _ in pairs(characterPool) do
        count = count + 1
    end
    return count
end

-- =====================================================================
-- CHARACTER POOL SLOTS (presets saved in save/character_pools.json)
-- =====================================================================
local function f_copyPoolTable(src)
    local t = {}
    if type(src) ~= "table" then return t end
    for k, v in pairs(src) do
        t[k] = v
    end
    return t
end

local function f_ensureCharacterPoolSlots()
    if characterPoolsSlots then return end
    characterPoolsSlots = {}
    for i = 1, CHARACTER_POOL_SLOTS do
        characterPoolsSlots[i] = {
            name = "Default",
            pool = {},
        }
    end
    characterPoolsActive = 1
end

local function f_saveCharacterPools()
    f_ensureCharacterPoolSlots()
    local data = {
        active = characterPoolsActive,
        slots = {},
    }
    for i = 1, CHARACTER_POOL_SLOTS do
        local s = characterPoolsSlots[i] or { name = "Default", pool = {} }
        data.slots[i] = {
            name = s.name or "Default",
            pool = f_copyPoolTable(s.pool),
        }
    end
    -- Unified file: pools section updated in memory, single disk write.
    -- Legacy character_pools.json is NOT written anymore (migrated to .bak).
    local td = f_ensureTournamentData()
    td.characterPools = data
    f_flushTournamentData()
    print("[Tournament] Character pools saved (slot ativo=" .. tostring(characterPoolsActive) .. ")")
end

local function f_decodeJsonFile(path)
    local file = io.open(path, "r")
    if not file then return nil end
    local content = file:read("*a")
    file:close()
    if not content or content == "" then return nil end
    local data = nil
    if type(jsonDecode) == "function" then
        local ok, res = pcall(jsonDecode, content)
        if ok and type(res) == "table" then data = res end
        if not data then
            ok, res = pcall(jsonDecode, path)
            if ok and type(res) == "table" then data = res end
        end
    end
    if not data and json and type(json.decode) == "function" then
        local ok, res = pcall(json.decode, content)
        if ok and type(res) == "table" then data = res end
    end
    return data
end

local function f_applyCharacterPoolSlot(slotIndex)
    f_ensureCharacterPoolSlots()
    if slotIndex < 1 then slotIndex = 1 end
    if slotIndex > CHARACTER_POOL_SLOTS then slotIndex = CHARACTER_POOL_SLOTS end
    characterPoolsActive = slotIndex
    local slot = characterPoolsSlots[slotIndex]
    if not slot then
        slot = { name = "Default", pool = {} }
        characterPoolsSlots[slotIndex] = slot
    end
    characterPool = f_copyPoolTable(slot.pool)
    characterPoolInitialized = false
    if main and main.t_selGrid and type(main.t_selGrid) == "table" and #main.t_selGrid > 0 then
        pcall(f_initializeCharacterPool)
    end
end

local function f_saveCurrentPoolToActiveSlot()
    f_ensureCharacterPoolSlots()
    if not characterPoolInitialized then
        f_initializeCharacterPool()
    end
    local slot = characterPoolsSlots[characterPoolsActive]
    if not slot then
        slot = { name = "Default", pool = {} }
        characterPoolsSlots[characterPoolsActive] = slot
    end
    slot.pool = f_copyPoolTable(characterPool)
    f_saveCharacterPools()
end

local function f_loadCharacterPools()
    f_ensureCharacterPoolSlots()
    -- Unified file first (migrates legacy character_pools.json on first boot).
    local data = nil
    local td = f_ensureTournamentData()
    if td and type(td.characterPools) == "table" then
        data = td.characterPools
    end
    if data == nil then
        data = f_decodeJsonFile(characterPoolsPath)
    end
    if type(data) ~= "table" then
        if characterPoolInitialized or next(characterPool) then
            characterPoolsSlots[1].pool = f_copyPoolTable(characterPool)
        end
        characterPoolsActive = 1
        f_saveCharacterPools()
        f_applyCharacterPoolSlot(1)
        print("[Tournament] character_pools.json created (empty slots / slot 1 = current pool).")
        return
    end

    local active = tonumber(data.active) or 1
    if active < 1 then active = 1 end
    if active > CHARACTER_POOL_SLOTS then active = CHARACTER_POOL_SLOTS end

    local rawSlots = data.slots
    if type(rawSlots) == "table" then
        for i = 1, CHARACTER_POOL_SLOTS do
            local src = rawSlots[i] or rawSlots[tostring(i)]
            if type(src) == "table" then
                local nm = (type(src.name) == "string" and src.name ~= "") and src.name or "Default"
                -- Legacy auto-generated names ("Slot 1"/"Preset 1"...) become "Default".
                local low = tostring(nm):lower()
                if low:match("^slot %d+$") or low:match("^preset %d+$") then nm = "Default" end
                characterPoolsSlots[i] = {
                    name = nm,
                    pool = f_copyPoolTable(src.pool),
                }
            end
        end
    end

    if (characterPoolInitialized or next(characterPool)) then
        local slotPool = characterPoolsSlots[active] and characterPoolsSlots[active].pool
        local slotEmpty = true
        if type(slotPool) == "table" then
            for _ in pairs(slotPool) do slotEmpty = false; break end
        end
        if slotEmpty then
            characterPoolsSlots[active].pool = f_copyPoolTable(characterPool)
        end
    end

    f_applyCharacterPoolSlot(active)
    print("[Tournament] Character pools loaded (active slot=" .. tostring(characterPoolsActive) .. ").")
end

local function f_getActivePoolSlotLabel()
    f_ensureCharacterPoolSlots()
    local slot = characterPoolsSlots[characterPoolsActive]
    local name = (slot and slot.name) or "Default"
    return string.format("PRESET %d/%d", characterPoolsActive, CHARACTER_POOL_SLOTS)
end

local function f_getActivePoolSlotName()
    f_ensureCharacterPoolSlots()
    local slot = characterPoolsSlots[characterPoolsActive]
    return (slot and slot.name) or "Default"
end

local function f_setActivePoolSlotName(newName)
    f_ensureCharacterPoolSlots()
    if type(newName) ~= "string" then return end
    newName = newName:match("^%s*(.-)%s*$") or newName
    if newName == "" then newName = "Default" end
    local slot = characterPoolsSlots[characterPoolsActive]
    if not slot then
        slot = { name = newName, pool = {} }
        characterPoolsSlots[characterPoolsActive] = slot
    else
        slot.name = newName
    end
end

