local function f_participantPath(p)
    if type(p) == "table" then return p.path end
    return p
end

local function f_participantId(p)
    if type(p) == "table" then return p.id end
    return p
end

local function f_participantRef(p)
    if type(p) == "table" then return p.ref end
    return nil
end

-- =====================================================================
-- FIX: f_isPlayerParticipant
-- =====================================================================
local function f_isPlayerParticipant(p)
    if type(p) ~= "table" then
        -- Strings: PLAYER, PLAYER1..PLAYERN (any count)
        if p == "PLAYER" then return true end
        if type(p) == "string" and p:match("^PLAYER%d+$") then return true end
        return false
    end
    if p.isPlayer == true then return true end
    local id = p.id
    if id == "PLAYER" then return true end
    if type(id) == "string" and id:match("^PLAYER%d+$") then return true end
    return false
end

-- Team / pals of a human participant (PLAYER / PLAYER1..PLAYER4)
local function f_getHumanTeamAndPals(participant)
    local id = f_participantId(participant)
    if id == "PLAYER" or id == "PLAYER1" then
        local team = tournament.playerTeam
        if (not team or #team == 0) and tournament.humanTeams and tournament.humanTeams["PLAYER1"] then
            team = tournament.humanTeams["PLAYER1"]
        end
        local pals = tournament.playerPals
        if (not pals or #pals == 0) and tournament.humanPals and tournament.humanPals["PLAYER1"] then
            pals = tournament.humanPals["PLAYER1"]
        end
        return team or {}, pals or {1}
    end
    if type(id) == "string" and id:match("^PLAYER%d+$") then
        local team = tournament.humanTeams and tournament.humanTeams[id]
        local pals = tournament.humanPals and tournament.humanPals[id]
        return team or {}, pals or {1}
    end
    return {}, {1}
end

-- Native ref (start.p[side].t_selected[i].ref) of the human character, used by
-- animGetPreloadedData to reuse data already loaded by the
-- native selection, instead of reloading the sff manually.
local function f_getHumanRef(participant)
    local id = f_participantId(participant)
    if id == "PLAYER" or id == "PLAYER1" then
        return tournament.playerRef or (tournament.humanRefs and tournament.humanRefs["PLAYER1"])
    end
    if type(id) == "string" and id:match("^PLAYER%d+$") then
        return tournament.humanRefs and tournament.humanRefs[id]
    end
    return nil
end

