-- =====================================================================
-- TRANSPARENT BLACK OVERLAY (darkened menu and bracket background)
-- =====================================================================
function f_drawBlackOverlay()
    local blackOverlay = f_getOrCreateRect("tournamentBlackOverlay")
    if blackOverlay then
        -- Fullscreen dim for EVERY tournament screen (this same function also
        -- paints behind the bracket Misc). Default Lua space on purpose (NO
        -- SetLocalcoord): it is always 240 units tall, 240*aspect wide, so a
        -- tight 320x240 window leaves the sides bare. Overscan covers any
        -- aspect (clipped by the screen).
        rectSetWindow(blackOverlay, -1000, -1000, 2000, 2000)
        rectSetColor(blackOverlay, 0, 0, 0)  -- Preto
        rectSetAlpha(blackOverlay, tournament.bgOpacity, tournament.bgOpacity)
        if rectUpdate then rectUpdate(blackOverlay) end
        rectDraw(blackOverlay)
    end
end

-- =====================================================================
-- FIX: f_participantKey - USES CORRECT ID FOR PLAYER1/PLAYER2
-- =====================================================================
local function f_participantKey(participant)
    local id = f_participantId(participant)
    -- If it has an ID, use it as key (each instance is unique!)
    if id ~= nil then
        return tostring(id)  -- "PLAYER1", "PLAYER2", "39", "40", ...
    end
    -- Fallback: if it has no ID, use the path
    local path = f_participantPath(participant)
    if path then
        return "path:" .. tostring(path)
    end
    return tostring(participant)
end

