tournamentPortrait9000Cache = {}  -- lower char path -> 9000,0 anim | false
tournamentPortrait9000Tries = {}  -- lower char path -> staging attempts
tournamentPortrait9001Cache = {}  -- lower char path -> 9000,1 anim | false
tournamentPortrait9001Tries = {}  -- lower char path -> staging attempts
-- Motif cell portrait sprite (system.def [Select Info] portrait.spr).
-- (Global: small-portrait fallback decision.)
function f_motifPortraitSpr()
    local si = motif and motif.select_info
    local pr = si and si.portrait
    local spr = pr and pr.spr
    if type(spr) == "table" then
        return tonumber(spr[1]), tonumber(spr[2])
    end
    return nil, nil
end
-- Mod standard is the char's own small 9000,0 (not the motif's, e.g. a
-- screenpack using custom 9000,120 big portraits). True unless the motif
-- already uses 9000,0 (or the value is unreadable: assume standard).
function f_useSmallPortraitFallback()
    local g, i = nil, nil
    if type(f_motifPortraitSpr) == "function" then
        g, i = f_motifPortraitSpr()
    end
    if g == nil then return false end
    return not (g == 9000 and i == 0)
end
-- DEBUG: true = logs to console how each 9000,0 resolved (store-hit vs
-- staging-pending vs failed). Pending logs once; hit/fail log on transition.
-- Turn off after tests.
TOURNAMENT_PORTRAIT_9000_DEBUG = true
tournamentPortrait9000Dbg = {}  -- lower char path -> "pending" | "done"
local function f_portrait9000Debug(key, msg, done)
    if not TOURNAMENT_PORTRAIT_9000_DEBUG then return end
    tournamentPortrait9000Dbg = tournamentPortrait9000Dbg or {}
    local st = tournamentPortrait9000Dbg[key]
    if done then
        if st ~= "done" then
            tournamentPortrait9000Dbg[key] = "done"
            print("[Tournament][9000] " .. tostring(key) .. " => " .. tostring(msg))
        end
    else
        if st == nil then
            tournamentPortrait9000Dbg[key] = "pending"
            print("[Tournament][9000] " .. tostring(key) .. " => " .. tostring(msg))
        end
    end
end
-- Char small portrait (9000,0) from the engine preloaded store (zero IO).
-- queueCharPreload stages it in background (pumped by entry blocks and the
-- per-frame ticks below); bounded retries, then false. NO sffNew anywhere.
-- (Global: loader fallback below.)
function f_loadCharPortrait9000(charPath)
    if type(charPath) ~= "string" or charPath == "" then return nil end
    local key = string.lower(charPath)
    local hit = tournamentPortrait9000Cache[key]
    if hit ~= nil then return hit or nil end
    local ref = nil
    if type(f_resolveCharRefFromPath) == "function" then
        local okR2, r2 = pcall(f_resolveCharRefFromPath, charPath)
        if okR2 then ref = r2 end
    end
    if ref ~= nil then
        if type(animGetPreloadedCharData) == "function" then
            local okP, aP = pcall(animGetPreloadedCharData, ref, 9000, 0, true)
            if okP and aP and type(aP) == "userdata" then
                tournamentPortrait9000Cache[key] = aP
                f_portrait9000Debug(key, "store-hit (tries=" .. tostring(tonumber(tournamentPortrait9000Tries[key]) or 0) .. ")", true)
                return aP
            end
        end
        -- Stage it (async): engine pumps via ticks (entry blocks + loops).
        if type(queueCharPreload) == "function" then
            pcall(queueCharPreload, ref, 2)
        end
        if main and type(main.f_preloadBoostChar) == "function" then
            pcall(main.f_preloadBoostChar, ref)
        end
    end
    local tries = (tonumber(tournamentPortrait9000Tries[key]) or 0) + 1
    tournamentPortrait9000Tries[key] = tries
    if tries > 300 then
        tournamentPortrait9000Cache[key] = false
        f_portrait9000Debug(key, "failed (300 tries, store never staged)", true)
        return nil
    end
    f_portrait9000Debug(key, "staging-pending (queued, try " .. tostring(tries) .. ")", false)
    return nil
end

-- Big portrait (9000,1) from the engine preloaded store (zero IO).
-- Same staging pattern as f_loadCharPortrait9000: store-hit, else queue
-- + retry (pending), give up after 300 tries. Returns anim|nil.
function f_loadCharPortrait9001(charPath)
    if type(charPath) ~= "string" or charPath == "" then return nil end
    local key = string.lower(charPath)
    local hit = tournamentPortrait9001Cache[key]
    if hit ~= nil then return hit or nil end
    local ref = nil
    if type(f_resolveCharRefFromPath) == "function" then
        local okR2, r2 = pcall(f_resolveCharRefFromPath, charPath)
        if okR2 then ref = r2 end
    end
    if ref ~= nil then
        if type(animGetPreloadedCharData) == "function" then
            local okP, aP = pcall(animGetPreloadedCharData, ref, 9000, 1, true)
            if okP and aP and type(aP) == "userdata" then
                tournamentPortrait9001Cache[key] = aP
                f_portrait9000Debug(key .. "@9001", "store-hit (tries=" .. tostring(tonumber(tournamentPortrait9001Tries[key]) or 0) .. ")", true)
                return aP
            end
        end
        -- Stage it (async): engine pumps via ticks (entry blocks + loops).
        if type(queueCharPreload) == "function" then
            pcall(queueCharPreload, ref, 2)
        end
        if main and type(main.f_preloadBoostChar) == "function" then
            pcall(main.f_preloadBoostChar, ref)
        end
    end
    local tries = (tonumber(tournamentPortrait9001Tries[key]) or 0) + 1
    tournamentPortrait9001Tries[key] = tries
    if tries > 300 then
        tournamentPortrait9001Cache[key] = false
        f_portrait9000Debug(key .. "@9001", "failed (300 tries, store never staged)", true)
        return nil
    end
    f_portrait9000Debug(key .. "@9001", "staging-pending (queued, try " .. tostring(tries) .. ")", false)
    return nil
end

-- DEBUG: true = logs once per participant which pipeline served the cell
