local function f_loadCharPortrait(participant)
    if TOURNAMENT_HIDE_CHAR_PORTRAITS then return nil end  -- TEMP perf test
    local participantId = f_participantId(participant)
    local charPath = f_participantPath(participant)
    if not charPath or charPath == "???" then return nil end
    local realPath = charPath
    local isPlayer = f_isPlayerParticipant(participant)
    
    if isPlayer then
        local placeholders = {
            PLAYER = true, PLAYER1 = true, PLAYER2 = true, PLAYER3 = true, PLAYER4 = true
        }
        -- Participant tables already carry their char path (bracket build /
        -- save data): trust it. The native-select shortcut below runs ONLY
        -- for placeholder refs ("PLAYER1"...). Otherwise a STALE side-1
        -- selection (sequential P2/P3... picks share side 1) would override
        -- P1's portrait with the last-picked char (reload works because
        -- f_restorePlayerSelection fixes the native refs).
        if realPath == nil or realPath == "" or placeholders[realPath] then
            local playerId = participantId
            local sideIdx = 1
            if playerId == "PLAYER2" then sideIdx = 2
            elseif playerId == "PLAYER3" then sideIdx = 3
            elseif playerId == "PLAYER4" then sideIdx = 4
            end
            if start and start.p and start.p[sideIdx] and start.p[sideIdx].t_selected and start.p[sideIdx].t_selected[1] then
                local pref = start.p[sideIdx].t_selected[1].ref
                if pref and not placeholders[pref] and start.f_getCharData then
                    local ok, data = pcall(start.f_getCharData, pref)
                    if ok and data and data.char then
                        realPath = data.char
                    end
                end
            end
            if placeholders[realPath] then realPath = "" end

            if realPath == "" then
                if (playerId == "PLAYER" or playerId == "PLAYER1") and tournament.playerTeam and #tournament.playerTeam > 0 then
                    realPath = tournament.playerTeam[1] or ""
                end
                local key = (playerId == "PLAYER") and "PLAYER1" or playerId
                if realPath == "" and tournament.humanTeams and tournament.humanTeams[key] then
                    local team = tournament.humanTeams[key]
                    if type(team) == "table" and #team > 0 then
                        realPath = team[1] or ""
                    end
                end
                if realPath == "" and playerId == "PLAYER2" and tournament.playerTeam and #tournament.playerTeam > 1 then
                    realPath = tournament.playerTeam[2] or ""
                end
            end
        end
    end
    
    if realPath == "" then return nil end
    
    if tournament.portraitCache[participantId] ~= nil then 
        return tournament.portraitCache[participantId] or nil 
    end
    local cleanName = string.lower(realPath)
    local cached = cellDataCache[cleanName]
    local cellAnim = (cached and cached.ready and cached.data) or nil
    -- Non-9000,0 motif: mod standard is the char's own small 9000,0 from
    -- the preloaded store (queued async above; per-frame ticks pump).
    -- Motif cell art (9000,120) is NEVER used here, not even temporarily.
    if type(f_useSmallPortraitFallback) == "function" and f_useSmallPortraitFallback() then
        local anim9 = nil
        if type(f_loadCharPortrait9000) == "function" then
            local ok9, a9 = pcall(f_loadCharPortrait9000, realPath)
            if ok9 then anim9 = a9 end
        end
        if anim9 then
            tournament.portraitCache[participantId] = anim9
            f_portraitCellPathDebug(participantId, "9000 store-hit")
            return anim9
        end
        return nil
    end
    if cellAnim then
        tournament.portraitCache[participantId] = cellAnim
        f_portraitCellPathDebug(participantId, "cell-hit (native select cell_data)")
        return cellAnim
    end
    -- No cell art (e.g. cell-mates of multi-char slots): fall back to the
    -- char's own 9000,0 instead of an empty cell.
    if type(f_loadCharPortrait9000) == "function" then
        local ok9, a9 = pcall(f_loadCharPortrait9000, realPath)
        if ok9 and a9 and type(a9) == "userdata" then
            tournament.portraitCache[participantId] = a9
            f_portraitCellPathDebug(participantId, "9000 store-hit (no cell art)")
            return a9
        end
    end
    tournament.portraitCache[participantId] = false
    f_portraitCellPathDebug(participantId, "cell-miss (cell_data not staged)")
    return nil
end

function f_invalidateCellBgAnim()
    cellBgAnim = nil
end

local function f_getCellBgAnim()
    if cellBgAnim ~= nil then return cellBgAnim end
    -- 3 = Screenpack Original: the motif's own cell.bg.spr (system.def).
    -- Shared anim: bracket draw backs it up and restores the def scale
    -- after (native select screen unaffected).
    if tournament and tonumber(tournament.portraitBgSprite) == 3 then
        if motif and motif.select_info and motif.select_info.cell and motif.select_info.cell.bg then
            local bgObj = motif.select_info.cell.bg
            if bgObj.AnimData or bgObj.anim or type(bgObj) == "userdata" then
                cellBgAnim = bgObj.AnimData or bgObj.anim or bgObj
                return cellBgAnim
            end
        end
        return nil
    end
    -- TournamentMode.sff group 150:
    --   1 = Module (150,1, current default) | 2 = Module 2 (150,0)
    local sprIdx = 1
    if tournament and tonumber(tournament.portraitBgSprite) == 2 then
        sprIdx = 0
    end
    local sff = f_loadTournamentSff()
    local air = "150," .. tostring(sprIdx) .. ", 0,0, -1"
    if sff then
        local ok, anim = pcall(animNew, sff, air)
        if ok and anim and type(anim) == "userdata" then
            cellBgAnim = anim
            return cellBgAnim
        end
    end
    -- Old fallbacks (motif / cellDataCache), for safety
    if motif and motif.select_info and motif.select_info.cell and motif.select_info.cell.bg then
        local bgObj = motif.select_info.cell.bg
        if bgObj.AnimData or bgObj.anim or type(bgObj) == "userdata" then
            cellBgAnim = bgObj.AnimData or bgObj.anim or bgObj
            return cellBgAnim
        end
    end
    for _, item in pairs(cellDataCache) do
        if item and item.ready and item.data then cellBgAnim = item.data; return cellBgAnim end
    end
    return nil
end

-- Module-only cell bg (150,1) for the pool + portrait-scales screens: own
-- cache, so the shared cellBgAnim (which follows portraitBgSprite) is never
-- polluted by the forced Module (bracket keeps the user option).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_getModuleCellBgAnim()
    if moduleCellBgAnim ~= nil then return moduleCellBgAnim end
    local sff = nil
    if type(f_loadTournamentSff) == "function" then
        local ok, s = pcall(f_loadTournamentSff)
        if ok then sff = s end
    end
    if sff and type(animNew) == "function" then
        local ok, anim = pcall(animNew, sff, "150,1, 0,0, -1")
        if ok and anim and type(anim) == "userdata" then
            moduleCellBgAnim = anim
            return moduleCellBgAnim
        end
    end
    return nil
end

-- =====================================================================
-- TOURNAMENT PLAYER CURSORS ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â from tournamentmode.sff group 4.
-- 4,0 = CPU cursor; players start at 4,1: player N -> 4,N (4,1 .. 4,128).
-- One STATIC sprite each. Groups 160/170/172/174 (animated) are retired.
-- =====================================================================
local TOURNAMENT_CURSOR_GROUP = 4
local TOURNAMENT_CURSOR_MAX = 128
local tournamentCursorCache = {}
local function f_getTournamentCursorAnim(side, frame)
    local n = math.floor(tonumber(side) or 1)
    if n < 0 then n = 0 end
    if n > TOURNAMENT_CURSOR_MAX then n = TOURNAMENT_CURSOR_MAX end
    local sprite = n  -- 4,0 is the CPU cursor (side 0); players start at 4,1
    local key = "4_" .. sprite
    local cached = tournamentCursorCache[key]
    if cached ~= nil then return cached or nil end
    local sff = f_loadTournamentSff()
    if not sff then
        tournamentCursorCache[key] = false
        return nil
    end
    local air = "4," .. sprite .. ", 0,0, -1"
    local ok, anim = pcall(animNew, sff, air)
    if ok and anim and type(anim) == "userdata" then
        tournamentCursorCache[key] = anim
    else
        tournamentCursorCache[key] = false
        return nil
    end
    return tournamentCursorCache[key]
end

-- Backup/restore motif P1 cursor + forces tournament sprite (group 4)
-- used in sequential selects (engine only draws side 1/2 cursor).
local _motifCursorBackup = nil
local function f_backupMotifP1Cursor()
    if _motifCursorBackup ~= nil then return end
    local si = motif and motif.select_info
    local p1 = si and si.p1
    local cur = p1 and p1.cursor
    if type(cur) ~= "table" then return end
    _motifCursorBackup = {
        active = cur.active,
        done = cur.done,
        AnimData = cur.AnimData,
        anim = cur.anim,
    }
end
local function f_restoreMotifP1Cursor()
    if _motifCursorBackup == nil then return end
    local si = motif and motif.select_info
    local p1 = si and si.p1
    local cur = p1 and p1.cursor
    if type(cur) == "table" then
        cur.active = _motifCursorBackup.active
        cur.done = _motifCursorBackup.done
        cur.AnimData = _motifCursorBackup.AnimData
        cur.anim = _motifCursorBackup.anim
    end
    _motifCursorBackup = nil
end
local function f_forceSelectCursorForPlayer(playerNum)
    playerNum = tonumber(playerNum) or 1
    if playerNum < 1 then playerNum = 1 end
    if playerNum > 128 then playerNum = 128 end
    -- Native cursor mode: leave motif p1.cursor untouched (nothing to back up, so the
    -- f_restoreMotifP1Cursor calls become no-ops). Returns true: the select proceeds
    -- with the screenpack's own cursor.
    if TOURNAMENT_SELECT_CURSOR_USE_NATIVE ~= false then
        return true
    end
    f_backupMotifP1Cursor()
    local anim0 = f_getTournamentCursorAnim(playerNum, 0)
    if not anim0 then return false end
    local si = motif and motif.select_info
    local p1 = si and si.p1
    if type(p1) ~= "table" then return false end
    if type(p1.cursor) ~= "table" then p1.cursor = {} end
    local cur = p1.cursor
    -- Preference: inject AnimData into active/default (common motif format)
    if type(cur.active) == "table" then
        if type(cur.active.default) == "table" then
            cur.active.default.AnimData = anim0
            cur.active.default.anim = anim0
        else
            cur.active.AnimData = anim0
            cur.active.anim = anim0
        end
    else
        cur.active = { AnimData = anim0, anim = anim0 }
    end
    cur.AnimData = anim0
    cur.anim = anim0
    -- Some builds read p1.cursor.done the same way
    if type(cur.done) == "table" then
        if type(cur.done.default) == "table" then
            cur.done.default.AnimData = anim0
            cur.done.default.anim = anim0
        else
            cur.done.AnimData = anim0
            cur.done.anim = anim0
        end
    end
    print(string.format("[Tournament] Forced select cursor to P%d (4,%d)",
        playerNum, playerNum))
    return true
end

local function f_getCursorAnimData(side)
    if not (motif and motif.select_info) then return nil end
    local pSide = motif.select_info["p" .. side]
    if not pSide or not pSide.cursor then return nil end
    local cursor = pSide.cursor
    if cursor.AnimData or cursor.anim or type(cursor) == "userdata" then return cursor.AnimData or cursor.anim or cursor end
    if cursor.active then
        local act = cursor.active
        if act.default then return act.default.AnimData or act.default.anim or act.default end
        return act.AnimData or act.anim or act
    end
    return nil
end

local grayscalePalFX = { time = -1, add = {0,0,0}, mul = {256,256,256}, sinadd = {0,0,0,0}, invertall = 0, color = 0 }
local normalPalFX = { time = -1, add = {0,0,0}, mul = {256,256,256}, sinadd = {0,0,0,0}, invertall = 0, color = 256 }

function f_getPlayerMatchCount(size)
    local matches = 0
    local participants = size
    while participants > 1 do participants = participants / 2; matches = matches + 1 end
    return matches
end

-- 128 slots:
--   ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¢ only on widescreen resolutions (~16:9)
--   ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¢ and only with Tournament Screen = HD (in SD it stays locked/red)
function f_isTournamentSizeAvailable(size)
    if tonumber(size) ~= 128 then return true end
    if tournament and tostring(tournament.screenMode or ""):upper() == "SD" then
        return false
    end
    if not _widescreen then return false end
    return true
end

function f_getPhaseName(size, round)
    local players = size / (2 ^ (round - 1))
    if players <= 2 then return "FINAL"
    elseif players == 4 then return "SEMIFINALS"
    elseif players == 8 then return "QUARTERFINALS"
    else return "ROUND OF " .. tostring(players) end
end

-- Name for summary/podium: displayname from .def (uppercase) or file name.
local function f_summaryDispName(path)
    local d = nil
    if type(f_getDisplayNameFromDef) == "function" and type(path) == "string" and path ~= "" then
        local ok, res = pcall(f_getDisplayNameFromDef, path)
        if ok and type(res) == "string" and res ~= "" then d = res end
    end
    if not d or d == "" then
        local p = tostring(path or "")
        d = p:match("([^/\\]+)%.[Dd][Ee][Ff]$") or p:match("([^/\\]+)$") or p
    end
    if d == "" then d = "???" end
    return string.upper(tostring(d))
end

-- Podium lines for finished save. Returns champ, runner, third
-- (third = nil if there was no 3rd-place match). Prefix: humans "1P"/"2P",
-- others "CPU". Returns nils if the bracket has no champion.
local function f_podiumLines(bracket, humanTeams, playerTeam)
    if type(bracket) ~= "table" or bracket.champion == nil then
        return nil, nil, nil
    end
    local placeholders = {
        PLAYER = true, PLAYER1 = true, PLAYER2 = true,
        PLAYER3 = true, PLAYER4 = true,
    }
    local function idKeyOf(p)
        local id = tostring(f_participantId(p) or "")
        if id == "PLAYER" then return "PLAYER1" end
        return id
    end
    local function prefixOf(p)
        local id = tostring(f_participantId(p) or "")
        if id == "PLAYER" then return "1P" end
        local n = id:match("^PLAYER(%d+)$")
        if n then return n .. "P" end
        return "CPU"
    end
    local function realPath(p)
        local path = f_participantPath(p)
        if f_isPlayerParticipant(p) then
            local idKey = idKeyOf(p)
            local team = (type(humanTeams) == "table") and humanTeams[idKey]
            if type(team) == "table" and team[1] and team[1] ~= "" then
                return team[1]
            end
            if (idKey == "PLAYER1") and type(playerTeam) == "table" and playerTeam[1] then
                return playerTeam[1]
            end
            if path == nil or path == "" or placeholders[path] then
                return ""
            end
        end
        return path
    end
    -- ID instead of char name when USE ID is on (panel FINISHED podium).
    local function nameOrId(p, path)
        if tournament and tournament.useHumanIds and tournament.humanIds then
            local id = tostring(f_participantId(p) or "")
            local n = id:match("^PLAYER(%d+)$")
            if n then
                local hid = tournament.humanIds["PLAYER" .. tostring(tonumber(n))]
                if type(hid) == "string" and hid ~= "" then return hid end
            end
        end
        if tournament and tournament.allowRandomCpuIds ~= false and tournament.cpuIds then
            local cname = tournament.cpuIds[tostring(f_participantId(p))]
            if type(cname) == "string" and cname ~= "" then return cname end
        end
        return f_summaryDispName(path)
    end
    local champ = bracket.champion
    local champLine = prefixOf(champ) .. " - "
        .. nameOrId(champ, realPath(champ)) .. " (Champion)"
    -- Runner-up: perdedor da final
    local runnerLine = nil
    do
        local totalR = 0
        if type(bracket.rounds) == "table" then
            for k, _ in pairs(bracket.rounds) do
                if type(k) == "number" and k > totalR then totalR = k end
            end
        end
        local finalMatch = (totalR > 0 and bracket.rounds[totalR])
            and bracket.rounds[totalR].left and bracket.rounds[totalR].left[1]
        if type(finalMatch) == "table" and finalMatch.winner ~= nil then
            local loser = (finalMatch.winner == finalMatch.a) and finalMatch.b or finalMatch.a
            if loser ~= nil then
                runnerLine = prefixOf(loser) .. " - "
                    .. nameOrId(loser, realPath(loser)) .. " (Runner-Up)"
            end
        end
    end
    -- Third: only if a match happened (winner registered)
    local thirdLine = nil
    local third = bracket.thirdPlaceWinner
        or (bracket.thirdPlaceMatch and bracket.thirdPlaceMatch.winner)
    if third ~= nil then
        thirdLine = prefixOf(third) .. " - "
            .. nameOrId(third, realPath(third)) .. " (Third Place)"
    end
    return champLine, runnerLine, thirdLine
end

-- =====================================================================
-- TOURNAMENT SUMMARY FOR THE MAIN SETTINGS PANEL (SLOT/CONTINUE)
-- Global: f_saveTournamentState (defined before
-- in file) calls it at runtime; snapshot goes to JSON on every save
-- done on the bracket screen.
-- =====================================================================
function f_buildTournamentSummary(bracket, roundNum, size)
    local s = {}
    s.format = tournament.format or "KNOCKOUT"
    s.title = tournament.title or "TOURNAMENT"
    s.subtitle = tournament.subtitle or "Championship"
    s.size = tonumber(size) or tonumber(tournament.size) or 64
    s.teamMode = tournament.teamMode or "single"
    s.teamSize = tonumber(tournament.teamSize) or 1
    s.humanPlayers = tonumber(tournament.humanPlayers) or 0
    s.roundNum = tonumber(roundNum) or 1
    local okPhase, phaseName = pcall(f_getPhaseName, s.size, s.roundNum)
    s.roundName = (okPhase and phaseName) or ("ROUND " .. tostring(s.roundNum))
    s.thirdPlace = (tournament.thirdPlacePlayoff ~= false)
    s.allowDup = (tournament.allowDuplicateChars == true)
    s.allowPal = (tournament.allowRandomCpuPalette == true)
    -- Human names resolved NOW (.def displayname or file name)
    local function dispName(path)
        local d = nil
        if type(f_getDisplayNameFromDef) == "function" and type(path) == "string" and path ~= "" then
            local ok, res = pcall(f_getDisplayNameFromDef, path)
            if ok and type(res) == "string" and res ~= "" then d = res end
        end
        if not d or d == "" then
            local p = tostring(path or "")
            d = p:match("([^/\\]+)%.[Dd][Ee][Ff]$") or p:match("([^/\\]+)$") or p
        end
        if d == "" then d = "???" end
        return string.upper(tostring(d))
    end
    local function teamFirstPath(idKey)
        if tournament.humanTeams and type(tournament.humanTeams[idKey]) == "table"
           and #tournament.humanTeams[idKey] > 0 then
            return tournament.humanTeams[idKey][1]
        end
        return nil
    end
    local p1Path = teamFirstPath("PLAYER1")
        or (tournament.playerTeam and tournament.playerTeam[1])
    local p2Path = teamFirstPath("PLAYER2")
    -- ID instead of char name when USE ID is on (panel 1P/2P lines).
    local function dispNameOrId(idKey, path)
        if tournament.useHumanIds and tournament.humanIds then
            local hid = tournament.humanIds[idKey]
            if type(hid) == "string" and hid ~= "" then return hid end
        end
        return dispName(path)
    end
    -- "1P - ID (CHAR)": ID when set, char name in parentheses.
    local function playerLine(prefix, idKey, path)
        local hid = nil
        if tournament.useHumanIds and tournament.humanIds then
            local v = tournament.humanIds[idKey]
            if type(v) == "string" and v ~= "" then hid = v end
        end
        if hid ~= nil and type(path) == "string" and path ~= "" then
            return prefix .. " - " .. hid .. " (" .. dispName(path) .. ")"
        end
        return prefix .. " - " .. dispNameOrId(idKey, path)
    end
    if s.humanPlayers <= 0 then
        s.chars1 = "CPU ONLY"
        s.chars2 = nil
    elseif s.humanPlayers == 1 then
        s.chars1 = playerLine("1P", "PLAYER1", p1Path)
        s.chars2 = nil
    else
        s.chars1 = playerLine("1P", "PLAYER1", p1Path)
        s.chars2 = playerLine("2P", "PLAYER2", p2Path)
        if s.humanPlayers > 2 then
            s.chars2 = s.chars2 .. " (+" .. tostring(s.humanPlayers - 2) .. ")"
        end
    end
    -- charsLine kept for compat (panel uses chars1/chars2 on separate lines)
    s.charsLine = s.chars1 .. ((s.chars2 ~= nil) and (", " .. s.chars2) or "")
    -- Podium (only in finished save, with champion already decided)
    local pc, pr, pt = f_podiumLines(bracket, tournament.humanTeams, tournament.playerTeam)
    if pc ~= nil then
        s.finished = true
        s.roundName = "FINISHED"
        s.podiumChamp, s.podiumRunner, s.podiumThird = pc, pr, pt
    end
    return s
end

-- Derives a summary from raw state (old saves, no embedded summary).
-- Used only for display in the Main Settings panel.
local function f_deriveSummaryFromState(data)
    if type(data) ~= "table" then return nil end
    local s = {}
    s.format = data.format or "KNOCKOUT"
    s.title = (type(data.title) == "string" and data.title ~= "") and data.title or "TOURNAMENT"
    s.subtitle = (data.subtitle == "Championship" or data.subtitle == "Cup") and data.subtitle or "Championship"
    s.size = tonumber(data.size) or 64
    s.teamMode = data.teamMode or "single"
    s.teamSize = tonumber(data.teamSize) or 1
    s.humanPlayers = tonumber(data.humanPlayers) or 0
    s.roundNum = tonumber(data.roundNum) or 1
    local okPhase, phaseName = pcall(f_getPhaseName, s.size, s.roundNum)
    s.roundName = (okPhase and phaseName) or ("ROUND " .. tostring(s.roundNum))
    if data.thirdPlacePlayoff ~= nil then s.thirdPlace = (data.thirdPlacePlayoff == true)
    else s.thirdPlace = true end
    s.allowDup = (data.allowDuplicateChars == true)
    s.allowPal = (data.allowRandomCpuPalette == true)
    local function dispName(path)
        local d = nil
        if type(f_getDisplayNameFromDef) == "function" and type(path) == "string" and path ~= "" then
            local ok, res = pcall(f_getDisplayNameFromDef, path)
            if ok and type(res) == "string" and res ~= "" then d = res end
        end
        if not d or d == "" then
            local p = tostring(path or "")
            d = p:match("([^/\\]+)%.[Dd][Ee][Ff]$") or p:match("([^/\\]+)$") or p
        end
        if d == "" then d = "???" end
        return string.upper(tostring(d))
    end
    local ht = data.humanTeams
    local function teamFirstPath(idKey)
        if type(ht) == "table" and type(ht[idKey]) == "table" and #ht[idKey] > 0 then
            return ht[idKey][1]
        end
        return nil
    end
    local p1Path = teamFirstPath("PLAYER1")
        or (type(data.playerTeam) == "table" and data.playerTeam[1])
    local p2Path = teamFirstPath("PLAYER2")
    local function playerLine(prefix, idKey, path)
        local hid = nil
        if data.useHumanIds ~= false and type(data.humanIds) == "table" then
            local v = data.humanIds[idKey]
            if type(v) == "string" and v ~= "" then hid = v end
        end
        if hid ~= nil and type(path) == "string" and path ~= "" then
            return prefix .. " - " .. hid .. " (" .. dispName(path) .. ")"
        elseif hid ~= nil then
            return prefix .. " - " .. hid
        end
        return prefix .. " - " .. dispName(path)
    end
    if s.humanPlayers <= 0 then
        s.chars1 = "CPU ONLY"
        s.chars2 = nil
    elseif s.humanPlayers == 1 then
        s.chars1 = playerLine("1P", "PLAYER1", p1Path)
        s.chars2 = nil
    else
        s.chars1 = playerLine("1P", "PLAYER1", p1Path)
        s.chars2 = playerLine("2P", "PLAYER2", p2Path)
        if s.humanPlayers > 2 then
            s.chars2 = s.chars2 .. " (+" .. tostring(s.humanPlayers - 2) .. ")"
        end
    end
    -- charsLine kept for compat (panel uses chars1/chars2 on separate lines)
    s.charsLine = s.chars1 .. ((s.chars2 ~= nil) and (", " .. s.chars2) or "")
    -- Podium (only in finished save, with champion already decided)
    local pc, pr, pt = f_podiumLines(data.bracket, data.humanTeams, data.playerTeam)
    if pc ~= nil then
        s.finished = true
        s.roundName = "FINISHED"
        s.podiumChamp, s.podiumRunner, s.podiumThird = pc, pr, pt
    end
    return s
end

-- =====================================================================
-- FIX: f_getCharPath - SUPPORTS PLAYER2
-- =====================================================================
local function f_getCharPath(ref)
    if ref == nil then return "" end
    if ref == "PLAYER" or ref == "PLAYER1" then
        if start and start.p and start.p[1] and start.p[1].t_selected and start.p[1].t_selected[1] then
            local p1Ref = start.p[1].t_selected[1].ref
            if p1Ref and p1Ref ~= "PLAYER" and p1Ref ~= "PLAYER1" then
                local ok, data = pcall(function()
                    return start.f_getCharData and start.f_getCharData(p1Ref)
                end)
                if ok and data and data.char then return data.char end
            end
        end
        if tournament.playerTeam and #tournament.playerTeam > 0 then
            return tournament.playerTeam[1]
        end
        if tournament.humanTeams and tournament.humanTeams["PLAYER1"] and #tournament.humanTeams["PLAYER1"] > 0 then
            return tournament.humanTeams["PLAYER1"][1]
        end
        return ""
        
    elseif ref == "PLAYER2" or ref == "PLAYER3" or ref == "PLAYER4" then
        local sideIdx = (ref == "PLAYER2") and 2 or ((ref == "PLAYER3") and 3 or 4)
        if start and start.p and start.p[sideIdx] and start.p[sideIdx].t_selected and start.p[sideIdx].t_selected[1] then
            local pref = start.p[sideIdx].t_selected[1].ref
            if pref and pref ~= ref then
                local ok, data = pcall(function()
                    return start.f_getCharData and start.f_getCharData(pref)
                end)
                if ok and data and data.char then return data.char end
            end
        end
        if tournament.humanTeams and tournament.humanTeams[ref] and #tournament.humanTeams[ref] > 0 then
            return tournament.humanTeams[ref][1]
        end
        if ref == "PLAYER2" and tournament.playerTeam and #tournament.playerTeam > 1 then
            return tournament.playerTeam[2]
        end
        return ""
    end
    
    local data = nil
    if start and type(start.f_getCharData) == "function" then
        local ok, res = pcall(start.f_getCharData, ref)
        if ok then data = res end
    end
    if data and data.char then return data.char end
    return tostring(ref)
end

-- Modify f_getValidCharData to respect the pool
-- Random select cell (select.def "randomselect") is not a real char:
-- it never enters the pool, the draw, or the pool screen.
-- (Global on purpose: the main chunk operates near the 200 locals limit.)
function f_isRandomSelectPath(p)
    if type(p) ~= "string" then return true end
    local low = string.lower(p:gsub("\\", "/"))
    low = low:gsub("^%s+", ""):gsub("%s+$", "")
    if low == "" then return true end
    if low == "randomselect" then return true end
    low = low:gsub("%.def%s*$", "")
    if low == "randomselect" then return true end
    local base = low:match("([^/]+)$") or low
    if base == "randomselect" then return true end
    return false
end
f_getValidCharData = function(ignorePool)
    local valid = {}
    local seenCharNames = {}
    for i = 1, #main.t_selGrid do
        local entry = start.f_selGrid(i)
        -- ALL refs in this cell (multi-char slots list every char; the
        -- engine only resolves the slotted one via char_ref).
        local refs = {}
        local cell = main.t_selGrid[i]
        if type(cell) == "table" and type(cell.chars) == "table" then
            for _, r in ipairs(cell.chars) do
                local n = tonumber(r)
                if n ~= nil then refs[#refs + 1] = n end
            end
        end
        if entry and entry.char_ref ~= nil then
            local n = tonumber(entry.char_ref)
            if n ~= nil then refs[#refs + 1] = n end
        end
        for _, ref in ipairs(refs) do
        if entry and entry.char ~= nil then
            if isCharUnlocked == nil or isCharUnlocked(ref) then
                local charData = start.f_getCharData and start.f_getCharData(ref) or nil
                local rawPath = (charData and charData.char) or tostring(entry.char)
                if not f_isRandomSelectPath(rawPath) then
                local cleanName = string.lower(rawPath)
                -- Cell art belongs to the SLOTTED char only: caching it under
                -- a cell-mate's name (multi-char slots) showed Cap's portrait
                -- on Ironman. Mates fall through to their own 9000,0 below.
                if string.lower(tostring(entry.char)) == cleanName then
                    cellDataCache[cleanName] = { data = entry.cell_data, ready = entry.cell_data_ready }
                end
                
                -- If ignorePool is true, do not filter (used only during pool init)
                local isEnabled = ignorePool or f_isCharacterEnabled(rawPath)
                
                if isEnabled then
                    if not seenCharNames[cleanName] then
                        seenCharNames[cleanName] = true
                        table.insert(valid, { ref = ref, path = rawPath })
                    end
                end
                end
            end
        end
        end
    end
    return valid
end

local function f_sortearOponentes(excludePaths, qty)
    local valid = f_getValidCharData()
    local selected = {}
    local excludeSet = {}
    if type(excludePaths) == "table" then
        for _, p in ipairs(excludePaths) do
            if p then excludeSet[string.lower(p)] = true end
        end
    elseif type(excludePaths) == "string" then
        excludeSet[string.lower(excludePaths)] = true
    end
    if tournament.allowDuplicateChars then
        if #valid > 0 then
            for i = 1, qty do
                local pick = valid[math.random(#valid)]
                table.insert(selected, { ref = pick.ref, path = pick.path })
            end
        end
    else
        for i = #valid, 1, -1 do
            if excludeSet[string.lower(valid[i].path)] then table.remove(valid, i) end
        end
        for i = #valid, 2, -1 do
            local j = math.random(i)
            valid[i], valid[j] = valid[j], valid[i]
        end
        for i = 1, math.min(qty, #valid) do table.insert(selected, valid[i]) end
    end
    return selected
end

