-- FIX: f_restorePlayerSelection - RESTORES P1 AND P2
-- =====================================================================
function f_restorePlayerSelection(p1Ref, p2Ref)
    if p1Ref and start.p and start.p[1] then
        start.p[1].t_selected = { { ref = p1Ref } }
    end
    if p2Ref and start.p and start.p[2] then
        start.p[2].t_selected = { { ref = p2Ref } }
    end
end

-- =====================================================================
-- CACHE + displayname READER
-- =====================================================================
local displayNameCache = {}
f_getDisplayNameFromDef = function(defPath)
    if displayNameCache[defPath] ~= nil then return displayNameCache[defPath] or nil end
    if type(defPath) ~= "string" or defPath == "" then return nil end
    -- ZSS dirs (e.g. chars/kfm_zss) yield no .def candidates: nothing to read.
    -- io.open on a directory succeeds but file:lines() raises
    -- "read <path>: Incorrect function." on Windows, so only .def opens.
    -- Bare select.def names ("kfm720") expand to "<dir>/<base>.def" guesses.
    local candidates = {}
    do
        local all = nil
        if type(f_expandCharDefCandidates) == "function" then
            all = f_expandCharDefCandidates(defPath)
        else
            all = { defPath }
        end
        for _, cand in ipairs(all) do
            if type(cand) == "string" and cand:lower():match("%.def$") then
                candidates[#candidates + 1] = cand
            end
        end
    end
    if #candidates == 0 then displayNameCache[defPath] = false; return nil end
    local ok, result = pcall(function()
        for _, fullDefPath in ipairs(candidates) do
            local file = io.open(fullDefPath, "r")
            if file then
                local found = nil
                for line in file:lines() do
                    line = line:match("^%s*(.-)%s*$")
                    line = line:match("^(.-);") or line
                    line = line:match("^%s*(.-)%s*$")
                    local key, value = line:match("^([%w_]+)%s*=%s*(.-)$")
                    if key and key:lower() == "displayname" and value and value ~= "" then
                        found = value:gsub('^["\']', ""):gsub('["\']$', "")
                        break
                    end
                end
                pcall(function() file:close() end)
                if found then return found end
            end
        end
        return nil
    end)
    if not ok then result = nil end
    displayNameCache[defPath] = result or false
    return result
end

-- =====================================================================
-- CACHE + displayname READER (FIXED - WITH TEAM SUPPORT)
-- =====================================================================
-- =====================================================================
-- CACHE + displayname READER (FIXED - SUPPORTS TEAM ONLY IN TEAM MODE)
-- =====================================================================
local function f_getCleanDisplayName(path, forceTeam, bare, withIds)
    -- IDs only when withIds ~= false. The next-match L2 names pass false
    -- (plain char names always); champions/podium keep IDs.
    -- Human IDs (USE ID...): player's typed ID instead of the char name.
    if withIds ~= false and tournament and tournament.useHumanIds then
        local pid = f_participantId(path)
        if type(pid) == "string" then
            local pn = pid:match("^PLAYER(%d+)$")
            if pn and tournament.humanIds then
                local hid = tournament.humanIds["PLAYER" .. tostring(tonumber(pn))]
                if type(hid) == "string" and hid ~= "" then return hid end
            end
        end
    end
    -- CPU IDs (ALLOW RANDOM ID...): champions/podium show the CPU nick too.
    if withIds ~= false and tournament and tournament.allowRandomCpuIds ~= false and tournament.cpuIds then
        local cname = tournament.cpuIds[tostring(f_participantId(path))]
        if type(cname) == "string" and cname ~= "" then return cname end
    end
    path = f_participantPath(path)
    if path == "PLAYER" or path == "PLAYER1" then 
        path = f_getCharPath("PLAYER1")
    elseif path == "PLAYER2" or path == "PLAYER3" or path == "PLAYER4" then
        path = f_getCharPath(path)
    end
    
    local display = f_getDisplayNameFromDef(path)
    local name = display or path:match("([^/]+)%.def$") or path:match("([^/]+)$") or path
    local upperName = string.upper(name)
    -- bare = no "TEAM " prefix (next-match L3 shows plain name/ID;
    -- the TEAM tag moved down to the L4 type line).
    if bare then return upperName end
    
    local tModeStr = (tournament.teamMode or "single"):lower():gsub("%s+", "")
    local isTeamMode = (tModeStr ~= "single")
    if not isTeamMode then
        return upperName
    end
    local shouldAddTeam = forceTeam or (path ~= "PLAYER" and path ~= "PLAYER1" and path ~= "PLAYER2"
        and path ~= "PLAYER3" and path ~= "PLAYER4")
    if shouldAddTeam then
        return "TEAM " .. upperName
    end
    return upperName
end

