-- INPUT
-- =====================================================================
-- Which side drives the tournament menus: whoever opened the mode
-- (tournament.enterPlayer, from getLastInputController at entry; 1|2).
-- (Global: the main chunk operates near the 200 locals limit.)
function f_menuSide()
    if tournament and tonumber(tournament.enterPlayer) == 2 then return 2 end
    return 1
end

-- Either side's mapped keyboard key, held or not (per-player attribution for
-- keys that getKey() alone cannot split). E.g. P1 START=physical Z.
-- (Global: the main chunk operates near the 200 locals limit.)
function f_menuKeyDown(cmd)
    if type(cmd) ~= "string" or cmd == "" then return false end
    if getKey == nil then return false end
    for _, side in ipairs({1, 2}) do
        local mk = nil
        if type(f_getMenuKeyNameSide) == "function" then mk = f_getMenuKeyNameSide(cmd, side) end
        if type(mk) == "string" and mk ~= "" then
            if getKey(mk) or getKey(string.upper(mk)) or getKey(string.lower(mk)) then return true end
        end
    end
    return false
end

-- Menu direction for either side: side commands first (player-attributed,
-- unlike raw arrow keycodes which fire globally), then each side's own
-- configured direction key. No getInput fallback on purpose: raw arrows
-- leak across sides and would defeat the menu lock.
-- (Global: the main chunk operates near the 200 locals limit.)
function f_menuDirPressed(dirCmd, arrowKey)
    if main and main.t_cmd and commandGetState and dirCmd then
        for _, side in ipairs({1, 2}) do
            local dcmd = main.t_cmd[side]
            if dcmd and commandGetState(dcmd, dirCmd) then return true end
        end
    end
    if type(f_menuKeyDown) == "function" and f_menuKeyDown(dirCmd) then return true end
    -- Joystick fÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â­sico (main.t_cmd ÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â© nil nos menus: commands nÃƒÆ’Ã†--  Ãƒâ€šÃ‚Â£o o veem).
    if type(f_joystickCmdDown) == "function" and dirCmd and f_joystickCmdDown(dirCmd) then return true end
    return false
end

-- Key repeat (typematic) for held directions, like the native Ikemen menus:
-- fires once on press, then repeats every `rateFrames` after `delayFrames`
-- held. Frame-based (menu loops tick once per frame; no clock needed).
-- Starts "released" (prev=true), like makeEdge: entering a screen holding
-- a direction does NOT fire until re-press.
function f_makeRepeatEdge(fn, delayFrames, rateFrames)
    delayFrames = tonumber(delayFrames) or 18
    rateFrames = math.max(1, tonumber(rateFrames) or 4)
    -- Starts from the LIVE state (not pressed): first tap fires immediately,
    -- held-at-entry still requires release + re-press (no accidental fire).
    local prev = fn() and true or false
    local hold = 0
    return function()
        local cur = fn() and true or false
        local trig = false
        if cur and not prev then
            trig = true
            hold = 0
        elseif cur and prev then
            hold = hold + 1
            if hold >= delayFrames and ((hold - delayFrames) % rateFrames == 0) then
                trig = true
            end
        else
            hold = 0
        end
        prev = cur
        return trig
    end
end

-- Max selectable humans: 128 total, 64 on SD (640x480, max 64 bracket slots).
function f_maxHumanPlayers()
    if tournament and tostring(tournament.screenMode or "HD"):upper() == "SD" then return 64 end
    return 128
end

function f_isButtonPressed(button)
    -- Menu input: either side answers here (1P+2P detection).
    -- (Every caller is a menu loop; fight code never uses this.)
    -- Tries via commandGetState (more reliable)
    if main and main.t_cmd and commandGetState then
        for _, side in ipairs({1, 2}) do
            local cmd = main.t_cmd[side]
            if cmd and commandGetState(cmd, button) then
                return true
            end
        end
    end

    -- Tries via getInput (fallback)
    if getInput then
        for _, side in ipairs({1, 2}) do
            if getInput(side, button) then
                return true
            end
            -- Try with $ (physical button)
            if getInput(side, "$" .. button) then
                return true
            end
        end
    end

    return false
end

function f_checkConfirmInput()
    -- A/B/C/X/Y/Z + Start (entrant side) + entrant's mapped START key.
    -- (Native Ikemen menus: all 6 advance. No universal Space/Enter here:
    -- shared physical keys cannot be locked.)
    if f_isButtonPressed then
        for _, b in ipairs({ 'a', 'b', 'c', 'x', 'y', 'z', 's' }) do
            if f_isButtonPressed(b) then return true end
        end
    end
    if f_menuKeyDown then
        for _, b in ipairs({ 'a', 'b', 'c', 'x', 'y', 'z', 'start' }) do
            if f_menuKeyDown(b) then return true end
        end
    end
    if main and main.f_inputPay and main.f_inputPay(1) then return true end
    return false
end

-- Physical ENTER (keyboard). `keyDown` only exists as a LOCAL inside four
-- other menus, so `type(keyDown) == "function"` was always false in the
-- Misc/Main menus and their ENTER edges never fired. Global on purpose
-- (the main chunk has a 200 locals limit).
function f_physicalEnterDown()
    if not getKey then return false end
    for _, keyName in ipairs({ "RETURN", "KP_ENTER", "ENTER" }) do
        local ok, down = pcall(getKey, keyName)
        if ok and down then return true end
    end
    return false
end

-- A/B/C/X/Y/Z + START all advance (native Ikemen menu behavior).
-- Used in the options menu to turn page / start tournament.
-- (Preview/erase/etc. overlaps will be remapped separately.)
function f_checkStartOnly()
    if f_isButtonPressed then
        for _, b in ipairs({ 'a', 'b', 'c', 'x', 'y', 'z', 's' }) do
            if f_isButtonPressed(b) then return true end
        end
    end
    if f_menuKeyDown then
        for _, b in ipairs({ 'a', 'b', 'c', 'x', 'y', 'z', 'start' }) do
            if f_menuKeyDown(b) then return true end
        end
    end
    return false
end

-- Button D opens the Character Pool item (exact paths; 'd' collides with DOWN in commands).
function f_checkPoolKey()
    if f_menuKeyDown and f_menuKeyDown('d') then return true end
    if type(f_joystickCmdDown) == "function" and f_joystickCmdDown('d') then return true end
    return false
end

function f_checkCancelInput()
    if esc and esc() then return true end
    -- NOTE: B does NOT go back here (native menus use it to advance;
    -- in the tournament only START advances). Back = ESC / MENU / Select.
    -- Entrant's mapped MENU key backs out too (hint keeps showing ESC).
    if f_menuKeyDown and f_menuKeyDown("menu") then
        return true
    end
    -- Joystick MENU (Select): engine commands don't cover it, poll it live.
    if type(f_joystickCmdDown) == "function" and f_joystickCmdDown("menu") then
        return true
    end
    
    return false
end

-- =====================================================================
-- FULL SKELETON (7 columns: scaled R128 + R64..R4 + final)
-- Col 1 (R128): 32 matches/side in 2 interleaved sub-columns
--   match impar -> sub-coluna externa (perto da borda)
--   even match   -> inner sub-column (more toward center, a bit lower)
-- =====================================================================
local function f_getSkeletonLayout()
    if skeletonCache then return skeletonCache end
    local C = FIRST_COL
    local R = RIGHT_COL
    local cols = {}
    local prevLeft, prevRight = {}, {}
    local lineH = C.slotSize + C.rowGap

    -- Col 1: Round of 128 ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â scaled layout (32 matches per side)
    for i = 1, C.lines do
        local group = math.ceil(i / 2)              -- 1..16
        local isOuter = (i % 2 == 1)                -- 1,3,5... outer; 2,4,6... inner
        local y = C.startY
            + (group - 1) * R128_GROUP_GAP_Y
            + (isOuter and 0 or R128_INNER_OFFSET_Y)
            + SLOT_SHIFT_Y
        local xOffL = isOuter and 0 or R128_INNER_OFFSET_X
        local xOffR = isOuter and 0 or R128_INNER_OFFSET_X
        prevLeft[i] = {
            a = { x = COLS_LEFT_X[1] + layout.pairShiftRight + xOffL, y = y },
            b = { x = COLS_LEFT_X[1] + C.slotSize + C.pairGap + layout.pairShiftRight - layout.bShiftLeft + xOffL, y = y }
        }
        -- Right side: inner pushes toward center (left = -xOff)
        prevRight[i] = {
            a = { x = COLS_RIGHT_X[1] + layout.pairShiftRight - xOffR, y = y },
            b = { x = COLS_RIGHT_X[1] + R.slotSize + R.pairGap + layout.pairShiftRight - layout.bShiftLeft - xOffR, y = y }
        }
    end
    cols[1] = { left = prevLeft, right = prevRight }

    -- Cols 2..6: each with half the matches of the previous (Y at pair middle)
    for c = 2, FINAL_COL - 1 do
        local curLeft, curRight = {}, {}
        local linesInCol = math.floor(#prevLeft / 2)
        if linesInCol < 1 then linesInCol = 1 end
        for i = 1, linesInCol do
            local yL = (prevLeft[2 * i - 1].a.y + prevLeft[2 * i].a.y) / 2
            local yR = (prevRight[2 * i - 1].a.y + prevRight[2 * i].a.y) / 2
            curLeft[i] = {
                a = { x = COLS_LEFT_X[c] + layout.pairShiftRight, y = yL },
                b = { x = COLS_LEFT_X[c] + C.slotSize + C.pairGap + layout.pairShiftRight - layout.bShiftLeft, y = yL }
            }
            curRight[i] = {
                a = { x = COLS_RIGHT_X[c] + layout.pairShiftRight, y = yR },
                b = { x = COLS_RIGHT_X[c] + C.slotSize + C.pairGap + layout.pairShiftRight - layout.bShiftLeft, y = yR }
            }
        end
        cols[c] = { left = curLeft, right = curRight }
        prevLeft, prevRight = curLeft, curRight
    end

    -- Col 7: Final / 3rd place / champion (center)
    --local finalY = C.startY + (C.lines / 2) * lineH + layout.finalY + SLOT_SHIFT_Y 
    --if #prevLeft >= 1 then
    --    finalY = prevLeft[1].a.y
    --end
    local championY = layout.finalY - C.slotSize - C.rowGap - 99999  -- small champion slot off-screen (intentional)

    cols[FINAL_COL] = {
        left = { [1] = {
            a = { x = COLS_LEFT_X[FINAL_COL] - C.slotSize - 1 + layout.pairShiftRight, y = layout.finalY },
            b = { x = COLS_LEFT_X[FINAL_COL] + 1 + layout.pairShiftRight - layout.bShiftLeft, y = layout.finalY }
        } },
        right = {},
        thirdPlace = {
            a = { x = COLS_LEFT_X[FINAL_COL] - C.slotSize - 1 + layout.pairShiftRight, y = layout.thirdPlaceY },
            b = { x = COLS_LEFT_X[FINAL_COL] + 1 + layout.pairShiftRight - layout.bShiftLeft, y = layout.thirdPlaceY },
        },
        champion = {
            x = COLS_LEFT_X[FINAL_COL] - (C.slotSize / 2) + layout.pairShiftRight - (layout.bShiftLeft / 2),
            y = championY,
        },
    }

    skeletonCache = cols
    return cols
end

