            if NE.t == nil then NE.t = f_makeRepeatEdge(function() return f_nudgeKeyDown("T", "t") end, 18, 4) end
            if NE.g == nil then NE.g = f_makeRepeatEdge(function() return f_nudgeKeyDown("G", "g") end, 18, 4) end
            if NE.u == nil then NE.u = f_makeRepeatEdge(function() return f_nudgeKeyDown("U", "u") end, 18, 4) end
            if NE.j == nil then NE.j = f_makeRepeatEdge(function() return f_nudgeKeyDown("J", "j") end, 18, 4) end
            local dy1, dy2, dy4 = 0, 0, 0
            if NE.r() then dy1 = dy1 - 1 end
            if NE.f() then dy1 = dy1 + 1 end
            if NE.t() then dy2 = dy2 - 1 end
            if NE.g() then dy2 = dy2 + 1 end
            if NE.u() then dy4 = dy4 - 1 end
            if NE.j() then dy4 = dy4 + 1 end
