            if dy2 ~= 0 then TOURNAMENT_NUDGE_Y2 = (tonumber(TOURNAMENT_NUDGE_Y2) or 0) + dy2 end
            if dy4 ~= 0 then TOURNAMENT_NUDGE_Y4 = (tonumber(TOURNAMENT_NUDGE_Y4) or 0) + dy4 end
