            apply = function(v) tournament.randomCharsForHumans = (v == "YES") end,
        },
        {
            page = 3,
            label = "TEAM MODE:",
            options = teamModeOptions,
            idx = idxOfTeamMode(),
            format = function(v) return v.label end,
            apply = function(v) tournament.teamMode = v.mode; tournament.teamSize = v.chars end,
            isTeamMode = true,
        },
        {
          page = 3,
          label = "TOURNAMENT SIZE:",
         options = sizeOptions,
         idx = idxOf(sizeOptions, tournament.size),
         format = function(v)
             return tostring(v) .. " SLOTS" -- vermelho tratado no desenho (via f_isTournamentSizeAvailable)
         end,
          apply = function(v) tournament.size = v end,
         },
         {
