            format = function()
                local total = tournament.size * (tournament.teamSize or 1)
                return tostring(total) .. " PARTICIPANTS"
            end,
            apply = function() end,
        },
        {
            page = 3,
            label = "CPU CHARACTER POOL:",
            options = {true},  -- Dummy (only to fill the options slot)
            idx = 1,
            format = function()
                -- Same enabled/total as the pool subtitle ("Preset X - 300/435").
                local en, to = "?", "?"
                if type(f_getEnabledCharacterCount) == "function" then
