                if type(f_getTotalCharacterCount) == "function" then
                    to = tostring(f_getTotalCharacterCount())
                end
                return "Preset " .. tostring(characterPoolsActive) .. " - " .. en .. "/" .. to
            end,
            apply = function()
                -- Edge (poolEdge) already consumed the press; opens the slot
                -- columns (name + pool per slot) instead of the pool directly.
                if type(f_poolSlotColumns) == "function" then
                    f_poolSlotColumns()
                end
                -- portraits/bg/cursor already restored at end of f_characterPoolScreen
            end,
            isAction = true,  -- Flag: only runs with cursor on this option
            isPoolSlotAction = true,  -- LEFT/RIGHT cycles the active slot on this row
        },
        {
            page = 3,
            id = "cpuFlagPool",
            label = "CPU FLAGS POOL:",
            options = {true},  -- Dummy (only to fill the options slot)
            idx = 1,
            format = function() return "" end,
            apply = function() end,
            isAction = true,
            isChange = true,
            onChange = function()
                if type(f_flagPoolScreen) == "function" then f_flagPoolScreen() end
            end,
        },
        {
            page = 3,
            label = "ALLOW DUPLICATE CHARACTERS:",
