            idx = tournament.allowDuplicateChars and 1 or 2,
            format = function(v) return v and "ON" or "OFF" end,
            apply = function(v) tournament.allowDuplicateChars = v end,
        },
        {
            page = 3,
            label = "ALLOW RANDOM CPU PALETTE:",
            options = {true, false},
            idx = tournament.allowRandomCpuPalette and 1 or 2,
            format = function(v) return v and "ON" or "OFF" end,
            apply = function(v) tournament.allowRandomCpuPalette = v end,
        },
        {
            page = 3,
            label = "THIRD-PLACE PLAYOFF:",
            options = {true, false},
            idx = tournament.thirdPlacePlayoff and 1 or 2,
            format = function(v) return v and "ON" or "OFF" end,
            apply = function(v) tournament.thirdPlacePlayoff = v end,
        },

        -- ==========================================
        -- PAGE 4: Advanced Settings
        -- ==========================================
        {
            page = 4,
            label = "ROUNDS TO WIN:",
            options = roundsOptions,
            idx = idxOf(roundsOptions, tournament.rounds),
            format = function(v) return tostring(v) end,
            apply = function(v) tournament.rounds = v end,
        },
        {
