    local page = math.floor(tonumber(startPage) or 1)
    if page < 1 then page = 1 end
    local maxPages = 5
    if page > maxPages then page = maxPages end

    -- RESTORE DEFAULTS row on every setup screen EXCEPT page 2 (Main
    -- Settings = START MODE/SLOT, the load/new tournament screen): pressing
    -- the action key (D, same as the scale rows) resets the current page to
    -- the SD/HD defaults. Rendered as "PRESS [D] TO [default-icon]" (isChange).
    for pg = 1, maxPages do
        if pg ~= 2 then
        items[#items + 1] = {
            page = pg,
            label = "RESTORE DEFAULTS:",
            options = {true},  -- Dummy (only to fill the options slot)
            idx = 1,
            format = function() return "" end,
            apply = function() end,
            isAction = true,   -- LEFT/RIGHT skip it; D triggers via isChange
            isChange = true,
            isRestoreDefaults = true,
        }
        end
    end

    -- Status do save do SLOT selecionado (Main Settings > SLOT).
    -- Updated on demand: on open and whenever the slot changes.
    local previewSlot, hasSave, saveValid, saveMissing, previewSummary = nil, false, false, {}, nil
    local function f_refreshSlotPreview(force)
        local slot = tonumber(tournament.saveSlot) or 1
        if not force and slot == previewSlot then return end
        hasSave, saveValid, saveMissing = f_getSaveValidationStatus(slot)
        previewSummary = nil
        if hasSave and saveValid then
            local data = f_loadTournamentState(slot)
            if type(data) == "table" then
                if type(data.summary) == "table" then
                    previewSummary = data.summary
                else
                    -- Old save (no summary): derives from raw state
                    previewSummary = f_deriveSummaryFromState(data)
                end
            end
        end
        previewSlot = slot
    end
    -- Valid 128 save outside widescreen, with CONTINUE selected:
    -- CONTINUE blocks, hint warns and the panel row turns red.
    -- In NEW TOURNAMENT everything stays gray (no warning).
    local function f_saveWrongSize()
        return tournament.startMode == "CONTINUE"
            and hasSave and saveValid and type(previewSummary) == "table"
            and not f_isTournamentSizeAvailable(previewSummary.size)
    end
    f_refreshSlotPreview(true)
    if isLoadMenu and hasSave and saveValid then
        tournament.startMode = "CONTINUE"
    elseif tournament.startMode == "CONTINUE" and not (hasSave and saveValid) then
        tournament.startMode = "NEW"
    end
    if tournament.startMode ~= "CONTINUE" then tournament.startMode = "NEW" end
    -- Slot 0 (auto-save): only CONTINUE (load). Never NEW.
    if (tonumber(tournament.saveSlot) or 1) == 0 then
        tournament.startMode = "CONTINUE"
    end
    for _, it in ipairs(items) do
        if it.isStartMode then
            it.idx = (tournament.startMode == "CONTINUE") and 2 or 1
            break
        end
    end

    local function getCurrentPageItems()
        local res = {}
        for i, it in ipairs(items) do
            if it.page == page then
                table.insert(res, {globalIndex = i, item = it})
            end
        end
        return res
    end

    local currentPageItems = getCurrentPageItems()
    local cursor = 1
    local scrollTop = 1  -- first visible row (window follows cursor)
    
    -- Prevents the cursor from starting on the info line
    if currentPageItems[cursor] and currentPageItems[cursor].item.isInfo then
        cursor = 2 
    end

    local cell = (motif and motif.select_info and motif.select_info.cell) or {}
    local kUp = (cell.up and cell.up.key) or "U"
    local kDown = (cell.down and cell.down.key) or "D"
    local kLeft = (cell.left and cell.left.key) or "L"
    local kRight = (cell.right and cell.right.key) or "R"
    
    local function makeEdge(fn)
        local prevVal = true
        return function()
            local cur = fn() and true or false
            local trig = cur and not prevVal
            prevVal = cur
            return trig
        end
    end

    local upEdge = f_makeRepeatEdge(function() return f_menuDirPressed("up", kUp) end, 22, 6)
    local downEdge = f_makeRepeatEdge(function() return f_menuDirPressed("down", kDown) end, 22, 6)
    local leftEdge = f_makeRepeatEdge(function() return f_menuDirPressed("left", kLeft) end, 18, 4)
    local rightEdge = f_makeRepeatEdge(function() return f_menuDirPressed("right", kRight) end, 18, 4)
    -- A/B/C/X/Y/Z/START turn page / start tournament; D on the Pool item opens it instead
    local startEdge = makeEdge(function() return f_checkStartOnly() end)
    -- Physical ENTER (+ stick START): same as START, advertised on Main
    -- Settings (page 2) only; other pages keep button-only advance.
    local enterEdge = makeEdge(function()
        if f_physicalEnterDown() then return true end
        if type(f_joystickCmdDown) == "function" and f_joystickCmdDown("start") then return true end
        return false
    end)
    local poolEdge = makeEdge(function() return f_checkPoolKey() end)
    local cancelEdge = makeEdge(function() return f_checkCancelInput() end)
    local restoreEdge = makeEdge(function()
        local rk = string.lower(tostring(TOURNAMENT_RESTORE_DEFAULTS_BUTTON or "w"))
        if f_menuKeyDown and f_menuKeyDown(rk) then return true end
        if type(f_joystickCmdDown) == "function" and f_joystickCmdDown(rk) then return true end
        return false
    end)

