    textImgSetText(previewHintTxt, "PRESS " .. string.upper(tostring(TOURNAMENT_PREVIEW_BUTTON or "c")) .. " TO PREVIEW!")

    -- SD warning (right above hint; ADJUST position/scale): only draws in SD on Misc page
    local sdHintTxt = textImgNew()
    textImgSetFont(sdHintTxt, minhaFonte); textImgSetBank(sdHintTxt, menuFontBank)
    textImgSetAlign(sdHintTxt, 0)
    textImgSetColor(sdHintTxt, 255, 80, 80)
