    textImgSetScale(sdHintTxt, MENU_CONFIG.hint.scaleX, MENU_CONFIG.hint.scaleY)
    textImgSetText(sdHintTxt, "not available in this current resolution")

local labelTxts, valueTxts = {}, {}
    local maxItemsPerPage = 14 
    for i = 1, maxItemsPerPage do
        local yPos = MENU_CONFIG.startY + (i - 1) * MENU_CONFIG.rowSpacing
        local lt = textImgNew()
        textImgSetFont(lt, minhaFonte); textImgSetBank(lt, menuFontBank)
        textImgSetAlign(lt, MENU_CONFIG.label.align or -1)
        textImgSetPos(lt, MENU_CONFIG.posX + MENU_CONFIG.label.offsetX, yPos)
        textImgSetScale(lt, MENU_CONFIG.label.scaleX, MENU_CONFIG.label.scaleY)
        labelTxts[i] = lt
        
        local vt = textImgNew()
        textImgSetFont(vt, minhaFonte); textImgSetBank(vt, menuFontBank)
        textImgSetAlign(vt, MENU_CONFIG.value.align or 1)
        textImgSetPos(vt, MENU_CONFIG.posX + MENU_CONFIG.value.offsetX, yPos)
        textImgSetScale(vt, MENU_CONFIG.value.scaleX, MENU_CONFIG.value.scaleY)
        valueTxts[i] = vt
    end

    -- Save panel (Main Settings, page 2): up to 16 label/value rows
    -- below the 2 items (16 only in finished save with 1P+2P and 3rd place:
    -- the title takes label + centered name on the next row).
    -- Always visible (NEW or CONTINUE); hint-colored gray.
    local SAVE_PANEL_ROWS = 16
    local SAVE_PANEL_START_Y = MENU_CONFIG.startY + 2 * MENU_CONFIG.rowSpacing + 0
    local SAVE_PANEL_SPACING = 9
    local SAVE_PANEL_SCALE = 0.21
    local savePanelLabelTxts, savePanelValueTxts = {}, {}
    for i = 1, SAVE_PANEL_ROWS do
        local yPos = SAVE_PANEL_START_Y + (i - 1) * SAVE_PANEL_SPACING
        local lt = textImgNew()
        textImgSetFont(lt, minhaFonte); textImgSetBank(lt, menuFontBank)
        textImgSetAlign(lt, MENU_CONFIG.label.align or -1)
        textImgSetPos(lt, MENU_CONFIG.posX + MENU_CONFIG.label.offsetX, yPos)
        textImgSetScale(lt, SAVE_PANEL_SCALE, SAVE_PANEL_SCALE)
        savePanelLabelTxts[i] = lt
        local vt = textImgNew()
        textImgSetFont(vt, minhaFonte); textImgSetBank(vt, menuFontBank)
        textImgSetAlign(vt, MENU_CONFIG.value.align or 1)
        textImgSetPos(vt, MENU_CONFIG.posX + MENU_CONFIG.value.offsetX, yPos)
        textImgSetScale(vt, SAVE_PANEL_SCALE, SAVE_PANEL_SCALE)
        savePanelValueTxts[i] = vt
    end

    -- "Empty Slot": same Y as panel 1st row, centered on X axis,
    -- hint-colored gray. Always visible (NEW or CONTINUE) with empty slot.
    local slotEmptyTxt = textImgNew()
    textImgSetFont(slotEmptyTxt, minhaFonte); textImgSetBank(slotEmptyTxt, menuFontBank)
    textImgSetAlign(slotEmptyTxt, 0)
    textImgSetColor(slotEmptyTxt, unpack(MENU_CONFIG.hint.color))
    textImgSetPos(slotEmptyTxt, 160, SAVE_PANEL_START_Y)
    textImgSetScale(slotEmptyTxt, SAVE_PANEL_SCALE, SAVE_PANEL_SCALE)
    textImgSetText(slotEmptyTxt, "Empty Slot")

    -- Gray "add more songs..." instead of SD hint; only with cursor on preview
    -- (ADJUST position/scale)
    local songsHintTxt = textImgNew()
    textImgSetFont(songsHintTxt, minhaFonte); textImgSetBank(songsHintTxt, menuFontBank)
    textImgSetAlign(songsHintTxt, 0)
    textImgSetColor(songsHintTxt, 255, 80, 80)
    textImgSetPos(songsHintTxt, MENU_CONFIG.hint.posX, MENU_CONFIG.hint.posY - 22)
    textImgSetScale(songsHintTxt, MENU_CONFIG.hint.scaleX, MENU_CONFIG.hint.scaleY)
    textImgSetText(songsHintTxt, "Add more songs by naming them")
    local songsHintTxt2 = textImgNew()
    textImgSetFont(songsHintTxt2, minhaFonte); textImgSetBank(songsHintTxt2, menuFontBank)
    textImgSetAlign(songsHintTxt2, 0)
    textImgSetColor(songsHintTxt2, 255, 80, 80)
    textImgSetPos(songsHintTxt2, MENU_CONFIG.hint.posX, MENU_CONFIG.hint.posY - 11)
    textImgSetScale(songsHintTxt2, MENU_CONFIG.hint.scaleX, MENU_CONFIG.hint.scaleY)
    textImgSetText(songsHintTxt2, "TournamentMode01.mp3, TournamentMode02.mp3, etc")

    local boxCursorRect = f_getOrCreateRect("tournamentMenuBoxCursor")
    if boxCursorRect then rectSetColor(boxCursorRect, unpack(MENU_CONFIG.box.color)) end
    
    local blinkTime = 0
    local confirmed, canceled = false, false

    if main and main.f_cmdInput then main.f_cmdInput() end
    -- Edge detection (prevVal=true) already ignores held button on enter ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â no wait = no flash

    while not confirmed and not canceled do
        if main and main.f_cmdInput then main.f_cmdInput() end
        blinkTime = blinkTime + 1

        local u, d = upEdge(), downEdge()
        local l, r = leftEdge(), rightEdge()
        local ent = enterEdge()

        -- Slot 0 (auto-save): keep START MODE locked on CONTINUE while selected.
        if (tonumber(tournament.saveSlot) or 1) == 0 then
            if tournament.startMode ~= "CONTINUE" then
                tournament.startMode = "CONTINUE"
            end
            for _, itSm in ipairs(items) do
                if itSm.isStartMode then
                    itSm.idx = 2
                    break
                end
            end
        end
        
        if u then
            repeat
                cursor = cursor - 1
                if cursor < 1 then cursor = #currentPageItems end
            until #currentPageItems == 0 or (currentPageItems[cursor] and currentPageItems[cursor].item and not currentPageItems[cursor].item.isInfo)
            sndMove()
        elseif d then
            repeat
                cursor = cursor + 1
                if cursor > #currentPageItems then cursor = 1 end
            until #currentPageItems == 0 or (currentPageItems[cursor] and currentPageItems[cursor].item and not currentPageItems[cursor].item.isInfo)
            sndMove()
        elseif l then
            local it = currentPageItems[cursor] and currentPageItems[cursor].item
            if it and it.isPoolSlotAction then
                -- CPU CHARACTER POOL row: LEFT cycles the active slot.
                local n = tonumber(CHARACTER_POOL_SLOTS) or 50
                local cur = (tonumber(characterPoolsActive) or 1) - 1
                if cur < 1 then cur = n end
                f_applyCharacterPoolSlot(cur)
                f_saveCharacterPools()
                sndMove()
            -- isAction (Character Pool) does not change with LEFT/RIGHT
            -- isSDLocked in SD also does not change (locked to OFF)
            elseif it and not it.isInfo and not it.isAction
               and not (it.isSDLocked and (tournament.screenMode or "HD") == "SD") then
                it.idx = it.idx - 1; if it.idx < 1 then it.idx = #it.options end
                if it.apply then it.apply(it.options[it.idx]) end
                if it.isSlotProp and type(f_refreshSlotPreview) == "function" then
                    f_refreshSlotPreview(true)
                end
                if type(f_markTournamentConfigDirty) == "function" then f_markTournamentConfigDirty() end
                sndMove()
            end
        elseif r then
            local it = currentPageItems[cursor] and currentPageItems[cursor].item
            if it and it.isPoolSlotAction then
                -- CPU CHARACTER POOL row: RIGHT cycles the active slot.
                local n = tonumber(CHARACTER_POOL_SLOTS) or 50
                local cur = (tonumber(characterPoolsActive) or 1) + 1
                if cur > n then cur = 1 end
                f_applyCharacterPoolSlot(cur)
                f_saveCharacterPools()
                sndMove()
            elseif it and not it.isInfo and not it.isAction
               and not (it.isSDLocked and (tournament.screenMode or "HD") == "SD") then
                it.idx = it.idx + 1; if it.idx > #it.options then it.idx = 1 end
                if it.apply then it.apply(it.options[it.idx]) end
                if it.isSlotProp and type(f_refreshSlotPreview) == "function" then
                    f_refreshSlotPreview(true)
                end
                if type(f_markTournamentConfigDirty) == "function" then f_markTournamentConfigDirty() end
                sndMove()
            end
        elseif poolEdge() then
            -- Button D: ONLY works on the Character Pool item
            -- (CHANGE rows use the preview-key branch below instead)
            local entry = currentPageItems[cursor]
            local it = entry and entry.item
            if it and it.isAction and not it.isChange then
                sndDone()
                if it.apply then it.apply() end
                -- edge detection already avoids re-trigger; no wait = no black flash
            end

     elseif startEdge() or (page == 2 and ent) then
         local blockStart = false
         local continueReady = (tournament.startMode == "CONTINUE") and hasSave and saveValid
             and not f_saveWrongSize()
           if page == 2 and tournament.startMode == "CONTINUE" and not continueReady then
              blockStart = true
          end
           if page == 2 and tournament.startMode ~= "CONTINUE" and hasSave then
               blockStart = true
           end
           -- Slot 0 (auto-save) can never start NEW (load only).
           if page == 2 and tournament.startMode ~= "CONTINUE"
               and (tonumber(tournament.saveSlot) or 1) == 0 then
               blockStart = true
           end
          if page >= 3 then
              local maxCharsAvailable = f_getEnabledCharacterCount()
              local totalParticipants = tournament.size * (tournament.teamSize or 1)
              local notEnoughChars = (not tournament.allowDuplicateChars) and (totalParticipants > maxCharsAvailable)
              local emptyPool = (maxCharsAvailable <= 0)
              local isWIP = (tournament.format ~= "KNOCKOUT")
              local is128NotAvailable = not f_isTournamentSizeAvailable(tournament.size)
              local tooManyHumans = (tonumber(tournament.humanPlayers) or 0) > (tonumber(tournament.size) or 0)
              blockStart = blockStart or notEnoughChars or emptyPool or isWIP or is128NotAvailable or tooManyHumans
          end
         if page == maxPages and tournament.startMode == "CONTINUE" and not continueReady then
             blockStart = true
         end
         if blockStart then
             sndCancel()
           elseif page == 2 and continueReady then
              -- Valid CONTINUE: skips Basic/Advanced and goes straight to bracket
              confirmed = true
              sndDone()
             elseif page < maxPages then
                  if page == 2 and tournament.startMode ~= "CONTINUE" then
                      -- NEW TOURNAMENT: tournament name entry first.
                      -- ENTER confirms (blank keeps previous title), ESC stays here.
                      sndDone()
                      local newName = nil
                      if type(f_promptTournamentName) == "function" then
                          newName = f_promptTournamentName()
                      end
                      if newName == nil then
                          sndCancel()
                      else
                          local trimmed = tostring(newName):match("^%s*(.-)%s*$") or ""
                          if trimmed ~= "" then
                              tournament.title = trimmed
                              f_saveTournamentConfig()
                          end
                          page = page + 1
                          currentPageItems = getCurrentPageItems()
                          cursor = 1
                          scrollTop = 1
                          if currentPageItems[cursor] and currentPageItems[cursor].item.isInfo then cursor = 2 end
                          sndDone()
                      end
                  else
                      page = page + 1
                      currentPageItems = getCurrentPageItems()
                      cursor = 1
                      scrollTop = 1
                      if currentPageItems[cursor] and currentPageItems[cursor].item.isInfo then cursor = 2 end
                      sndDone()
                  end
            else
                confirmed = true
                sndDone()
            end
        elseif cancelEdge() then
            if page > 1 then
                page = page - 1
                currentPageItems = getCurrentPageItems()
                cursor = 1
                scrollTop = 1
                if currentPageItems[cursor] and currentPageItems[cursor].item.isInfo then cursor = 2 end
                sndCancel()
            else
                canceled = true
                sndCancel()
            end
        end

        -- Scroll window follows the cursor (only matters when rows overflow).
        do
            local V = tonumber(MENU_CONFIG.visibleRows) or 10
            local n = #currentPageItems
            if n > V then
                if cursor < scrollTop then scrollTop = cursor
                elseif cursor > scrollTop + V - 1 then scrollTop = cursor - V + 1 end
                if scrollTop < 1 then scrollTop = 1 end
                if scrollTop > n - V + 1 then scrollTop = n - V + 1 end
            else
                scrollTop = 1
            end
        end

        -- Music preview: dedicated key only with cursor on item (saves nothing).
        -- CHANGE rows (PLAYERS IDS/FLAGS) use the same key to open the editor.
        if f_checkPreviewKeyEdge() then
            local pentry = currentPageItems[cursor]
            local pit = pentry and pentry.item
            if pit and pit.isPreview then
                if type(f_previewTournamentMusic) == "function" then
                    f_previewTournamentMusic(pit.options[pit.idx], pit.previewWhich)
                end
                sndDone()
            elseif pit and pit.isRestoreDefaults then
                sndDone()
                if type(f_resetMenuItemsToDefaults) == "function" then
                    f_resetMenuItemsToDefaults(currentPageItems)
                end
            elseif pit and pit.isChange and type(pit.onChange) == "function" then
                sndDone()
                pit.onChange()
            end
        end

        -- X: polled ONCE per frame (erases current slot save on Main
        -- (page 2, any row: SLOT, CONTINUE, NEW...), restore elsewhere).
        -- A second same-key poll in the same frame would starve (first read
        -- consumes the press), which is why erase+restore share this block.
        if restoreEdge() then
            -- Slot 0 (auto-save) is load-only: never erased here.
            if page == 2 and hasSave and (tonumber(tournament.saveSlot) or 1) ~= 0 then
                f_clearSavedTournament()
                f_refreshSlotPreview(true)
                sndDone()
            elseif page == 2 and hasSave then
                sndCancel()
            elseif page ~= 2 then
                if type(f_resetMenuItemsToDefaults) == "function" then
                    f_resetMenuItemsToDefaults(currentPageItems)
                end
                sndDone()
            end
        end

        -- Slot may have changed via LEFT/RIGHT: revalidates (no-op if same)
        f_refreshSlotPreview()

                if clearColor then clearColor(0, 0, 0) end
        tournamentBgSys.draw()
        f_drawBlackOverlay()

        -- Menu box behind rows (native options style).
        if type(f_drawMenuBox) == "function" then f_drawMenuBox() end
        -- Desenho do Cursor Box
        if boxCursorRect and currentPageItems[cursor] and currentPageItems[cursor].item and not currentPageItems[cursor].item.isInfo then
            local selY = MENU_CONFIG.startY + (cursor - (scrollTop or 1)) * MENU_CONFIG.rowSpacing
            local boxY1 = selY + MENU_CONFIG.box.offsetY - MENU_CONFIG.box.height
            local boxY2 = selY + MENU_CONFIG.box.offsetY
            if rectSetWindow then rectSetWindow(boxCursorRect, MENU_CONFIG.box.x1, boxY1, MENU_CONFIG.box.x2, boxY2) end
            local alphaRange = MENU_CONFIG.box.alphaMax - MENU_CONFIG.box.alphaMin
            local srcAlpha = MENU_CONFIG.box.alphaMin + math.floor(alphaRange * math.sin(blinkTime * 0.15))
            local dstAlpha = 255 - srcAlpha
            if rectSetAlpha then rectSetAlpha(boxCursorRect, srcAlpha, dstAlpha) end
            if rectUpdate then rectUpdate(boxCursorRect) end
        end

        if boxCursorRect and currentPageItems[cursor] and currentPageItems[cursor].item and not currentPageItems[cursor].item.isInfo then pcall(rectDraw, boxCursorRect) end
        
        textImgDraw(titleTxt)
        
        -- Draws Subtitle
        if page == 1 then
            textImgSetText(subtitleTxt, T("title_misc"))
        elseif page == 2 then
            textImgSetText(subtitleTxt, T("title_main"))
        elseif page == 3 then
            textImgSetText(subtitleTxt, T("title_basic"))
        elseif page == 4 then
            textImgSetText(subtitleTxt, T("title_advanced"))
        else
            textImgSetText(subtitleTxt, T("title_music"))
        end
        textImgDraw(subtitleTxt)

          -- Avisos: Main (save) | Basic/Advanced (tournament)
     local maxCharsAvailable = f_getEnabledCharacterCount()
     local totalParticipants = tournament.size * (tournament.teamSize or 1)
     local notEnoughChars = (not tournament.allowDuplicateChars) and (totalParticipants > maxCharsAvailable)
     local emptyPool = (maxCharsAvailable <= 0)
     local isWIP = (tournament.format ~= "KNOCKOUT")
     local is128NotAvailable = not f_isTournamentSizeAvailable(tournament.size)
      local continueInvalid = (tournament.startMode == "CONTINUE") and not (hasSave and saveValid)
      -- Empty slot uses its own object (slotEmptyTxt, at panel Y).
      -- Invalid save: red warning in any mode (NEW or CONTINUE).
       if page == 2 and hasSave and not saveValid then
           local nMiss = (type(saveMissing) == "table") and #saveMissing or 0
          textImgSetText(hintTxt, "WARNING: CANNOT LOAD SAVE ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â "
              .. tostring(nMiss) .. " CHAR(S) MISSING FROM SELECT.DEF")
          textImgSetColor(hintTxt, 255, 80, 80)
      elseif page == 2 and f_saveWrongSize() then
          textImgSetText(hintTxt, "Can't load this tournament size in the current resolution")
          textImgSetColor(hintTxt, 255, 80, 80)
      elseif page == 2 and tournament.startMode ~= "CONTINUE"
          and (tonumber(tournament.saveSlot) or 1) == 0 then
          -- Auto-save slot: no "clean first" (cannot erase here); load-only.
          textImgSetText(hintTxt, "SLOT 0 IS AUTO-SAVE ONLY!")
          textImgSetColor(hintTxt, 255, 80, 80)
      elseif page == 2 and tournament.startMode ~= "CONTINUE" and hasSave
          and (tonumber(tournament.saveSlot) or 1) ~= 0 then
          textImgSetText(hintTxt, "Clean the slot first!")
          textImgSetColor(hintTxt, 255, 80, 80)
      elseif page >= 3 and isWIP then
         textImgSetText(hintTxt, "WARNING: THIS FORMAT IS WORK IN PROGRESS! (SELECT KNOCKOUT)")
         textImgSetColor(hintTxt, 255, 80, 80)
      elseif page >= 3 and emptyPool then
         textImgSetText(hintTxt, "WARNING: CHARACTER POOL IS EMPTY! (Enable at least 1 character)")
         textImgSetColor(hintTxt, 255, 80, 80)
      elseif page >= 3 and notEnoughChars then
         textImgSetText(hintTxt, "WARNING: NOT ENOUGH CHARACTERS! (Need " .. totalParticipants .. " | Have " .. maxCharsAvailable .. ")")
         textImgSetColor(hintTxt, 255, 80, 80)
      elseif page >= 3 and is128NotAvailable then
         if tournament and tostring(tournament.screenMode or ""):upper() == "SD" then
             textImgSetText(hintTxt, "128 slots not available for this current resolution")
         else
             textImgSetText(hintTxt, "Not available in the current resolution")
         end
         textImgSetColor(hintTxt, 255, 80, 80)
      elseif page >= 3 and (tonumber(tournament.humanPlayers) or 0) > (tonumber(tournament.size) or 0) then
         textImgSetText(hintTxt, "WARNING: HUMAN PLAYERS cannot exceed TOURNAMENT SIZE!")
         textImgSetColor(hintTxt, 255, 80, 80)
      else
          local stS = f_menuKeySpec("start", "START")
          local kxS = f_menuKeySpec("w", tostring(TOURNAMENT_RESTORE_DEFAULTS_BUTTON or "w"))
            if page == 2 and tournament.startMode == "CONTINUE" and hasSave and saveValid then
               f_drawHintSegments(hintTxt, {
                   { icon = 22 },
                   { key = "return", pad = "12", key2 = false },
                   { text = "   " }, { icon = 18 },
                   { key = "left" }, { text = "/" },
                   { key = "right" },
                  --[[ VOIDED (kept): BACK
                  { text = "   BACK " },
                  { key = "escape" },
                  ]]
              }, MENU_CONFIG.hint.posX, MENU_CONFIG.hint.posY)
           elseif page < maxPages then
                if page == 2 then
                    f_drawHintSegments(hintTxt, {
                       { icon = 22 },
                       { key = "return", pad = "12", key2 = false },
