                      { text = "SELECT " },
                      { key = "up" }, { text = "/" },
                      { key = "down" },
                      ]]
                      { icon = 18 },
                      { key = "left" }, { text = "/" },
                      { key = "right" },
                      --[[ VOIDED (kept):
                      { text = "   NEXT " },
                      { key = stS.key }, { text = "   BACK " },
                      { key = "escape" },
                      ]]
                  }, MENU_CONFIG.hint.posX, MENU_CONFIG.hint.posY)
              else
                  -- pages 1/3 (Misc/Basic): DEFAULT + NEXT
                  f_drawHintSegments(hintTxt, {
                      --[[ VOIDED (kept): SELECT, NEXT, BACK
                      { text = "SELECT " },
                      { key = "up" }, { text = "/" },
                      { key = "down" },
                      ]]
                      { icon = 18 },
                      { key = "left" }, { text = "/" },
                      { key = "right" },
                      --[[ VOIDED: RESTORE DEFAULTS now lives as a row
                      { text = "   " }, { icon = 7 },
