                      ]]
                      --[[ VOIDED (kept):
                      { text = "   NEXT " },
                      { key = stS.key }, { text = "   BACK " },
                      { key = "escape" },
                      ]]
                  }, MENU_CONFIG.hint.posX, MENU_CONFIG.hint.posY)
              end
          else
              f_drawHintSegments(hintTxt, {
                  --[[ VOIDED (kept): SELECT, START, BACK
                  { text = "SELECT " },
                  { key = "up" }, { text = "/" },
                  { key = "down" },
                  ]]
                  { icon = 18 },
                  { key = "left" }, { text = "/" },
