              }, MENU_CONFIG.hint.posX, MENU_CONFIG.hint.posY)
          end
          textImgSetColor(hintTxt, unpack(MENU_CONFIG.hint.color))
      end
      -- Avisos em texto puro: recentraliza (segments deixam pos stale,
