      textImgSetAlign(hintTxt, MENU_CONFIG.hint.align or 0)
      textImgSetPos(hintTxt, MENU_CONFIG.hint.posX, MENU_CONFIG.hint.posY)
      textImgDraw(hintTxt)
      local sdCursorEntry = currentPageItems[cursor]
      if page == 1 and (tournament.screenMode or "HD") == "SD"
         and sdCursorEntry and sdCursorEntry.item and sdCursorEntry.item.isSDLocked then
          textImgDraw(sdHintTxt)
      end

      -- Gray "PRESS X TO ERASE" next to SLOT value (Main page with save only;
