      if page == 2 and hasSave and (tonumber(tournament.saveSlot) or 1) ~= 0 then
          local exX = MENU_CONFIG.posX + MENU_CONFIG.value.offsetX + (SLOT_ERASE_HINT_DX or 50)
          local exY = MENU_CONFIG.startY - 0.5 + MENU_CONFIG.rowSpacing
          local exRaw = nil
          if type(f_getMenuKeyName) == "function" then exRaw = f_getMenuKeyName("w") end
          if type(exRaw) ~= "string" or exRaw == "" then exRaw = tostring(TOURNAMENT_ERASE_BUTTON or "w") end
          local exKey = string.upper(exRaw)
            f_drawHintSegments(eraseHintTxt, {
