            local it = entry.item
            textImgSetText(labelTxts[vi], it.label)
            local _vtextS = it.format(it.options[it.idx])
            textImgSetText(valueTxts[vi], _vtextS)
            
          if (it.isInfo and (notEnoughChars or emptyPool))
              or ((it._en or it.label) == "CPU CHARACTER POOL:" and emptyPool)
              or ((it._en or it.label) == "TOURNAMENT FORMAT:" and isWIP)
              or ((it._en or it.label) == "TOURNAMENT SIZE:" and not f_isTournamentSizeAvailable(tournament.size)) then
              textImgSetColor(valueTxts[vi], 255, 80, 80)
           elseif it.isSDLocked and (tournament.screenMode or "HD") == "SD" then
               -- SD: locked to OFF (gray value, does not change with LEFT/RIGHT)
               textImgSetColor(valueTxts[vi], unpack(MENU_CONFIG.hint.color))
           elseif it.isScreenMode and (not _hdAvailable or #(it.options or {}) <= 1) then
               -- Only SD available at this resolution: gray value (does not change with LEFT/RIGHT)
               textImgSetColor(valueTxts[vi], unpack(MENU_CONFIG.hint.color))
          else
              textImgSetColor(valueTxts[vi], unpack(MENU_CONFIG.value.color))
          end
            textImgSetColor(labelTxts[vi], unpack(MENU_CONFIG.label.color))
            
            if ((it._en or it.label) == "SLOT:") then
                f_drawHintSegments(labelTxts[vi], {{icon = 0}},
                    MENU_CONFIG.posX + MENU_CONFIG.label.offsetX,
                    MENU_CONFIG.startY + (vi - 1) * MENU_CONFIG.rowSpacing, 1)
                -- Drawer leaves align=1; row labels are right-anchored:
                -- restore or every later label on this visible slot shifts right.
                textImgSetAlign(labelTxts[vi], (MENU_CONFIG.label and MENU_CONFIG.label.align) or -1)
            else
                textImgDraw(labelTxts[vi])
            end
            f_drawMenuValueIconOrText(valueTxts[vi], it, _vtextS,
                MENU_CONFIG.posX + MENU_CONFIG.value.offsetX,
                MENU_CONFIG.startY + (vi - 1) * MENU_CONFIG.rowSpacing)
            if it.isPreview and previewHintTxt ~= nil then
