                local pvY = MENU_CONFIG.startY + (vi - 1) * MENU_CONFIG.rowSpacing
                local pvRaw = nil
                if type(f_getMenuKeyName) == "function" then pvRaw = f_getMenuKeyName("d") end
                if type(pvRaw) ~= "string" or pvRaw == "" then pvRaw = tostring(TOURNAMENT_PREVIEW_BUTTON or "d") end
                local pvKey = string.upper(pvRaw)
                f_drawHintSegments(previewHintTxt, {
                    { text = "PRESS " },
