                local axX = MENU_CONFIG.posX + MENU_CONFIG.label.offsetX + 8
                local axY = vy or (MENU_CONFIG.startY + (vi - 1) * MENU_CONFIG.rowSpacing)
                local axRaw = nil
                if type(f_getMenuKeyName) == "function" then axRaw = f_getMenuKeyName("d") end
