                local chRaw = nil
                if type(f_getMenuKeyName) == "function" then chRaw = f_getMenuKeyName("d") end
                if type(chRaw) ~= "string" or chRaw == "" then chRaw = tostring(TOURNAMENT_PREVIEW_BUTTON or "d") end
                local chKey = string.upper(chRaw)
                -- PLAYERS FLAGS / CPU FLAGS POOL use 16, PLAYERS IDS uses 17.
                -- ANIM SCALES uses 8 (same as SMALL above).
                local chIcon = 17
                if ((it._en or it.label) == "PLAYERS FLAGS:") then chIcon = 16 end
                if ((it._en or it.label) == "CPU FLAGS POOL:") then chIcon = 16 end
                if ((it._en or it.label) == "CHARACTERS ANIM PORTRAIT SCALE:") then chIcon = 8 end
                if it.isRestoreDefaults then chIcon = 7 end
                f_drawHintSegments(previewHintTxt, {
                    { text = "PRESS " },
                    { key = string.lower(chKey) },
                    { text = " TO " },
                    { icon = chIcon },
                }, chX, chY, 1)
            end

            -- Red sentence only when cursor is on a pool item (Character or
            -- Flags): line 1 with dual A icons (Key Config), line 2 plain.
            if it.isAction and not it.isChange and cursor == i then
                local rowY = MENU_CONFIG.startY + (vi - 1) * MENU_CONFIG.rowSpacing
                local paRaw = nil
                if type(f_getMenuKeyName) == "function" then paRaw = f_getMenuKeyName("d") end
                if type(paRaw) ~= "string" or paRaw == "" then paRaw = "d" end
                local what = "characters"
                if it.id == "cpuFlagPool" then what = "flags" end
                f_drawHintSegments(poolHintTxt, {
                    { text = "Press " },
                    { key = string.lower(paRaw) },
                    { text = " to choose which " .. what },
                }, 160, 211)
                textImgSetAlign(poolHintTxt, 0)
                textImgSetText(poolHintTxt, "should be included in the draw!")
                textImgSetPos(poolHintTxt, 160, 211 + 9)
                textImgDraw(poolHintTxt)
            end

            -- Team Mode icons
            if it.isTeamMode then
                local opt = it.options[it.idx]
                if opt.mode ~= "single" then
                    local red, white, iconScale = f_getTeamIcons()
                    local s = (iconScale or 1) * TEAM_ICON_SCALE_MULT
                    local nameW = TEAM_MODE_NAME_WIDTH[opt.label] or 50
                    local iconsX = (MENU_CONFIG.posX or 200) + (MENU_CONFIG.value.offsetX or 5) + nameW + TEAM_ICON_GAP
                    local rowY = (MENU_CONFIG.startY or 50) + (vi - 1) * (MENU_CONFIG.rowSpacing or 14)
                    for slot = 0, 3 do
                        local icon = (slot < opt.chars) and red or white
                        if icon then
                            animUpdate(icon)
                            pcall(animSetScale, icon, s, s)
                            pcall(animSetPos, icon, iconsX + slot * TEAM_ICON_SPACING, rowY + TEAM_ICON_OFFSET_Y)
                            pcall(animDraw, icon)
                        end
                    end
                end
            end
        end

        -- Scroll arrows (native options style) when rows overflow the window.
        do
            local V = tonumber(MENU_CONFIG.visibleRows) or 10
            local n = #currentPageItems
            if n > V and type(f_drawMenuScrollArrows) == "function" then
                f_drawMenuScrollArrows((scrollTop or 1) > 1,
                    ((scrollTop or 1) + V - 1) < n,
                    tonumber(MENU_CONFIG.scrollArrowX) or 306,
                    tonumber(MENU_CONFIG.scrollArrowUpY) or 62,
                    tonumber(MENU_CONFIG.scrollArrowDownY) or 226,
                    tonumber(MENU_CONFIG.scrollArrowScale) or 0.5)
            end
        end

        -- Save panel (Main Settings, page 2): always visible (NEW or
        -- CONTINUE) with valid save in slot; all hint-colored gray.
        -- Slot vazio: "Empty Slot" no Y da 1ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Âª linha.
        if page == 2 and not hasSave then
            textImgDraw(slotEmptyTxt)
        elseif page == 2 and hasSave and saveValid and type(previewSummary) == "table" then
            local ps = previewSummary
            local function fmtOnOff(v) return v and "ON" or "OFF" end
            local hp = tonumber(ps.humanPlayers) or 0
            local hpStr = "0 (CPU ONLY)"
            if hp == 1 then hpStr = "1 PLAYER"
            elseif hp > 1 then hpStr = tostring(hp) .. " PLAYERS" end
            local tmStr = "Single"
            do
                local m = tostring(ps.teamMode or "single"):lower()
                local n = tonumber(ps.teamSize) or 1
                if m ~= "single" then
                    local cap = m:sub(1, 1):upper() .. m:sub(2)
                    tmStr = cap .. " x" .. tostring(n)
                end
            end
            local totalR = ps.size
            do
                local ok, r = pcall(f_getPlayerMatchCount, tonumber(ps.size) or 64)
                if ok and r then totalR = r end
            end
            local rows = {
                { "TOURNAMENT TITLE:", "" },
                { "", tostring((ps.title ~= nil and ps.title ~= "") and ps.title or "TOURNAMENT"), true },
                { "TOURNAMENT SUBTITLE:", tostring((ps.subtitle ~= nil and ps.subtitle ~= "") and ps.subtitle or "Championship") },
                { "TOURNAMENT FORMAT:", tostring(ps.format or "KNOCKOUT") },
                { "HUMAN PLAYERS:", hpStr },
            }
            -- Char line only with humans: at hp==0 it renders "CPU ONLY",
            -- redundant with "0 (CPU ONLY)" right above it.
            if hp > 0 then
                rows[#rows + 1] = { "", tostring(ps.chars1 or ps.charsLine or "---"), true }  -- no label, centered
            end
            -- 2P goes on the bottom row (no comma, no repeated label), centered
            if ps.chars2 ~= nil and ps.chars2 ~= "" then
                rows[#rows + 1] = { "", tostring(ps.chars2), true }
            end
            if ps.finished then
                rows[#rows + 1] = { "ACTUAL ROUND:", "FINISHED" }
                -- Podium below Actual Round (3rd only if a match happened)
                if ps.podiumChamp ~= nil and ps.podiumChamp ~= "" then
                    rows[#rows + 1] = { "", tostring(ps.podiumChamp), true }
                end
                if ps.podiumRunner ~= nil and ps.podiumRunner ~= "" then
                    rows[#rows + 1] = { "", tostring(ps.podiumRunner), true }
                end
                if ps.podiumThird ~= nil and ps.podiumThird ~= "" then
                    rows[#rows + 1] = { "", tostring(ps.podiumThird), true }
                end
            else
                rows[#rows + 1] = { "ACTUAL ROUND:", tostring(ps.roundName or "---")
                    .. " (" .. tostring(ps.roundNum or 1) .. "/" .. tostring(totalR) .. ")" }
            end
            rows[#rows + 1] = { "TEAM MODE:", tmStr }
            rows[#rows + 1] = { "TOURNAMENT SIZE:", tostring(ps.size or "---") .. " SLOTS" }
            for i = 1, SAVE_PANEL_ROWS do
                local row = rows[i]
                if row then
                    textImgSetText(savePanelLabelTxts[i], row[1])
                    textImgSetText(savePanelValueTxts[i], row[2])
                    textImgSetColor(savePanelLabelTxts[i], unpack(MENU_CONFIG.hint.color))
                    -- Save that does not run at this resolution: "128 SLOTS" in red,
                    -- same as the screen that sets 128
                    if f_saveWrongSize() and row[1] == "TOURNAMENT SIZE:" then
                        textImgSetColor(savePanelValueTxts[i], 255, 80, 80)
                    else
                        textImgSetColor(savePanelValueTxts[i], unpack(MENU_CONFIG.hint.color))
                    end
                    -- Podium rows (FINISHED): value centered on X
                    if row[3] == true then
                        textImgSetAlign(savePanelValueTxts[i], 0)
                        textImgSetPos(savePanelValueTxts[i], PODIUM_CENTER_X or 160,
                            SAVE_PANEL_START_Y + (i - 1) * SAVE_PANEL_SPACING)
                    else
                        textImgSetAlign(savePanelValueTxts[i], 1)
                        textImgSetPos(savePanelValueTxts[i],
                            MENU_CONFIG.posX + MENU_CONFIG.value.offsetX,
                            SAVE_PANEL_START_Y + (i - 1) * SAVE_PANEL_SPACING)
                    end
                    textImgDraw(savePanelLabelTxts[i])
                    textImgDraw(savePanelValueTxts[i])
                end
            end
        end

        -- Invalid-save detail (Main page): ~10px below last item
      if page == 2 and hasSave and not saveValid then
            local n = #currentPageItems
            local lastY = MENU_CONFIG.startY + (n - 1) * MENU_CONFIG.rowSpacing
            local detail = "Missing from select.def ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â cannot continue this tournament."
            if type(saveMissing) == "table" and #saveMissing > 0 then
                local show = {}
                for i = 1, math.min(3, #saveMissing) do
                    local p = saveMissing[i]
                    local short = tostring(p):match("([^/\\]+)$") or tostring(p)
                    show[#show + 1] = short
                end
                detail = "Missing: " .. table.concat(show, ", ")
                if #saveMissing > 3 then
                    detail = detail .. " (+" .. tostring(#saveMissing - 3) .. " more)"
                end
            end
            textImgSetText(visualHintTxt, detail)
            textImgSetPos(visualHintTxt, 160, lastY + 12)
            textImgDraw(visualHintTxt)
        end
        
        if type(f_flushTournamentConfigTick) == "function" then f_flushTournamentConfigTick() end
        refresh()
    end

    if canceled then
        -- Does not call isAction apply (open Character Pool) on cancel/save.
        -- Music rows neither (already live on L/R; replaying tracks here
        -- played 1,2,3,4 in sequence on every setup exit).
        for _, it in ipairs(items) do
            if it.apply and not it.isAction and not it.isInfo
                and not (type(it.label) == "string"
                    and (it.label:find("MUSIC:", 1, true) or it.label:find("VOLUME:", 1, true))) then
                it.apply(it.options[it.idx])
            end
        end
        f_saveTournamentConfig()
        -- Preview must not follow onto the title: back to the set menu
        -- track first (title plays its own right after and wins).
        -- Guarded: no replay when already correct.
        do
            if type(f_getTournamentMusicPath) == "function" then
                local okW, wantW = pcall(f_getTournamentMusicPath, "menu")
                if okW and type(wantW) == "string" and wantW ~= ""
                    and tostring(TournamentSetMusic) ~= wantW then
                    if type(f_updateTournamentMusicPath) == "function" then f_updateTournamentMusicPath("menu") end
                    if type(f_playTournamentMusic) == "function" then f_playTournamentMusic("menu") end
                end
            end
        end
        -- Hold lock out (keyboard + joystick MENU): title resumes with its
        -- native menu and a held BACK would act there.
        if type(f_waitForRelease) == "function" then f_waitForRelease() end
        return false, false
    end

    for _, it in ipairs(items) do
        if it.apply and not it.isAction and not it.isInfo
            and not (type(it.label) == "string"
                and (it.label:find("MUSIC:", 1, true) or it.label:find("VOLUME:", 1, true))) then
            it.apply(it.options[it.idx])
        end
    end
    -- loadChoice: CONTINUE only if save exists, chars are still
    -- in select.def and the size runs at current resolution
    local wantContinue = (tournament.startMode == "CONTINUE")
    f_refreshSlotPreview()
    local hasSave2, saveValid2, missing2 = hasSave, saveValid, saveMissing
    if wantContinue and (not (hasSave2 and saveValid2) or f_saveWrongSize()) then
        print("[Tournament] CONTINUE blocked ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â invalid save/missing chars: "
            .. tostring(missing2 and #missing2 or 0))
        wantContinue = false
        tournament.startMode = "NEW"
    end
    loadSavedOption = wantContinue
    f_saveTournamentConfig()
    -- Final layout after all menu applies
    if type(f_applyLayoutMode) == "function" then
        pcall(f_applyLayoutMode)
    end
    -- Hold lock out (keyboard + joystick MENU): select resumes next and a
    -- held confirm/BACK would instantly pick or skip there.
    if type(f_waitForRelease) == "function" then f_waitForRelease() end
    return true, loadSavedOption
end
-- =====================================================================
-- INICIALIZA ESTRUTURA DAS RODADAS
-- =====================================================================
local function f_initAllRounds(bracket, size)
    local totalRounds = f_getPlayerMatchCount(size)
    local currentMatchesPerSide = size / 4
    for r = 2, totalRounds do
        if r == totalRounds then
            bracket.rounds[r] = { left = { { a = nil, b = nil, winner = nil } }, right = {} }
        else
            currentMatchesPerSide = math.ceil(currentMatchesPerSide / 2)
            local leftMatches, rightMatches = {}, {}
            for i = 1, currentMatchesPerSide do leftMatches[i] = { a = nil, b = nil, winner = nil } end
            for i = 1, currentMatchesPerSide do rightMatches[i] = { a = nil, b = nil, winner = nil } end
            bracket.rounds[r] = { left = leftMatches, right = rightMatches }
        end
    end
end

