-- WAIT FOR THE PLAYER TO RELEASE THE KEY
-- =====================================================================
-- =====================================================================
-- MAIN TOURNAMENT LOOP (FIXED - WITH PAUSE HANDLING)
-- =====================================================================

-- =====================================================================
-- CPU PALETTES
-- - random OFF + no duplicates: always palette 1
-- - random ON: random 1..12
-- - duplicates ON: 1st instance ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ palette 1; extras ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ other free ones
-- =====================================================================
local function f_pickCpuPalette(path, usedPalsByPath)
    path = tostring(path or "")
    usedPalsByPath[path] = usedPalsByPath[path] or {}
    local used = usedPalsByPath[path]

    if tournament.allowDuplicateChars then
        if not used[1] then
            used[1] = true
            return 1
        end
        local candidates = {}
        for p = 2, 12 do
            if not used[p] then candidates[#candidates + 1] = p end
        end
        if #candidates == 0 then
            for p = 1, 12 do candidates[#candidates + 1] = p end
        end
        local pick = candidates[math.random(1, #candidates)]
        used[pick] = true
        return pick
    end

    if tournament.allowRandomCpuPalette then
        local pick = math.random(1, 12)
        used[pick] = true
        return pick
    end

    used[1] = true
    return 1
end

f_tournamentRun = function(forceLoad, skipSetup, keepMusic)
    local p1Ref = nil
    -- Seeding ESC re-entry: the edit track is already playing; carry its
    -- file so the NEW-start and build replays below can skip it (same-file
    -- replay would restart the song). Fresh runs always clear this.
    if tournament then tournament.keepMusicFile = (keepMusic and TournamentSetMusic) or nil end
    tournament.stagePickIdx = nil  -- bracket stage picker restarts at random
    local isLoad = forceLoad or false
    local savedData = nil
    if isLoad then
        savedData = f_loadTournamentState()
        if not savedData then
            print("[Tournament ERROR] No save found while trying to load tournament.")
            isLoad = false
            if tournament then tournament.reopenMiscLoad = nil; tournament.miscOpenInLoadMode = nil end
        end
    end

    if not isLoad then
        if skipSetup then
            -- Setup was already confirmed (and applied) by the reopened
            -- mid-run menu: goes straight to the NEW select, no 2nd pass.
            -- startMode is NEW here (menu exit forces it when loadChoice=false).
            tournament.startMode = "NEW"
            print("[Tournament] Setup skipped (already confirmed) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â starting NEW on slot "
                .. tostring(tournament.saveSlot) .. ".")
        else
            local menuOk, loadChoice = f_tournamentOptionsMenu(false)
            if not menuOk then f_backToTitle(); return nil end
            f_waitForRelease()
            if loadChoice then
                savedData = f_loadTournamentState()
                if savedData then
                    local okSave, missing = f_validateTournamentSave(savedData)
                    if okSave then
                        isLoad = true
                    else
                        print("[Tournament] Save rejected ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â chars missing in select.def: "
                            .. tostring(missing and #missing or 0))
                        savedData = nil
                        isLoad = false
                        tournament.startMode = "NEW"
                    end
                end
            end
        end
    end

    tournament.active = true
    -- Reapplies HD/SD at tournament start (ensures correct columns/scales/anims)
    if type(f_applyLayoutMode) == "function" then
        pcall(f_applyLayoutMode)
    end
    print("[Tournament] portrait caches cleared (tournament start).")
    tournamentPortraitPalMissCount = {}
    tournament.portraitCache = {}
    tournamentNextPortraitCache = {}
    tournamentDualKeyMemo = {}
    tournamentElimOverlayCache = {}
    tournamentPortraitPalCache = {}
    tournamentPortraitPlaced = {}
    tournamentPortraitPalEntry = {}
    tournamentPortraitPalDbg = {}
    tournamentPortraitCellPathDbg = {}
    cellDataCache = {}
    tournamentAnimatedPortraitCache = {}
    tournamentAnimatedSffCache = {}
    tournamentPortrait9000Cache = {}
    tournamentPortrait9000Tries = {}
    tournamentPortrait9001Cache = {}
    tournamentPortrait9001Tries = {}
    tournamentPortrait9000Dbg = {}
    tournamentWinPoseCache = {}
    tournamentPrewarmDone = {}
    skeletonCache = nil

    local bracket = nil
    local size = tournament.size
    local R = f_getPlayerMatchCount(size)
    local startRound = 1
    local playerAlive = true
    local isFirstLoadMatch = false

    if isLoad and savedData then
        size = savedData.size or tournament.size
        tournament.size = size
        R = f_getPlayerMatchCount(size)
        startRound = savedData.roundNum or 1
        -- Finished save: jumps straight to champion screen (loop does not run)
        if savedData.finished then startRound = R + 1 end
        p1Ref = savedData.p1Ref
        tournament.playerPals = savedData.playerPals or {}
        tournament.cpuPals = savedData.cpuPals or {}
        playerAlive = (savedData.playerAlive ~= false)
        bracket = savedData.bracket
        tournament.seeding = false
        tournament.cellEdit = false
        -- Compatibility with old saves: old participants were strings.
        -- They keep working, but new tournaments use unique IDs.
        isFirstLoadMatch = true
        if savedData.teamMode ~= nil then tournament.teamMode = savedData.teamMode end
        if savedData.teamSize ~= nil then tournament.teamSize = savedData.teamSize end
        if savedData.playerTeam then
            tournament.playerTeam = savedData.playerTeam
        elseif p1Ref ~= nil then
            tournament.playerTeam = { f_getCharPath(p1Ref) }
        else
            tournament.playerTeam = {}
        end
        local p2Ref = nil
    if savedData.humanTeams and savedData.humanTeams["PLAYER2"] and #savedData.humanTeams["PLAYER2"] > 0 then
        -- If humanTeams exists, P2 is there
        p2Ref = "PLAYER2"  -- Usa o ID diretamente
    end
        tournament.humanIds = {}
        if savedData.humanTeams then tournament.humanTeams = savedData.humanTeams end
        if savedData.humanPals then tournament.humanPals = savedData.humanPals end
        if savedData.humanIds then tournament.humanIds = savedData.humanIds end
        if savedData.humanFlags then tournament.humanFlags = savedData.humanFlags end
        if savedData.cpuFlags then tournament.cpuFlags = savedData.cpuFlags end
        tournament.cpuFlags = tournament.cpuFlags or {}
        tournament.useHumanIds = true  -- VOIDED menu; always ON (saved value ignored)
        if savedData.cpuIds then tournament.cpuIds = savedData.cpuIds end
        tournament.allowRandomCpuIds = true  -- VOIDED menu; always ON (saved value ignored)
        if savedData.randomHumanIds ~= nil then tournament.randomHumanIds = (savedData.randomHumanIds == true) end
        if savedData.randomCharsForHumans ~= nil then tournament.randomCharsForHumans = (savedData.randomCharsForHumans == true) end
        if savedData.humanPlayers ~= nil then
            local hpS = tonumber(savedData.humanPlayers) or 1
            if hpS < 0 then hpS = 0 end
            local maxHPS = 128
            if type(f_maxHumanPlayers) == "function" then maxHPS = f_maxHumanPlayers() end
            if hpS > maxHPS then hpS = maxHPS end
            tournament.humanPlayers = hpS
        end
        tournament.cpuTeams = savedData.cpuTeams or {}
        f_restorePlayerSelection(p1Ref, p2Ref)
        print("[Tournament] Tournament loaded from Round " .. tostring(startRound))
        f_getValidCharData()
        f_loadCharPortrait("PLAYER1")
        local hpLoad = tonumber(tournament.humanPlayers) or 1
        for pnLoad = 2, hpLoad do f_loadCharPortrait("PLAYER" .. tostring(pnLoad)) end
        for _, roundData in pairs(bracket.rounds) do
            for _, side in ipairs({ "left", "right" }) do
                for _, m in ipairs(roundData[side] or {}) do
                    if m.a and not f_isPlayerParticipant(m.a) then f_loadCharPortrait(m.a) end
                    if m.b and not f_isPlayerParticipant(m.b) then f_loadCharPortrait(m.b) end
                end
            end
        end
        -- Syncs bracket music on load (menu was playing menu music)
        if type(f_updateTournamentMusicPath) == "function" then f_updateTournamentMusicPath("bracket") end
        if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
            motif.Music.select[1].bgm = TournamentSetMusic
        end
        if motif and motif.select_info then
            motif.select_info.bgm = TournamentSetMusic
        end
        if type(f_playTournamentMusic) == "function" then f_playTournamentMusic("bracket") end
    else
        safeSelectReset(true)
        -- NEW opens the seeding bracket (EDIT/START/MISC) first ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â use edit music.
        if type(f_updateTournamentMusicPath) == "function" then pcall(f_updateTournamentMusicPath, "bracketEdit") end
        print("[Tournament] NEW start: menu=" .. tostring(tournament.menuMusicTrack) .. " edit=" .. tostring(tournament.bracketEditMusicTrack) .. " bracket=" .. tostring(tournament.bracketMusicTrack) .. " bgm=" .. tostring(TournamentSetMusic))
        if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
            if originalSelectBgm == nil then originalSelectBgm = motif.Music.select[1].bgm or "" end
            motif.Music.select[1].bgm = TournamentSetMusic
        end
        -- Seeding ESC re-entry (keepMusic): the edit track is already
        -- playing from the seeding bracket. f_playTournamentMusic forces
        -- interrupt=true, so replaying the same file restarts the song
        -- (this unconditional replay was the restart). Skip it when the
        -- file is unchanged; the flag stays set for the later checks.
        local keepEditBgm = tournament and tournament.keepMusicFile ~= nil
            and tournament.keepMusicFile == TournamentSetMusic
        if type(f_playTournamentMusic) == "function" and not keepEditBgm then
            f_playTournamentMusic("bracketEdit")
        end
        if setMatchNo then setMatchNo(1) end
        start.exit = false
        local originalPlayBgm = playBgm
        playBgm = function(...)
            -- Respects Misc Settings > MUSIC (OFF = silence), per-track MUSIC VOLUMEs and MUSIC SELECTION.
            -- NEW flow opens the seeding bracket next ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â keep edit-screen track.
            if tournament and tournament.musicEnabled == false then
                if stopBgm then pcall(stopBgm) end
                return
            end
            -- NEW flow opens the seeding/edit bracket next. Until seeding is
            -- actually true (bracket built), keep BRACKET EDIT — do not use
            -- f_tournamentBracketViewMusic() yet (it returns "bracket" while
            -- seeding is still false and caused a brief wrong-track flash).
            local which = "bracketEdit"
            if tournament and tournament.seeding and type(f_tournamentBracketViewMusic) == "function" then
                which = f_tournamentBracketViewMusic()
            end
            if type(f_updateTournamentMusicPath) == "function" then
                pcall(f_updateTournamentMusicPath, which)
            end
            do
                local f = io.open(TournamentSetMusic, "r")
                if f then f:close()
                else
                    if stopBgm then pcall(stopBgm) end
                    return
                end
            end
            local vol = 100
            if type(f_musicVolumeFor) == "function" then
                vol = tonumber(f_musicVolumeFor(which)) or 100
            elseif tournament then
                vol = tonumber(tournament.musicVolume) or 100
            end
            -- Same-file guard (peek, no consume: the build replay check owns
            -- the single use): the engine restarts motif.select BGM on every
            -- select entry even when it is the same file already playing
            -- (seeding ESC re-entry). A track change mid-select still flows
            -- through (TournamentSetMusic differs then).
            if tournament and tournament.keepMusicFile ~= nil
                and tournament.keepMusicFile == TournamentSetMusic then
                return
            end
            return originalPlayBgm({bgm = TournamentSetMusic, loop = 1, volume = vol})
        end

        -- Numeric mode mapping for the Ikemen GO engine
        -- 0 = Single, 1 = Simul, 2 = Turns, 3 = Tag
        local modeMap = { single = 0, simul = 1, turns = 2, tag = 3 }
        local tModeStr = (tournament.teamMode or "single"):lower():gsub("%s+", "")
        local tModeNum = modeMap[tModeStr] or 0
        local tNumChars = math.max(1, tournament.teamSize or 1)
        local teamSize = tNumChars

        local hpCount = tonumber(tournament.humanPlayers) or 1
        if hpCount < 0 then hpCount = 0 end
        local maxHPCount = 128
        if type(f_maxHumanPlayers) == "function" then maxHPCount = f_maxHumanPlayers() end
        if hpCount > maxHPCount then hpCount = maxHPCount end
        tournament.humanPlayers = hpCount

        -- Re-runs common setup (setGameMode + selectMenu/cpuSide) now that
        -- humanPlayers is already confirmed by the options menu. Without this, the engine
        -- may have "snapshotted" the old config at setGameMode time back in
        -- f_menuStartNew, before the user changes the option.
        if type(f_setupTournamentModeCommon) == "function" then
            f_setupTournamentModeCommon()
        end

        local function f_applyTeamModeFlags(sideHuman)
            main.teamMenu = main.teamMenu or {{}, {}}
            main.teamMenu[1] = main.teamMenu[1] or {}
            main.teamMenu[2] = main.teamMenu[2] or {}
            main.teamMenu[1].single = (tModeStr == "single")
            main.teamMenu[1].simul  = (tModeStr == "simul")
            main.teamMenu[1].tag    = (tModeStr == "tag")
            main.teamMenu[1].turns  = (tModeStr == "turns")
            if sideHuman then
                main.teamMenu[2].single = (tModeStr == "single")
                main.teamMenu[2].simul  = (tModeStr == "simul")
                main.teamMenu[2].tag    = (tModeStr == "tag")
                main.teamMenu[2].turns  = (tModeStr == "turns")
            else
                main.teamMenu[2].single = true
                main.teamMenu[2].simul  = false
                main.teamMenu[2].tag    = false
                main.teamMenu[2].turns  = false
            end
            if tModeStr == "simul" then
                main.numSimul = { tNumChars, tNumChars }
            elseif tModeStr == "tag" then
                main.numTag = { tNumChars, tNumChars }
            elseif tModeStr == "turns" then
                main.numTurns = { tNumChars, tNumChars }
            end
        end

        -- Applies mode/size AFTER safeSelectReset.
        -- O reset zera teamMode/numChars/numSimul (= Options.Min, em geral 2).
        -- Do NOT set teamEnd=true without filling t_selCmd: cursor vanishes and hangs.
        -- With min==max in main.numSimul/Tag/Turns and 1 mode in teamMenu,
        -- f_teamMenu auto-confirma e cria o t_selCmd (cursor).
        local function f_setupSelectSides(dualHuman)
            f_applyTeamModeFlags(dualHuman)
            main.p1TeamMenu = { mode = tModeNum, chars = tNumChars }
            if dualHuman then
                main.p2TeamMenu = { mode = tModeNum, chars = tNumChars }
            else
                main.p2TeamMenu = { mode = 0, chars = 1 }
            end
            main.selectMenu = main.selectMenu or {}
            main.selectMenu[1] = true
            main.selectMenu[2] = dualHuman and true or false
            main.cpuSide = main.cpuSide or {}
            main.cpuSide[1] = false
            main.cpuSide[2] = not dualHuman
            -- Fixed range => native team menu auto-skip with tournament size
            if tModeStr == "simul" then
                main.numSimul = { tNumChars, tNumChars }
            elseif tModeStr == "tag" then
                main.numTag = { tNumChars, tNumChars }
            elseif tModeStr == "turns" then
                main.numTurns = { tNumChars, tNumChars }
            end
            local nSim = (tModeStr == "single") and 2 or math.max(2, tNumChars)
            local nChars = (tModeStr == "single") and 1 or tNumChars
            if start.p then
                if start.p[1] then
                    start.p[1].teamMode = tModeNum
                    start.p[1].numChars = nChars
                    start.p[1].numSimul = nSim
                    start.p[1].numTag   = nSim
                    start.p[1].numTurns = nSim
                    start.p[1].teamMenu = 1
                    -- human: teamEnd false so f_teamMenu runs 1x and creates t_selCmd
                    start.p[1].teamEnd = false
                    start.p[1].selEnd = false
                    start.p[1].t_selected = {}
                    start.p[1].t_selTemp = {}
                    start.p[1].t_selCmd = {}
                end
                if start.p[2] then
                    if dualHuman then
                        start.p[2].teamMode = tModeNum
                        start.p[2].numChars = nChars
                        start.p[2].numSimul = nSim
                        start.p[2].numTag   = nSim
                        start.p[2].numTurns = nSim
                        start.p[2].teamMenu = 1
                        start.p[2].teamEnd = false
                        start.p[2].selEnd = false
                    else
                        start.p[2].teamMode = 0
                        start.p[2].numChars = 1
                        start.p[2].teamEnd = true
                        start.p[2].selEnd = true
                    end
                    start.p[2].t_selected = {}
                    start.p[2].t_selTemp = {}
                    start.p[2].t_selCmd = {}
                end
            end
            print(string.format(
                "[Tournament] Select sides: dual=%s mode=%s numChars=%d numSimul=%d",
                tostring(dualHuman), tModeStr, nChars, nSim
            ))
        end

        local function f_captureSideTeam(sideIdx)
            local teamPaths, pals, firstRef = {}, {}, nil
            if start.p and start.p[sideIdx] and start.p[sideIdx].t_selected then
                for i = 1, #start.p[sideIdx].t_selected do
                    local sel = start.p[sideIdx].t_selected[i]
                    if sel and sel.ref then
                        if not firstRef then firstRef = sel.ref end
                        local path = f_getCharPath(sel.ref)
                        if path and path ~= "" then
                            table.insert(teamPaths, path)
                            table.insert(pals, sel.pal or 1)
                        end
                    end
                end
            end
            while #pals < teamSize do table.insert(pals, 1) end
            return teamPaths, pals, firstRef
        end

        -- Human ID entry: delegates to the global session picker.
        local function f_promptHumanId(playerNum, defaultId, charName, slotCount)
            -- Single implementation lives in global f_promptPlayerId
            -- (typing session with ALT/CTRL player switching).
            if type(f_promptPlayerId) == "function" then
                return f_promptPlayerId(playerNum, slotCount)
            end
            return nil
        end

        -- Draws a unique name from TOURNAMENT_CPU_ID_POOL, avoiding every
        -- name already in tournament.cpuIds / tournament.humanIds (humans
        -- pick first at select; CPUs skip them later). Draw pile built ONCE
        -- per tournament with swap-remove: re-filtering 81k names per draw
        -- (128x = ~10M Lua iterations) froze the build for seconds.
        -- Exhausted pile refills (reuse allowed), mirroring the old fallback.
        function f_drawUniquePoolName()
            if type(TOURNAMENT_CPU_ID_POOL) ~= "table" or #TOURNAMENT_CPU_ID_POOL == 0 then
                return ""
            end
            local function buildPile(useTaken)
                local pile = {}
                local taken = {}
                if useTaken then
                    for _, t in ipairs({tournament.cpuIds, tournament.humanIds}) do
                        if type(t) == "table" then
                            for _, v in pairs(t) do
                                if type(v) == "string" and v ~= "" then taken[v] = true end
                            end
                        end
                    end
                end
                for i = 1, #TOURNAMENT_CPU_ID_POOL do
                    local nm = TOURNAMENT_CPU_ID_POOL[i]
                    if type(nm) == "string" and nm ~= "" and not taken[nm] then
                        pile[#pile + 1] = nm
                    end
                end
                return pile
            end
            local pile = tournament._cpuIdPile
            if type(pile) ~= "table" then
                pile = buildPile(true)  -- first build: skip taken (human IDs)
                tournament._cpuIdPile = pile
            elseif #pile == 0 then
                pile = buildPile(false)  -- exhausted: allow reuse
                tournament._cpuIdPile = pile
            end
            if #pile == 0 then return "" end
            local idx = math.random(#pile)
            local nm = pile[idx]
            pile[idx] = pile[#pile]
            pile[#pile] = nil
            return nm
        end

        -- Draws a unique flag from TOURNAMENT_COUNTRY_FLAGS, avoiding every
        -- flag already in tournament.cpuFlags / tournament.humanFlags.
        -- Reshuffles on empty (pool >> fighters, so this rarely triggers).
        -- Currently unused (CPU draw uses f_drawAnyFlagName); kept so the
        -- unique behavior can be restored by switching one call back.
        local function f_drawUniqueFlagName()
            if type(TOURNAMENT_COUNTRY_FLAGS) ~= "table" or #TOURNAMENT_COUNTRY_FLAGS == 0 then
                return ""
            end
            local taken = {}
            for _, t in ipairs({tournament.cpuFlags, tournament.humanFlags}) do
                if type(t) == "table" then
                    for _, v in pairs(t) do
                        if type(v) == "string" and v ~= "" then taken[v] = true end
                    end
                end
            end
            local fresh = {}
            for i = 1, #TOURNAMENT_COUNTRY_FLAGS do
                local nm = TOURNAMENT_COUNTRY_FLAGS[i]
                if type(nm) == "string" and nm ~= "" and not taken[nm] then
                    fresh[#fresh + 1] = nm
                end
            end
            if #fresh == 0 then  -- pool exhausted: allow reuse
                for i = 1, #TOURNAMENT_COUNTRY_FLAGS do fresh[#fresh + 1] = TOURNAMENT_COUNTRY_FLAGS[i] end
            end
            if #fresh == 0 then return "" end
            return fresh[math.random(#fresh)]
        end

        -- Draws ANY flag from the CPU flag pool (repeats allowed):
        -- several CPUs may share USA, Israel, etc. IDs stay unique
        -- (f_drawUniquePoolName); only flags are freed here.
        -- Empty pool falls back to the full list (cosmetic; never blocks).
        function f_drawAnyFlagName()
            if type(TOURNAMENT_COUNTRY_FLAGS) ~= "table" or #TOURNAMENT_COUNTRY_FLAGS == 0 then
                return ""
            end
            local list = TOURNAMENT_COUNTRY_FLAGS
            if type(f_enabledFlagNames) == "function" then
                local ok, en = pcall(f_enabledFlagNames)
                if ok and type(en) == "table" and #en > 0 then list = en end
            end
            -- CPUs never take Unknown (players only): filter the default flag.
            -- If the pool was reduced to Unknown alone, fall back to every
            -- other flag so a CPU still gets a real one.
            local dn = nil
            if type(f_defaultFlagName) == "function" then dn = f_defaultFlagName() end
            if type(dn) == "string" and dn ~= "" then
                local filtered = {}
                for _, nm in ipairs(list) do
                    if nm ~= dn then filtered[#filtered + 1] = nm end
                end
                if #filtered > 0 then
                    list = filtered
                elseif list ~= TOURNAMENT_COUNTRY_FLAGS then
                    local all = {}
                    for _, nm in ipairs(TOURNAMENT_COUNTRY_FLAGS) do
                        if nm ~= dn then all[#all + 1] = nm end
                    end
                    if #all > 0 then list = all end
                end
            end
            local nm = list[math.random(#list)]
            if type(nm) == "string" and nm ~= "" then return nm end
            return ""
        end

        local function f_promptHumanFlag(playerNum, defaultFlag, slotCount)
            -- Single implementation lives in global f_promptPlayerFlag
            -- (session with ALT/CTRL player switching).
            if type(f_promptPlayerFlag) == "function" then
                return f_promptPlayerFlag(playerNum, defaultFlag, slotCount)
            end
            return nil
        end

        local function f_assignHumanFlag(playerNum)
            local key = "PLAYER" .. tostring(playerNum)
            -- Always opens (no skip): a stored flag only prefills the picker.
            local cur = ""
            if tournament.humanFlags and type(tournament.humanFlags[key]) == "string" then
                cur = tournament.humanFlags[key]
            end
            -- Focused single-slot session; ESC ends it (nil = back, caller
            -- reopens the ID screen). The prompt's own return decides: a
            -- stale stored flag must NOT auto-confirm an ESC.
            local okF = nil
            if type(f_promptHumanFlag) == "function" then
                okF = f_promptHumanFlag(playerNum, cur, 1)
            end
            if okF == true then return true end
            return "back"
        end

        local function f_assignHumanId(playerNum, charName)
            if not (tournament and tournament.useHumanIds) then return true end
            local key = "PLAYER" .. tostring(playerNum)
            -- RANDOM IDS FOR HUMANS: no typing screen; draws a pool name.
            if tournament.randomHumanIds then
                tournament.humanIds = tournament.humanIds or {}
                if tournament.humanIds[key] == nil or tournament.humanIds[key] == "" then
                    tournament.humanIds[key] = f_drawUniquePoolName()
                    f_saveTournamentConfig()
                end
                print("[Tournament] ID " .. key .. " = '" .. tostring(tournament.humanIds[key]) .. "' (random)")
                return true
            end
            -- Always shows (no skip): ID screen first, then flag. ESC on ID
            -- backs to char select; ESC on flag reopens the ID screen.
            -- Empty stays empty (display falls back to "Player N").
            while true do
                local ir = true
                if type(f_promptHumanId) == "function" then
                    ir = f_promptHumanId(playerNum, nil, nil, 1)
                end
                if ir == nil then return "back" end
                local fr = true
                if type(f_assignHumanFlag) == "function" then
                    fr = f_assignHumanFlag(playerNum)
                end
                if fr ~= "back" then return true end
            end
        end

        -- ESC in native select: back to setup page 4 (Advanced), not title.
        -- Returns true when setup confirmed again (caller retries select).
        local function f_setupBackFromSelect()
            safeSelectReset(false)
            -- Same pos/facing reset as the bracket ESC (stale transforms
            -- from a previous run must not leak into setup/select/pool).
            f_restoreOriginalAnimStates()
            print("[Tournament] Select canceled ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â back to setup (Advanced page).")
            -- Menu music back (select/bracket track keeps playing otherwise).
            if type(originalPlayBgm) == "function" then playBgm = originalPlayBgm end
            if type(f_updateTournamentMusicPath) == "function" then
                pcall(f_updateTournamentMusicPath, "menu")
            end
            if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
                if originalSelectBgm == nil then originalSelectBgm = motif.Music.select[1].bgm or "" end
                motif.Music.select[1].bgm = TournamentSetMusic
            end
            if type(f_playTournamentMusic) == "function" then f_playTournamentMusic("menu") end
            -- Structural fingerprint: human count / team / size captured by the
            -- run go stale if the user changes them here. On mismatch the
            -- select phase restarts from player 1 instead of retrying same pn.
            local function f_selectFingerprint()
                return tostring(tournament.humanPlayers) .. "|"
                    .. tostring(tournament.teamMode) .. "|"
                    .. tostring(tournament.teamSize) .. "|"
                    .. tostring(tournament.size) .. "|"
                    .. tostring(tournament.format)
            end
            local liveFingerprint = f_selectFingerprint()
            local setupOk, setupLoad = f_tournamentOptionsMenu(false, 4)
            if not setupOk then
                tournament.active = false
                f_backToTitle()
                return false
            end
            f_waitForRelease()
            if setupLoad then
                -- CONTINUE picked here (valid save, maybe another slot):
                -- abandons this select and loads it (same as fresh CONTINUE).
                print("[Tournament] Setup switched to CONTINUE ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â loading slot "
                    .. tostring(tournament.saveSlot) .. ", abandoning select.")
                if setMatchNo then setMatchNo(-1) end
                main.cpuSide[1] = false
                safeSelectReset(false)
                tournament.active = false
                -- Portrait anims may already carry transforms; restores them
                -- before the loaded run re-backs-up (ESC-select abandon).
                f_restoreOriginalAnimStates()
                f_tournamentRun(true)
                return false
            end
            if f_selectFingerprint() ~= liveFingerprint then
                -- Structure changed (e.g. human count): retrying the same
                -- select would resume a stale pn (IDs continue at 15...).
                -- Abandons and restarts the select phase from player 1
                -- (skipSetup: the reopened menu already applied everything).
                print("[Tournament] Setup changed tournament structure mid-select ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â restarting select phase.")
                if setMatchNo then setMatchNo(-1) end
                main.cpuSide[1] = false
                safeSelectReset(false)
                tournament.active = false
                f_restoreOriginalAnimStates()
                f_tournamentRun(false, true)
                return false
            end
            -- NEW (+ slot switch, if any): select simply retries under the
            -- new slot, so the new tournament builds there. Nothing to divert.
            return true
        end

        -- Re-arms select music after setup-again: reinstalls the bracket
        -- forcing wrapper (same as first entry). Engine motif resolution
        -- fails on select re-entry (mute), so select#2 must go through
        -- it exactly like select#1 did. Sites restore original after.
        local function f_rearmSelectMusic()
            -- Tournament selects run on BRACKET EDIT music (from char
            -- select through the edit/seeding phase).
            if type(f_updateTournamentMusicPath) == "function" then
                pcall(f_updateTournamentMusicPath, "bracketEdit")
            end
            if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
                motif.Music.select[1].bgm = TournamentSetMusic
            end
            if type(originalPlayBgm) == "function" then playBgm = originalPlayBgm end
            if type(originalPlayBgm) == "function" then
                playBgm = function(...)
                    if tournament and tournament.musicEnabled == false then
                        if stopBgm then pcall(stopBgm) end
                        return
                    end
                    if type(f_updateTournamentMusicPath) == "function" then
                        pcall(f_updateTournamentMusicPath, "bracketEdit")
                    end
                    do
                        local f = io.open(TournamentSetMusic, "r")
                        if f then f:close()
                        else
                            if stopBgm then pcall(stopBgm) end
                            return
                        end
                    end
                    -- Selects run on BRACKET EDIT: its own volume.
                    local vol = 100
                    if type(f_musicVolumeFor) == "function" then
                        vol = tonumber(f_musicVolumeFor("bracketEdit")) or 100
                    elseif tournament then
                        vol = tonumber(tournament.musicVolume) or 100
                    end
                    return originalPlayBgm({bgm = TournamentSetMusic, loop = 1, volume = vol})
                end
            end
        -- Seeding ESC re-entry skips the replay (same file already playing).
        local keepBgm = tournament and tournament.keepMusicFile ~= nil
            and tournament.keepMusicFile == TournamentSetMusic
        if type(f_playTournamentMusic) == "function" and not keepBgm then f_playTournamentMusic("bracketEdit") end
        end

        tournament.humanTeams = {}
        tournament.humanPals = {}
        -- IDs/flags persist per player in tournament_config.json: NEW keeps
        -- the last config (select only prompts for unset slots).
        tournament.humanIds = tournament.humanIds or {}
        tournament.humanFlags = tournament.humanFlags or {}
        tournament.cpuIds = {}
        tournament.cpuFlags = {}
        tournament._cpuIdPile = nil  -- rebuilt on first draw (see f_drawUniquePoolName)
        tournament.playerTeam = {}
        tournament.playerPals = {}
        -- Fresh draw every NEW: reseed here (chunk reloads can reset the Lua
        -- RNG, which repeated the previous sample+shuffle+names on re-entry).
        -- os.clock fraction keeps back-to-back builds distinct.
        if type(math.randomseed) == "function" and os ~= nil then
            local tsec = 0
            if type(os.time) == "function" then
                local okT, vt = pcall(os.time)
                if okT and tonumber(vt) then tsec = tonumber(vt) end
            end
            local cfrac = 0
            if type(os.clock) == "function" then
                local okC, vc = pcall(os.clock)
                if okC and tonumber(vc) then cfrac = tonumber(vc) % 1 end
            end
            pcall(math.randomseed, tsec + math.floor(cfrac * 1000000))
            pcall(math.random); pcall(math.random); pcall(math.random)
        end
        local excludeForSampling = {}

        if hpCount == 0 then
            playBgm = originalPlayBgm
            p1Ref = nil
            playerAlive = false
            print("[Tournament] HUMAN PLAYERS=0 ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â select skipped (CPU-only tournament).")
        elseif tournament.randomCharsForHumans then
            -- RANDOM CHARS: skips every select screen; draws random team(s)
            -- per human (same sampler as CPUs, humans excluded from each
            -- other). IDs still assigned (typed or random) per player.
            safeSelectReset(true)
            if type(remapInput) == "function" then
                if main and type(main.f_restoreBaseRemapInput) == "function" then
                    pcall(main.f_restoreBaseRemapInput)
                end
                pcall(remapInput, 1, 1)
                pcall(remapInput, 2, 2)
            end
            for pn = 1, hpCount do
                local idKey = "PLAYER" .. tostring(pn)
                local sampled = nil
                if type(f_sortearOponentes) == "function" then
                    sampled = f_sortearOponentes(excludeForSampling, tNumChars)
                end
                if type(sampled) ~= "table" or #sampled < tNumChars then
                    playBgm = originalPlayBgm
                    print("[Tournament] Not enough characters to random-pick humans.")
                    safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
                end
                local team, pals, first = {}, {}, nil
                for c = 1, tNumChars do
                    local pick = sampled[c]
                    local path = nil
                    if type(pick) == "table" then
                        path = pick.path
                        if first == nil then first = pick.ref end
                    else
                        path = pick
                    end
                    table.insert(team, path)
                    table.insert(pals, 1)
                end
                if pn == 1 then
                    p1Ref = first
                    tournament.playerTeam = team
                    tournament.playerPals = pals
                    tournament.playerRef = first
                end
                tournament.humanRefs = tournament.humanRefs or {}
                if first ~= nil then tournament.humanRefs[idKey] = first end
                tournament.humanTeams[idKey] = team
                tournament.humanPals[idKey] = pals
                for _, p in ipairs(team) do table.insert(excludeForSampling, p) end
                print("[Tournament] " .. idKey .. " random OK: " .. tostring(team[1]))
                f_assignHumanId(pn, f_getCleanDisplayName(team[1]))
            end
            playBgm = originalPlayBgm
            f_restoreMotifP1Cursor()
        elseif hpCount == 1 then
            -- ESC on the ID screen backs here to redo the char select.
            local idBack = true
            while idBack do
            idBack = false
            safeSelectReset(true)
            f_setupSelectSides(false)
            f_forceSelectCursorForPlayer(1)
            f_rearmSelectMusic()
            print(string.format("[Tournament] Select 1P: mode=%s numChars=%d", tModeStr, tNumChars))
            local selectOk = false
            repeat
                selectOk = start.f_selectScreen()
                playBgm = originalPlayBgm
                if not selectOk then
                    print("[Tournament] Select P1 canceled ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â back to setup.")
                    if not f_setupBackFromSelect() then
                        safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
                    end
                    safeSelectReset(true)
                    f_setupSelectSides(false)
                    f_rearmSelectMusic()
                end
            until selectOk
            f_restoreMotifP1Cursor()
            local p1Team, p1Pals, p1First = f_captureSideTeam(1)
            if not p1First or #p1Team == 0 then
                print("[Tournament] P1 with no character after select.")
                safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
            end
            p1Ref = p1First
            tournament.playerTeam = p1Team
            tournament.playerPals = p1Pals
            tournament.playerRef = p1First
            tournament.humanRefs = tournament.humanRefs or {}
            tournament.humanRefs["PLAYER1"] = p1First
            tournament.humanTeams["PLAYER1"] = p1Team
            tournament.humanPals["PLAYER1"] = p1Pals
            for _, p in ipairs(p1Team) do table.insert(excludeForSampling, p) end
            if f_assignHumanId(1, f_getCleanDisplayName(p1Team[1])) == "back" then
                print("[Tournament] Back from ID/flag screens ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â redoing P1 select.")
                idBack = true
            end
            end
        else
            -- ========== 2..N HUMANS ==========
            -- teamSize==1 (Single): coop workaround ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â N simultaneous cursors on side 1,
            --   each pick becomes a separate PLAYER in bracket.
            -- teamSize>1 or coop failure: simultaneous 2P + sequential (P3+),
            --   each with its own group-4 cursor (4,N-1).
            local function f_selectOneHumanSequential(playerLabel, playerNum)
                playerNum = tonumber(playerNum) or 1
                f_waitForRelease()
                if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
                    motif.Music.select[1].bgm = TournamentSetMusic
                end
                playBgm = function(...)
                    -- Respects Misc Settings > MUSIC (OFF = silence), MUSIC VOLUME and MUSIC SELECTION
                    if tournament and tournament.musicEnabled == false then
                        if stopBgm then pcall(stopBgm) end
                        return
                    end
                    if type(f_updateTournamentMusicPath) == "function" then
                        pcall(f_updateTournamentMusicPath)
                    end
                    do
                        local f = io.open(TournamentSetMusic, "r")
                        if f then f:close()
                        else
                            if stopBgm then pcall(stopBgm) end
                            return
                        end
                    end
                    -- Sequential selects run on BRACKET EDIT: its own volume.
                    local vol = 100
                    if type(f_musicVolumeFor) == "function" then
                        vol = tonumber(f_musicVolumeFor("bracketEdit")) or 100
                    elseif tournament then
                        vol = tonumber(tournament.musicVolume) or 100
                    end
                    return originalPlayBgm({bgm = TournamentSetMusic, loop = 1, volume = vol})
                end
                safeSelectReset(true)
                f_setupSelectSides(false)
                f_forceSelectCursorForPlayer(playerNum)
                if motif and motif.select_info and motif.select_info.title and motif.select_info.title.TextSpriteData then
                    pcall(textImgSetText, motif.select_info.title.TextSpriteData, "TOURNAMENT - " .. playerLabel)
                end
    -- Guard: native select restarts motif.select BGM on entry even when it
    -- is the same file already playing. Skip that restart so the bracket
    -- track continues seamlessly under the pick screen.
    if type(playBgm) == "function" and carouselPickPlayBgmOrig == nil then
        carouselPickPlayBgmOrig = playBgm
        playBgm = function(arg)
            if type(arg) == "table" and arg.source == "motif.select" then
                local cur = motif and motif.Music and motif.Music.select
                    and motif.Music.select[1] and motif.Music.select[1].bgm
                if type(cur) == "string" and cur ~= ""
                    and cur == TournamentSetMusic then
                    return -- same file already set: keep playing, no restart
                end
            end
            if type(carouselPickPlayBgmOrig) == "function" then
                return carouselPickPlayBgmOrig(arg)
            end
        end
    end
    local ok = start.f_selectScreen()
                f_restoreMotifP1Cursor()
                while not ok do
                    print("[Tournament] Sequential select canceled ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â back to setup.")
                    if not f_setupBackFromSelect() then return nil, nil, nil end
                    safeSelectReset(true)
                    f_setupSelectSides(false)
                    f_forceSelectCursorForPlayer(playerNum)
                    f_rearmSelectMusic()
                    ok = start.f_selectScreen()
                    f_restoreMotifP1Cursor()
                end
                return f_captureSideTeam(1)
            end

            local usedCoopSplit = false
            if tournament.useHumanIds then
                -- IDs ON: strict 1-by-1 with the P1 cursor (any hpCount).
                -- Each player picks the char, types the ID, then the next goes.
                -- Sets usedCoopSplit to skip the standard multi path below.
                if type(remapInput) == "function" then
                    if main and type(main.f_restoreBaseRemapInput) == "function" then
                        pcall(main.f_restoreBaseRemapInput)
                    end
                    pcall(remapInput, 1, 1)
                    pcall(remapInput, 2, 2)
                end
                for pn = 1, hpCount do
                    local label = "PLAYER " .. tostring(pn)
                    -- ESC on the ID screen backs here to redo this player's select.
                    local backToSelect = true
                    while backToSelect do
                    backToSelect = false
                    local idKey = "PLAYER" .. tostring(pn)
                    print("[Tournament] Sequential select + ID " .. idKey)
                    local team, pals, first = f_selectOneHumanSequential(label, pn)
                    if not first or not team or #team == 0 then
                        playBgm = originalPlayBgm
                        print("[Tournament] " .. idKey .. " with no character / canceled.")
                        safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
                    end
                    if pn == 1 then
                        p1Ref = first
                        tournament.playerTeam = team
                        tournament.playerPals = pals
                        tournament.playerRef = first
                    end
                    tournament.humanRefs = tournament.humanRefs or {}
                    tournament.humanRefs[idKey] = first
                    tournament.humanTeams[idKey] = team
                    tournament.humanPals[idKey] = pals
                    for _, p in ipairs(team) do table.insert(excludeForSampling, p) end
                    print("[Tournament] " .. idKey .. " OK: " .. tostring(team[1]))
                    if f_assignHumanId(pn, f_getCleanDisplayName(team[1])) == "back" then
                        print("[Tournament] Back from ID/flag screens ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â redoing " .. idKey .. " select.")
                        backToSelect = true
                    end
                    end
                end
                usedCoopSplit = true
            end
            -- Simultaneous COOP disabled: on current engine/screenpack it loses cursor and hangs.
            -- We keep simultaneous P1|P2 + sequential P3+ (own group-4 cursor each).
            -- --- COOP SPLIT (off; re-enable only if tested with correct teamEnd/t_selCmd) ---
            if false and teamSize <= 1 and hpCount >= 3 then
                print(string.format("[Tournament] Trying simultaneous COOP select (%dP single)...", hpCount))
                if type(remapInput) == "function" then
                    if main and type(main.f_restoreBaseRemapInput) == "function" then
                        pcall(main.f_restoreBaseRemapInput)
                    end
                    for i = 1, hpCount do
                        pcall(remapInput, i, i)
                    end
                end
                main.coop = true
                main.selectMenu = main.selectMenu or {}
                main.selectMenu[1] = true
                main.selectMenu[2] = false
                main.cpuSide = main.cpuSide or {}
                main.cpuSide[1] = false
                main.cpuSide[2] = true
                -- SIMUL only in team menu, fixed size = hpCount (each member = 1 human)
                main.teamMenu = main.teamMenu or {{}, {}}
                main.teamMenu[1] = main.teamMenu[1] or {}
                main.teamMenu[2] = main.teamMenu[2] or {}
                main.teamMenu[1].single = false
                main.teamMenu[1].simul  = true
                main.teamMenu[1].tag    = false
                main.teamMenu[1].turns  = false
                main.teamMenu[2].single = true
                main.teamMenu[2].simul  = false
                main.teamMenu[2].tag    = false
                main.teamMenu[2].turns  = false
                main.numSimul = { hpCount, hpCount }
                main.p1TeamMenu = { mode = 1, chars = hpCount }
                main.p2TeamMenu = { mode = 0, chars = 1 }
                if start.p and start.p[1] then
                    start.p[1].teamMode = 1
                    start.p[1].numChars = hpCount
                    start.p[1].numSimul = hpCount
                    start.p[1].numTag = hpCount
                    start.p[1].numTurns = hpCount
                    start.p[1].teamMenu = 1
                    start.p[1].t_selected = {}
                    start.p[1].teamEnd = true  -- pula team menu se o engine respeitar
                end
                if start.p and start.p[2] then
                    start.p[2].teamMode = 0
                    start.p[2].numChars = 1
                    start.p[2].t_selected = {}
                    start.p[2].teamEnd = true
                    start.p[2].selEnd = true
                end
                safeSelectReset(true)
                -- re-applies after reset (some builds clear flags)
                main.coop = true
                main.selectMenu[1] = true
                main.selectMenu[2] = false
                main.cpuSide[1] = false
                main.cpuSide[2] = true
                main.numSimul = { hpCount, hpCount }
                if start.p and start.p[1] then
                    start.p[1].teamMode = 1
                    start.p[1].numChars = hpCount
                    start.p[1].numSimul = hpCount
                    start.p[1].teamEnd = true
                    start.p[1].t_selected = {}
                end
                if motif and motif.select_info and motif.select_info.title and motif.select_info.title.TextSpriteData then
                    pcall(textImgSetText, motif.select_info.title.TextSpriteData,
                        string.format("TOURNAMENT - %d PLAYERS", hpCount))
                end
                local selectOk = start.f_selectScreen()
                main.coop = false
                local allOk = selectOk
                local teams = {}
                if selectOk and start.p and start.p[1] and start.p[1].t_selected then
                    for i = 1, hpCount do
                        local sel = start.p[1].t_selected[i]
                        if sel and sel.ref then
                            local path = f_getCharPath(sel.ref)
                            if path and path ~= "" then
                                teams[i] = {
                                    paths = { path },
                                    pals = { sel.pal or 1 },
                                    firstRef = sel.ref,
                                }
                            end
                        end
                    end
                end
                for i = 1, hpCount do
                    if not teams[i] then allOk = false; break end
                end
                if allOk then
                    usedCoopSplit = true
                    p1Ref = teams[1].firstRef
                    tournament.playerTeam = teams[1].paths
                    tournament.playerPals = teams[1].pals
                    for i = 1, hpCount do
                        local idKey = "PLAYER" .. tostring(i)
                        tournament.humanTeams[idKey] = teams[i].paths
                        tournament.humanPals[idKey] = teams[i].pals
                        for _, p in ipairs(teams[i].paths) do
                            table.insert(excludeForSampling, p)
                        end
                        print("[Tournament] COOP split " .. idKey .. " = " .. tostring(teams[i].paths[1]))
                    end
                    print("[Tournament] Simultaneous COOP OK ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â " .. tostring(hpCount) .. " humans split.")
                else
                    print("[Tournament] Simultaneous COOP failed/incomplete ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â sequential fallback.")
                end
            end

            if not usedCoopSplit then
                if type(remapInput) == "function" then
                    if main and type(main.f_restoreBaseRemapInput) == "function" then
                        pcall(main.f_restoreBaseRemapInput)
                    end
                    pcall(remapInput, 1, 1)
                    pcall(remapInput, 2, 2)
                end
                safeSelectReset(true)
                f_setupSelectSides(true)
                if motif and motif.select_info and motif.select_info.title and motif.select_info.title.TextSpriteData then
                    pcall(textImgSetText, motif.select_info.title.TextSpriteData,
                        string.format("TOURNAMENT - %d PLAYERS", hpCount))
                end
                print(string.format(
                    "[Tournament] Select multi-human (%dP) P1|P2: selectMenu={%s,%s} cpuSide={%s,%s} mode=%s",
                    hpCount,
                    tostring(main.selectMenu[1]), tostring(main.selectMenu[2]),
                    tostring(main.cpuSide[1]), tostring(main.cpuSide[2]), tModeStr
                ))
                local selectOk = false
                repeat
                    selectOk = start.f_selectScreen()
                    if not selectOk then
                        print("[Tournament] Select multi-human canceled (P1/P2) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â back to setup.")
                        if not f_setupBackFromSelect() then
                            playBgm = originalPlayBgm
                            safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
                        end
                        safeSelectReset(true)
                        f_setupSelectSides(true)
                        f_rearmSelectMusic()
                    end
                until selectOk
                local p1Team, p1Pals, p1First = f_captureSideTeam(1)
                local p2Team, p2Pals, p2First = f_captureSideTeam(2)

                if selectOk and p1First and #p1Team > 0 and (not p2First or #p2Team == 0) then
                    print("[Tournament] multi-human: P1 OK, P2 empty ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â sequential P2 select fallback.")
                    p2Team, p2Pals, p2First = f_selectOneHumanSequential("PLAYER 2", 2)
                end

                if not p1First or #p1Team == 0 then
                    playBgm = originalPlayBgm
                    print("[Tournament] P1 with no character after multi-human select.")
                    safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
                end
                if not p2First or #p2Team == 0 then
                    playBgm = originalPlayBgm
                    print("[Tournament] P2 with no character after multi-human select.")
                    safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
                end

                p1Ref = p1First
                tournament.playerTeam = p1Team
                tournament.playerPals = p1Pals
                tournament.playerRef = p1First
                tournament.humanRefs = tournament.humanRefs or {}
                tournament.humanRefs["PLAYER1"] = p1First
                tournament.humanRefs["PLAYER2"] = p2First
                tournament.humanTeams["PLAYER1"] = p1Team
                tournament.humanPals["PLAYER1"] = p1Pals
                tournament.humanTeams["PLAYER2"] = p2Team
                tournament.humanPals["PLAYER2"] = p2Pals
                for _, p in ipairs(p1Team) do table.insert(excludeForSampling, p) end
                for _, p in ipairs(p2Team) do table.insert(excludeForSampling, p) end
                print("[Tournament] multi-human P1/P2 OK: P1=" .. tostring(p1Team[1]) .. " P2=" .. tostring(p2Team[1]))

                for extraN = 3, hpCount do
                    local label = "PLAYER " .. tostring(extraN)
                    local idKey = "PLAYER" .. tostring(extraN)
                    print("[Tournament] Sequential select " .. idKey)
                    local team, pals, first = f_selectOneHumanSequential(label, 1)
                    if not first or not team or #team == 0 then
                        playBgm = originalPlayBgm
                        print("[Tournament] " .. idKey .. " with no character / canceled.")
                        safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
                    end
                    tournament.humanRefs = tournament.humanRefs or {}
                    tournament.humanRefs[idKey] = first
                    tournament.humanTeams[idKey] = team
                    tournament.humanPals[idKey] = pals
                    for _, p in ipairs(team) do table.insert(excludeForSampling, p) end
                    print("[Tournament] " .. idKey .. " OK: " .. tostring(team[1]))
                end
            end

            playBgm = originalPlayBgm
            f_restoreMotifP1Cursor()
        end

        if start and start.reset then
            if main.f_saveBaseRemapInput then main.f_saveBaseRemapInput() end
            if main.f_tableCopy and start.f_getOrderChars then main.t_availableChars = main.f_tableCopy(start.f_getOrderChars()) end
            start.reset = false
        end

        tournament.cpuTeams = {}
        local humanSlots = (hpCount >= 1 and hpCount or 0)
        local totalCpuSlots = size - humanSlots
        if totalCpuSlots < 0 then totalCpuSlots = 0 end
        local totalCpuCharsNeeded = totalCpuSlots * teamSize
        -- Reseed right before the draw too (select screens may reload the
        -- chunk and reset the RNG after the setup reseed above).
        if type(math.randomseed) == "function" and os ~= nil then
            local tsec = 0
            if type(os.time) == "function" then
                local okT, vt = pcall(os.time)
                if okT and tonumber(vt) then tsec = tonumber(vt) end
            end
            local cfrac = 0
            if type(os.clock) == "function" then
                local okC, vc = pcall(os.clock)
                if okC and tonumber(vc) then cfrac = tonumber(vc) % 1 end
            end
            pcall(math.randomseed, tsec + math.floor(cfrac * 1000000))
            pcall(math.random); pcall(math.random); pcall(math.random)
        end
        local sampledPool = f_sortearOponentes(excludeForSampling, totalCpuCharsNeeded)
        if #sampledPool < totalCpuCharsNeeded then
            print("[Tournament] Not enough characters for the chosen size/team. need="
                .. tostring(totalCpuCharsNeeded) .. " got=" .. tostring(#sampledPool))
            safeSelectReset(false); tournament.active = false; f_backToTitle(); return nil
        end

        local sampledCPUs = {}
        local nextParticipantId = 0
        local function newParticipant(path, isPlayer, forcedId, ref)
            nextParticipantId = nextParticipantId + 1
            local id
            if isPlayer then
                id = forcedId or "PLAYER1"
            else
                id = nextParticipantId
            end
            return { id = id, path = path, isPlayer = isPlayer == true, ref = ref }
        end
        tournament.cpuPals = {}
        local usedPalsByPath = {}
        for slotIdx = 1, totalCpuSlots do
            local team = {}
            local pals = {}
            local representativeRef = nil
            for c = 1, teamSize do
                local pick = sampledPool[(slotIdx - 1) * teamSize + c]
                table.insert(team, pick.path)
                table.insert(pals, f_pickCpuPalette(pick.path, usedPalsByPath))
                if c == 1 then representativeRef = pick.ref end
            end
            local representative = team[1]
            local participant = newParticipant(representative, false, nil, representativeRef)
            tournament.cpuTeams[participant.id] = team
            tournament.cpuPals[participant.id] = pals
            table.insert(sampledCPUs, participant)
        end

        local participants = {}
        if hpCount >= 1 then
            local path1 = (tournament.playerTeam and tournament.playerTeam[1]) or "PLAYER1"
            table.insert(participants, newParticipant(path1, true, "PLAYER1"))
        end
        for pn = 2, hpCount do
            local idKey = "PLAYER" .. tostring(pn)
            local pathN = (tournament.humanTeams[idKey] and tournament.humanTeams[idKey][1]) or idKey
            table.insert(participants, newParticipant(pathN, true, idKey))
        end
        for i = 1, #sampledCPUs do table.insert(participants, sampledCPUs[i]) end
        for i = #participants, 2, -1 do
            local j = math.random(i)
            participants[i], participants[j] = participants[j], participants[i]
        end
        -- Random CPU IDs (ALLOW RANDOM ID...): one unique name per CPU
        -- (f_drawUniquePoolName also skips human IDs picked at select).
        -- Flags are free: same pass draws ANY flag per CPU, repeats allowed.
        tournament.cpuIds = tournament.cpuIds or {}
        tournament.cpuFlags = tournament.cpuFlags or {}
        if tournament.allowRandomCpuIds ~= false then
            for _, p in ipairs(participants) do
                if not p.isPlayer then
                    local key = tostring(p.id)
                    if tournament.cpuIds[key] == nil or tournament.cpuIds[key] == "" then
                        local nm = f_drawUniquePoolName()
                        if nm ~= "" then tournament.cpuIds[key] = nm end
                    end
                    if tournament.cpuFlags[key] == nil or tournament.cpuFlags[key] == "" then
                        local fl = f_drawAnyFlagName()
                        if fl ~= "" then tournament.cpuFlags[key] = fl end
                    end
                end
            end
        end
        for _, p in ipairs(participants) do f_loadCharPortrait(p) end

        local half = size / 2
local function toMatches(list)
    local m = {}
    for i = 1, #list / 2 do
        local a = list[2*i - 1]
        local b = list[2*i]
        m[i] = { 
            a = a, 
            b = b,
            winner = nil 
        }
    end
    return m
end
        local leftList, rightList = {}, {}
        for i = 1, half do leftList[i] = participants[i] end
        for i = 1, half do rightList[i] = participants[half + i] end

        bracket = {
            rounds = { [1] = { left = toMatches(leftList), right = toMatches(rightList) } },
            final = nil, champion = nil, eliminated = {},
            thirdPlaceMatch = { a = nil, b = nil, winner = nil },
            thirdPlaceWinner = nil,
        }
        f_initAllRounds(bracket, size)
        -- Pre-tournament seeding phase (NEW only): bracket opens straight
        -- into cell-edit (cursor live from the first frame). LOAD keeps
        -- whatever it had (mid-tournament resume). Edit-screen music plays
        -- until START.
        if not isLoad then
            tournament.seeding = true
            tournament.cellEdit = true
            tournament.seedCursor = nil
            tournament.seedCursorEdges = nil
            tournament.seedGrab = nil
            if type(f_seedCursorMoveBracket) == "function" then
                f_seedCursorMoveBracket(bracket, "init")
            end
            if type(f_playTournamentMusic) == "function" then
                -- Single-use: skip only if the file didn't change since the
                -- seeding ESC (a track change mid-select still resyncs).
                local keepBgm = tournament and tournament.keepMusicFile ~= nil
                    and tournament.keepMusicFile == TournamentSetMusic
                tournament.keepMusicFile = nil
                if not keepBgm then f_playTournamentMusic("bracketEdit") end
            end
        end
    end

    tournament.totalCPUs = size - 1
    tournament.maxMatches = R
    local p1Path = ""
    if p1Ref ~= nil then
        p1Path = f_getCharPath(p1Ref)
    elseif tournament.playerTeam and tournament.playerTeam[1] then
        p1Path = tournament.playerTeam[1]
    end
    local endedEarly = false

