    -- ============================================================
-- FUNCTION TO RESTART THE TOURNAMENT (Character Change) - FIXED
-- ============================================================
local function f_restartTournament()
    print("[Tournament] Restarting tournament (Character Change)...")
    --f_clearSavedTournament()
    if setMatchNo then setMatchNo(-1) end
    main.cpuSide[1] = false

    -- Forces tournament music back ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â the versus/fight screen plays
    -- its own music (motif.vs), which keeps playing unless
    -- explicitly stopped here.
    if type(f_playTournamentMusic) == "function" then f_playTournamentMusic("bracket") end
    
    -- 1. Clears the portrait cache
    tournament.portraitCache = {}
    tournamentElimOverlayCache = {}
    tournamentPortraitPalMissCount = {}
    tournamentDualKeyMemo = {}
    tournamentPortraitPalCache = {}
    tournamentPortraitPlaced = {}
    tournamentPortraitPalEntry = {}
    tournamentPortraitPalDbg = {}
    tournamentPortraitCellPathDbg = {}
    tournamentAnimatedPortraitCache = {}
    tournamentAnimatedSffCache = {}
    tournamentPortrait9000Cache = {}
    tournamentPortrait9000Tries = {}
    tournamentPortrait9001Cache = {}
    tournamentPortrait9001Tries = {}
    tournamentPortrait9000Dbg = {}
    tournamentWinPoseCache = {}
    tournamentPrewarmDone = {}
    
    -- 2. Clears cell data cache
    cellDataCache = {}
    
    -- 3. Resets original animations
    f_restoreOriginalAnimStates()
    originalAnimStates = {}
    
    -- 4. Resets skeleton cache to force rebuild
    skeletonCache = nil
    
    -- 6. Resets cell background
    cellBgAnim = nil
    cellBgSff = nil
    
    -- 7. Resets overlay animations
    --overlayAnim = nil
    --overlayTried = false
    --overlayBgAnim = nil
    --overlayBgTried = false
    
    -- 8. Resets bracket animations
    --bracketAnimCache = {}
    
    -- 9. Fully resets start state
    if start then
        -- Resets all flags
        start.exit = false
        start.stageEnd = false
        start.stageMenu = true
        start.stageSelected = false
        start.stageSelect = false
        start.stageSelectMenu = false
        start.stageScreen = false
        start.reset = false
        start.stageReset = true  -- Forces visual reset
        
        -- Clears character selection
        if start.p and start.p[1] then
            start.p[1].t_selected = {}
            start.p[1].face = nil
            start.p[1].portrait = nil
        end
        if start.p and start.p[2] then
            start.p[2].t_selected = {}
            start.p[2].face = nil
            start.p[2].portrait = nil
        end
    end

    -- 12. Resets match number
    if setMatchNo then setMatchNo(-1) end
    
    -- 13. Reseta o CPU side
    main.cpuSide[1] = false
    
    -- 10. Resets main state
    --if main then
    --    main.t_selGrid = nil
    --    main.t_selectableStages = nil
    --end
    
    tournament.active = false

    if tournamentBgSys.defs.select then
        pcall(bgReset, tournamentBgSys.defs.select)
    end

        -- 18. Recarrega os overlays
    --f_getOverlayAnim()
    --f_getOverlayBgAnim()
    --f_getCellBgAnim()
    
    -- 19. Reloads bracket animations
    --for _, num in pairs(BRACKET_MAIN_BY_SIZE) do 
    --    bracketAnimCache[num] = nil
    --    f_getBracketAnimByNumber(num) 
    --end
    --for _, num in pairs(BRACKET_FINAL_BY_3RD) do 
    --    bracketAnimCache[num] = nil
    --    f_getBracketAnimByNumber(num) 
    --end
    
    -- Forces a full select reset
    safeSelectReset(true)
    
    -- Calls the tournament again without forcing load
    f_tournamentRun(false)
    return true
end

    -- ============================================================
    -- FUNCTION TO EXIT THE TOURNAMENT (Exit)
    -- ============================================================
    local function f_exitTournament()
        print("[Tournament] Exiting tournament (Exit)...")
        --f_clearSavedTournament()
        if setMatchNo then setMatchNo(-1) end
        main.cpuSide[1] = false
        safeSelectReset(false)
        tournament.active = false
        f_backToTitle(p1Ref)
        return true
    end

-- =====================================================================
-- RESOLVE MATCH INLINE (FIXED - PALETAS CORRETAS)
-- =====================================================================
local function resolveMatchInline(m, isFinal, skipElimination)
    -- Stage from the bracket picker (tournament.stagePickIdx, 0/nil = random).
    local stagePick = nil
    do
        local idx = tonumber(tournament.stagePickIdx) or 0
        if idx ~= 0 and type(main) == "table" and type(main.t_selectableStages) == "table" then
            local ref = main.t_selectableStages[idx]
            if ref ~= nil then
                print("[Tournament] bracket stage: " .. tostring(ref))
                stagePick = ref
            end
        end
    end
    f_waitForRelease()
