            end
            -- SKIP FIGHT (Character Change): random winner, then the same
            -- bookkeeping as a played fight. Tournament is NOT restarted.
            if charChanged then
                print("[Tournament] Fight skipped (Character Change) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â random result.")
                m.winner = (math.random(2) == 1) and m.a or m.b
            elseif ok then
                -- Result: ok == true ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ fight P1 side (side1) won
                m.winner = side1
            else
                m.winner = side2
            end
if not isFinal and not skipElimination then
    local loser = (m.winner == m.a) and m.b or m.a
    -- If mapping side1!=m.a (human was in m.b), winner is already the right participant
    if m.winner ~= m.a and m.winner ~= m.b then
        -- safety: should not happen
        m.winner = ok and m.a or m.b
        loser = ok and m.b or m.a
    end
    local loserKey = f_participantKey(loser)
    bracket.eliminated[loserKey] = true
    print("[Tournament] Eliminated: " .. tostring(loserKey) .. " (ID: " .. tostring(f_participantId(loser)) .. ")")
    if f_isPlayerParticipant(loser) then
        -- Any human still alive in bracket?
        local anyHumanLeft = false
        local function checkSide(p)
            if p and f_isPlayerParticipant(p) and not bracket.eliminated[f_participantKey(p)] then
                anyHumanLeft = true
            end
        end
        for _, rd in pairs(bracket.rounds or {}) do
            for _, side in ipairs({"left", "right"}) do
                for _, mm in ipairs(rd[side] or {}) do
                    if mm.winner == nil then
                        checkSide(mm.a); checkSide(mm.b)
                    elseif f_isPlayerParticipant(mm.winner) then
                        checkSide(mm.winner)
                    end
                end
            end
        end
