end
if f_isPlayerParticipant(m.winner) then
    return "WIN"
else
    return "LOSS"
end
        else
            local result = f_simulateCpuOnlyMatch(m.a, m.b)
            if result == "EXIT" then
                f_exitTournament()
                return "EXIT"
            end
            if result == "RESTART" then
                f_restartTournament()
                return "RESTART"
            end
            
         m.winner = result
         local loser = (m.winner == m.a) and m.b or m.a
         if not isFinal and not skipElimination then
             bracket.eliminated[f_participantKey(loser)] = true
             print("[Tournament] Eliminated: " .. f_participantKey(loser))  -- temporary debug
         end
         return "CPU_WIN"
        end
    end

    local totalRounds = R
    local roundNum = startRound
    f_autoSaveTournamentState(bracket, roundNum, p1Ref, playerAlive)

    while roundNum <= totalRounds and not endedEarly do
        local isFinalRound = (roundNum == totalRounds)
        if setMatchNo then setMatchNo(1) end
        f_autoSaveTournamentState(bracket, roundNum, p1Ref, playerAlive)

        local willShowThirdPlace = isFinalRound and tournament.thirdPlacePlayoff
            and bracket.thirdPlaceMatch and bracket.thirdPlaceMatch.winner == nil

        if not f_showBracketOrExit(bracket, size, roundNum, false, p1Ref, willShowThirdPlace, playerAlive) then return nil end
        isFirstLoadMatch = false

        local roundData = bracket.rounds[roundNum]
        local totalMatchesThisRound = #(roundData.left or {}) + #(roundData.right or {})
        local matchIndex = 0
        local isSemifinalRound = (roundNum == totalRounds - 1)

        if willShowThirdPlace and bracket.thirdPlaceMatch.a and bracket.thirdPlaceMatch.b then
            local result = resolveMatchInline(bracket.thirdPlaceMatch, false)
            if result == "EXIT" or result == "RESTART" then return nil end
            bracket.thirdPlaceWinner = bracket.thirdPlaceMatch.winner
            f_autoSaveTournamentState(bracket, roundNum, p1Ref, playerAlive)
            if not f_showBracketOrExit(bracket, size, roundNum, false, p1Ref, false, playerAlive) then return nil end
        end

        for _, side in ipairs({ "left", "right" }) do
            for i, m in ipairs(roundData[side] or {}) do
                if m.winner == nil then
                    matchIndex = matchIndex + 1
                    local isLastMatchOfRound = (matchIndex == totalMatchesThisRound)
                    local skipElim = isSemifinalRound and tournament.thirdPlacePlayoff
                    local matchResult = resolveMatchInline(m, isFinalRound, skipElim)
                    
                    -- >>> TRATA EXIT E CHARACTER CHANGE <<<
                    if matchResult == "EXIT" then
                        f_clearSavedTournament()
                        if setMatchNo then setMatchNo(-1) end
                        main.cpuSide[1] = false
                        safeSelectReset(false)
                        tournament.active = false
                        f_backToTitle(p1Ref)
                        return nil
                    elseif matchResult == "RESTART" then
                        f_clearSavedTournament()
                        if setMatchNo then setMatchNo(-1) end
                        main.cpuSide[1] = false
                        safeSelectReset(false)
                        tournament.active = false
                        f_tournamentRun(false)
                        return nil
                    end

                    if isSemifinalRound and tournament.thirdPlacePlayoff and m.winner then
                        local loser = (m.winner == m.a) and m.b or m.a
                        if side == "left" then bracket.thirdPlaceMatch.a = loser
                        else bracket.thirdPlaceMatch.b = loser end
                    end

                    if m.winner and not isFinalRound then
                        local nextRoundData = bracket.rounds[roundNum + 1]
                        if nextRoundData then
                            if roundNum + 1 == totalRounds then
                                if side == "left" then nextRoundData.left[1].a = m.winner
                                else nextRoundData.left[1].b = m.winner end
                            else
                                local nextMatchIndex = math.ceil(i / 2)
                                local slot = (i % 2 == 1) and "a" or "b"
                                local targetMatch = nextRoundData[side][nextMatchIndex]
                                if targetMatch then targetMatch[slot] = m.winner end
                            end
                        end
                    end

                    f_autoSaveTournamentState(bracket, roundNum, p1Ref, playerAlive)
                    if matchResult == "LOSS" and not playerAlive and not tournament.continueAfterPlayerElimination then endedEarly = true end
                    if tournament.showBracketBetweenMatches and not endedEarly and not isLastMatchOfRound then
                        if not f_showBracketOrExit(bracket, size, roundNum, false, p1Ref, nil, playerAlive) then return nil end
                    end
                    if endedEarly then break end
                end
            end
            if endedEarly then break end
        end
        if endedEarly then break end

        if isFinalRound then
            local finalMatch = roundData.left[1] or (roundData.right and roundData.right[1])
            bracket.champion = finalMatch and finalMatch.winner
            break
        end
        roundNum = roundNum + 1
    end

    if not endedEarly and bracket.champion then
        -- Saves the FINALIZED state (podium) so the panel shows FINISHED and
        -- keeps it in the slot (no wipe): remaining CONTINUE replays the podium.
        f_autoSaveTournamentState(bracket, totalRounds + 1, p1Ref, playerAlive)
        if not f_showBracketOrExit(bracket, size, totalRounds, true, p1Ref, nil, playerAlive) then return nil end
        safeSelectReset(false)
        tournament.active = false
        f_backToTitle(p1Ref)
        return nil
    end

    f_clearSavedTournament()
    if setMatchNo then setMatchNo(-1) end
    main.cpuSide[1] = false
    safeSelectReset(false)
    tournament.active = false
    f_backToTitle(p1Ref)
    return nil
end

