f_setupTournamentModeCommon = function()
    setGameMode('tournamentmode')
    -- Who opened the tournament menu: hints/sprites show THAT controller's key
    -- config (Keys_P1 vs Keys_P2). Session-only, never saved.
    tournament.enterPlayer = 1
    if type(getLastInputController) == "function" then
        local ok, lc = pcall(getLastInputController)
        if ok and tonumber(lc) and tonumber(lc) >= 1 then
            tournament.enterPlayer = math.floor(tonumber(lc))
        end
    end
    -- Menu music only on first entry (from title). Re-calls mid-run (after
    -- HUMAN PLAYERS is confirmed) must NOT restart BGM: the playBgm wrapper
    -- installed for NEW still sees seeding=false and would force the BRACKET
    -- track for a moment before the edit/seeding screen plays bracketEdit
    -- (CPU-only path skips select and goes straight there).
    if not (tournament and tournament.active) then
        if type(f_updateTournamentMusicPath) == "function" then
            pcall(f_updateTournamentMusicPath, "menu")
        end
        if motif and motif.Music and motif.Music.select and motif.Music.select[1] then
            if originalSelectBgm == nil then originalSelectBgm = motif.Music.select[1].bgm or "" end
            motif.Music.select[1].bgm = TournamentSetMusic
        end
        if type(f_playTournamentMusic) == "function" then f_playTournamentMusic("menu") end
    end
    if type(f_applySkipPauseLabel) == "function" then f_applySkipPauseLabel() end
    main.charparam = main.charparam or {}
    main.cpuSide = main.cpuSide or {}
    main.selectMenu = main.selectMenu or {}
    main.teamMenu = main.teamMenu or {{}, {}}
    main.teamMenu[1] = main.teamMenu[1] or {}
    main.teamMenu[2] = main.teamMenu[2] or {}
    main.motif = main.motif or {}
    main.orderSelect = main.orderSelect or {}
    main.forceChar = main.forceChar or {}
    main.charparam.ai = true
    main.charparam.music = true
    main.charparam.rounds = true
    main.charparam.single = true
    main.charparam.stage = true
    main.charparam.time = true
    main.charparam.arcadepath = false
    local hp = tonumber(tournament.humanPlayers) or 1
    if hp < 0 then hp = 0 end
    local maxHPCommon = 128
    if type(f_maxHumanPlayers) == "function" then maxHPCommon = f_maxHumanPlayers() end
    if hp > maxHPCommon then hp = maxHPCommon end

    main.cpuSide[1] = false
    -- Native select only has 2 sides; 3P/4P use sequential selects (side 1)
    main.cpuSide[2] = (hp < 2)
    main.selectMenu[1] = (hp >= 1)
    main.selectMenu[2] = (hp == 2)  -- simultaneous only in classic 2P case

    -- Base team menu (refined later in f_tournamentRun per teamMode)
    main.teamMenu[1].single = true
    main.teamMenu[1].simul = false
    main.teamMenu[1].tag = false
    main.teamMenu[1].turns = false
    main.teamMenu[2].single = true
    main.teamMenu[2].simul = false
    main.teamMenu[2].tag = false
    main.teamMenu[2].turns = false

    main.orderSelect[1] = false
    main.orderSelect[2] = false
    main.elimination = true
    main.motif.continuescreen = false
    main.motif.vsscreen = true
    main.motif.victoryscreen = false
    main.motif.winscreen = false
    main.forceChar[1] = nil
    main.forceChar[2] = nil
    if motif.select_info and motif.select_info.title and motif.select_info.title.TextSpriteData then
        textImgSetText(motif.select_info.title.TextSpriteData, "TOURNAMENT MODE")
    end
    -- Controles:
    --  ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¢ 1P (or 0): whoever pressed Start becomes P1 (classic tournament behavior)
    --  ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¢ 2P: do NOT steal P2 pad ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â 1ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â1 and 2ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â2 mapping (like versus)
    if type(remapInput) == "function" then
        if hp >= 2 then
            if main and type(main.f_restoreBaseRemapInput) == "function" then
                pcall(main.f_restoreBaseRemapInput)
            end
            pcall(remapInput, 1, 1)
            pcall(remapInput, 2, 2)
            print("[Tournament] Remap 2P: player1ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â Ãƒâ€šÃ‚Âctrl1, player2ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â Ãƒâ€šÃ‚Âctrl2")
        else
            local last = 1
            if type(getLastInputController) == "function" then
                last = getLastInputController() or 1
            end
            pcall(remapInput, 1, last)
            pcall(remapInput, last, 1)
            print("[Tournament] Remap 1P: player1ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â Ãƒâ€šÃ‚Âctrl" .. tostring(last))
        end
    end
end

-- =====================================================================
-- MAIN MENU ENTRIES
--
-- In system.def use DOTS (like menuversus.versus). Motif converts
-- internally to "_" keys and main.f_start splits by "_".
--
--   menu.itemname.tournamentmode = "TOURNAMENT MODE"
--   menu.itemname.tournamentmode.startnew = "START NEW"
--   menu.itemname.tournamentmode.continue = "CONTINUE"
--   menu.itemname.tournamentmode.back = "BACK"
--
-- IMPORTANT: do NOT register main.t_itemname["tournamentmode"].
-- If parent has a handler, the engine NEVER opens the submenu (enters mode
-- directly). Only startnew/continue children have handlers.
-- =====================================================================
local function f_menuStartNew(t, item)
    f_setupTournamentModeCommon()
    hook.run("main.t_itemname", t, item)
    return function() return f_tournamentRun(false) end
end

local function f_menuContinue(t, item)
    if not f_hasSavedTournament() then
        if type(sndCancel) == "function" then sndCancel() end
        print("[Tournament] No saved tournament to continue.")
        return nil
    end
    f_setupTournamentModeCommon()
    hook.run("main.t_itemname", t, item)
    return function() return f_tournamentRun(true) end
end

main.t_itemname = main.t_itemname or {}
-- Single item in main menu: enters setup (Misc ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ Main ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ New/Continue)
main.t_itemname['tournamentmode'] = f_menuStartNew
-- Legacy aliases (in case they still exist in system.def)
main.t_itemname['startnew'] = f_menuStartNew
main.t_itemname['continue'] = f_menuStartNew
main.t_itemname['tournamentload'] = f_menuStartNew

-- =====================================================================
-- INJECTS THE ITEM INTO THE MAIN MENU (no system.def edit needed)
--
-- Setting menu_itemname_* alone is NOT enough: the engine iterates
-- motif.title_info.menu.itemname_order. The official API is
-- main.f_appendItemname(menu, parent, name, src, before).
-- =====================================================================
pcall(function()
    local menuSec = motif and motif.title_info
    if not menuSec then
        print("[Tournament] motif.title_info missing ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â could not inject menu.")
        return
    end

    local inserted = false

    -- Modern path (nightly / develop): menu.itemname + menu.itemname_order
    if type(main.f_appendItemname) == "function"
       and type(menuSec.menu) == "table"
       and type(menuSec.menu.itemname) == "table"
       and type(menuSec.menu.itemname_order) == "table" then

        -- before = "exit" (or "options"): positions the item before that in the list
        local before = nil
        for _, key in ipairs(menuSec.menu.itemname_order) do
            if key == "exit" or key == "options" then
                before = key
                break
            end
        end

        -- A single item (no startnew/continue submenu) ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â choice stays in Main Settings
        inserted = main.f_appendItemname(menuSec.menu, "", "tournamentmode", {
            __value = "TOURNAMENT MODE",
        }, before) and true or false

        -- If it already existed in system.def, f_appendItemname returns false (no overwrite).
        -- Item must still show because it is already in order.
        if not inserted then
            if menuSec.menu.itemname["tournamentmode"] == nil or menuSec.menu.itemname["tournamentmode"] == "" then
                menuSec.menu.itemname["tournamentmode"] = "TOURNAMENT MODE"
            end
        end
        -- Removes old order subitems (startnew/continue/back) if present
        if type(menuSec.menu.itemname_order) == "table" then
            local clean = {}
            for _, key in ipairs(menuSec.menu.itemname_order) do
                if key ~= "tournamentmode_startnew"
                   and key ~= "tournamentmode_continue"
                   and key ~= "tournamentmode_back"
                   and key ~= "startnew"
                   and key ~= "continue"
                   and key ~= "back" then
                    -- only removes back/startnew if they are tournament children ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â safer:
                    if key ~= "tournamentmode_startnew" and key ~= "tournamentmode_continue" and key ~= "tournamentmode_back" then
                        clean[#clean + 1] = key
                    end
                elseif key == "tournamentmode" then
                    clean[#clean + 1] = key
                else
                    -- drop tournamentmode_* children
                end
            end
            -- rebuild without tournament children only
            clean = {}
            for _, key in ipairs(menuSec.menu.itemname_order) do
                if key ~= "tournamentmode_startnew" and key ~= "tournamentmode_continue" and key ~= "tournamentmode_back" then
                    clean[#clean + 1] = key
                end
            end
            menuSec.menu.itemname_order = clean
        end
        if type(menuSec.menu.itemname) == "table" then
            menuSec.menu.itemname["tournamentmode_startnew"] = nil
            menuSec.menu.itemname["tournamentmode_continue"] = nil
            menuSec.menu.itemname["tournamentmode_back"] = nil
        end

        print("[Tournament] Menu inject (f_appendItemname): inserted=" .. tostring(inserted))

        -- If the main menu was ALREADY built (main.menu exists), rebuilds
        if type(main.f_start) == "function" and main.menu ~= nil then
            local prevGroup = main.group
            main.group = "title_info"
            pcall(main.f_start)
            if prevGroup ~= nil then main.group = prevGroup end
            print("[Tournament] main.f_start() re-executed to apply the menu item.")
        end

    else
        -- Legacy fallback: flat keys + main.t_sort.title_info.menu
        local function f_setIfEmpty(tbl, key, value)
            if tbl[key] == nil or tbl[key] == "" then
                tbl[key] = value
            end
        end
        f_setIfEmpty(menuSec, "menu_itemname_tournamentmode", "TOURNAMENT MODE")

        if main.t_sort and main.t_sort.title_info and type(main.t_sort.title_info.menu) == "table" then
            local order = main.t_sort.title_info.menu
            local function has(key)
                for _, v in ipairs(order) do
                    if v == key then return true end
                end
                return false
            end
            local function insertBefore(key, beforeKey)
                if has(key) then return end
                local pos = #order + 1
                if beforeKey then
                    for i, v in ipairs(order) do
                        if v == beforeKey then pos = i; break end
                    end
                end
                table.insert(order, pos, key)
            end
            local before = has("exit") and "exit" or (has("options") and "options" or nil)
            insertBefore("tournamentmode", before)
            -- remove filhos antigos do order
            local clean = {}
            for _, v in ipairs(order) do
                if v ~= "tournamentmode_startnew" and v ~= "tournamentmode_continue" and v ~= "tournamentmode_back" then
                    clean[#clean + 1] = v
                end
            end
            for i = #order, 1, -1 do table.remove(order, i) end
            for _, v in ipairs(clean) do order[#order + 1] = v end
            inserted = true
            print("[Tournament] Menu inject (legacy t_sort): OK")
            if type(main.f_start) == "function" and main.menu ~= nil then
                local prevGroup = main.group
                main.group = "title_info"
                pcall(main.f_start)
                if prevGroup ~= nil then main.group = prevGroup end
            end
        else
            print("[Tournament] WARNING: did not find menu.itemname_order nor t_sort ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â item may not show without system.def.")
        end
    end

    -- Optional debug file in the game root (OFF: it littered releases).
    -- Set true to re-enable TOURNAMENT_MENUNAME_DEBUG.txt once.
    local MENUNAME_DEBUG_FILE = false
    if MENUNAME_DEBUG_FILE then
    local dbg = io.open("TOURNAMENT_MENUNAME_DEBUG.txt", "w")
    if dbg then
        dbg:write("inserted = " .. tostring(inserted) .. "\n")
        dbg:write("has f_appendItemname = " .. tostring(type(main.f_appendItemname) == "function") .. "\n")
        dbg:write("has menu.itemname = " .. tostring(menuSec.menu and type(menuSec.menu.itemname) == "table") .. "\n")
        dbg:write("has menu.itemname_order = " .. tostring(menuSec.menu and type(menuSec.menu.itemname_order) == "table") .. "\n")
        if menuSec.menu and type(menuSec.menu.itemname) == "table" then
            dbg:write("itemname.tournamentmode = " .. tostring(menuSec.menu.itemname["tournamentmode"]) .. "\n")
            dbg:write("itemname.tournamentmode_startnew = " .. tostring(menuSec.menu.itemname["tournamentmode_startnew"]) .. "\n")
            dbg:write("itemname.tournamentmode_continue = " .. tostring(menuSec.menu.itemname["tournamentmode_continue"]) .. "\n")
            dbg:write("itemname.tournamentmode_back = " .. tostring(menuSec.menu.itemname["tournamentmode_back"]) .. "\n")
            if type(menuSec.menu.itemname_order) == "table" then
                dbg:write("itemname_order =\n")
                for i, k in ipairs(menuSec.menu.itemname_order) do
                    dbg:write(string.format("  %d: %s\n", i, tostring(k)))
                end
            end
        else
            dbg:write("menu_itemname_tournamentmode = " .. tostring(menuSec.menu_itemname_tournamentmode) .. "\n")
        end
        dbg:close()
    end
    end
end)

-- =====================================================================
-- MENU COEXISTENCE (other menu-injecting modules / +system.def addons)
-- =====================================================================
-- Anything that rebuilds itemname_order from the defs after us (e.g. a
-- +system.def addon applied late, like trials') wipes runtime entries.
-- f_ensureTournamentMenuItemNow() re-asserts ours: called at load (above),
-- on every menu open (hook), and BEFORE every title build (f_start
-- wrapper below, so a rebuild-then-build sequence still shows us).
-- Strictly additive (never touches other items), no-op when present.
-- (Global: hook + wrapper call it.)
function f_ensureTournamentMenuItemNow()
    main.t_itemname = main.t_itemname or {}
    if type(f_menuStartNew) == "function" then
        main.t_itemname['tournamentmode'] = f_menuStartNew
    end
    local okM, menuSec = pcall(function() return motif and motif.title_info end)
    if not okM or type(menuSec) ~= "table" then return end
    local m = menuSec.menu
    if type(m) ~= "table" or type(m.itemname) ~= "table"
        or type(m.itemname_order) ~= "table" then return end
    for _, k in ipairs(m.itemname_order) do
        if k == "tournamentmode" then return end
    end
    if type(main.f_appendItemname) == "function" then
        local before = nil
        for _, key in ipairs(m.itemname_order) do
            if key == "exit" or key == "options" then before = key; break end
        end
        pcall(main.f_appendItemname, m, "", "tournamentmode", {
            __value = "TOURNAMENT MODE",
        }, before)
    else
        m.itemname["tournamentmode"] = "TOURNAMENT MODE"
        m.itemname_order[#m.itemname_order + 1] = "tournamentmode"
    end
end
if type(hook) == "table" and type(hook.add) == "function" then
    pcall(hook.add, "main.menu.loop", "tournamentMenuItem", function()
        if type(f_ensureTournamentMenuItemNow) == "function" then
            pcall(f_ensureTournamentMenuItemNow)
        end
    end)
end
-- main.f_start() builds the title menu FROM itemname_order: re-assert ours
-- first so a rebuild (defs) immediately followed by a build still shows us.
-- (Precedent: trials wraps menu.f_start the same way.)
if type(main) == "table" and type(main.f_start) == "function"
    and type(tournamentMenuFStartWrapped) == "nil" then
    tournamentMenuFStartWrapped = true
    local _tournamentOrigFStart = main.f_start
    main.f_start = function(...)
        if type(f_ensureTournamentMenuItemNow) == "function" then
            pcall(f_ensureTournamentMenuItemNow)
        end
        return _tournamentOrigFStart(...)
    end
end

