-- ---------------------------------------------------------------------
-- Engine preload store: Action 0 + win pose WITHOUT sffNew
-- ---------------------------------------------------------------------
-- The engine's per-char preload keeps only the actions registered in its list
-- (charAnimPreload) when the char is preloaded. A screenpack registers them via
-- p1.face.anim / p1.face.done.anim. This module can do the same itself:
-- preloadListChar(n) registers an action, and with BootLoadingMode 0 the chars
-- (already preloaded without it) are re-queued once, behind Ikemen's own
-- "NOW LOADING..." screen. (Global: the main chunk has a 200 locals limit.)

-- Samples the first playable chars: is Action 0 / any win pose (181-189) in the store?
function f_engineStoreSample(maxCharsToCheck)
    local action0Found, winPoseFound, checkedCharCount = false, false, 0
    for _, selectChar in ipairs(main.t_selChars) do
        if type(selectChar) == "table" and selectChar.playable ~= false and selectChar.char_ref ~= nil then
            checkedCharCount = checkedCharCount + 1
            if not action0Found then
                local callOk, storedAnim = pcall(animGetPreloadedCharData, selectChar.char_ref, 0, -1, true)
                action0Found = callOk and storedAnim ~= nil
            end
            if not winPoseFound then
                for winActionNumber = 181, 189 do
                    local callOk, storedAnim = pcall(animGetPreloadedCharData, selectChar.char_ref, winActionNumber, -1, true)
                    if callOk and storedAnim ~= nil then winPoseFound = true break end
                end
            end
            if (action0Found and winPoseFound) or checkedCharCount >= maxCharsToCheck then break end
        end
    end
    return action0Found, winPoseFound, checkedCharCount
end

function f_engineActionPreloadAtBoot()
    if not TOURNAMENT_ENGINE_ACTION_PRELOAD_AT_BOOT then return end
    if type(preloadListChar) ~= "function" or type(queueCharPreload) ~= "function"
       or type(preloading) ~= "function" or type(animGetPreloadedCharData) ~= "function"
       or type(getCharPreloadStatus) ~= "function"
       or type(modifyGameOption) ~= "function" or type(gameOption) ~= "function" then
        print("[Tournament][Preload] engine preload API incomplete: skipping boot action preload")
        return
    end
    if type(main) ~= "table" or type(main.t_selChars) ~= "table" then return end

    local action0Found, winPoseFound = f_engineStoreSample(40)
    if action0Found and winPoseFound then
        print("[Tournament][Preload] engine store already holds Action 0 and a win pose (screenpack declares them): nothing to do")
        return
    end

    -- Register exactly what the loaders look for: Action 0 + the win chain.
    local registeredActions = { 0 }
    if type(WIN_POSE_ACTION_CHAIN) == "table" then
        for _, winActionNumber in ipairs(WIN_POSE_ACTION_CHAIN) do
            registeredActions[#registeredActions + 1] = winActionNumber
        end
    else
        for winActionNumber = 181, 189 do registeredActions[#registeredActions + 1] = winActionNumber end
    end
    for _, actionNumber in ipairs(registeredActions) do
        pcall(preloadListChar, actionNumber)
    end

    -- Full roster at boot is OFF by default (slow on huge rosters); the
    -- participants-scoped path at bracket entry covers tournament needs.
    if not TOURNAMENT_ENGINE_PRELOAD_FULL_ROSTER_AT_BOOT then
        print("[Tournament][Preload] full-roster boot re-queue skipped (participants path covers it).")
        return
    end

    local originalBootMode = gameOption("Config.BootLoadingMode")
    if originalBootMode ~= 0 and not TOURNAMENT_PRELOAD_RETRY_NONZERO_BOOTMODE then
        print("[Tournament][Preload] BootLoadingMode > 0: actions registered, but chars the background preload already finished can't be redone; those fall back to sffNew. Use BootLoadingMode = 0 for full coverage.")
        return
    end
    if originalBootMode ~= 0 then
        print("[Tournament][Preload] TEST: BootLoadingMode ~= 0, re-queueing anyway to check if ready chars pick up the new actions.")
    end

    -- Unique playable char refs of the whole roster.
    local refsToQueue, seenRefs = {}, {}
    for _, selectChar in ipairs(main.t_selChars) do
        if type(selectChar) == "table" and selectChar.playable ~= false
           and selectChar.char_ref ~= nil and not seenRefs[selectChar.char_ref] then
            seenRefs[selectChar.char_ref] = true
            refsToQueue[#refsToQueue + 1] = selectChar.char_ref
        end
    end
    if #refsToQueue == 0 then return end

    -- Progress: Ikemen's own loading text ("NOW LOADING...  i/N").
    local loadingTextSprite, loadingBaseText = nil, ""
    if motif and motif.title_info and motif.title_info.loading
       and motif.title_info.loading.TextSpriteData ~= nil then
        loadingTextSprite = motif.title_info.loading.TextSpriteData
        loadingBaseText = tostring(motif.title_info.loading.text or "")
    end

    local startClock = os.clock()
    -- Temporarily enable the queue (QueueCharPreload is a no-op in mode 0) and
    -- ALWAYS restore the original mode, even if something below errors.
    pcall(modifyGameOption, "Config.BootLoadingMode", 1)
    local loopOk, loopError = pcall(function()
        for _, charRef in ipairs(refsToQueue) do
            queueCharPreload(charRef, 1)
        end
        local lastProgressClock = -1
        while preloading() do
            local nowClock = os.clock()
            if nowClock - startClock > TOURNAMENT_ENGINE_REPRELOAD_TIMEOUT_SECONDS then
                print("[Tournament][Preload] timeout waiting for the engine preload: continuing")
                break
            end
            if loadingTextSprite ~= nil and nowClock - lastProgressClock >= 0.25 then
                lastProgressClock = nowClock
                local readyCount = 0
                for _, charRef in ipairs(refsToQueue) do
                    if getCharPreloadStatus(charRef) == "ready" then readyCount = readyCount + 1 end
                end
                textImgSetText(loadingTextSprite,
                    loadingBaseText .. "  " .. tostring(readyCount) .. "/" .. tostring(#refsToQueue))
            end
            -- Same pacing as the engine's own wait loop: draw + refresh per iteration.
            clearColor(0, 0, 0)
            if loadingTextSprite ~= nil then textImgDraw(loadingTextSprite) end
            refresh()
        end
    end)
    pcall(modifyGameOption, "Config.BootLoadingMode", originalBootMode)
    if loadingTextSprite ~= nil then
        pcall(textImgSetText, loadingTextSprite, loadingBaseText)
    end
    if not loopOk then
        print("[Tournament][Preload] error while re-preloading: " .. tostring(loopError))
        return
    end
    print(string.format("[Tournament][Preload] re-preloaded %d chars with actions %s in %.1fs",
        #refsToQueue, table.concat(registeredActions, ","), os.clock() - startClock))
end

pcall(f_engineActionPreloadAtBoot)

-- One-time report (after the step above): are Action 0 / a win pose in the store?
-- TEST: per char_ref (not the 40-char sample), so YES/NO is per character.
function f_engineStoreVerifyRefs(maxRefs)
    if type(animGetPreloadedCharData) ~= "function" then return end
    if type(main) ~= "table" or type(main.t_selChars) ~= "table" then return end
    local n = 0
    for _, selectChar in ipairs(main.t_selChars) do
        if type(selectChar) == "table" and selectChar.playable ~= false and selectChar.char_ref ~= nil then
            n = n + 1
            if n > (tonumber(maxRefs) or 12) then break end
            local ok0, a0 = pcall(animGetPreloadedCharData, selectChar.char_ref, 0, -1, true)
            local has0 = ok0 and a0 ~= nil
            local hasWin, winAct = false, nil
            for winActionNumber = 181, 189 do
                local okW, aW = pcall(animGetPreloadedCharData, selectChar.char_ref, winActionNumber, -1, true)
                if okW and aW ~= nil then hasWin, winAct = true, winActionNumber break end
            end
            print(string.format("[Tournament][Preload][TEST] ref=%s action0=%s winpose=%s%s",
                tostring(selectChar.char_ref), has0 and "YES" or "NO",
                hasWin and "YES" or "NO", hasWin and ("(" .. tostring(winAct) .. ")") or ""))
        end
    end
end
pcall(function()
    if type(animGetPreloadedCharData) ~= "function" then return end
    if type(main) ~= "table" or type(main.t_selChars) ~= "table" then return end
    if gameOption("Config.BootLoadingMode") ~= 0 and not TOURNAMENT_PRELOAD_RETRY_NONZERO_BOOTMODE then return end
    if TOURNAMENT_PRELOAD_RETRY_NONZERO_BOOTMODE then
        f_engineStoreVerifyRefs(12)
    end
    local action0Found, winPoseFound, checkedCharCount = f_engineStoreSample(40)
    print(string.format("[Tournament][Preload] engine store (first %d chars): Action 0 = %s | win pose 181-189 = %s",
        checkedCharCount, action0Found and "YES" or "NO", winPoseFound and "YES" or "NO"))
    if not action0Found or not winPoseFound then
        print("[Tournament][Preload] missing ones fall back to sffNew.")
    end
end)
